typedef struct {
    int ue_id;
    int radio_resource_params;
    char* uplink_data_buffer;
} LTE_UESession_t;

LTE_UESession_t* initialize_and_populate_sessions(int num_sessions) {
    if (num_sessions > MAX_UE_SESSIONS) {
        return NULL; // Handle error: too many sessions
    }

    LTE_UESession_t* sessions = (LTE_UESession_t*)malloc(num_sessions * sizeof(LTE_UESession_t));
    if (!sessions) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < num_sessions; i++) {
        sessions[i].ue_id = i + 1;
        sessions[i].radio_resource_params = rand() % 100; // Example radio resource params

        int buffer_size = 1024 * (i + 1); // Example buffer size
        sessions[i].uplink_data_buffer = (char*)malloc(buffer_size);
        if (!sessions[i].uplink_data_buffer) {
            for (int j = 0; j < i; j++) {
                free(sessions[j].uplink_data_buffer);
            }
            free(sessions);
            return NULL; // Handle memory allocation failure
        }

        memset(sessions[i].uplink_data_buffer, 'A' + i % 26, buffer_size); // Example data
    }

    return sessions;
}

void validate_sessions(LTE_UESession_t* sessions, int num_sessions) {
    for (int i = 0; i < num_sessions; i++) {
        if (!sessions[i].uplink_data_buffer) {
            printf("Session %d buffer not initialized.\n", sessions[i].ue_id);
        } else {
            char expected_char = 'A' + i % 26;
            for (int j = 0; j < strlen(sessions[i].uplink_data_buffer); j++) {
                if (sessions[i].uplink_data_buffer[j] != expected_char) {
                    printf("Session %d buffer corruption at index %d.\n", sessions[i].ue_id, j);
                    break;
                }
            }
        }
    }
}

int main() {
    int num_sessions = 5;
    LTE_UESession_t* sessions = initialize_and_populate_sessions(num_sessions);

    if (sessions) {
        validate_sessions(sessions, num_sessions);
        for (int i = 0; i < num_sessions; i++) {
            free(sessions[i].uplink_data_buffer);
        }
        free(sessions);
    } else {
        printf("Failed to initialize sessions.\n");
    }

    return 0;
}
