#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define DEFAULT_MAX_SIZE (MAX_RECORDS * sizeof(long) + MAX_RECORDS * sizeof(int) + MAX_RECORDS * sizeof(record))

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t size;
    size_t max_size;
    pthread_mutex_t mutex;
} memory_manager;

int init_memory_manager(memory_manager* manager, size_t max_size) {
    if (max_size == 0) {
        max_size = DEFAULT_MAX_SIZE;
    }
    manager->offsets = malloc(max_size);
    manager->keys = (int*)((char*)manager->offsets + max_size / 3);
    manager->records = (record*)((char*)manager->keys + max_size / 3);
    if (!manager->offsets || !manager->keys || !manager->records) {
        return -1; // Memory allocation failed
    }
    manager->size = 0;
    manager->max_size = max_size;
    pthread_mutex_init(&manager->mutex, NULL);
    srand(time(NULL));
    return 0; // Success
}

void free_memory_manager(memory_manager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free(manager->offsets);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

int allocate_records(memory_manager* manager, int num_records, size_t offset_range) {
    pthread_mutex_lock(&manager->mutex);
    if (num_records + manager->size > MAX_RECORDS) {
        return -2; // Exceeds maximum number of records
    }
    if ((offset_range * num_records * sizeof(int)) + manager->size * sizeof(record) > manager->max_size - manager->size) {
        return -3; // Exceeds memory limit
    }
    for (int i = 0; i < num_records; i++) {
        manager->offsets[manager->size] = rand() % offset_range;
        manager->keys[manager->size] = rand();
        manager->records[manager->size].value = rand();
        manager->size++;
    }
    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

void reset_random_generator() {
    srand(time(NULL));
}
