#include <stdio.h>
#include <stdlib.h>

#define INT_MAX 2147483647
#define INT_MIN (-INT_MAX - 1)

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntArray;

void init_array(IntArray *arr) {
    arr->data = NULL;
    arr->size = 0;
    arr->capacity = 0;
}

void resize_array(IntArray *arr, size_t new_capacity) {
    int *new_data = (int *)realloc(arr->data, new_capacity * sizeof(int));
    if (new_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
}

void add_to_array(IntArray *arr, int value) {
    if (arr->size >= arr->capacity) {
        resize_array(arr, arr->capacity == 0 ? 1 : arr->capacity * 2);
    }
    arr->data[arr->size++] = value;
}

int read_int() {
    char buffer[12];
    int value;
    if (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        if (sscanf(buffer, "%d", &value) == 1 && value >= INT_MIN && value <= INT_MAX) {
            return value;
        }
    }
    return -1; // Invalid input
}

void free_array(IntArray *arr) {
    free(arr->data);
    arr->data = NULL;
    arr->size = arr->capacity = 0;
}

int main() {
    IntArray arr;
    init_array(&arr);

    int value;
    printf("Enter integers (or non-integer to stop):\n");
    while ((value = read_int()) != -1) {
        add_to_array(&arr, value);
    }

    if (arr.size == 0) {
        printf("No valid integers provided.\n");
    } else {
        int max_value = arr.data[0];
        for (size_t i = 1; i < arr.size; ++i) {
            if (arr.data[i] > max_value) {
                max_value = arr.data[i];
            }
        }
        printf("The largest integer is: %d\n", max_value);
    }

    free_array(&arr);

    return 0;
}
