    EVP_CIPHER *cipher;
    bool is_token_valid;
} CryptoResult;

CryptoResult process_crypto_and_validate_token(const char *cipher_mode, const char *json_string) {
    CryptoResult result = {NULL, false};

    if (strcmp(cipher_mode, "null") == 0) {
        result.cipher = EVP_enc_null();
    } else if (strcmp(cipher_mode, "ecb") == 0) {
        result.cipher = EVP_des_ecb();
    } else if (strcmp(cipher_mode, "ede") == 0) {
        result.cipher = EVP_des_ede3_cbc();
    } else if (strcmp(cipher_mode, "cfb") == 0) {
        result.cipher = EVP_des_cfb64();
    } else {
        return result; // Invalid cipher mode
    }

    json_object *jobj = json_tokener_parse(json_string);
    if (!jobj || !json_is_object(jobj)) {
        return result; // Invalid JSON format
    }

    const char *access_token = json_object_get_string(json_object_object_get_ex(jobj, "access_token", NULL));
    int expires_in;
    if (!json_object_get_int_ex(json_object_object_get_ex(jobj, "expires_in", NULL), &expires_in) || expires_in <= 0) {
        return result; // Missing or invalid expires_in
    }

    const char *token_type = json_object_get_string(json_object_object_get_ex(jobj, "token_type", NULL));
    if (strcmp(token_type, "Bearer") != 0) {
        return result; // Invalid token_type
    }

    // Optionally check for refresh_token
    // json_bool has_refresh_token = json_object_get_boolean(json_object_object_get_ex(jobj, "refresh_token", NULL));

    result.is_token_valid = true;
    return result;
}
