def modify_kickstart_config(kickstart_file, replacements):
    try:
        # Create a temporary file for the modified configuration
        temp_file = kickstart_file + ".tmp"

        # Replace placeholders using sed commands
        for placeholder, value in replacements.items():
            sed_command = f"sed -i 's/{placeholder}/{value}/g' {kickstart_file}"
            subprocess.run(sed_command, check=True, shell=True)

        # Add a new line with an encrypted password to the temporary file
        encrypted_password = encrypt_password("password123")
        with open(temp_file, "a") as f:
            f.write(f"encrypted_password {encrypted_password}\n")

        # Rename the temporary file to the original file name
        subprocess.run(f"mv {temp_file} {kickstart_file}", check=True, shell=True)
    except subprocess.CalledProcessError as e:
        print(f"Error executing sed command: {e}")

