#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int init_file_lock(const char *lock_file_path, int initial_timeout) {
    int fd = open(lock_file_path, O_CREAT | O_EXCL | O_RDWR, 0644);
    if (fd == -1 && errno == EEXIST) {
        // Lock file already exists
        return -1;
    } else if (fd == -1) {
        // Failed to create lock file
        perror("Failed to create lock file");
        return -2;
    }

    struct flock lock = {0};
    lock.l_type = F_WRLCK;
    lock.l_whence = SEEK_SET;
    lock.l_start = 0;
    lock.l_len = 0;

    if (fcntl(fd, F_SETLK, &lock) == -1) {
        close(fd);
        perror("Failed to set file lock");
        return -3;
    }

    // Set initial timeout for the lock
    // This part is simplified as setting a timeout typically involves signal handling and alarm()
    printf("File lock acquired with initial timeout: %d\n", initial_timeout);

    return fd;
}

void release_file_lock(int fd) {
    struct flock lock = {0};
    lock.l_type = F_UNLCK;
    lock.l_whence = SEEK_SET;
    lock.l_start = 0;
    lock.l_len = 0;

    if (fcntl(fd, F_SETLK, &lock) == -1) {
        perror("Failed to release file lock");
    } else {
        close(fd);
        printf("File lock released\n");
    }
}
