#include <vector>
#include <mutex>

class SafeVectorModifier {
private:
    std::vector<int> data;
    mutable std::mutex mtx;

public:
    void insertAfter(const int& target, const int& value) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find(data.begin(), data.end(), target);
        if (it != data.end()) {
            data.insert(it + 1, value);
        } else {
            data.push_back(value);
        }
    }

    void insertAtEnd(const int& value) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push_back(value);
    }
};
