};

// Sandesh client class
class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& io_context, MockInterfaceTable& mock_table)
        : io_context_(io_context), mock_table_(mock_table) {}

    void sendRequest(const std::string& url, const std::string& method, const std::string& data = "") {
        // Simulate sending request and handle response
        boost::property_tree::ptree pt;
        if (method == "GET") {
            // Send GET request
            boost::asio::ip::tcp::resolver resolver(io_context_);
            boost::asio::ip::tcp::resolver::results_type endpoints = resolver.resolve(url);
            boost::asio::ip::tcp::socket socket(io_context_);
            boost::asio::connect(socket, endpoints);

            boost::system::error_code ec;
            boost::asio::write(socket, boost::asio::buffer("GET / HTTP/1.1\r\nHost: " + url + "\r\nConnection: close\r\n\r\n"), ec);
            if (ec) throw std::runtime_error("Failed to send GET request");

            // Read response
            boost::asio::streambuf response;
            boost::asio::read_until(socket, response, "\r\n\r\n", ec);
            if (ec && ec != boost::asio::error::eof) throw std::runtime_error("Failed to read GET response");
        } else if (method == "POST") {
            // Send POST request
            boost::asio::ip::tcp::resolver resolver(io_context_);
            boost::asio::ip::tcp::resolver::results_type endpoints = resolver.resolve(url);
            boost::asio::ip::tcp::socket socket(io_context_);
            boost::asio::connect(socket, endpoints);

            std::string request = "POST / HTTP/1.1\r\nHost: " + url + "\r\nContent-Type: application/json\r\nContent-Length: " + std::to_string(data.size()) + "\r\nConnection: close\r\n\r\n" + data;
            boost::system::error_code ec;
            boost::asio::write(socket, boost::asio::buffer(request), ec);
            if (ec) throw std::runtime_error("Failed to send POST request");

            // Read response
            boost::asio::streambuf response;
            boost::asio::read_until(socket, response, "\r\n\r\n", ec);
            if (ec && ec != boost::asio::error::eof) throw std::runtime_error("Failed to read POST response");
        }

        // Parse response and log details
        boost::property_tree::read_json(std::istreambuf_iterator<char>(response), pt);
        std::cout << "Request completed in: " << (std::chrono::steady_clock::now() - start_time_).count() << " ms" << std::endl;
        std::cout << "Response size: " << response.size() << " bytes" << std::endl;
    }

private:
    boost::asio::io_context& io_context_;
    MockInterfaceTable& mock_table_;
    std::chrono::steady_clock::time_point start_time_;
};

int main() {
    try {
        boost::asio::io_context io_context;
        MockInterfaceTable mock_table;

        SandeshClient client(io_context, mock_table);

        // Simulate concurrent requests
        std::vector<std::thread> threads;
        for (int i = 0; i < 1000; ++i) {
            threads.emplace_back([&client, &mock_table]() {
                try {
                    client.sendRequest("http://example.com", "GET");
                    client.sendRequest("http://example.com/api/data", "POST", "{\"key\":\"value\"}");
                } catch (const std::exception& e) {
                    std::cerr << "Error: " << e.what() << std::endl;
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }

        // Print statistics
