using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public async IAsyncEnumerable<string> ProcessHttpRequests(List<string> urls, HttpClient client, TimeSpan timeout)
{
    var tasks = new List<Task<string>>();
    foreach (var url in urls)
    {
        tasks.Add(RetryRequestAsync(url, client, timeout));
    }

    foreach (var task in await Task.WhenAll(tasks))
    {
        yield return task;
    }
}

private async Task<string> RetryRequestAsync(string url, HttpClient client, TimeSpan timeout)
{
    const int maxRetries = 3;
    for (int attempt = 0; attempt <= maxRetries; attempt++)
    {
        try
        {
            using (var requestMessage = new HttpRequestMessage(HttpMethod.Get, url))
            {
                requestMessage.Timeout = timeout;
                var response = await client.SendAsync(requestMessage);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
            }
        }
        catch (HttpRequestException ex)
        {
            // Handle non-fatal errors and retry
            if (IsNonFatalError(ex))
            {
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
                continue;
            }
        }

        throw new Exception($"Failed to process request after {maxRetries} attempts.");
    }
}

private bool IsNonFatalError(Exception ex)
{
    // Define non-fatal errors based on exception type or message
    return ex is HttpRequestException || ex.Message.Contains("Connection timed out");
}
