public class WeatherServiceClient
{
    private HttpClient _httpClient;
    private string _apiUrl = "https://api.weather.com/data/2.5/weather?q=your_city&appid=your_api_key";
    private JObject _cachedWeatherData;

    public WeatherServiceClient()
    {
        _httpClient = new HttpClient();
    }

    public async Task<JObject> GetWeatherDataAsync()
    {
        try
        {
            if (_cachedWeatherData != null)
                return _cachedWeatherData;

            var response = await _httpClient.GetAsync(_apiUrl);
            response.EnsureSuccessStatusCode();

            string weatherJson = await response.Content.ReadAsStringAsync();
            JObject weatherData = JObject.Parse(weatherJson);

            // Cache the data for 15 minutes
            _cachedWeatherData = weatherData;
            Task.Delay(TimeSpan.FromMinutes(15)).ContinueWith(t => _cachedWeatherData = null);

            return weatherData;
        }
        catch (HttpRequestException e)
        {
            Console.WriteLine($"Request error: {e.Message}");
            // Handle network delays and retries here
            throw;
        }
    }

    public void AdjustLightingIntensity(JObject weatherData)
    {
        if (weatherData == null) return;

        double temperature = weatherData["main"]["temp"].Value<double>();

        // Adjust lighting based on temperature
        if (temperature < 10)
        {
            Console.WriteLine("Adjusting lighting to warm mode for cold weather.");
            // Logic to adjust lighting intensity in the 3D environment
        }
        else if (temperature > 25)
        {
            Console.WriteLine("Adjusting lighting to cool mode for hot weather.");
            // Logic to adjust lighting intensity in the 3D environment
        }
        else
        {
            Console.WriteLine("Maintaining normal lighting intensity for moderate weather.");
            // Logic to maintain lighting intensity in the 3D environment
        }
    }

    public void UpdateLightingBasedOnWeather()
    {
        try
        {
            JObject weatherData = await GetWeatherDataAsync();
            AdjustLightingIntensity(weatherData);
        }
        catch (Exception ex)
        {
