using System;
using System.Collections.Generic;
using Microsoft.AspNetCore.Mvc;

[Route("api/[controller]")]
public class UserController : ControllerBase
{
    private static Dictionary<string, UserProfile> users = new Dictionary<string, UserProfile>();
    private static int versionCounter = 0;

    [HttpPut("{userId}")]
    public IActionResult UpdateUserProfile(string userId, [FromBody] UserProfile updatedProfile)
    {
        if (!users.ContainsKey(userId))
        {
            return NotFound();
        }

        lock (users)
        {
            users[userId].Version++;
            users[userId].LastModified = DateTime.UtcNow;
            users[userId].Merge(updatedProfile);
        }

        return Ok(users[userId]);
    }

    [HttpPatch("{userId}")]
    public IActionResult PartiallyUpdateUserProfile(string userId, [FromBody] UserProfile partialUpdate)
    {
        if (!users.ContainsKey(userId))
        {
            return NotFound();
        }

        lock (users)
        {
            users[userId].Version++;
            users[userId].LastModified = DateTime.UtcNow;
            users[userId].Merge(partialUpdate);
        }

        return Ok(users[userId]);
    }

    [HttpGet("{userId}")]
    public IActionResult GetUserProfile(string userId)
    {
        if (!users.ContainsKey(userId))
        {
            return NotFound();
        }

        return Ok(new
        {
            UserProfile = users[userId],
            LastModified = users[userId].LastModified,
            Version = users[userId].Version
        });
    }
}

public class UserProfile
{
    public string Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Email { get; set; }
    public DateTime LastModified { get; private set; } = DateTime.UtcNow;
    public int Version { get; private set; }

    public void Merge(UserProfile other)
    {
        if (other.Name != null) Name = other.Name;
        if (other.Age > 0) Age = other.Age;
        if (other.Email != null) Email = other.Email;
    }
}
```

