using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static List<XmlNode> FindElementsByXPath(string xmlContent, string xpathExpression, bool stripNamespaces = false)
    {
        var nodeList = new List<XmlNode>();
        using (var reader = XmlReader.Create(new StringReader(xmlContent)))
        {
            var doc = new XmlDocument();
            doc.Load(reader);
            var nav = doc.CreateNavigator();

            if (stripNamespaces)
                xpathExpression = StripNamespace(xpathExpression);

            foreach (XPathNavigator node in nav.Select(xpathExpression))
            {
                nodeList.Add(node.Clone());
            }
        }

        return nodeList;
    }

    private static string StripNamespace(string xpathExpression)
    {
        // This is a simple example of namespace stripping. For a more robust solution, consider using an XPath expression that doesn't depend on namespaces.
        if (xpathExpression.Contains("/*:"))
        {
            xpathExpression = xpathExpression.Replace("/*:", "/");
        }
        return xpathExpression;
    }
}
```

