import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class StringHasher {

    public static String hashStrings(String... strings) throws NoSuchAlgorithmException {
        return hashStrings(strings, false);
    }

    public static String hashStrings(String[] strings, boolean base64Encode) throws NoSuchAlgorithmException {
        StringBuilder sb = new StringBuilder();
        for (String str : strings) {
            if (str == null || str.isEmpty()) continue;
            if (str.length() > 1024) throw new IllegalArgumentException("String too long");
            sb.append(str);
        }

        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(sb.toString().getBytes());

        return base64Encode ? Base64.getEncoder().encodeToString(hashBytes) : bytesToHex(hashBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println("MD5 Hex: " + hashStrings("Hello", "World"));
            System.out.println("Base64 Encoded: " + hashStrings("Hello", "World", true));
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
