const fs = require('fs').promises;
const request = require('request-promise');
const rateLimit = require('async-rate-limit');

// Configure the rate limiter to limit to 5 concurrent operations
const configRateLimiter = rateLimit({
  max: 5,
  windowMs: 1000, // Time frame in milliseconds for the limit
});

async function readConfigFile(filePath) {
  try {
    const fileContent = await fs.readFile(filePath, 'utf8');
    return JSON.parse(fileContent);
  } catch (error) {
    console.error(`Error reading configuration file at ${filePath}:`, error);
    throw new Error('Failed to read configuration file');
  }
}

async function fetchExternalConfig(url) {
  try {
    const response = await request.get(url, { json: true });
    return response;
  } catch (error) {
    console.error(`Error fetching external configuration from ${url}:`, error);
    throw new Error('Failed to fetch external configuration');
  }
}

async function getConfigurations(configFilePaths, externalConfigUrl) {
  const configPromises = configFilePaths.map(async (filePath) => {
    try {
      return await readConfigFile(filePath);
    } catch (error) {
      console.warn(`Skipping failed file: ${filePath}`);
      return null;
    }
  });

  const rateLimitedFetchExternalConfig = configRateLimiter(fetchExternalConfig);
  const externalConfigPromise = rateLimitedFetchExternalConfig(externalConfigUrl);

  const [localConfigs, externalConfig] = await Promise.all([...configPromises, externalConfigPromise]);
  return { localConfigs, externalConfig };
}

// Example usage:
const configFilePaths = ['./config1.json', './config2.json'];
const externalConfigUrl = 'https://api.example.com/config';

getConfigurations(configFilePaths, externalConfigUrl)
  .then((result) => {
    console.log('Configuration data:', result);
  })
  .catch((error) => {
    console.error('Error loading configurations:', error);
  });
```

