async function runModuleTests(modulePath, testLabel, tests) {
  const results = [];
  let concurrencyLimit = 5;
  const maxTests = 100;
  const timeoutDefault = 5000;

  try {
    const module = await import(modulePath);

    for (let i = 0; i < tests.length; i++) {
      if (results.length >= maxTests) break;

      const testFunction = tests[i];
      const testName = testFunction.name;
      const startTime = new Date();
      let success = false;
      let error = null;

      try {
        await Promise.race([
          new Promise((resolve, reject) => {
            setTimeout(() => reject(new Error('Test timed out')), timeoutDefault);
          }),
          new Promise(async (resolve, reject) => {
            try {
              await testFunction(module, results);
              success = true;
              resolve();
            } catch (err) {
              error = err.message;
              reject(err);
            }
          })
        ]);
      } catch (err) {
        console.error(`Test ${testName} failed:`, err);
      } finally {
        blueslip.reset(); // Reset mocking library after each test
        const endTime = new Date();
        results.push({ testName, success, error, startTime, endTime });
        console.log(`Test ${testName} completed in ${endTime - startTime}ms`);
      }
    }
  } catch (err) {
    console.error('Failed to load module:', err);
  }

  return Promise.resolve(results);
}
