    let matches = text.match(oldTestamentRegex) || [];
    let oldTestamentCount = oldTestamentBooks.reduce((acc, book) => acc + (matches.filter(m => m.toLowerCase() === book.toLowerCase()).length), 0);

    matches = text.match(newTestamentRegex) || [];
    let newTestamentCount = newTestamentBooks.reduce((acc, book) => acc + (matches.filter(m => m.toLowerCase() === book.toLowerCase()).length), 0);

    return {
        oldTestament: oldTestamentCount,
        newTestament: newTestamentCount
    };
}
