['```javascript
function copyBufferedData(chunks, offset, length) {
    const newBuffer = Buffer.alloc(length);
    let copiedBytes = 0;
    const bytesCopiedPerChunk = [];

    for (let i = 0; i < chunks.length && copiedBytes < length; i++) {
        const chunk = chunks[i];
        const availableBytes = chunk.length - offset;

        if (availableBytes > length - copiedBytes) {
            chunk.copy(newBuffer, copiedBytes, offset, offset + length - copiedBytes);
            bytesCopiedPerChunk.push(length - copiedBytes);
            copiedBytes = length;
        } else {
            chunk.copy(newBuffer, copiedBytes, offset, availableBytes + offset);
            bytesCopiedPerChunk.push(availableBytes);
            copiedBytes += availableBytes;
            offset = 0; // Reset offset for the next chunk
        }
    }

    return { newBuffer, bytesCopiedPerChunk };
}
