const cache = new Map();

async function traverseAndFilter(data, criteria, visited = new Set()) {
  if (!data || typeof data !== 'object' || visited.has(data)) return;

  visited.add(data);

  try {
    if (Array.isArray(data)) {
      for (let item of data) {
        await traverseAndFilter(item, criteria, visited);
      }
    } else if (typeof data === 'object') {
      const shouldKeep = Object.entries(data).some(([key, value]) => {
        return typeof value === 'string' && value.includes(criteria[key]);
      });

      if (shouldKeep) {
        console.log('Filtered object:', data);
      }

      for (let key in data) {
        await traverseAndFilter(data[key], criteria, visited);
      }
    }
  } catch (error) {
    console.error('Error processing data:', error);
  }
}

async function fetchAndCache(url, criteria) {
  if (cache.has(`${url}-${JSON.stringify(criteria)}`)) {
    return cache.get(`${url}-${JSON.stringify(criteria)}`);
  }

  try {
    const response = await fetch(url);
    const data = await response.json();

    await traverseAndFilter(data, criteria);

    cache.set(`${url}-${JSON.stringify(criteria)}`, data);
    return data;
  } catch (error) {
    console.error('Error fetching data:', error);
    throw error;
  }
}

// Example usage:
const url = 'https://api.example.com/data';
const criteria = { category: 'electronics', price: 'high' };

fetchAndCache(url, criteria)
  .then(data => console.log('Final cached data:', data))
  .catch(error => console.error('Failed to fetch and cache data:', error));
