// scriptLoader.js

const scriptQueue = [];
let currentScriptIndex = 0;

function loadScript(url) {
    return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = url;
        script.onload = resolve;
        script.onerror = () => reject(new Error(`Failed to load script: ${url}`));
        document.head.appendChild(script);
    });
}

async function executeScripts() {
    if (currentScriptIndex >= scriptQueue.length) return;

    const currentScriptUrl = scriptQueue[currentScriptIndex];
    try {
        await loadScript(currentScriptUrl);
        console.log(`Successfully loaded and executed script: ${currentScriptUrl}`);
        currentScriptIndex++;
        executeScripts();
    } catch (error) {
        console.error(error.message);
        // Optionally, skip the failed script and continue with the next
        currentScriptIndex++;
        executeScripts();
    }
}

function addScript(url) {
    scriptQueue.push(url);
}

async function loadAndExecuteAllScripts() {
    if (scriptQueue.length === 0) {
        console.log('No scripts to load.');
        return;
    }
    await executeScripts();
    console.log('All scripts loaded and executed successfully.');
}

// Usage example
addScript('path/to/script1.js');
addScript('path/to/script2.js');
loadAndExecuteAllScripts();
