      if (!fallbackResponse.ok) {
        throw new Error('Fallback network response was not ok');
      }
      const fallbackResource = await fallbackResponse.blob();
      assetCache.set(url, fallbackResource);
      return fallbackResource;
    } catch (fallbackError) {
      console.error(`Failed to load fallback resource from ${fallbackUrl}:`, fallbackError);
      return null; // Return null or handle the error as needed
    }
