public class ServiceManager {

    private static final String MESSAGE_QUEUE_URL = "your_message_queue_url";
    private static final int MIN_DELAY = 1000; // 1 second
    private static final int MAX_DELAY = 5000; // 5 seconds

    public static void main(String[] args) {
        while (true) {
            try {
                startService();
                stopService();
            } catch (IOException e) {
                System.err.println("Error managing service: " + e.getMessage());
            }
        }
    }

    private static void startService() throws IOException {
        Random random = new Random();
        int delay = random.nextInt(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
        System.out.println("Starting service with a delay of " + delay + "ms");
        Thread.sleep(delay);
    }

    private static void stopService() throws IOException {
        // Simulate sending a message to the messaging system
        String message = "Service stopped at " + System.currentTimeMillis();
        sendMessageToQueue(message);
        System.out.println("Message sent: " + message);
    }

    private static void sendMessageToQueue(String message) throws IOException {
        // Code to send a message to the messaging system using MESSAGE_QUEUE_URL
        ProcessBuilder processBuilder = new ProcessBuilder(
            "your_messaging_system_command",
            "-url", MESSAGE_QUEUE_URL,
            "-message", message
        );
        processBuilder.start();
    }
}
