use hyper::{Client, Request, Body, Uri};
use hyper_tls::HttpsConnector;
use std::time::Duration;
use tokio::time::{sleep, Instant};

#[derive(Clone)]
pub struct Config {
    pub retry_max: u32,
    pub timeout: Duration,
    pub user_agent: String,
    pub whitelist: Vec<String>,
}

pub struct HttpClient {
    client: Client<HttpsConnector>,
    config: Config,
}

impl HttpClient {
    pub fn new(config: Config) -> Self {
        let https = HttpsConnector::new();
        HttpClient {
            client: Client::builder().build(https),
            config,
        }
    }

    pub async fn request<B>(&self, url: &str, method: hyper::Method, body: B) -> Result<hyper::Response<Body>, hyper::Error>
    where
        B: Into<Body>,
    {
        let uri = Uri::from_str(url)?;
        if !self.is_whitelisted(&uri.host().unwrap_or_default()) {
            return Err(hyper::Error::new(
                hyper::error::Kind::InvalidInput,
                "Domain not whitelisted",
            ));
        }

        let mut req = Request::builder()
            .method(method)
            .uri(uri)
            .header("User-Agent", &self.config.user_agent)
            .body(body.into())?;

        for (key, value) in req.headers() {
            println!("Request header: {}={}", key, value);
        }

        let mut retries = 0;
        loop {
            match self.client.request(req.clone()).await {
                Ok(response) => return Ok(response),
                Err(_) if retries < self.config.retry_max => {
                    retries += 1;
                    sleep(Duration::from_secs(2_u32.pow(retries))).await;
                }
                Err(e) => return Err(e),
            }
        }
    }

    fn is_whitelisted(&self, domain: &str) -> bool {
        self.config.whitelist.contains(domain)
    }
}
