<?php

class PasswordManager {
    private $charSet;
    private $saltingStrategy;

    public function __construct($configService) {
        $this->charSet = $configService->get('password_char_set');
        $this->saltingStrategy = $configService->get('password_salting_strategy');
    }

    public function generateSecureString($length) {
        return substr(str_shuffle(str_repeat($this->charSet, ceil($length / strlen($this->charSet)))), 1, $length);
    }

    public function hashPassword($plainTextPassword, $salt = null) {
        if ($this->saltingStrategy === 'none') {
            return password_hash($plainTextPassword . (is_null($salt) ? '' : $salt), PASSWORD_BCRYPT);
        } elseif ($this->saltingStrategy === 'random') {
            $salt = $this->generateSecureString(16);
            return password_hash($plainTextPassword . $salt, PASSWORD_BCRYPT);
        } elseif ($this->saltingStrategy === 'static') {
            $staticSalt = $configService->get('static_salt');
            return password_hash($plainTextPassword . $staticSalt, PASSWORD_BCRYPT);
        }
    }

    public function verifyPassword($hashedPassword, $plainTextPassword) {
        return password_verify($plainTextPassword, $hashedPassword);
    }
}

