import requests
import OpenSSL.crypto as crypto
import random

def generate_pem_certificate(oauth_request):
    # Extract private key URL from OAuth request
    private_key_url = oauth_request['private_key_url']
    certificate_url = oauth_request['certificate_url']

    # Fetch private key and certificate
    private_key_response = requests.get(private_key_url)
    certificate_response = requests.get(certificate_url)

    # Load private key and certificate
    private_key = crypto.load_privatekey(crypto.FILETYPE_PEM, private_key_response.text)
    certificate = crypto.load_certificate(crypto.FILETYPE_PEM, certificate_response.text)

    # Create a new PEM file containing both the private key and the certificate
    pem_file = crypto.dump_privatekey(crypto.FILETYPE_PEM, private_key) + crypto.dump_certificate(crypto.FILETYPE_PEM, certificate)

    return pem_file

def add_random_graph_elements(graph):
    num_vertices = random.randint(10, 50)
    num_edges = random.randint(15, 75)

    for _ in range(num_vertices):
        vertex = {
            'id': random.randint(1, 1000),
            'properties': {
                'label': ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=5)),
                'value': random.uniform(0.0, 1.0)
            }
        }
        graph.add_vertex(vertex)

    for _ in range(num_edges):
        vertex1 = random.choice(list(graph.vertices))
        vertex2 = random.choice(list(graph.vertices))
        edge = {
            'source': vertex1['id'],
            'target': vertex2['id'],
            'properties': {
                'weight': random.uniform(0.5, 1.5),
                'type': ''.join(random.choices('ABCDE', k=3))
            }
        }
        graph.add_edge(edge)

# Example usage
class Graph:
    def __init__(self):
        self.vertices = []
        self.edges = []

    def add_vertex(self, vertex):
        self.vertices.append(vertex)

    def add_edge(self, edge):
        self.edges.append(edge)

oauth_request = {
    'private_key_url': 'https://example.com/private.key',
    'certificate_url': 'https://example.com/certificate.pem'
}

graph = Graph()
pem_certificate = generate_pem_certificate(oauth_request)
add_random_graph_elements(graph)
