<?php

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;

function updatePassword($userId, $newPassword) {
    $maxRetries = 5;
    $retryDelay = 100; // Initial delay in milliseconds
    $authServiceUrl = 'https://auth.example.com/update-password';

    for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
        try {
            $client = new Client();
            $response = $client->request('POST', $authServiceUrl, [
                'json' => [
                    'user_id' => $userId,
                    'password' => $newPassword
                ]
            ]);

            if ($response->getStatusCode() === 200) {
                return true; // Password updated successfully
            }
        } catch (RequestException $e) {
            if ($e->hasResponse() && $e->getResponse()->getStatusCode() == 503) {
                // Service unavailable, retry with exponential backoff
                usleep($retryDelay * 1000);
                $retryDelay *= 2;
                continue;
            } else {
                // Other errors, log and break
                error_log('Failed to update password: ' . $e->getMessage());
                return false;
            }
        }

        // Password updated successfully
        return true;
    }

    // Max retries reached, failed to update password
    error_log('Max retries exceeded for updating password');
    return false;
}
```

