#include <stdio.h>
#include <stdlib.h>

#define MAX_STATES 10000

typedef struct State {
    int id;
    struct State* next;
} State;

State** findContiguousSubsequence(State** states, int start, int end, bool includeFilter) {
    if (start < 0 || end >= MAX_STATES || start > end) {
        return NULL; // Invalid range
    }

    State** newStates = (State**)malloc((end - start + 1) * sizeof(State*));
    if (!newStates) {
        return NULL; // Insufficient memory
    }

    for (int i = start; i <= end; ++i) {
        if (includeFilter && !states[i]->next) {
            continue; // Exclude states based on filter condition
        }
        newStates[i - start] = states[i];
        newStates[i - start]->next = NULL; // Ensure correct 'next' pointer handling
    }

    // Update 'next' pointers for the last states in both lists
    if (start > 0) {
        states[start - 1]->next = newStates[0];
    }
    if (end < MAX_STATES - 1) {
        newStates[end - start] = NULL; // Set the end of the list to NULL
    }

    return newStates;
}
