#include <stdio.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000000
#define ROLLING_WINDOW_SIZE 10000
#define MAX_RATE 100

typedef struct {
    time_t timestamp;
    int id;
    double value;
    double weight;
} Transaction;

Transaction transactions[MAX_TRANSACTIONS];
int transaction_count = 0;
time_t last_processed_time = 0;
double max_weighted_sum = 0.0;
int max_transaction_id = -1;

void process_transaction(Transaction new_transaction) {
    if (transaction_count >= MAX_TRANSACTIONS) {
        // Remove the oldest transaction to make space
        memmove(transactions, transactions + 1, sizeof(Transaction) * (MAX_TRANSACTIONS - 1));
        transaction_count--;
    }

    transactions[transaction_count++] = new_transaction;

    if (time(NULL) - last_processed_time >= 1) {
        // Process transactions at most once per second
        double total_weighted_sum = 0.0;
        int count_3_seconds = 0;
        for (int i = transaction_count > ROLLING_WINDOW_SIZE ? transaction_count - ROLLING_WINDOW_SIZE : 0; i < transaction_count; i++) {
            double weighted_sum = transactions[i].value * transactions[i].weight;
            if (time(NULL) - transactions[i].timestamp < 5) {
                total_weighted_sum += weighted_sum;
                count_3_seconds++;
            }
        }

        if (count_3_seconds > 0) {
            double average_weighted_sum = total_weighted_sum / count_3_seconds;

            for (int i = transaction_count > ROLLING_WINDOW_SIZE ? transaction_count - ROLLING_WINDOW_SIZE : 0; i < transaction_count; i++) {
                double weighted_sum = transactions[i].value * transactions[i].weight;
                if (weighted_sum > average_weighted_sum) {
                    // Filter and update metrics
                    if (weighted_sum > max_weighted_sum) {
                        max_weighted_sum = weighted_sum;
                        max_transaction_id = transactions[i].id;
                    }
                }
            }
        }

        last_processed_time = time(NULL);
    }
}

double* get_max_metrics(double* out_max_weighted_sum, int* out_max_transaction_id) {
    *out_max_weighted_sum = max_weighted_sum;
    *out_max_transaction_id = max_transaction_id;
    return out_max_weighted_sum;
}
