class CharacterAttack {
private:
    std::mt19937 generator;
    std::uniform_int_distribution<int> distribution;
    std::mutex cooldownMutex;
    bool isCoolingDown;

public:
    CharacterAttack() : generator(std::random_device{}()), distribution(0, 1), isCoolingDown(false) {}

    void selectAttack() {
        if (isCoolingDown) {
            return; // Attack already on cooldown
        }

        std::lock_guard<std::mutex> lock(cooldownMutex);
        if (isCoolingDown) {
            return; // Double-check under lock
        }

        int attack = distribution(generator); // Randomly select an attack

        // Simulate cooldown check with external API (simulated delay)
        try {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            if (!checkCooldownFromAPI()) {
                return; // Cooldown not available
            }
        } catch (...) {
            std::cerr << "Failed to communicate with the cooldown API." << std::endl;
            return; // Handle communication failure
        }

        // Simulate attack and start cooldown
        performAttack(attack);
        isCoolingDown = true;

        // Start a thread to handle cooldown timer
        std::thread([this]() {
            std::this_thread::sleep_for(std::chrono::seconds(9));
            std::lock_guard<std::mutex> lock(cooldownMutex);
            isCoolingDown = false;
        }).detach();
    }

private:
    bool checkCooldownFromAPI() {
        // Simulate external API call
        std::this_thread::sleep_for(std::chrono::seconds(1));
        return true; // Simulated success
    }

    void performAttack(int attack) {
        std::cout << "Attacking with Attack " << (attack + 1) << std::endl;
    }
};

int main() {
    CharacterAttack character;
    for (int i = 0; i < 20; ++i) {
        character.selectAttack();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
    return 0;
}
