using System;
using System.Linq;

public class RandomValueGenerator
{
    private int? intMin = null;
    private int? intMax = null;
    private float? floatMin = null;
    private float? floatMax = null;

    public void SetIntRange(int min, int max)
    {
        if (min <= max)
        {
            intMin = min;
            intMax = max;
        }
        else
        {
            Console.WriteLine("Invalid range for integers. Using default range.");
            ResetIntRange();
        }
    }

    public void SetFloatRange(float min, float max)
    {
        if (min <= max)
        {
            floatMin = min;
            floatMax = max;
        }
        else
        {
            Console.WriteLine("Invalid range for floats. Using default range.");
            ResetFloatRange();
        }
    }

    public int GenerateRandomInt(bool includeMax = true)
    {
        if (!intMin.HasValue || !intMax.HasValue) return 0;

        int min = intMin.Value;
        int max = intMax.Value + (includeMax ? 1 : 0);
        Random rand = new Random();
        return rand.Next(min, max);
    }

    public float GenerateRandomFloat(Distribution distribution = Distribution.Uniform)
    {
        if (!floatMin.HasValue || !floatMax.HasValue) return 0;

        float min = floatMin.Value;
        float max = floatMax.Value;
        Random rand = new Random();
        switch (distribution)
        {
            case Distribution.Uniform:
                return (float)(rand.NextDouble() * (max - min)) + min;
            case Distribution.Normal:
                float mean = (min + max) / 2f;
                float stdev = Math.Abs(max - min) / 4f;
                return (float)rand.NextGaussian(mean, stdev);
            default:
                throw new ArgumentException("Unsupported distribution type.");
        }
    }

    private void ResetIntRange()
    {
        intMin = null;
        intMax = null;
    }

    private void ResetFloatRange()
    {
        floatMin = null;
        floatMax = null;
    }

    public override string ToString()
    {
        return $"Integer Range: {intMin ?? "N/A"} to {intMax ?? "N/A"}, Float Range: {floatMin ?? "N/A"} to {floatMax ?? "N/A "}";
    }
}

public enum Distribution
{
    Uniform,
    Normal
}
