["```javascript
const asyncReduce = (array, initialValue, callback, isAsync = true) => {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    const processNext = () => {
      if (array.length === 0) {
        resolve(accumulator);
        return;
      }
      const nextItem = array.shift();
      if (isAsync && callback.constructor.name === 'AsyncFunction') {
        callback(nextItem, accumulator)
          .then(newAccumulator => {
            accumulator = newAccumulator;
            processNext();
          })
          .catch(reject);
      } else {
        try {
          const newAccumulator = callback(nextItem, accumulator);
          if (newAccumulator instanceof Promise) {
            newAccumulator.then(resolvedValue => {
              accumulator = resolvedValue;
              processNext();
            }).catch(reject);
          } else {
            accumulator = newAccumulator;
            processNext();
          }
        } catch (error) {
          reject(error);
        }
      }
    };
    processNext();
  });
};

// Example usage:
async function exampleCallback(item, acc) {
  return new Promise(resolve => setTimeout(() => resolve(acc + item), 100));
}

(async () => {
  try {
    const result = await asyncReduce([1, 2, 3, 4], 0, exampleCallback);
    console.log(result); // Output: 10
  } catch (error) {
    console.error(error);
  }
})();
