#include <stdio.h>
#include <stdlib.h>

#define MAGIC_NUMBER 0xDEADBEEF
#define VERSION 1

typedef struct {
    char type;
    size_t size;
    void* data;
} ResourceItem;

typedef struct {
    int itemCount;
    ResourceItem* items;
} ResourceBundle;

enum ErrorCode {
    EC_SUCCESS,
    EC_FILE_NOT_FOUND,
    EC_PERMISSION_DENIED,
    EC_OUT_OF_MEMORY,
    EC_INVALID_FORMAT,
    EC_CORRUPTED_DATA
};

ResourceBundle* loadResourceBundle(const char* filePath, enum ErrorCode* errorCode) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        *errorCode = EC_FILE_NOT_FOUND;
        return NULL;
    }

    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fclose(file);
        *errorCode = EC_OUT_OF_MEMORY;
        return NULL;
    }
    bundle->itemCount = 0;
    bundle->items = NULL;

    uint32_t magicNumber, version, itemCount;
    fread(&magicNumber, sizeof(uint32_t), 1, file);
    fread(&version, sizeof(uint32_t), 1, file);
    fread(&itemCount, sizeof(uint32_t), 1, file);

    if (magicNumber != MAGIC_NUMBER || version != VERSION) {
        fclose(file);
        free(bundle);
        *errorCode = EC_INVALID_FORMAT;
        return NULL;
    }

    bundle->items = (ResourceItem*)malloc(itemCount * sizeof(ResourceItem));
    if (!bundle->items) {
        fclose(file);
        free(bundle);
        *errorCode = EC_OUT_OF_MEMORY;
        return NULL;
    }
    bundle->itemCount = itemCount;

    for (int i = 0; i < itemCount; ++i) {
        fread(&bundle->items[i].type, sizeof(char), 1, file);
        fread(&bundle->items[i].size, sizeof(size_t), 1, file);

        bundle->items[i].data = malloc(bundle->items[i].size);
        if (!bundle->items[i].data) {
            for (int j = 0; j < i; ++j) {
                free(bundle->items[j].data);
            }
            fclose(file);
            free(bundle->items);
            free(bundle);
            *errorCode = EC_OUT_OF_MEMORY;
            return NULL;
        }

        fread(bundle->items[i].data, bundle->items[i].size, 1, file);
    }

    fclose(file);
    *errorCode = EC_SUCCESS;
    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->itemCount; ++i) {
        free(bundle->items[i].data);
    }
    free(bundle->items);
    free(bundle);
}
