void log_operation(const char* str, size_t limit, const char* result) {
    printf("String: '%s', Limit: %zu, Result: %s\n", str, limit, result);
}

char* append_separator(const char* input, size_t size_limit, int add_separator, pthread_mutex_t* lock) {
    if (input == NULL || size_limit <= 0) {
        log_operation(NULL, size_limit, "Invalid input");
        return NULL;
    }

    pthread_mutex_lock(lock);

    size_t len = strlen(input);
    char* new_str = realloc(NULL, (len + 2) * sizeof(char));
    if (new_str == NULL) {
        pthread_mutex_unlock(lock);
        log_operation(input, size_limit, "Memory allocation failed");
        return NULL;
    }

    memory_stats.reallocations++;

    strcpy(new_str, input);

    if (add_separator && len <= size_limit) {
        new_str[len] = '/';
        new_str[len + 1] = '\0';
    } else {
        new_str[len] = '\0';
    }

    log_operation(input, size_limit, "Operation successful");
    pthread_mutex_unlock(lock);
    return new_str;
}

int main() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    char* result = append_separator("example", 10, 1, &lock);
    if (result != NULL) {
        printf("Result: '%s'\n", result);
        free(result);
    }

    return 0;
}
