void process_line(const char *line, FILE *output_file) {
    int count = 0;
    double sum = 0.0;
    char *token = strtok((char *)line, " ");
    while (token != NULL && count < 3) {
        if (sscanf(token, "%lf", &sum[count % 3]) == 1) {
            count++;
        }
        token = strtok(NULL, " ");
    }

    json_object *root = json_object_new_array();
    if (count > 0) {
        for (int i = count - 1; i >= 0 && i >= count - 3; i--) {
            json_object_array_add(root, json_object_new_double(sum[i]));
        }
    } else {
        json_object_array_add(root, json_object_new_int(-1));
    }

    char *json_str = json_object_to_json_string_ext(root, JSON_C_TO_STRING_PRETTY);
    fprintf(output_file, "%s\n", json_str);
    free(json_str);
    json_object_put(root);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s input.txt output.json\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    FILE *output_file = fopen(argv[2], "w");
    if (!output_file) {
        perror("Error opening output file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, input_file)) != -1) {
        process_line(line, output_file);
    }

    free(line);
    fclose(input_file);
    fclose(output_file);

    return EXIT_SUCCESS;
}
