void modifyFilename(char *newFilename, const char *filename, size_t maxLength) {
    int digitsCount = 3;
    char fileType[] = ".log";
    unsigned int checksum = calculateChecksum(filename, strlen(filename));

    snprintf(newFilename, maxLength, "%.*s%d%s%02d", 
             (int)(maxLength - sizeof(fileType) - 4), filename, digitsCount, fileType, checksum);
}

int main() {
    char originalFilename[] = "example_file.txt";
    char newFilename[100];

    modifyFilename(newFilename, originalFilename, sizeof(newFilename));

    printf("Original: %s\n", originalFilename);
    printf("Modified: %s\n", newFilename);

