typedef struct {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char salt[32];
} CipherContext;

CipherContext* init_cipher(const char* password, size_t password_len) {
    static CipherContext ctx;
    static int is_initialized = 0;

    if (is_initialized) {
        return &ctx;
    }

    if (!RAND_bytes(ctx.salt, sizeof(ctx.salt))) {
        return NULL; // Failed to generate salt
    }

    if (PKCS5_PBKDF2_HMAC(password, password_len, ctx.salt, sizeof(ctx.salt), 20000, EVP_sha256(), AES_256_KEY_SIZE, ctx.key.enc_key)) {
        is_initialized = 1;
    } else {
        return NULL; // Failed to derive key
    }

    // Initialize IV
    if (!RAND_bytes(ctx.iv, sizeof(ctx.iv))) {
        return NULL; // Failed to generate IV
    }

    return &ctx;
}

void cleanup_cipher(CipherContext* ctx) {
    if (ctx) {
        memset(ctx, 0, sizeof(*ctx));
    }
}
