// Define the conversion function prototype (assume this is provided by a third-party library)
int convert_image(const char *input_path, const char *output_path);

typedef struct {
    const char *directory;
    const char *base_name;
    const char *target_format;
} ConversionTask;

void* worker_thread(void *arg) {
    ConversionTask *task = (ConversionTask *) arg;
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(task->directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, task->base_name, strlen(task->base_name)) == 0 &&
                strstr(entry->d_name, ".") != NULL) {

                char input_path[256];
                snprintf(input_path, sizeof(input_path), "%s/%s", task->directory, entry->d_name);

                char output_path[256];
                char *ext = strrchr(entry->d_name, '.');
                if (ext != NULL) {
                    *ext = '\0';
                }
                snprintf(output_path, sizeof(output_path), "%s.%s", input_path, task->target_format);

                int result = convert_image(input_path, output_path);
                if (result != 0) {
                    fprintf(stderr, "Failed to convert %s\n", input_path);
                    return (void *) 1;
                }
            }
        }
        closedir(dir);
    } else {
        perror("opendir");
        return (void *) 1;
    }

    return (void *) 0;
}

int batch_convert_images(const char *directory, const char *base_name, const char *target_format) {
    pthread_t threads[16]; // Assuming up to 16 concurrent conversions
    int thread_count = 0;

    ConversionTask tasks[16];

    for (int i = 0; i < 16 && thread_count < 16; i++) {
        tasks[i].directory = directory;
        tasks[i].base_name = base_name;
        tasks[i].target_format = target_format;

        if (pthread_create(&threads[i], NULL, worker_thread, &tasks[i]) != 0) {
            perror("pthread_create");
            return 1;
        }
        thread_count++;
    }

    for (int i = 0; i < thread_count; i++) {
        int result;
        if (pthread_join(threads[i], (void **) &result) != 0) {
            perror("pthread_join");
            return 1;
        }

        if (result != 0) {
            return 1;
        }
    }

    return 0;
}
