using Microsoft.Web.Administration;

public class WebsiteManager
{
    public async Task<object> AddAndStartWebsite(string directoryPath, string siteName)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
                return Task.FromResult<object>("Directory does not exist.");

            string webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
                return Task.FromResult<object>("Missing web.config file.");

            using (var serverManager = new ServerManager())
            {
                var sites = serverManager.Sites;
                foreach (Site site in sites)
                {
                    if (site.Name.Equals(siteName, StringComparison.OrdinalIgnoreCase))
                        return $"Site '{siteName}' already exists.";
                }

                Site newSite = serverManager.Sites.Add(
                    name: siteName,
                    physicalPath: directoryPath,
                    id: sites.Count + 1);

                if (!newSite.Bindings.Any(b => b.Protocol == "http" && b.BindingInformation.Contains(":80")))
                {
                    Binding binding = new Binding
                    {
                        Protocol = "http",
                        BindingInformation = "*:80:" + siteName,
                        HostName = siteName
                    };
                    newSite.Bindings.Add(binding);
                }

                serverManager.CommitChanges();
                return Task.FromResult<object>("Site added and started successfully.");
            }
        }
        catch (Exception ex)
        {
            // Log the exception to a centralized logging service
            LogException(ex);
            return Task.FromResult<object>(ex.Message);
        }
    }

    private void LogException(Exception ex)
    {
        // Implement your centralized logging logic here
        Console.WriteLine($"Error: {ex.Message}");
    }
}
