import java.io.*;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.util.concurrent.*;

public class CommandExecutor {

    private static final int MAX_RETRIES = 3;
    private static final long DEFAULT_TIMEOUT = 60L; // seconds

    public static void main(String[] args) {
        List<String> commands = Arrays.asList(
            "ls -la",
            "echo Hello World",
            "rm -rf /path/to/unsafe/directory"
        );

        for (String command : commands) {
            executeCommand(command, Path.of("/tmp"), 10L); // Adjust timeout based on data size
        }
    }

    public static void executeCommand(String command, Path workingDir, long dataSizeInMB) {
        int retries = MAX_RETRIES;
        while (retries > 0) {
            try {
                File fileToDelete = new File("temp.txt");
                if (fileToDelete.exists()) {
                    Files.delete(fileToDelete.toPath());
                }

                ProcessBuilder pb = new ProcessBuilder("bash", "-c", command);
                pb.directory(workingDir.toFile());

                long adjustedTimeout = calculateTimeout(dataSizeInMB);
                Process process = pb.start();

                CompletableFuture.runAsync(() -> readOutput(process.getInputStream()));
                CompletableFuture.runAsync(() -> readOutput(process.getErrorStream()));

                if (process.waitFor(adjustedTimeout, TimeUnit.SECONDS)) {
                    System.out.println("Command executed successfully: " + command);
                } else {
                    throw new TimeoutException();
                }

                break;
            } catch (IOException | InterruptedException | TimeoutException e) {
                retries--;
                if (retries > 0) {
                    System.err.println("Command failed, retrying: " + e.getMessage());
                }
            }
        }

        if (retries == 0) {
            System.err.println("Failed to execute command after multiple attempts: " + command);
        }
    }

    private static void readOutput(InputStream inputStream) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                log(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static long calculateTimeout(long dataSizeInMB) {
        // Simple linear scaling, adjust as needed
        return DEFAULT_TIMEOUT + dataSizeInMB / 10;
    }

    private static void log(String message) {
        LocalDateTime now = LocalDateTime.now();
        System.out.println(now + " - " + message);
        // Integrate with external logging service here
    }
}
