    NetworkSettings *networkSettings;
    CallbackMechanism *callback;
} ConfigStructure;

int validateConfig(ConfigStructure *config) {
    if (config->userProfile == NULL || config->networkSettings == NULL || config->callback == NULL) {
        return ERR_CALLBACK_NOT_INITIALIZED; // Simplified check for callback initialization
    }

    if (!strstr(config->userProfile->email, "@") || !strchr(config->userProfile->email, '.')) {
        return ERR_INVALID_EMAIL;
    }

    if (strlen(config->userProfile->password) == 0) {
        return ERR_EMPTY_PASSWORD;
    }

    if (config->networkSettings->host == NULL || strlen(config->networkSettings->host) == 0) {
        return ERR_INVALID_HOST;
    }

    if (config->networkSettings->port == 0) {
        return ERR_ZERO_PORT;
    }

    // Placeholder for callback validation
    if (config->callback->onConnect == NULL) {
        return ERR_CALLBACK_NOT_INITIALIZED; // Simplified check for callback initialization
    }

    return ERR_SUCCESS;
}

// Example usage
int main() {
    ConfigStructure config = {0};
    config.userProfile = (UserProfile *)malloc(sizeof(UserProfile));
    config.networkSettings = (NetworkSettings *)malloc(sizeof(NetworkSettings));
    config.callback = (CallbackMechanism *)malloc(sizeof(CallbackMechanism));

    // Initialize config members here

    int result = validateConfig(&config);
    if (result != ERR_SUCCESS) {
        printf("Validation failed with error code: %d\n", result);
    } else {
        printf("Configuration is valid.\n");
    }

    free(config.userProfile);
    free(config.networkSettings);
    free(config.callback);

    return 0;
}
