using System;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Threading;

public class ImageUploader
{
    public IAsyncResult BeginUpload(byte[] imageData, AsyncCallback callback, object state)
    {
        // Create a temporary file to store the compressed image data
        string tempFilePath = Path.GetTempFileName();

        using (FileStream fs = new FileStream(tempFilePath, FileMode.Create))
        using (DeflateStream zipStream = new DeflateStream(fs, CompressionLevel.Optimal))
        {
            // Write the compressed image data to the temporary file
            zipStream.Write(imageData, 0, imageData.Length);
        }

        // Use BeginUploadToStorage method to upload the compressed file asynchronously
        return BeginUploadToStorage(tempFilePath, callback, state);
    }

    private IAsyncResult BeginUploadToStorage(string filePath, AsyncCallback callback, object state)
    {
        HttpWebRequest request = (HttpWebRequest)WebRequest.Create("http://example.com/upload");
        request.Method = "POST";
        request.ContentType = "application/octet-stream";

        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = fs.Read(buffer, 0, buffer.Length)) > 0)
            {
                request.GetRequestStream().Write(buffer, 0, bytesRead);
            }
        }

        IAsyncResult result = request.BeginGetResponse(callback, state);

        return result;
    }

    public void EndUpload(IAsyncResult asyncResult)
    {
        HttpWebRequest request = (HttpWebRequest)((IAsyncResult)asyncResult).AsyncState;
        HttpWebResponse response = (HttpWebResponse)request.EndGetResponse(asyncResult);

        // Handle the response from the server
        Console.WriteLine("Upload completed with status: " + response.StatusCode);
    }
}
