using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class StringHashProcessor
{
    private readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();
    private readonly ILogger _logger;

    public StringHashProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<string> GetMd5HashAsync(string input)
    {
        if (_hashCache.TryGetValue(input, out var cachedHash))
        {
            return cachedHash;
        }

        try
        {
            var hash = await ComputeMd5HashAsync(input);
            _hashCache.TryAdd(input, hash);
            return hash;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to compute MD5 hash for input: {Input}", input);
            throw;
        }
    }

    private async Task<string> ComputeMd5HashAsync(string input)
    {
        using var md5 = MD5.Create();
        var inputBytes = Encoding.UTF8.GetBytes(input);
        var hashBytes = await Task.Run(() => md5.ComputeHash(inputBytes));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message, params object[] args);
}
