using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;

public class AesCbcDecryptor
{
    private static readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>(10000);

    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode padding)
    {
        if (key.Length != 16 && key.Length != 32)
            throw new ArgumentException("Invalid key size. Must be 16 or 32 bytes.");

        if (iv.Length != 16)
            throw new ArgumentException("IV length must be 16 bytes.");

        string cacheKey = $"{Convert.ToBase64String(key)}_{Convert.ToBase64String(iv)}";

        if (_cache.TryGetValue(cacheKey, out var cachedValue))
            return cachedValue;

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Padding = padding;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                byte[] decryptedData = new byte[ciphertext.Length];
                int bytesRead = csDecrypt.Read(decryptedData, 0, decryptedData.Length);

                if (_cache.Count < 10000)
                    _cache.TryAdd(cacheKey, decryptedData);

                return decryptedData.Take(bytesRead).ToArray();
            }
        }
    }
}
