using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;
using System.IO.MemoryMappedFiles;

public class DatasetLoader
{
    public static T Load<T>(string filePath) where T : new()
    {
        try
        {
            using (var fileStream = File.Open(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            using (var decompressionStream = new DecompressionStream(fileStream))
            using (var memoryMappedFile = MemoryMappedFile.CreateFromFile(decompressionStream, null, 0, MemoryMappedFileAccess.Read, HandleInheritability.None, false))
            using (var memoryMappedViewAccessor = memoryMappedFile.CreateViewAccessor(0, 0, AccessMode.ReadOnly))
            {
                var formatter = new BinaryFormatter();
                memoryMappedViewAccessor.SafeMemoryMappedViewHandle.AcquirePointer(out IntPtr pointer);
                try
                {
                    return (T)formatter.Deserialize(new MemoryStream((byte[])Marshal.PtrToStructure(pointer, typeof(byte[]))));
                }
                finally
                {
                    memoryMappedViewAccessor.SafeMemoryMappedViewHandle.ReleasePointer();
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading dataset: {ex.Message}");
            return default(T);
        }
    }
}
