### JavaScript Program for Dynamic Loading and Execution of JS Files

```javascript
function loadAndExecuteScript(url, onComplete) {
    const script = document.createElement('script');
    script.src = url;

    script.onload = function() {
        if (onComplete) {
            onComplete();
        }
    };

    script.onerror = function() {
        console.error(`Failed to load and execute script from ${url}`);
    };

    document.head.appendChild(script);
}

function loadScriptsSequentially(urls, onComplete) {
    let index = 0;

    function loadNextScript() {
        if (index < urls.length) {
            loadAndExecuteScript(urls[index], () => {
                index++;
                loadNextScript();
            });
        } else if (onComplete) {
            onComplete();
        }
    }

    loadNextScript();
}

// Example usage:
const scriptUrls = [
    'https://example.com/script1.js',
    'https://example.com/script2.js'
];

loadScriptsSequentially(scriptUrls, () => {
    console.log('All scripts have been loaded and executed');
});
```

This JavaScript program dynamically loads each JavaScript file specified in the `scriptUrls` array. It ensures that each script is loaded and executed before moving on to the next one, using a callback mechanism to handle the sequence. Error handling is included to log any issues encountered during the loading or execution of scripts.']

