const Bluebird = require('bluebird');
const fs = Bluebird.promisifyAll(require('fs'));
const path = require('path');

class RandomValueGenerator {
  #minInt;
  #maxInt;
  #minFloat;
  #maxFloat;

  constructor(minInt = 0, maxInt = 100, minFloat = 0.0, maxFloat = 1.0) {
    this.#setRange(minInt, maxInt, minFloat, maxFloat);
  }

  #setRange(minInt, maxInt, minFloat, maxFloat) {
    if (minInt < maxInt && minFloat < maxFloat) {
      this.#minInt = minInt;
      this.#maxInt = maxInt;
      this.#minFloat = minFloat;
      this.#maxFloat = maxFloat;
    } else {
      console.error('Invalid range settings. Using default values.');
      this.#minInt = 0;
      this.#maxInt = 100;
      this.#minFloat = 0.0;
      this.#maxFloat = 1.0;
    }
  }

  async generateRandomInteger(inclusive = true) {
    const range = inclusive ? (this.#maxInt - this.#minInt + 1) : (this.#maxInt - this.#minInt);
    return Math.floor(Math.random() * range) + this.#minInt;
  }

  async generateRandomFloat(exclusive = true, distribution = 'uniform') {
    if (distribution === 'normal') {
      const mean = (this.#maxFloat + this.#minFloat) / 2;
      const stdDev = (this.#maxFloat - this.#minFloat) / 4;
      let result;
      do {
        result = mean + stdDev * Math.random() * 2 - stdDev;
      } while (result < this.#minFloat || result > this.#maxFloat);
      return result;
    } else {
      const range = exclusive ? (this.#maxFloat - this.#minFloat) : (this.#maxFloat - this.#minFloat + 1);
      return Math.random() * range + this.#minFloat;
    }
  }

  async uploadFile(url) {
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to fetch file');
      const blob = await response.blob();
      const filePath = path.join(__dirname, 'uploads', `file_${Date.now()}.tmp`);
      await fs.writeFileAsync(filePath, Buffer.from(await blob.arrayBuffer()));
      return filePath;
    } catch (error) {
      console.error('Error uploading file:', error);
      throw error;
    }
  }

  toString() {
    return `Int Range: ${this.#minInt} to ${this.#maxInt}, Float Range: ${this.#minFloat} to ${this.#maxFloat}`;
  }
}

module.exports = RandomValueGenerator;
