const { exec } = require('child_process');
const sanitizeHtml = require('sanitize-html');

function executeShellCommand(command, callback) {
  exec(command, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command: ${error.message}`);
      return callback(sanitizeHtml(error.message), true);
    }
    if (stderr) {
      console.error(`Command stderr: ${sanitizeHtml(stderr)}`);
      return callback(sanitizeHtml(stderr), true);
    }
    const sanitizedOutput = sanitizeHtml(stdout, {
      allowedTags: [],
      allowedAttributes: {}
    });
    callback(sanitizedOutput, false);
  });
}
