import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ConcurrentGraphDatabase {
    private ConcurrentHashMap<String, Vertex> vertices = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, Edge> edges = new ConcurrentHashMap<>();
    private ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public void addVertex(String vertexId) {
        try (WriteLock writeLock = lock.writeLock()) {
            vertices.put(vertexId, new Vertex(vertexId));
        }
    }

    public void addEdge(String edgeId, String fromVertexId, String toVertexId, int weight) {
        try (WriteLock writeLock = lock.writeLock()) {
            if (!vertices.containsKey(fromVertexId) || !vertices.containsKey(toVertexId)) {
                throw new IllegalArgumentException("Vertices not found");
            }
            edges.put(edgeId, new Edge(edgeId, vertices.get(fromVertexId), vertices.get(toVertexId), weight));
        }
    }

    public void batchAddVertices(Vertex[] vertices) {
        try (WriteLock writeLock = lock.writeLock()) {
            for (Vertex vertex : vertices) {
                this.vertices.put(vertex.getId(), vertex);
            }
        }
    }

    public void batchAddEdges(Edge[] edges) {
        try (WriteLock writeLock = lock.writeLock()) {
            for (Edge edge : edges) {
                if (!this.vertices.containsKey(edge.getFromVertex().getId()) || !this.vertices.containsKey(edge.getToVertex().getId())) {
                    throw new IllegalArgumentException("Vertices not found");
                }
                this.edges.put(edge.getId(), edge);
            }
        }
    }

    private static class Vertex {
        private String id;

        public Vertex(String id) {
            this.id = id;
        }

        public String getId() {
            return id;
        }
    }

    private static class Edge {
        private String id;
        private Vertex fromVertex;
        private Vertex toVertex;
        private int weight;

        public Edge(String id, Vertex fromVertex, Vertex toVertex, int weight) {
            this.id = id;
            this.fromVertex = fromVertex;
            this.toVertex = toVertex;
            this.weight = weight;
        }

        public String getId() {
            return id;
        }

        public Vertex getFromVertex() {
            return fromVertex;
        }

        public Vertex getToVertex() {
            return toVertex;
        }

        public int getWeight() {
            return weight;
        }
    }
}
