use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;

fn manage_config_directory(service: &str) {
    let env_var_name = format!("{}_CONFIG_DIR", service.to_uppercase());
    if let Ok(env_var_path) = env::var(&env_var_name) {
        log::info!("Using existing configuration directory for {} at {:?}", service, Path::new(&env_var_path));
        return;
    }

    let base_dir = "/etc/myapp"; // Assuming a base directory
    let config_dir = format!("{}/{}", base_dir, service);
    let dir_builder = DirBuilder::new().recursive(true);

    if dir_builder.create(&config_dir).is_err() {
        log::error!("Failed to create configuration directory for {}", service);
        return;
    }

    env::set_var(&env_var_name, config_dir.clone());
    log::info!("Created new configuration directory for {} at {:?}", service, Path::new(&config_dir));
}

fn main() {
    // Example usage
    manage_config_directory("database");
    manage_config_directory("cache");
}
```

