import json
from abc import ABC, abstractmethod
from threading import Lock

class JsonModel(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str) -> 'JsonModel':
        pass

class JsonModelRegistry:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register_factory(cls, identifier: str, factory_func):
        with cls._lock:
            if identifier in cls._registry:
                raise ValueError(f"Factory for identifier '{identifier}' already exists.")
            cls._registry[identifier] = factory_func

    @classmethod
    def get_instance(cls, identifier: str, json_str: str) -> JsonModel:
        with cls._lock:
            if identifier not in cls._registry:
                raise ValueError(f"No factory found for identifier '{identifier}'.")
            factory_func = cls._registry[identifier]
            return factory_func(json_str)

class ConcreteJsonModel(JsonModel):
    def __init__(self, data):
        self.data = data

    def to_json(self) -> str:
        try:
            return json.dumps(self.data)
        except TypeError as e:
            raise ValueError("Invalid data for JSON serialization.") from e

    @classmethod
    def from_json(cls, json_str: str) -> 'ConcreteJsonModel':
        try:
            data = json.loads(json_str)
            return cls(data)
        except (json.JSONDecodeError, TypeError) as e:
            raise ValueError("Invalid JSON input.") from e

# Example usage:
def create_concrete_model(json_str):
    return ConcreteJsonModel.from_json(json_str)

JsonModelRegistry.register_factory('concrete', create_concrete_model)

model = JsonModelRegistry.get_instance('concrete', '{"key": "value"}')
print(model.to_json())  # Output: {"key": "value"}
```']

