void load_config() {
    pthread_mutex_lock(&config_mutex);
    if (config != NULL) {
        free(config);
    }
    config = (CryptoConfig *)malloc(sizeof(CryptoConfig));
    memset(config, 0, sizeof(CryptoConfig));

    FILE *file = fopen(CONFIG_FILE_PATH, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
