    unsigned char *file_content;
    size_t file_size;

    FILE *file = fopen(CONFIG_FILE_PATH, "rb");
    if (file == NULL) {
        perror("Failed to open configuration file for integrity check");
        return;
    }

    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    file_content = (unsigned char *)malloc(file_size + 1);
    fread(file_content, 1, file_size, file);
    fclose(file);
    file_content[file_size] = '\0';

    unsigned char hmac_key[] = HMAC_KEY;
    HMAC(EVP_sha256(), hmac_key, strlen((char *)hmac_key), (unsigned char *)file_content, file_size, hmac, NULL);

    // Compare the computed HMAC with the stored one in the config
    // This is a simplified example; in production, use secure comparison functions.
    if (memcmp(config->computed_hmac, hmac, SHA256_DIGEST_LENGTH) != 0) {
        fprintf(stderr, "Configuration file integrity check failed\n");
    }

    free(file_content);
}

void *config_loader_thread(void *arg) {
    while (1) {
        load_config();
        verify_config_integrity();
        sleep(3600); // Check every hour
    }
    return NULL;
}

