import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.json.JSONObject;

public class CryptoUtils {

    public static String processAndHash(String... inputStrings) {
        StringBuilder sb = new StringBuilder();
        for (String str : inputStrings) {
            if (str != null && str.length() <= 1024) {
                sb.append(str);
            }
        }
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(sb.toString().getBytes());
            if ("hex".equalsIgnoreCase(outputFormat)) {
                return bytesToHex(hashBytes);
            } else if ("base64".equalsIgnoreCase(outputFormat)) {
                return Base64.getEncoder().encodeToString(hashBytes);
            }
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
        return null;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static Cipher getCipher(String algorithm, String mode) throws Exception {
        switch (algorithm + "-" + mode.toUpperCase()) {
            case "DES-ECB":
                return Cipher.getInstance("DES/ECB/PKCS5Padding");
            case "DES-EDE":
                return Cipher.getInstance("DESede/ECB/PKCS5Padding");
            case "DES-EDE3":
                return Cipher.getInstance("DESede/ECB/PKCS5Padding");
            case "AES-GCM-128":
                return Cipher.getInstance("AES/GCM/NoPadding");
            case "AES-GCM-192":
                return Cipher.getInstance("AES/GCM/NoPadding");
            case "AES-GCM-256":
                return Cipher.getInstance("AES/GCM/NoPadding");
            default:
                throw new IllegalArgumentException("Unsupported algorithm or mode");
        }
    }

    public static boolean validateAccessToken(String tokenResponse, boolean requireRefreshToken) {
        try {
            JSONObject json = new JSONObject(tokenResponse);
            if (!"Bearer".equals(json.getString("token_type"))) {
                return false;
            }
            int expiresIn = Integer.parseInt(json.getString("expires_in"));
            if (expiresIn <= 0) {
                return false;
            }
            if (requireRefreshToken && !json.has("refresh_token")) {
                return false;
            }
            return true;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    // Additional methods for handling command line options, cryptographic operations,
    // and concurrency can be added here.
}
