EVP_CIPHER_CTX* modify_filename_and_encrypt(const char* filename, const char* option) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Extract number of digits and determine file type
    int num_digits = 0;
    for (int i = 0; filename[i]; i++) {
        if (filename[i] >= '0' && filename[i] <= '9') num_digits++;
        else if (filename[i] == '.') break;
    }

    // Modify filename extension based on number of digits
    char modified_filename[256];
    sprintf(modified_filename, "%s_%d", filename, num_digits);
    strcat(modified_filename, ".enc");

    // Perform operation based on command line option
    if (strcmp(option, "-encrypt") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    } else if (strcmp(option, "-decrypt") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
    }

    return ctx;
}
