import hashlib
import os

def compute_md5(file_path):
    try:
        hash_object = hashlib.md5()
        with open(file_path, 'rb') as file:
            while chunk := file.read(4096):  # Read the file in 4KB chunks
                hash_object.update(chunk)
        return hash_object.hexdigest()
    except FileNotFoundError:
        print(f"Error: The file '{file_path}' does not exist.")
        return None
    except PermissionError:
        print(f"Error: Permission denied to access the file '{file_path}'.")
        return None
    except IOError as e:
        print(f"Error: An I/O error occurred while reading the file '{file_path}': {e}")
        return None

# Example usage
file_hash = compute_md5('path_to_large_file.txt')
if file_hash:
    print(f"MD5 hash of the file: {file_hash}")
