    size_t size;
} Item;

typedef struct {
    Item *items;
    size_t count;
} ResourceBundle;

enum ErrorCodes {
    ERROR_FILE_NOT_FOUND,
    ERROR_PERMISSION_DENIED,
    ERROR_INVALID_FORMAT,
    ERROR_CORRUPTED_FILE,
    ERROR_INVALID_DATA
};

ResourceBundle* load_resource_bundle(const char *file_path, enum ErrorCodes *error_code) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        *error_code = ERROR_FILE_NOT_FOUND;
        return NULL;
    }

    // Read and validate file header and version
    // ...

    ResourceBundle *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->count = 0;
    bundle->items = NULL;

    // Process items from the file
    // ...

    fclose(file);
    return bundle;
}

void print_resource_bundle(const ResourceBundle *bundle) {
    printf("Number of Items: %zu\n", bundle->count);
    for (size_t i = 0; i < bundle->count; ++i) {
        printf("Item %zu - Size: %zu\n", i, bundle->items[i].size);
    }
}

void free_resource_bundle(ResourceBundle *bundle) {
    if (bundle) {
        for (size_t i = 0; i < bundle->count; ++i) {
            free(bundle->items[i].data);
        }
        free(bundle->items);
        free(bundle);
    }
}

int main() {
    const char *file_path = "path/to/resource_file.bin";
    enum ErrorCodes error_code;

    ResourceBundle *bundle = load_resource_bundle(file_path, &error_code);
    if (bundle) {
        print_resource_bundle(bundle);
        free_resource_bundle(bundle);
    } else {
        switch (error_code) {
            case ERROR_FILE_NOT_FOUND:
                printf("Error: File not found.\n");
                break;
            case ERROR_PERMISSION_DENIED:
                printf("Error: Permission denied.\n");
                break;
            case ERROR_INVALID_FORMAT:
                printf("Error: Invalid file format.\n");
                break;
            case ERROR_CORRUPTED_FILE:
                printf("Error: Corrupted file.\n");
                break;
            case ERROR_INVALID_DATA:
                printf("Error: Invalid data in file.\n");
                break;
            default:
                printf("An unexpected error occurred.\n");
        }
    }

    return 0;
}
