#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000000
#define ROLLING_WINDOW_SIZE 10000
#define THROTTLE_LIMIT 100

typedef struct {
    int transaction_id;
    time_t timestamp;
    double value;
    double weight;
    char source_identifier[256];
} Transaction;

typedef struct {
    double weighted_sum;
    int count;
    int top_10_percent_count;
    int max_weighted_sum_transaction_id;
    double max_weighted_sum;
    double average_weighted_sum_last_3_seconds;
    time_t last_processed_time;
    int transaction_rate;
} SourceData;

Transaction transactions[MAX_TRANSACTIONS];
SourceData source_data[256]; // Assuming 256 possible source identifiers
int next_transaction_index = 0;
int current_transaction_count = 0;
time_t system_start_time = 0;

void process_transaction(Transaction* transaction) {
    time_t now = time(NULL);
    char* source_id = transaction->source_identifier;

    if (system_start_time == 0) {
        system_start_time = now;
    }

    int source_index = *source_id % 256; // Simple hash for simplicity
    SourceData* data = &source_data[source_index];

    // Initialize source data if not already done
    if (data->last_processed_time == 0) {
        data->last_processed_time = now;
        data->average_weighted_sum_last_3_seconds = transaction->weighted_sum;
        data->max_weighted_sum_transaction_id = transaction->transaction_id;
        data->max_weighted_sum = transaction->weighted_sum;
    }

    // Update metrics
    data->weighted_sum += transaction->weighted_sum;
    data->count++;
    if (data->weighted_sum > data->max_weighted_sum) {
        data->max_weighted_sum = data->weighted_sum;
        data->max_weighted_sum_transaction_id = transaction->transaction_id;
    }

    // Calculate top 10% count
    if (current_transaction_count >= ROLLING_WINDOW_SIZE) {
        data->top_10_percent_count = current_transaction_count * 0.1;
    } else {
        data->top_10_percent_count = current_transaction_count / 2; // Simplified for example
    }

    // Calculate average weighted sum for the last 3 seconds
    double time_diff = difftime(now, data->last_processed_time);
    if (time_diff >= 3) {
        data->average_weighted_sum_last_3_seconds = data->weighted_sum / current_transaction_count;
        data->last_processed_time = now;
    }

    // Apply adaptive throttling
    if (data->transaction_rate > THROTTLE_LIMIT) {
        return; // Drop transaction due to high load
    }
    data->transaction_rate++;

    // Filter transactions based on criteria
    if (difftime(now, transaction->timestamp) < 5 &&
        data->weighted_sum > data->average_weighted_sum_last_3_seconds &&
        current_transaction_count >= ROLLING_WINDOW_SIZE && 
        current_transaction_count <= ROLLING_WINDOW_SIZE * 1.02) {

        // Accept the transaction
        printf("Accepted: Source=%s, ID=%d, Weighted Sum=%.2f\n", source_id, transaction->transaction_id, transaction->weighted_sum);
    } else {
        // Drop the transaction
        printf("Filtered out: Source=%s, ID=%d\n", source_id, transaction->transaction_id);
    }

    // Log transaction
    FILE* log_file = fopen("transaction_log.txt", "a");
    fprintf(log_file, "Source=%s, ID=%d, Action=%s\n", source_id, transaction->transaction_id, 
            current_transaction_count >= ROLLING_WINDOW_SIZE && 
            current_transaction_count <= ROLLING_WINDOW_SIZE * 1.02 ? "Accepted" : "Filtered out");
    fclose(log_file);

    // Store transaction in the rolling window
    if (current_transaction_count < MAX_TRANSACTIONS) {
        transactions[next_transaction_index] = *transaction;
        next_transaction_index = (next_transaction_index + 1) % MAX_TRANSACTIONS;
        current_transaction_count++;
    }
}

int get_most_active_source() {
    int max_count = 0;
    int most_active_source = -1;

    for (int i = 0; i < 256; i++) {
        if (source_data[i].count > max_count) {
            max_count = source_data[i].count;
            most_active_source = i;
        }
    }

    return most_active_source;
}

double get_max_weighted_sum(int source_id) {
    int index = *source_id % 256;
    return source_data[index].max_weighted_sum;
}

int main() {
    // Example usage
    Transaction transaction = {1, time(NULL), 100.0, 0.5, "SourceA"};
    process_transaction(&transaction);

    int most_active_source_id = get_most_active_source();
    double max_weighted_sum = get_max_weighted_sum((char*)&most_active_source_id);

    printf("Most active source ID: %d\n", most_active_source_id);
    printf("Max weighted sum for source: %.2f\n", max_weighted_sum);

    return 0;
}
