#include <stdlib.h>
#include <stdio.h>

typedef struct LTE_UESession_t {
    int ueId;
    void* radioConfigParams;
    char* uplinkDataBuffer;
    size_t bufferSize;
} LTE_UESession_t;

typedef struct UeSessionList {
    LTE_UESession_t** sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UeSessionList;

UeSessionList* initializeUeSessions(size_t initialCapacity) {
    UeSessionList* list = malloc(sizeof(UeSessionList));
    if (list == NULL) {
        perror("Failed to allocate memory for UeSessionList");
        return NULL;
    }

    list->sessions = malloc(initialCapacity * sizeof(LTE_UESession_t*));
    if (list->sessions == NULL) {
        free(list);
        perror("Failed to allocate memory for session array");
        return NULL;
    }

    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int addUeSession(UeSessionList* list, LTE_UESession_t* session) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        LTE_UESession_t** newSessions = realloc(list->sessions, newCapacity * sizeof(LTE_UESession_t*));
        if (newSessions == NULL) {
            pthread_mutex_unlock(&list->lock);
            perror("Failed to reallocate memory for session array");
            return -1;
        }
        list->sessions = newSessions;
        list->capacity = newCapacity;
    }

    list->sessions[list->count++] = session;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void destroyUeSession(LTE_UESession_t* session) {
    free(session->uplinkDataBuffer);
    free(session->radioConfigParams);
    free(session);
}

void destroyUeSessionList(UeSessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        destroyUeSession(list->sessions[i]);
    }
    pthread_mutex_unlock(&list->lock);

    free(list->sessions);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
