#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct State {
    long offset;
    int key;
    Record record;
    struct State* next;
} State;

typedef enum Error {
    SUCCESS = 0,
    MEMORY_ALLOCATION_FAILED,
    MAX_STATES_EXCEEDED,
    INVALID_TRANSITION
} Error;

Error manageStateList(State** stateList, size_t maxSize, bool includeStates) {
    // Initialize random seed
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL));
        seeded = true;
    }

    // Check for maximum states exceeded
    if (*stateList != NULL && countStates(*stateList) >= maxSize) {
        return MAX_STATES_EXCEEDED;
    }

    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }

    // Initialize new state with random record value
    newState->record.value = rand() % 100; // Example range, can be adjusted

    // Set other fields based on includeStates flag
    newState->offset = rand(); // Example initialization
    newState->key = rand();
    if (includeStates) {
        newState->next = *stateList;
    } else {
        newState->next = NULL;
    }

    // Append to state list or replace current head
    *stateList = newState;

    return SUCCESS;
}

size_t countStates(State* stateList) {
    size_t count = 0;
    while (stateList != NULL) {
        count++;
        stateList = stateList->next;
    }
    return count;
}
```

