def modify_config_file(file_path, replacements):
    try:
        with open(file_path, 'r') as file:
            content = file.read()

        for key, value in replacements.items():
            content = content.replace(key, value)

        encrypted_password = encrypt_password('password123')
        new_line = f"new_line={encrypted_password}\n"
        content += new_line

        with open(file_path + '.modified', 'w') as file:
            file.write(content)

    except Exception as e:
        logging.error(f"Failed to modify config file: {e}")
        raise

def encrypt_password(password):
    key = b'Sixteen byte key'
    cipher = AES.new(key, AES.MODE_EAX)
    ciphertext, tag = cipher.encrypt_and_digest(password.encode())
    return cipher.nonce + tag + ciphertext

# Example usage
