            throw new IllegalArgumentException("File paths list must not be null and should contain up to 1000 elements.");
        }

        List<CompletableFuture<String>> futures = new ArrayList<>();
        for (String path : filePaths) {
            futures.add(CompletableFuture.supplyAsync(() -> readFileContent(path)));
        }

        CompletableFuture<Void> allFutures = CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
        allFutures.get();

        StringBuilder contentBuilder = new StringBuilder();
        for (CompletableFuture<String> future : futures) {
            contentBuilder.append(future.get());
        }

        byte[] hashBytes = computeSHA256Hash(contentBuilder.toString().getBytes());
        return returnHex ? bytesToHex(hashBytes) : Base64.getEncoder().encodeToString(hashBytes);
    }

    private static String readFileContent(String path) throws IOException {
        if (!Files.exists(Paths.get(path))) {
            System.err.println("File does not exist: " + path);
            return "";
        }
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(path), StandardCharsets.UTF_8)) {
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                contentBuilder.append(line).append(System.lineSeparator());
            }
            return contentBuilder.toString();
        }
    }

    private static byte[] computeSHA256Hash(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        digest.update(data);
        return digest.digest();
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            List<String> filePaths = Arrays.asList("path/to/file1.txt", "path/to/file2.txt");
            String hash = processFiles(filePaths, true);
            System.out.println("SHA-256 Hash (Hex): " + hash);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
