int hash_large_file(const char *filename, unsigned char *md5_digest) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // Return error code for file open failure

    EVP_MD_CTX *md5_ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(md5_ctx, EVP_md5(), NULL);

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        EVP_DigestUpdate(md5_ctx, buffer, bytesRead);
    }

    EVP_DigestFinal_ex(md5_ctx, md5_digest, NULL);
    EVP_MD_CTX_free(md5_ctx);
    fclose(file);

    return 0; // Return success
