#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAGIC_NUMBER 0x12345678
#define VERSION 1

typedef struct {
    char type;
    size_t size;
    void* data;
} ResourceItem;

typedef struct {
    ResourceItem* items;
    size_t itemCount;
    size_t itemCapacity;
} ResourceBundle;

enum ErrorCode {
    SUCCESS,
    FILE_NOT_FOUND,
    PERMISSION_DENIED,
    OUT_OF_MEMORY,
    FORMAT_ERROR,
    VERSION_MISMATCH
};

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        return NULL;
    }

    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fclose(file);
        return NULL;
    }
    memset(bundle, 0, sizeof(ResourceBundle));

    uint32_t magicNumber, version, itemCount;
    if (!fread(&magicNumber, sizeof(uint32_t), 1, file) ||
        !fread(&version, sizeof(uint32_t), 1, file) ||
        !fread(&itemCount, sizeof(uint32_t), 1, file)) {
        free(bundle);
        fclose(file);
        return NULL;
    }

    if (magicNumber != MAGIC_NUMBER || version != VERSION) {
        free(bundle);
        fclose(file);
        return NULL;
    }

    bundle->items = (ResourceItem*)malloc(itemCount * sizeof(ResourceItem));
    if (!bundle->items) {
        free(bundle);
        fclose(file);
        return NULL;
    }
    bundle->itemCapacity = itemCount;

    for (size_t i = 0; i < itemCount; ++i) {
        ResourceItem* item = &bundle->items[i];
        if (!fread(&item->type, sizeof(char), 1, file) ||
            !fread(&item->size, sizeof(size_t), 1, file)) {
            free(bundle->items);
            free(bundle);
            fclose(file);
            return NULL;
        }

        item->data = malloc(item->size);
        if (!item->data) {
            for (size_t j = 0; j < i; ++j) {
                free(bundle->items[j].data);
            }
            free(bundle->items);
            free(bundle);
            fclose(file);
            return NULL;
        }

        if (fread(item->data, item->size, 1, file) != 1) {
            for (size_t j = 0; j <= i; ++j) {
                free(bundle->items[j].data);
            }
            free(bundle->items);
            free(bundle);
            fclose(file);
            return NULL;
        }
    }

    bundle->itemCount = itemCount;
    fclose(file);
    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (size_t i = 0; i < bundle->itemCount; ++i) {
        free(bundle->items[i].data);
    }
    free(bundle->items);
    free(bundle);
}
