    if (!sessions) {
        // Handle memory allocation failure
        return NULL;
    }

    for (int i = 0; i < numSessions; ++i) {
        sessions[i] = (LTE_UESession_t *)malloc(sizeof(LTE_UESession_t));
        if (!sessions[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                free(sessions[j]);
            }
            free(sessions);
            return NULL;
        }

        sessions[i]->ueId = i + 1; // Example initialization
        memset(&sessions[i]->radioResourceConfig, 0, sizeof(struct in_addr));
        sessions[i]->uplinkDataBuffer = (u_char *)malloc(4096); // Example buffer size
        if (!sessions[i]->uplinkDataBuffer) {
            // Handle memory allocation failure
            for (int j = 0; j <= i; ++j) {
                free(sessions[j]->uplinkDataBuffer);
                free(sessions[j]);
            }
            free(sessions);
            return NULL;
        }

        // Initialize buffer to a known state
        memset(sessions[i]->uplinkDataBuffer, 0, 4096);
    }

    return sessions;
}

int resolveHostname(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return status; // Return error code from getaddrinfo
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // Free the linked list
        return 0; // Success
    }

    freeaddrinfo(res); // Free the linked list if no address found
    return -1; // Error: No valid IP address found
}
