void stopStreamingService() {
    pthread_mutex_lock(&streamMutex);
    for (int i = 0; i < streamCount; ++i) {
        if (streamList[i]) {
            free(streamList[i]->clientMetadata);
            free(streamList[i]->buffer);
            free(streamList[i]);
        }
