enum PaddingOptions {
    NO_PADDING,
    PKCS7_PADDING,
    ANOTHER_PADDING_OPTION // Add more padding options as needed
};

void insertAfterForwardList(std::forward_list<std::string>& myList, const std::string& target, const std::string& insertion, PaddingOptions padding) {
    auto it = myList.begin();
    while (it != myList.end() && *it != target) {
        ++it;
    }

    if (it != myList.end()) {
        // Target found, insert after
        it++;
        myList.insert_after(it, insertion);
    } else {
        // Target not found, append at the end
        myList.push_front(insertion); // Note: This is an example; push_front is typically slow for forward_list. Consider using push_back or another approach.
    }
}

int main() {
    std::forward_list<std::string> myList = {"hello", "world"};
    insertAfterForwardList(myList, "hello", "secure", PKCS7_PADDING);

    // Output the modified list
    for (const auto& str : myList) {
        std::cout << str << " ";
    }
    return 0;
}
