        sprintf(hex + (i * 2), "%02x", md[i]);
    }
    hex[32] = '\0';
}

void md5_to_base64(const unsigned char *md, char *base64) {
    // Base64 encoding implementation here
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    int cs_flag = 0;  // Flag to indicate if MD5 hash should be in hexadecimal format
    FILE *output_file = stdout;

    for (int i = 1; i < argc && argv[i][0] == '-'; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            cs_flag = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                perror("Error opening output file");
                return 1;
            }
        }
    }

    char concatenated_string[MAX_INPUT_LEN * MAX_ARGS] = "";
    for (int i = 1; i < argc && strlen(concatenated_string) + strlen(argv[i]) <= MAX_INPUT_LEN; ++i) {
        strcat(concatenated_string, argv[i]);
        if (i < argc - 1) strcat(concatenated_string, " ");
    }

    if (strlen(concatenated_string) == 0) {
        fprintf(stderr, "Error: No input strings provided.\n");
        print_usage();
        return 1;
    }

    unsigned char md[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)concatenated_string, strlen(concatenated_string), md);

    char output[MAX_OUTPUT_LEN];
    if (cs_flag) {
        md5_to_base64(md, output);
    } else {
        md5_to_hex(md, output);
    }

    fprintf(output_file, "%s\n", output);
    fclose(output_file);

    return 0;
}
