typedef struct MemoryPool_t {
    size_t poolSize;
    size_t blockSize;
    void* freeList;
} MemoryPool_t;

MemoryPool_t* createMemoryPool(size_t poolSize, size_t blockSize) {
    MemoryPool_t* pool = (MemoryPool_t*)malloc(sizeof(MemoryPool_t));
    if (!pool) return NULL;
    pool->poolSize = poolSize;
    pool->blockSize = blockSize;
    pool->freeList = malloc(poolSize * blockSize);
    if (!pool->freeList) {
        free(pool);
        return NULL;
    }
    for (size_t i = 0; i < poolSize - 1; ++i) {
        ((void**)(pool->freeList))[i] = &((char*)(pool->freeList))[blockSize * (i + 1)];
    }
    ((void**)(pool->freeList))[poolSize - 1] = NULL;
    return pool;
}

void* allocateFromPool(MemoryPool_t* pool) {
    if (!pool || !pool->freeList) return NULL;
    void* block = pool->freeList;
    pool->freeList = *(void**)block;
    return block;
}

void deallocateToPool(MemoryPool_t* pool, void* block) {
    if (!pool || !block) return;
    *(void**)block = pool->freeList;
    pool->freeList = block;
}

void destroyMemoryPool(MemoryPool_t* pool) {
    if (pool) {
        free(pool->freeList);
        free(pool);
    }
}

void startStreamingService() {
    MemoryPool_t* mediaBufferPool = createMemoryPool(100, 4096); // Example: 100 blocks of 4KB each
    if (!mediaBufferPool) {
        fprintf(stderr, "Failed to allocate memory pool for media buffers.\n");
        return;
    }

