using System;
using System.Collections.Generic;
using System.Linq;

public class RandomValueGenerator : ICloneable<RandomValueGenerator>
{
    private int _minInt = 0, _maxInt = 100;
    private float _minFloat = 0.0f, _maxFloat = 1.0f;
    private Random _random;

    public RandomValueGenerator(int seed = -1)
    {
        InitializeRange();
        if (seed >= 0)
            SetSeed(seed);
    }

    public void InitializeRange(int? minInt = null, int? maxInt = null,
                                 float? minFloat = null, float? maxFloat = null)
    {
        _minInt = minInt.HasValue ? Math.Min(minInt.Value, maxInt ?? int.MaxValue) : 0;
        _maxInt = maxInt.HasValue ? Math.Max(maxInt.Value, minInt ?? int.MinValue) : 100;

        _minFloat = minFloat.HasValue ? Math.Min(minFloat.Value, maxFloat ?? float.MaxValue) : 0.0f;
        _maxFloat = maxFloat.HasValue ? Math.Max(maxFloat.Value, minFloat ?? float.MinValue) : 1.0f;

        if (_minInt > _maxInt || _minFloat > _maxFloat)
        {
            Console.WriteLine("Warning: Invalid range settings. Reverting to default.");
            InitializeRange();
        }
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    public int GenerateRandomInt(bool includeMax = true, bool useCustomSeed = false)
    {
        if (useCustomSeed)
        {
            return _random.Next(_minInt, includeMax ? _maxInt + 1 : _maxInt);
        }
        else
        {
            Random defaultRandom = new Random();
            return defaultRandom.Next(_minInt, includeMax ? _maxInt + 1 : _maxInt);
        }
    }

    public float GenerateRandomFloat(DistributionType distribution = DistributionType.Uniform, bool useCustomSeed = false)
    {
        if (useCustomSeed)
        {
            switch (distribution)
            {
                case DistributionType.Normal:
                    return (float)_random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
                default:
                    return (float)_random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            }
        }
        else
        {
            Random defaultRandom = new Random();
            switch (distribution)
            {
                case DistributionType.Normal:
                    return (float)defaultRandom.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
                default:
                    return (float)defaultRandom.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            }
        }
    }

    public IEnumerable<int> GenerateIntegers(int batchSize, bool includeMax = true, bool useCustomSeed = false)
    {
        for (int i = 0; i < batchSize; i++)
        {
            yield return GenerateRandomInt(includeMax, useCustomSeed);
        }
    }

    public IEnumerable<float> GenerateFloats(int batchSize, DistributionType distribution = DistributionType.Uniform, bool useCustomSeed = false)
    {
        for (int i = 0; i < batchSize; i++)
        {
            yield return GenerateRandomFloat(distribution, useCustomSeed);
        }
    }

    public override string ToString()
    {
        return $"Int Range: {_minInt}-{_maxInt}, Float Range: {_minFloat}-{_maxFloat}";
    }

    public RandomValueGenerator Clone()
    {
        return new RandomValueGenerator(_random?.Seed ?? -1) { _minInt = _minInt, _maxInt = _maxInt, _minFloat = _minFloat, _maxFloat = _maxFloat };
    }
}

public enum DistributionType
{
    Uniform,
    Normal
}
