#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1024
#define LOG_BUFFER_SIZE 1024

typedef struct MediaStream_t {
    int sessionID;
    char* clientMetadata;
    unsigned char* mediaDataBuffer;
    size_t bufferCapacity;
} MediaStream_t;

typedef enum LogLevel { DEBUG, INFO, WARN, ERROR } LogLevel;

typedef struct Logger {
    LogLevel level;
    char logBuffer[LOG_BUFFER_SIZE];
    size_t logIndex;
} Logger;

typedef struct MemoryPool {
    size_t blockSize;
    size_t poolSize;
    void* blocks[MAX_SESSIONS];
    size_t freeBlocks;
} MemoryPool;

Logger logger = {INFO, "", 0};
MemoryPool memoryPool = {1024, MAX_SESSIONS, {NULL}, 0};

void logMessage(LogLevel level, const char* message) {
    if (level >= logger.level) {
        time_t now = time(NULL);
        strftime(logger.logBuffer + logger.logIndex, sizeof(logger.logBuffer) - logger.logIndex, "%Y-%m-%d %H:%M:%S", localtime(&now));
        logger.logIndex += strlen(logger.logBuffer + logger.logIndex);
        snprintf(logger.logBuffer + logger.logIndex, sizeof(logger.logBuffer) - logger.logIndex, " [%s] %s\n", level == DEBUG ? "DEBUG" : level == INFO ? "INFO" : level == WARN ? "WARN" : "ERROR", message);
        logger.logIndex += strlen(logger.logBuffer + logger.logIndex);
    }
}

void* allocateFromPool(size_t size) {
    if (size > memoryPool.blockSize) {
        logMessage(ERROR, "Requested block size exceeds pool block size");
        return NULL;
    }
    if (memoryPool.freeBlocks == 0) {
        logMessage(WARN, "Memory pool is full, reallocating blocks");
        void** newBlocks = realloc(memoryPool.blocks, memoryPool.poolSize * 2 * sizeof(void*));
        if (newBlocks == NULL) {
            logMessage(ERROR, "Failed to reallocate memory for pool");
            return NULL;
        }
        memoryPool.blocks = newBlocks;
        memoryPool.poolSize *= 2;
    }
    void* block = memoryPool.blocks[memoryPool.poolSize - memoryPool.freeBlocks];
    memoryPool.freeBlocks--;
    memset(block, 0, size);
    logMessage(DEBUG, "Allocated block from pool");
    return block;
}

void freeToPool(void* block) {
    for (size_t i = 0; i < memoryPool.poolSize - memoryPool.freeBlocks; i++) {
        if (memoryPool.blocks[i] == block) {
            memoryPool.blocks[i] = NULL;
            memoryPool.freeBlocks++;
            logMessage(DEBUG, "Freed block to pool");
            return;
        }
    }
    logMessage(ERROR, "Attempted to free a block not in the pool");
}

MediaStream_t* createMediaStream(int sessionID, const char* clientMetadata) {
    MediaStream_t* stream = (MediaStream_t*)allocateFromPool(sizeof(MediaStream_t));
    if (stream == NULL) return NULL;
    stream->sessionID = sessionID;
    stream->clientMetadata = strdup(clientMetadata);
    if (stream->clientMetadata == NULL) {
        freeToPool(stream);
        return NULL;
    }
    stream->mediaDataBuffer = allocateFromPool(1024); // Initial buffer size
    if (stream->mediaDataBuffer == NULL) {
        free(stream->clientMetadata);
        freeToPool(stream);
        return NULL;
    }
    stream->bufferCapacity = 1024;
    logMessage(INFO, "Created media stream with session ID %d", sessionID);
    return stream;
}

void destroyMediaStream(MediaStream_t* stream) {
    if (stream != NULL) {
        free(stream->clientMetadata);
        free(stream->mediaDataBuffer);
        freeToPool(stream);
        logMessage(INFO, "Destroyed media stream with session ID %d", stream->sessionID);
    }
}
