                var navigator = new XPathDocument(reader).CreateNavigator();
                var expression = $"/*[local-name()='{elementName}']";
                return navigator.Select(expression);
            }
        }
        catch (XPathException ex)
        {
            Console.WriteLine($"XPath error: {ex.Message}");
            return null;
        }
        catch (System.Xml.XmlException ex)
        {
            Console.WriteLine($"XML parse error: {ex.Message}");
            return null;
        }
        catch (OutOfMemoryException ex)
        {
            Console.WriteLine($"Out of memory: {ex.Message}");
            return null;
        }
