#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_CONNECTIONS 100

typedef struct {
    int *connection_ids;
    int pool_size;
    int current_connections;
} ConnectionPool;

ConnectionPool *create_connection_pool(int initial_size) {
    ConnectionPool *pool = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    if (pool == NULL) return NULL;

    pool->connection_ids = (int *)calloc(initial_size, sizeof(int));
    if (pool->connection_ids == NULL) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->current_connections = 0;

    for (int i = 0; i < initial_size; i++) {
        pool->connection_ids[i] = i + 1;
    }

    return pool;
}

void destroy_connection_pool(ConnectionPool *pool) {
    if (pool != NULL) {
        free(pool->connection_ids);
        free(pool);
    }
}

bool get_next_connection(ConnectionPool *pool, int *connection_id) {
    if (pool == NULL || connection_id == NULL) return false;

    if (pool->current_connections < pool->pool_size) {
        *connection_id = pool->connection_ids[pool->current_connections++];
        return true;
    } else {
        // Optionally expand the pool here
        return false;
    }
}

void close_connection(ConnectionPool *pool, int connection_id) {
    if (pool == NULL) return;

    for (int i = 0; i < pool->current_connections; i++) {
        if (pool->connection_ids[i] == connection_id) {
            pool->connection_ids[i] = pool->connection_ids[pool->current_connections - 1];
            pool->current_connections--;
            break;
        }
    }
}

int main() {
    ConnectionPool *pool = create_connection_pool(50);
    if (pool != NULL) {
        int connection_id;
        if (get_next_connection(pool, &connection_id)) {
            printf("Connection ID: %d\n", connection_id);
            close_connection(pool, connection_id);
        }

        destroy_connection_pool(pool);
    } else {
        printf("Failed to create connection pool.\n");
    }

    return 0;
}
```

