#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAGIC_NUMBER 0x12345678
#define VERSION 1

typedef enum {
    TYPE_RESOURCE_BUNDLE,
    TYPE_STATE_OBJECT
} FileType;

typedef struct {
    char type;
    size_t size;
    void* data;
} ResourceItem;

typedef struct {
    uint32_t identifier;
    void* data;
} StateObject;

typedef struct {
    FILE* file;
    FileType type;
    union {
        ResourceItem* items;
        StateObject state;
    } content;
    int itemCount;
} FileBundle;

FileBundle* loadFile(const char* filename, FileType fileType) {
    FileBundle* bundle = (FileBundle*)malloc(sizeof(FileBundle));
    if (!bundle) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    bundle->file = fopen(filename, "rb");
    if (!bundle->file) {
        perror("Failed to open file");
        free(bundle);
        return NULL;
    }

    uint32_t header, version;
    if (fread(&header, sizeof(uint32_t), 1, bundle->file) != 1 ||
        fread(&version, sizeof(uint32_t), 1, bundle->file) != 1) {
        perror("Failed to read file header or version");
        fclose(bundle->file);
        free(bundle);
        return NULL;
    }

    if (header != MAGIC_NUMBER || version != VERSION) {
        fprintf(stderr, "Invalid file format\n");
        fclose(bundle->file);
        free(bundle);
        return NULL;
    }

    bundle->type = fileType;

    if (bundle->type == TYPE_RESOURCE_BUNDLE) {
        if (fread(&bundle->itemCount, sizeof(int), 1, bundle->file) != 1) {
            perror("Failed to read item count");
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }

        bundle->content.items = (ResourceItem*)malloc(bundle->itemCount * sizeof(ResourceItem));
        if (!bundle->content.items) {
            fprintf(stderr, "Out of memory\n");
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }

        for (int i = 0; i < bundle->itemCount; i++) {
            if (fread(&bundle->content.items[i].type, sizeof(char), 1, bundle->file) != 1 ||
                fread(&bundle->content.items[i].size, sizeof(size_t), 1, bundle->file) != 1) {
                perror("Failed to read item type or size");
                free(bundle->content.items);
                fclose(bundle->file);
                free(bundle);
                return NULL;
            }

            bundle->content.items[i].data = malloc(bundle->content.items[i].size);
            if (!bundle->content.items[i].data) {
                fprintf(stderr, "Out of memory\n");
                for (int j = 0; j < i; j++) {
                    free(bundle->content.items[j].data);
                }
                free(bundle->content.items);
                fclose(bundle->file);
                free(bundle);
                return NULL;
            }

            if (fread(bundle->content.items[i].data, bundle->content.items[i].size, 1, bundle->file) != 1) {
                perror("Failed to read item data");
                for (int j = 0; j <= i; j++) {
                    free(bundle->content.items[j].data);
                }
                free(bundle->content.items);
                fclose(bundle->file);
                free(bundle);
                return NULL;
            }
        }
    } else if (bundle->type == TYPE_STATE_OBJECT) {
        if (fread(&bundle->content.state.identifier, sizeof(uint32_t), 1, bundle->file) != 1) {
            perror("Failed to read state object identifier");
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }

        size_t dataSize;
        if (fread(&dataSize, sizeof(size_t), 1, bundle->file) != 1) {
            perror("Failed to read data size");
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }

        bundle->content.state.data = malloc(dataSize);
        if (!bundle->content.state.data) {
            fprintf(stderr, "Out of memory\n");
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }

        if (fread(bundle->content.state.data, dataSize, 1, bundle->file) != 1) {
            perror("Failed to read state object data");
            free(bundle->content.state.data);
            fclose(bundle->file);
            free(bundle);
            return NULL;
        }
    }

    return bundle;
}

void unloadFile(FileBundle* bundle) {
    if (bundle->type == TYPE_RESOURCE_BUNDLE) {
        for (int i = 0; i < bundle->itemCount; i++) {
            free(bundle->content.items[i].data);
        }
        free(bundle->content.items);
    } else if (bundle->type == TYPE_STATE_OBJECT) {
        free(bundle->content.state.data);
    }

    fclose(bundle->file);
    free(bundle);
}

int main() {
    FileBundle* resourceBundle = loadFile("resource_bundle.bin", TYPE_RESOURCE_BUNDLE);
    if (resourceBundle) {
        printf("Resource Bundle Loaded:\n");
        for (int i = 0; i < resourceBundle->itemCount; i++) {
            printf("Type: %c, Size: %zu bytes\n", resourceBundle->content.items[i].type, resourceBundle->content.items[i].size);
        }
        unloadFile(resourceBundle);
    }

    FileBundle* stateObject = loadFile("state_object.bin", TYPE_STATE_OBJECT);
    if (stateObject) {
        printf("\nState Object Loaded:\n");
        printf("Identifier: 0x%08X\n", stateObject->content.state.identifier);
        unloadFile(stateObject);
    }

    return 0;
}
```

This code provides a basic structure for loading resource bundles and state objects from custom binary files. It includes error handling, dynamic memory management, and file validation as per the given requirements. The `loadFile` function reads the file header and version, then processes the items based on the file type (resource bundle or state object). The `unloadFile` function frees all dynamically allocated memory and closes the file handle. The `main` function demonstrates how to use these functions to load and report on files.']

