typedef struct record {
    int value;
} Record;

typedef struct state {
    long offset;
    int key;
    Record rec;
    char* label;
    struct state* next;
} State;

State* create_state(long offset, int key, int minValue, int maxValue) {
    State* s = (State*)malloc(sizeof(State));
    if (!s) return NULL;

    s->offset = offset;
    s->key = key;
    s->rec.value = rand() % (maxValue - minValue + 1) + minValue;
    s->label = (char*)malloc(256 * sizeof(char));
    if (!s->label) {
        free(s);
        return NULL;
    }

    snprintf(s->label, 256, "State_%d", key);
    s->next = NULL;

    return s;
}

void initialize_state_list(State** head, long offset, int key, int minValue, int maxValue, int limit) {
    if (*head || offset > limit) return;

    *head = create_state(offset, key, minValue, maxValue);
    if (!*head) return;

    for (int i = 1; i < 4000; ++i) { // Assuming each state represents 10 transitions
        State* nextState = create_state(*((*head)->offset + 1), key + i, minValue, maxValue);
        if (!nextState) break;

        (*head)->next = nextState;
        *head = nextState;
    }
}

// Additional functions for managing the state list (e.g., adding states, freeing memory, etc.) should be implemented here
