#define MAX_CONFIG_ENTRIES 5000
#define MAX_KEY_LENGTH 100
#define MAX_DESCRIPTION_LENGTH 256

typedef struct ConfigInt {
    int key;
    int value;
} ConfigInt;

typedef struct ConfigFloat {
    float default_value;
} ConfigFloat;

typedef struct ConfigStruct {
    int nested_int;
    char* description;
} ConfigStruct;

typedef enum ConfigType {
    INT_TYPE,
    FLOAT_TYPE,
    STRUCT_TYPE
} ConfigType;

typedef struct ConfigEntry {
    char key[MAX_KEY_LENGTH];
    union {
        ConfigInt intValue;
        ConfigFloat floatValue;
        ConfigStruct structValue;
    };
    ConfigType type;
    char description[MAX_DESCRIPTION_LENGTH];
    struct ConfigEntry* next;
} ConfigEntry;

typedef struct ConfigFile {
    ConfigEntry* head;
    ConfigEntry** last;
    pthread_mutex_t mutex;
} ConfigFile;

int initializeConfig(ConfigFile** file, size_t max_size) {
    *file = (ConfigFile*)malloc(sizeof(ConfigFile));
    if (*file == NULL) return -1; // Memory allocation failed
    (*file)->head = NULL;
    (*file)->last = &(*file)->head;
    pthread_mutex_init(&(*file)->mutex, NULL);
    return 0;
}

int addEntry(ConfigFile* file, const char* key, int intValue, ConfigType type, const char* description) {
    if (file->head != NULL && strlen(key) > MAX_KEY_LENGTH) return -2; // Key too long
    pthread_mutex_lock(&file->mutex);
    ConfigEntry* newEntry = (ConfigEntry*)malloc(sizeof(ConfigEntry));
    if (newEntry == NULL) {
        pthread_mutex_unlock(&file->mutex);
        return -1; // Memory allocation failed
    }
    strncpy(newEntry->key, key, MAX_KEY_LENGTH);
    newEntry->intValue.value = intValue;
    newEntry->type = type;
    strncpy(newEntry->description, description, MAX_DESCRIPTION_LENGTH);
    newEntry->next = NULL;
    *file->last = newEntry;
    file->last = &newEntry->next;
    pthread_mutex_unlock(&file->mutex);
    return 0;
}

void destroyConfig(ConfigFile* file) {
    ConfigEntry* current = file->head;
    while (current != NULL) {
        ConfigEntry* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&file->mutex);
}
