#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    RESOURCE_FILE,
    STATE_FILE,
    // Add more file types as needed
} FileType;

typedef struct {
    char type;
    size_t size;
    void* data;
} ResourceItem;

typedef struct {
    FILE* file;
    int error_code;
} FileHandle;

int loadFile(const char* filename, FileType fileType, FileHandle* handle) {
    handle->file = fopen(filename, "rb");
    if (handle->file == NULL) {
        perror("Error opening file");
        return -1; // File not found or permission denied
    }

    uint32_t magicNumber;
    fread(&magicNumber, sizeof(uint32_t), 1, handle->file);
    if (ferror(handle->file)) {
        perror("Error reading magic number");
        fclose(handle->file);
        return -1; // File corrupted or invalid data
    }

    uint32_t version;
    fread(&version, sizeof(uint32_t), 1, handle->file);
    if (ferror(handle->file)) {
        perror("Error reading version");
        fclose(handle->file);
        return -1; // File corrupted or invalid data
    }

    switch (fileType) {
        case RESOURCE_FILE:
            if (magicNumber != 0x52455354 || version != 1) { // "RESOURCE"
                fprintf(stderr, "Invalid resource file format\n");
                fclose(handle->file);
                return -1;
            }
            break;
        case STATE_FILE:
            if (magicNumber != 0x53454154 || version != 1) { // "STATE"
                fprintf(stderr, "Invalid state file format\n");
                fclose(handle->file);
                return -1;
            }
            break;
        default:
            fprintf(stderr, "Unknown file type\n");
            fclose(handle->file);
            return -1;
    }

    handle->error_code = 0; // No error
    return 0;
}

void freeResourceItems(ResourceItem* items, size_t itemCount) {
    for (size_t i = 0; i < itemCount; ++i) {
        free(items[i].data);
    }
    free(items);
}

int main() {
    FileHandle resourceHandle;
    ResourceItem* resourceItems;
    size_t resourceItemCount;

    if (loadFile("resource.bin", RESOURCE_FILE, &resourceHandle) != 0) {
        return 1; // Handle error
    }

    uint32_t itemCount;
    fread(&itemCount, sizeof(uint32_t), 1, resourceHandle.file);
    if (ferror(resourceHandle.file)) {
        perror("Error reading item count");
        fclose(resourceHandle.file);
        return 1; // Handle error
    }

    resourceItems = (ResourceItem*)malloc(itemCount * sizeof(ResourceItem));
    if (resourceItems == NULL) {
        fprintf(stderr, "Out of memory\n");
        fclose(resourceHandle.file);
        return 1; // Handle error
    }

    for (size_t i = 0; i < itemCount; ++i) {
        fread(&resourceItems[i].type, sizeof(char), 1, resourceHandle.file);
        fread(&resourceItems[i].size, sizeof(size_t), 1, resourceHandle.file);

        if (ferror(resourceHandle.file)) {
            perror("Error reading item details");
            freeResourceItems(resourceItems, i + 1);
            fclose(resourceHandle.file);
            return 1; // Handle error
        }

        resourceItems[i].data = malloc(resourceItems[i].size);
        if (resourceItems[i].data == NULL) {
            fprintf(stderr, "Out of memory\n");
            freeResourceItems(resourceItems, i + 1);
            fclose(resourceHandle.file);
            return 1; // Handle error
        }

        fread(resourceItems[i].data, 1, resourceItems[i].size, resourceHandle.file);
    }

    fclose(resourceHandle.file);

    printf("Resource bundle contains %zu items:\n", itemCount);
    for (size_t i = 0; i < itemCount; ++i) {
        printf("Item %zu: Type %c, Size %zu bytes\n", i, resourceItems[i].type, resourceItems[i].size);
    }

    freeResourceItems(resourceItems, itemCount);

    return 0;
}
```

