using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private Random random;
    private int intValueMin;
    private int intValueMax;
    private float floatValueMin;
    private float floatValueMax;

    public DynamicValueGenerator(int seed = 0)
    {
        random = new Random(seed);
        SetIntRange(0, 100);
        SetFloatRange(0.0f, 1.0f);
    }

    public void SetIntRange(int min, int max)
    {
        if (min > max)
        {
            Console.WriteLine("Warning: Invalid integer range. Setting to default [0, 100].");
            intValueMin = 0;
            intValueMax = 100;
        }
        else
        {
            intValueMin = min;
            intValueMax = max;
        }
    }

    public void SetFloatRange(float min, float max)
    {
        if (min > max)
        {
            Console.WriteLine("Warning: Invalid float range. Setting to default [0.0, 1.0].");
            floatValueMin = 0.0f;
            floatValueMax = 1.0f;
        }
        else
        {
            floatValueMin = min;
            floatValueMax = max;
        }
    }

    public int GetRandomInt()
    {
        return random.Next(intValueMin, intValueMax + 1);
    }

    public float GetRandomFloat()
    {
        return (float)random.NextDouble() * (floatValueMax - floatValueMin) + floatValueMin;
    }

    public List<int> GetBatchOfRandomInts(int count)
    {
        return Enumerable.Range(0, count).Select(_ => GetRandomInt()).ToList();
    }

    public List<float> GetBatchOfRandomFloats(int count)
    {
        return Enumerable.Range(0, count).Select(_ => GetRandomFloat()).ToList();
    }
}
