typedef struct {
    char* (*alloc)(size_t size);
    void (*dealloc)(void*);
} LoggingConfig;

char* custom_string_process(const char* input, size_t limit, int append_separator, const LoggingConfig* config) {
    if (input == NULL || limit <= 0) return NULL;

    size_t input_len = strlen(input);
    if (input_len > limit) return NULL;

    char* result;
    if (append_separator && input_len + 2 <= limit) {
        result = config->alloc(input_len + 2);
        if (result == NULL) return NULL;
        strcpy(result, input);
        result[input_len] = '/';
        result[input_len + 1] = '\0';
    } else {
        result = config->alloc(input_len + 1);
        if (result == NULL) return NULL;
        strcpy(result, input);
    }

    // Log operation details
    if (config->log_enabled) {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "String: %s, Limit: %zu, Appended Separator: %d", input, limit, append_separator);
        config->log_function(log_message);
    }

    return result;
}

// Example usage
int main() {
    LoggingConfig config = {
        .alloc = malloc,
        .dealloc = free,
        .log_enabled = 1,
        .log_function = printf
    };

    const char* input = "example";
    size_t limit = 20;
    int append_separator = 1;

    char* result = custom_string_process(input, limit, append_separator, &config);
    if (result != NULL) {
        printf("Processed string: %s\n", result);
        free(result);
    } else {
        printf("Failed to process string.\n");
    }

    return 0;
}
