#define CACHE_SIZE 1024

typedef struct {
    char* data;
    size_t size;
} FileChunk_t;

typedef struct {
    FileChunk_t** cache;
    size_t cache_size;
    pthread_mutex_t cache_lock;
} Allocator_t;

Allocator_t allocator = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

FileChunk_t* allocateChunk(size_t size) {
    pthread_mutex_lock(&allocator.cache_lock);
    if (allocator.cache_size > 0 && allocator.cache[0]->size >= size) {
        FileChunk_t* chunk = allocator.cache[0];
        for (size_t i = 0; i < allocator.cache_size - 1; i++) {
            allocator.cache[i] = allocator.cache[i + 1];
        }
        allocator.cache_size--;
        pthread_mutex_unlock(&allocator.cache_lock);
        return chunk;
    }
    pthread_mutex_unlock(&allocator.cache_lock);

    FileChunk_t* chunk = (FileChunk_t*)malloc(sizeof(FileChunk_t));
    if (!chunk) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    chunk->data = (char*)malloc(size);
    if (!chunk->data) {
        free(chunk);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    chunk->size = size;

    return chunk;
}

void deallocateChunk(FileChunk_t* chunk) {
    pthread_mutex_lock(&allocator.cache_lock);
    if (allocator.cache_size < CACHE_SIZE) {
        allocator.cache[allocator.cache_size++] = chunk;
    } else {
        free(chunk->data);
        free(chunk);
    }
    pthread_mutex_unlock(&allocator.cache_lock);
}

void processFileChunks(int numChunks) {
    for (int i = 0; i < numChunks; i++) {
        FileChunk_t* chunk = allocateChunk(1024); // Example size
        if (!chunk) continue;

        // Process the chunk...

        deallocateChunk(chunk);
    }
}

void parseMetaData(int taskID, void (*parseFunction)(int)) {
