#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>

#define MD5_DIGEST_LENGTH 16

void printUsage() {
    printf("Usage: program [options] input_file\n");
    printf("Options:\n");
    printf("--manpage\tPrint detailed usage information.\n");
    printf("-cs\tCompress output lines using a simple algorithm before printing.\n");
    printf("-o output_file\tRedirect the output to a specified file instead of stdout.\n");
    printf("-l limit_lines\tLimit the number of lines processed from the input file to a specified value.\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printUsage();
        return 1;
    }

    // Parse command line arguments
    int compress = 0;
    char *output_file = NULL;
    int limit_lines = -1;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printUsage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            compress = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limit_lines = atoi(argv[++i]);
        }
    }

    FILE *file = fopen(argv[argc - 1], "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    // Initialize MD5 hash
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    memset(md5_hash, 0, MD5_DIGEST_LENGTH);

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    char buffer[4096];
    size_t lines = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        if (limit_lines >= 0 && lines >= limit_lines) break;

        // Update MD5 hash
        unsigned int len = strlen(buffer);
        for (size_t j = 0; j < len; j++) {
            md5_hash[j % MD5_DIGEST_LENGTH] ^= buffer[j];
        }

        lines++;
    }

    fclose(file);

    gettimeofday(&end_time, NULL);
    double processing_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1e6;

    // Print MD5 hash
    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5_hash[i]);
    }
    printf("\n");

    printf("Lines processed: %zu\n", lines);
    printf("Processing time: %.6f seconds\n", processing_time);

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("Error opening output file");
            return 3;
        }
        fprintf(out, "Lines processed: %zu\n", lines);
        fprintf(out, "Processing time: %.6f seconds\n", processing_time);
        fclose(out);
    }

    return 0;
}
