#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);
        free(array);
    }
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Out of capacity
    }

    array->data[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

void clear_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        array->size = 0;
        pthread_mutex_unlock(&array->mutex);
    }
}
