```python
import hashlib
import threading

def compute_md5_hash(file_path):
    try:
        with open(file_path, 'rb') as f:
            md5_hash = hashlib.md5()
            while chunk := f.read(4096):  # Read in chunks of 4KB to handle large files
                md5_hash.update(chunk)
            return md5_hash.hexdigest()
    except FileNotFoundError:
        print(f"File not found: {file_path}")
    except PermissionError:
        print(f"Permission denied for file: {file_path}")
    except Exception as e:
        print(f"An error occurred: {e}")

def hash_files_concurrently(file_paths):
    results = {}
    threads = []

    def thread_function(file_path):
        result_hash = compute_md5_hash(file_path)
        if result_hash is not None:
            results[file_path] = result_hash

    for file_path in file_paths:
        thread = threading.Thread(target=thread_function, args=(file_path,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return results
