```python
import hashlib
import os

def computeMD5Hash(file_path):
    hasher = hashlib.md5()
    chunk_size = 8192  # Read file in chunks to handle large files efficiently
    try:
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()
    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
        return None
    except PermissionError:
        print(f"Error: Permission denied to read file '{file_path}'.")
        return None
    except Exception as e:
        print(f"An error occurred while reading file '{file_path}': {e}")
        return None

# Example usage
if __name__ == "__main__":
    file_path = "example.txt"
    md5_hash = computeMD5Hash(file_path)
    if md5_hash is not None:
        print(f"MD5 Hash: {md5_hash}")
