#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char name[50];
    unsigned long packets;
    double error_rate;
} NICStats;

void parseNetworkConfig(const char *config_file, NICStats *nic_stats, int max_nics) {
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Failed to open configuration file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Skip comments
        if (line[0] == '#' || line[0] == '\n') continue;

        NICStats nic;
        int result = sscanf(line, "%s %lu %lf", nic.name, &nic.packets, &nic.error_rate);
        if (result != 3) {
            fprintf(stderr, "Invalid configuration entry: %s\n", line);
            continue;
        }

        // Populate the NIC statistics array
        for (int i = 0; i < max_nics; ++i) {
            if (strcmp(nic_stats[i].name, "") == 0) {
                nic_stats[i] = nic;
                break;
            }
        }
    }

    fclose(fp);
}
