```cpp
#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <fstream>

class WorkerPool {
public:
    WorkerPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~WorkerPool() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([f, args...] { f(args...); });
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
};

void monitorResourceUsage(WorkerPool& pool, size_t interval) {
    while (!pool.stop) {
        // Simulate resource monitoring
        std::this_thread::sleep_for(std::chrono::seconds(interval));
        // Log CPU usage and memory consumption here
        std::cout << "Monitoring resource usage..." << std::endl;
    }
}

int main() {
    size_t numThreads = 4;
    WorkerPool pool(numThreads);
    std::thread monitor(monitorResourceUsage, std::ref(pool), 5); // Log every 5 seconds

    for (size_t i = 0; i < 10; ++i) {
        pool.enqueue([]() {
            // Simulate task processing
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        });
    }

    monitor.join();
    return 0;
}
