def computeMD5Hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):  # Read in manageable chunks
            hasher.update(chunk)
    return hasher.hexdigest()

# Example usage:
file_hash = computeMD5Hash('large_file.txt')
print(f"MD5 hash of the file: {file_hash}")
