LTE_DL_FRAME* init_and_populate_frames(int *frame_count, int threshold) {
    LTE_DL_FRAME *frames = (LTE_DL_FRAME*)malloc(MAX_FRAMES * sizeof(LTE_DL_FRAME));
    if (!frames) return NULL;
    int current_size = MAX_FRAMES;

    // Populate frames logic here

    *frame_count = 0; // Initialize frame count
    while (*frame_count < threshold) {
        // Add new frames and manage reallocation as needed
        if (*frame_count >= current_size - MIN_REALLOC_SIZE) {
            LTE_DL_FRAME *new_frames = (LTE_DL_FRAME*)realloc(frames, (current_size + MIN_REALLOC_SIZE) * sizeof(LTE_DL_FRAME));
            if (!new_frames) {
                free(frames);
                return NULL;
            }
            frames = new_frames;
            current_size += MIN_REALLOC_SIZE;
        }
        // Populate new frame
        (*frame_count)++;
    }

    return frames;
}

void report_frame_count(int frame_count, int interval) {
    static int last_reported = 0;
    if (frame_count % interval == 0 && frame_count != last_reported) {
        printf("Frame count: %d\n", frame_count);
        last_reported = frame_count;
    }
}

