typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_crc_array() {
    NFAPI_CRC_ARRAY* array = (NFAPI_CRC_ARRAY*)malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) {
        log_error("Memory allocation failed for NFAPI_CRC_ARRAY");
        return NULL;
    }
    pthread_mutex_init(&array->mutex, NULL);
    array->count = 0;
    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY* array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_crc_indication(NFAPI_CRC_ARRAY* array, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti) {
    if (!array) {
        log_error("Invalid NFAPI_CRC_ARRAY pointer");
        return -1;
    }

    pthread_mutex_lock(&array->mutex);
    if (array->count >= MAX_ELEMENTS) {
        log_warning("Maximum number of elements reached");
        pthread_mutex_unlock(&array->mutex);
        return -2;
    }

    array->data[array->count].rx_ue_information_tag = ue_info;
    array->data[array->count].rnti = rnti;
    array->data[array->count].crc_indication_rel8_tag.crc_flag = rand() % 2; // Random CRC flag
    array->count++;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int load_resource_bundle(const char* path, void** bundle) {
    FILE* file = fopen(path, "r");
    if (!file) {
        log_error("Failed to open resource file: %s", path);
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *bundle = malloc(size + 1);
    if (!*bundle) {
        log_error("Memory allocation failed for resource bundle");
        fclose(file);
        return -2;
    }

    fread(*bundle, 1, size, file);
    (*bundle)[size] = '\0';
    fclose(file);

    return size;
}
