#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>

#define MAX_INPUT_SIZE 1024

void print_usage() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  --help        Display this help message\n");
    printf("  -cs          Compress the output lines using a configurable compression algorithm\n");
    printf("  -o output_file Redirect the output to a specified file instead of stdout\n");
    printf("  -l limit_lines Limit the number of lines processed from the input file\n");
}

void process_file(const char* filename, int compress_output, const char* output_file, int limit_lines) {
    FILE* input = fopen(filename, "r");
    if (!input) {
        perror("Error opening input file");
        return;
    }

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    // Process the file in chunks
    char buffer[MAX_INPUT_SIZE];
    int line_count = 0;
    while (fgets(buffer, sizeof(buffer), input) != NULL && (limit_lines == -1 || line_count < limit_lines)) {
        if (compress_output) {
            // Implement compression logic here
            printf("Compressed: %s", buffer);
        } else {
            printf("%s", buffer);
        }
        line_count++;
    }

    fclose(input);

    gettimeofday(&end_time, NULL);
    long seconds = end_time.tv_sec - start_time.tv_sec;
    long microseconds = end_time.tv_usec - start_time.tv_usec;
    double elapsed_time = seconds + microseconds * 1e-6;

    printf("Processing time: %.6f seconds\n", elapsed_time);
}

int main(int argc, char* argv[]) {
    int compress_output = 0;
    const char* output_file = NULL;
    int limit_lines = -1;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            compress_output = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limit_lines = atoi(argv[++i]);
        }
    }

    if (argc <= 1) {
        print_usage();
        return 0;
    }

    process_file(argv[argc - 1], compress_output, output_file, limit_lines);

    return 0;
}
