#define MAX_NICS 10000

typedef struct {
    char name[256];
    int packetCounter;
    float errorRate;
} NICStats;

NICStats *nicStatsArray[MAX_NICS];
int nicCount = 0;
pthread_mutex_t nicMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeNICStats(int maxNics) {
    if (maxNics > MAX_NICS || maxNics <= 0) {
        fprintf(stderr, "Invalid number of NICs.\n");
        return;
    }

    for (int i = 0; i < maxNics; i++) {
        nicStatsArray[i] = malloc(sizeof(NICStats));
        if (!nicStatsArray[i]) {
            fprintf(stderr, "Memory allocation failed for NICStats.\n");
            return;
        }
        pthread_mutex_lock(&nicMutex);
        strcpy(nicStatsArray[i]->name, "NIC");
        nicStatsArray[i]->packetCounter = rand() % 100000;
        nicStatsArray[i]->errorRate = (float)(rand() % 100) / 100.0;
        pthread_mutex_unlock(&nicMutex);
    }
    nicCount = maxNics;
}

void* updateNICStats(void *arg) {
    int index = *(int*)arg;
    if (index < 0 || index >= nicCount) {
        fprintf(stderr, "Invalid NIC index.\n");
        return NULL;
    }

    pthread_mutex_lock(&nicMutex);
    nicStatsArray[index]->packetCounter += rand() % 100;
    nicStatsArray[index]->errorRate = (float)(rand() % 100) / 100.0;
    pthread_mutex_unlock(&nicMutex);

    return NULL;
}

int findLargestInt(int *array, int size, int filterNegative) {
    if (!array || size <= 0) {
        fprintf(stderr, "Invalid input array.\n");
        return -1;
    }

    int largest = filterNegative ? INT_MIN : array[0];
    for (int i = 0; i < size; i++) {
        if (filterNegative && array[i] < 0) continue;
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void cleanNICStats() {
    pthread_mutex_lock(&nicMutex);
    for (int i = 0; i < nicCount; i++) {
        free(nicStatsArray[i]);
    }
    pthread_mutex_unlock(&nicMutex);
}
