import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def computeMD5Hash(file_path):
    hasher = hashlib.md5()
    chunk_size = 4096
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def hash_files_concurrently(file_paths):
    results = {}
    with ThreadPoolExecutor() as executor:
        future_to_file = {executor.submit(computeMD5Hash, path): path for path in file_paths}
        for future in as_completed(future_to_file):
            path = future_to_file[future]
            try:
                hash_value = future.result()
                results[path] = hash_value
            except Exception as e:
                print(f"An error occurred while hashing {path}: {e}")
    return results

# Example usage
file_paths = ['path/to/file1', 'path/to/file2']
hash_results = hash_files_concurrently(file_paths)
print(hash_results)
