typedef struct QueueManager {
    TaskStructure* tasks;
    int front, rear;
    int size;
    int capacity;
    pthread_mutex_t lock;
} QueueManager;

QueueManager* initializeQueueManager(int capacity) {
    QueueManager* manager = (QueueManager*)malloc(sizeof(QueueManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for QueueManager\n");
        return NULL;
    }

    manager->tasks = (TaskStructure*)calloc(capacity, sizeof(TaskStructure));
    if (!manager->tasks) {
        free(manager);
        fprintf(stderr, "Memory allocation failed for task array\n");
        return NULL;
    }

    manager->front = manager->rear = -1;
    manager->size = 0;
    manager->capacity = capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

