```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <chrono>

struct Task {
    int priority;
    // Add other fields as needed
};

class TaskQueueManager {
public:
    TaskQueueManager(int capacity, bool enableLogging = false)
        : queue(capacity), enableLogging(enableLogging) {
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back(&TaskQueueManager::workerThread, this);
        }
    }

    ~TaskQueueManager() {
        stop.store(true);
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void enqueue(const Task& task) {
        std::lock_guard<std::mutex> lock(queueMutex);
        queue.push_back(task);
        condition.notify_one();
    }

private:
    std::vector<Task> queue;
    std::vector<std::thread> workerThreads;
    std::atomic<bool> stop{false};
    std::mutex queueMutex;
    bool enableLogging;

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return !queue.empty() || stop.load(); });

            if (stop.load()) break;

            Task task = queue.front();
            queue.erase(queue.begin());
            lock.unlock();

            // Process the task
        }
    }
};

// Add other functions for managing resource usage and graceful shutdown as needed
