#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char interfaceName[256];
    unsigned long packetCounter;
    double errorRate;
} NICStat;

int parseNetworkConfig(const char* configFilePath, NICStat* nicStats, int maxNICs) {
    FILE* file = fopen(configFilePath, "r");
    if (file == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    char line[256];
    int index = 0;

    while (fgets(line, sizeof(line), file) != NULL && index < maxNICs) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        char interfaceName[256];
        unsigned long packetCounter;
        double errorRate;

        if (sscanf(line, "%255s %lu %lf", interfaceName, &packetCounter, &errorRate) != 3) {
            fprintf(stderr, "Invalid format in configuration file\n");
            fclose(file);
            return -1;
        }

        strncpy(nicStats[index].interfaceName, interfaceName, sizeof(nicStats[index].interfaceName));
        nicStats[index].packetCounter = packetCounter;
        nicStats[index].errorRate = errorRate;

        index++;
    }

    fclose(file);

    if (index == 0) {
        fprintf(stderr, "No valid entries in configuration file\n");
        return -1;
    }

    return index;
}
