#define MAX_INTERFACES 1000
#define MIN_PACKETS 100
#define MAX_PACKETS 100000
#define MIN_ERRORS 1
#define MAX_ERRORS 1000
#define MIN_BYTES 1024
#define MAX_BYTES 1000000
#define MIN_LATENCY 1
#define MAX_LATENCY 100

typedef struct {
    char interface_name[32];
    int packets;
    int errors;
    int bytes_sent;
    int bytes_received;
    int latency;
} NicStats;

int validate_interface_name(const char *name) {
    if (name == NULL || name[0] == '\0') return 0;
    if (!isalpha(name[0])) return 0;
    for (const char *p = &name[1]; *p != '\0'; p++) {
        if (!(isalnum(*p) || *p == '-')) return 0;
    }
    return 1;
}

int initialize_nic_stats(NicStats **stats, int num_interfaces) {
    if (num_interfaces <= 0 || num_interfaces > MAX_INTERFACES) {
        printf("Invalid number of interfaces: %d\n", num_interfaces);
        return -1;
    }

    NicStats *new_stats = realloc(*stats, num_interfaces * sizeof(NicStats));
    if (new_stats == NULL) {
        printf("Memory allocation failed for %d NIC stats\n", num_interfaces);
        return -2;
    }

    srand(time(NULL));
    for (int i = 0; i < num_interfaces; i++) {
        snprintf(new_stats[i].interface_name, sizeof(new_stats[i].interface_name),
                 "eth%d", i + 1);
        new_stats[i].packets = rand() % (MAX_PACKETS - MIN_PACKETS + 1) + MIN_PACKETS;
        new_stats[i].errors = rand() % (MAX_ERRORS - MIN_ERRORS + 1) + MIN_ERRORS;
        new_stats[i].bytes_sent = rand() % (MAX_BYTES - MIN_BYTES + 1) + MIN_BYTES;
        new_stats[i].bytes_received = rand() % (MAX_BYTES - MIN_BYTES + 1) + MIN_BYTES;
        new_stats[i].latency = rand() % (MAX_LATENCY - MIN_LATENCY + 1) + MIN_LATENCY;
    }

    *stats = new_stats;
    return num_interfaces;
}

int main() {
