    int num_interfaces = 500;

    int result = initialize_nic_stats(&nic_stats, num_interfaces);
    if (result < 0) {
        printf("Failed to initialize NIC stats\n");
        exit(EXIT_FAILURE);
    }

    // Use the nic_stats array for further processing...

    free(nic_stats);
    return 0;
}
