int add_stage(DataProcessor **pipeline, int *stage_count, const char *config_path) {
    DataProcessor *new_processor = malloc(sizeof(DataProcessor));
    if (!new_processor) return 1; // Return non-zero for memory allocation failure

    if (parse_config_file(config_path, &new_processor)) {
        free(new_processor);
        return 2; // Return non-zero for configuration parsing failure
    }

    initialize_stage(new_processor);

    pipeline[*stage_count] = new_processor;
    (*stage_count)++;
    return 0; // Return 0 for success
}

// Function to remove a stage from the pipeline
void remove_stage(DataProcessor **pipeline, int *stage_count, int index) {
    if (index < 0 || index >= *stage_count) return;

    free(pipeline[index]);
    memmove(&pipeline[index], &pipeline[index + 1], (*stage_count - index - 1) * sizeof(DataProcessor*));
    (*stage_count)--;
}

// Function to initialize the data pipeline
int initialize_data_pipeline(DataProcessor ***pipeline, int *stage_count, const char **config_paths, int config_count) {
    *pipeline = malloc(config_count * sizeof(DataProcessor*));
    if (!(*pipeline)) return 1; // Return non-zero for memory allocation failure

    *stage_count = 0;
    for (int i = 0; i < config_count; i++) {
        if (add_stage(*pipeline, stage_count, config_paths[i])) {
            free_pipeline(*pipeline, stage_count);
            return 2; // Return non-zero for initialization failure
        }
    }

    return 0; // Return 0 for success
}

// Function to free the pipeline resources
void free_pipeline(DataProcessor **pipeline, int *stage_count) {
    for (int i = 0; i < *stage_count; i++) {
        free(pipeline[i]);
    }
    free(pipeline);
    *stage_count = 0;
}
