#define MAX_DEVICE_NAME_LEN 50
#define MAX_INTERFACE_NAME_LEN 20

typedef struct {
    char name[MAX_DEVICE_NAME_LEN];
    double read_speed;
    double write_speed;
    uint64_t bytes_transferred;
    uint32_t errors;
} StorageDeviceMetadata;

typedef struct {
    char name[MAX_INTERFACE_NAME_LEN];
    uint64_t packets_sent;
    uint64_t packets_received;
    uint64_t bytes_sent;
    uint64_t bytes_received;
    double latency;
} NICStats;

int validate_device_name(const char *name) {
    for (size_t i = 0; name[i]; ++i) {
        if (!isalnum(name[i]) && name[i] != '-') return 0;
    }
    return 1;
}

int validate_interface_name(const char *name) {
    if (name[0] == '\0' || !isalpha(name[0])) return 0;
    for (size_t i = 1; name[i]; ++i) {
        if (!isalnum(name[i]) && name[i] != '-') return 0;
    }
    return 1;
}

int initialize_storage_and_nic_stats(StorageDeviceMetadata **storage_devices, NICStats **nic_stats,
                                      size_t num_devices, size_t num_interfaces) {
    *storage_devices = (StorageDeviceMetadata *)malloc(num_devices * sizeof(StorageDeviceMetadata));
    *nic_stats = (NICStats *)malloc(num_interfaces * sizeof(NICStats));

    if (*storage_devices == NULL || *nic_stats == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*storage_devices);
        free(*nic_stats);
        return -1;
    }

    for (size_t i = 0; i < num_devices; ++i) {
        memset(&(*storage_devices)[i], 0, sizeof(StorageDeviceMetadata));
        snprintf((*storage_devices)[i].name, MAX_DEVICE_NAME_LEN, "device-%zu", i);
        (*storage_devices)[i].read_speed = (double)(rand() % 100 + 50); // 50-149 MB/s
        (*storage_devices)[i].write_speed = (double)(rand() % 100 + 50); // 50-149 MB/s
        (*storage_devices)[i].bytes_transferred = rand() % 100000; // up to 99999 bytes
        (*storage_devices)[i].errors = rand() % 10; // up to 9 errors
    }

    for (size_t i = 0; i < num_interfaces; ++i) {
        memset(&(*nic_stats)[i], 0, sizeof(NICStats));
        snprintf((*nic_stats)[i].name, MAX_INTERFACE_NAME_LEN, "interface-%zu", i);
        (*nic_stats)[i].packets_sent = rand() % 1000; // up to 999 packets
        (*nic_stats)[i].packets_received = rand() % 1000; // up to 999 packets
        (*nic_stats)[i].bytes_sent = rand() % 100000; // up to 99999 bytes
        (*nic_stats)[i].bytes_received = rand() % 100000; // up to 99999 bytes
        (*nic_stats)[i].latency = (double)(rand() % 100) / 100.0; // 0-0.99 seconds
    }

    return 0;
}

int update_storage_stats(StorageDeviceMetadata *storage_devices, size_t num_devices) {
    for (size_t i = 0; i < num_devices; ++i) {
        if (storage_devices[i].read_speed > 149 || storage_devices[i].write_speed > 149 ||
            storage_devices[i].bytes_transferred > 99999 || storage_devices[i].errors > 9) {
            // Simulate stress test
            storage_devices[i].read_speed *= 0.8; // Reduce read speed by 20%
            storage_devices[i].write_speed *= 0.8; // Reduce write speed by 20%
            if (storage_devices[i].errors < 9) ++storage_devices[i].errors;
        }
    }
    return 0;
}

int update_nic_stats(NICStats *nic_stats, size_t num_interfaces) {
    for (size_t i = 0; i < num_interfaces; ++i) {
        if (nic_stats[i].packets_sent > 999 || nic_stats[i].packets_received > 999 ||
            nic_stats[i].bytes_sent > 99999 || nic_stats[i].bytes_received > 99999 ||
            nic_stats[i].latency > 0.99) {
            // Simulate stress test
            nic_stats[i].packets_sent *= 0.8; // Reduce packets sent by 20%
            nic_stats[i].packets_received *= 0.8; // Reduce packets received by 20%
            if (nic_stats[i].errors < 9) ++nic_stats[i].errors;
        }
    }
    return 0;
}

int main() {
    StorageDeviceMetadata *storage_devices = NULL;
    NICStats *nic_stats = NULL;
    size_t num_devices = 5, num_interfaces = 3;

    if (initialize_storage_and_nic_stats(&storage_devices, &nic_stats, num_devices, num_interfaces) != 0) {
        return -1;
    }

    // Simulate stress test
    update_storage_stats(storage_devices, num_devices);
    update_nic_stats(nic_stats, num_interfaces);

    // Print updated statistics
    for (size_t i = 0; i < num_devices; ++i) {
        printf("Storage Device %s: Read Speed %.2f MB/s, Write Speed %.2f MB/s, Bytes Transferred %zu, Errors %u\n",
               storage_devices[i].name, storage_devices[i].read_speed, storage_devices[i].write_speed,
               storage_devices[i].bytes_transferred, storage_devices[i].errors);
    }

    for (size_t i = 0; i < num_interfaces; ++i) {
        printf("NIC %s: Packets Sent %zu, Packets Received %zu, Bytes Sent %zu, Bytes Received %zu, Latency %.2f sec\n",
               nic_stats[i].name, nic_stats[i].packets_sent, nic_stats[i].packets_received,
               nic_stats[i].bytes_sent, nic_stats[i].bytes_received, nic_stats[i].latency);
    }

    free(storage_devices);
    free(nic_stats);

    return 0;
}
