        fprintf(stderr, "Invalid array size\n");
        return NULL;
    }

    ProcessMonitoringStructure* array = (ProcessMonitoringStructure*)malloc(size * sizeof(ProcessMonitoringStructure));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Populate the array with random values for demonstration purposes
    for (int i = 0; i < size; i++) {
        array[i].pid = rand() % 10000 + 1;
        array[i].cpu_usage = (float)rand() / RAND_MAX * 100.0f;
        array[i].memory_consumption = (double)rand() / RAND_MAX * 1024.0;
    }

    // Examine the filename and determine the number of digits and file type for modification
    char* extension = strrchr(filename, '.');
    if (!extension) {
        fprintf(stderr, "Invalid filename\n");
        free(array);
        return NULL;
    }

    int num_digits = 0;
    while (*filename <= '9' && *filename >= '0') {
        num_digits++;
        filename++;
    }

    // Alter the filename's extension accordingly
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%.*s_%s", num_digits, filename - num_digits, option);

    // Implement an operation based on the specified command line option using the OpenSSL library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(array);
        return NULL;
