ProcessMonitoringStruct* initialize_monitoring_array(int size, char* filename, const char* operation) {
    // Memory allocation and error handling
    ProcessMonitoringStruct* array = (ProcessMonitoringStruct*)malloc(size * sizeof(ProcessMonitoringStruct));
    if (array == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

