    for (int i = 0; i < size; i++) {
        array[i].pid = rand() % 1000 + 1;
        array[i].cpu_usage = ((float)rand() / RAND_MAX) * 100.0f;
        array[i].memory_consumption = (double)(rand() % 1024) * 1024.0;
        array[i].io_statistics = rand();
    }

    // Modify filename based on the number of digits and file type
    int num_digits = snprintf(NULL, 0, "%d", size);
    char* new_filename = (char*)malloc(strlen(filename) + num_digits + 1);
    if (new_filename == NULL) {
        perror("Memory allocation failed");
        free(array);
        return NULL;
    }
    sprintf(new_filename, "%s_%d.%s", filename, size, "mon");

    // Perform operation using OpenSSL library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "OpenSSL error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(array);
        free(new_filename);
        return NULL;
    }
    int result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)"0123456789abcdef0123456789abcdef", (unsigned char*)"0123456789abcdef");
    if (!result) {
        fprintf(stderr, "OpenSSL error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        EVP_CIPHER_CTX_free(ctx);
        free(array);
        free(new_filename);
        return NULL;
    }

    // Return the pointer to the cipher object
    return array;
}

