    const char* operation = "encrypt";
    ProcessMonitoringStruct* monitoring_array = initialize_monitoring_array(MAX_PROCESSES, filename, operation);
    if (monitoring_array != NULL) {
        // Free the allocated memory when done
        free(monitoring_array);
        free(filename);
    }
    return 0;
}
