EVP_CIPHER_CTX* modify_filename_and_perform_op(char* filename, const char* op, const EVP_CIPHER* cipher_type) {
    // Examine the filename to determine number of digits and file type
    int num_digits = 0;
    for (int i = strlen(filename) - 1; i >= 0 && isdigit(filename[i]); i--) {
        num_digits++;
    }
    if (num_digits > 3 || strcmp(&filename[strlen(filename) - 4], ".txt") != 0) {
        fprintf(stderr, "Invalid filename\n");
        return NULL;
