    // Alter the filename's extension
    char new_filename[256];
    strcpy(new_filename, filename);
    strcat(new_filename, "_processed.txt");

    // Perform OpenSSL operation based on command line option
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }
