#include <string.h>

#define MAX_DEVICE_NAME_LEN 32
#define MAX_INTERFACE_NAME_LEN 16

typedef struct {
    char device_name[MAX_DEVICE_NAME_LEN];
    int read_speed; // in MB/s
    int write_speed; // in MB/s
    long packets_read;
    long packets_written;
    double error_rate;
    unsigned long bytes_read;
    unsigned long bytes_written;
    double latency; // in milliseconds
} StorageMetadata;

typedef struct {
    char interface_name[MAX_INTERFACE_NAME_LEN];
    int rx_packets;
    int tx_packets;
    int errors;
    unsigned long bytes_rx;
    unsigned long bytes_tx;
    double rx_rate; // in Mbps
    double tx_rate; // in Mbps
} NICStatistics;

int validate_device_name(const char *name) {
    if (name[0] == '\0' || !isalpha(name[0])) return 0;
    for (size_t i = 1; i < strlen(name); ++i) {
        if (!isalnum(name[i]) && name[i] != '-') return 0;
    }
    return 1;
}

int validate_interface_name(const char *name) {
    if (name[0] == '\0' || !isalpha(name[0])) return 0;
    for (size_t i = 1; i < strlen(name); ++i) {
        if (!isalnum(name[i])) return 0;
    }
    return 1;
}

int generateMD5AndInitializeStorage(int num_devices, int num_interfaces,
                                  StorageMetadata **storage, NICStatistics **nic_stats) {
    *storage = (StorageMetadata *)malloc(num_devices * sizeof(StorageMetadata));
    if (*storage == NULL) {
        fprintf(stderr, "Memory allocation failed for storage metadata.\n");
        return -1;
    }

    *nic_stats = (NICStatistics *)malloc(num_interfaces * sizeof(NICStatistics));
    if (*nic_stats == NULL) {
        fprintf(stderr, "Memory allocation failed for NIC statistics.\n");
        free(*storage);
        return -1;
    }

    for (int i = 0; i < num_devices; ++i) {
        snprintf((*storage)[i].device_name, MAX_DEVICE_NAME_LEN, "Device-%d", i + 1);
        (*storage)[i].read_speed = rand() % 100;
        (*storage)[i].write_speed = rand() % 100;
        (*storage)[i].packets_read = rand() % 100000;
        (*storage)[i].packets_written = rand() % 100000;
        (*storage)[i].error_rate = (double)(rand() % 100) / 100.0;
        (*storage)[i].bytes_read = rand() % 100000000;
        (*storage)[i].bytes_written = rand() % 100000000;
        (*storage)[i].latency = (double)(rand() % 100) / 10.0;
    }

    for (int i = 0; i < num_interfaces; ++i) {
        snprintf((*nic_stats)[i].interface_name, MAX_INTERFACE_NAME_LEN, "Interface-%d", i + 1);
        (*nic_stats)[i].rx_packets = rand() % 100000;
        (*nic_stats)[i].tx_packets = rand() % 100000;
        (*nic_stats)[i].errors = rand() % 1000;
        (*nic_stats)[i].bytes_rx = rand() % 100000000;
        (*nic_stats)[i].bytes_tx = rand() % 100000000;
        (*nic_stats)[i].rx_rate = (double)(rand() % 100) / 1.0;
        (*nic_stats)[i].tx_rate = (double)(rand() % 100) / 1.0;
    }

    return 0;
}

int main() {
    int num_devices = 3;
    int num_interfaces = 2;

    StorageMetadata *storage;
    NICStatistics *nic_stats;

