    if (interface_id >= 0 && interface_id < MAX_INTERFACES) {
        network_config.interfaces[interface_id].packet_counter += rand() % 1000;
        network_config.interfaces[interface_id].error_rate = (double)(rand() % 200) / 100.0;
        network_config.interfaces[interface_id].byte_count += rand() % 1000000L;
        network_config.interfaces[interface_id].latency += (double)(rand() % 1000) / 100.0;
    }
    pthread_mutex_unlock(&config_mutex);
}

