    unsigned long packetCounters;
    double errorRates;
    unsigned long byteCounts;
    int latency;
} DeviceMetadata;

typedef struct {
    char interfaceName[256];
    float performanceMetrics;
    unsigned long packetCounters;
    double errorRates;
    unsigned long byteCounts;
    int latency;
} NetworkInterfaceData;

typedef enum { DEVICE, NETWORK } MetricType;

typedef struct {
    void (*callback)(void*);
    void* userData;
    pthread_mutex_t mutex;
} MonitoringSystem;

DeviceMetadata** initializeSystemMetrics(int numDevices, int numInterfaces) {
    // Allocate memory for devices and interfaces
    DeviceMetadata** deviceMetadatas = (DeviceMetadata**)malloc(numDevices * sizeof(DeviceMetadata*));
    NetworkInterfaceData** interfaceDatas = (NetworkInterfaceData**)malloc(numInterfaces * sizeof(NetworkInterfaceData*));

    if (deviceMetadatas == NULL || interfaceDatas == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numDevices; ++i) {
        deviceMetadatas[i] = (DeviceMetadata*)malloc(sizeof(DeviceMetadata));
        if (deviceMetadatas[i] == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }
    }

    for (int i = 0; i < numInterfaces; ++i) {
        interfaceDatas[i] = (NetworkInterfaceData*)malloc(sizeof(NetworkInterfaceData));
        if (interfaceDatas[i] == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }
    }

    // Initialize mutex for concurrency control
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Setup monitoring system callback and data
    MonitoringSystem ms = {reportPerformanceMetrics, deviceMetadatas, mutex};

    // Return pointers to dynamically allocated memory
    return (DeviceMetadata**)deviceMetadatas;
}

void reportPerformanceMetrics(void* userData) {
    DeviceMetadata** deviceMetadatas = (DeviceMetadata**)userData;
    pthread_mutex_t* mutex = &((MonitoringSystem*)userData)->mutex;

    // Lock the mutex for critical section
    pthread_mutex_lock(mutex);

    for (int i = 0; i < numDevices; ++i) {
        printf("Device %d: Performance Metrics - %.2f\n", i, deviceMetadatas[i]->performanceMetrics);
    }

    for (int i = 0; i < numInterfaces; ++i) {
        printf("Interface %d: Performance Metrics - %.2f\n", i, interfaceDatas[i]->performanceMetrics);
    }

    // Unlock the mutex
    pthread_mutex_unlock(mutex);
}

// Function to free allocated memory and clean up resources
void cleanup(DeviceMetadata** deviceMetadatas, NetworkInterfaceData** interfaceDatas) {
    for (int i = 0; i < numDevices; ++i) {
        free(deviceMetadatas[i]);
    }
    for (int i = 0; i < numInterfaces; ++i) {
        free(interfaceDatas[i]);
    }
    free(deviceMetadatas);
    free(interfaceDatas);
}
