#define MAX_SERVICE_NAME_LENGTH 256

typedef struct {
    char name[MAX_SERVICE_NAME_LENGTH];
    int cpu_utilization;
    int memory_usage;
    int io_throughput;
    int error_rate;
} Service;

typedef struct {
    Service *services;
    size_t count;
    size_t capacity;
} ServiceCollection;

bool is_valid_service_name(const char *name) {
    while (*name) {
        if (!isalnum(*name) && *name != '_') return false;
        name++;
    }
    return true;
}

ServiceCollection* create_service_collection(size_t initial_capacity) {
    ServiceCollection *collection = (ServiceCollection*)malloc(sizeof(ServiceCollection));
    if (!collection) return NULL;

    collection->services = (Service*)malloc(initial_capacity * sizeof(Service));
    if (!collection->services) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    return collection;
}

bool add_service(ServiceCollection *collection, const char *name, int cpu_utilization, int memory_usage, int io_throughput, int error_rate) {
    if (collection->count >= collection->capacity) {
        Service *new_services = (Service*)realloc(collection->services, collection->capacity * 2 * sizeof(Service));
        if (!new_services) return false;
        collection->services = new_services;
        collection->capacity *= 2;
    }

    Service *service = &collection->services[collection->count];
    strncpy(service->name, name, MAX_SERVICE_NAME_LENGTH - 1);
    service->cpu_utilization = cpu_utilization;
    service->memory_usage = memory_usage;
    service->io_throughput = io_throughput;
    service->error_rate = error_rate;

    collection->count++;
    return true;
}

void destroy_service_collection(ServiceCollection *collection) {
    free(collection->services);
    free(collection);
}
