        metrics[i].device_id = i + 1;
        metrics[i].throughput_rate = rand() % 1000 / 10.0; // Random throughput between 0 and 99.9 Mbps
        metrics[i].latency_stats = (rand() % 500) / 10.0;   // Random latency between 0 and 49.9 ms
        metrics[i].temperature = rand() % 70 + 20;         // Random temperature between 20 and 89 Celsius
    }

    return metrics;
}

