#include <time.h>

#define MAX_SESSIONS 1024

typedef struct {
    int sessionId;
    char authToken[65];
    time_t lastActivity;
    time_t expirationTime;
} UserSessionInfo;

UserSessionInfo* usiList = NULL;
int currentSize = 0;
int maxSize = MAX_SESSIONS;

void initializeUSI(int size) {
    if (size <= 0) {
        printf("Invalid size for USI list\n");
        return;
    }

    if (usiList != NULL) {
        free(usiList);
    }

    usiList = (UserSessionInfo*)malloc(size * sizeof(UserSessionInfo));
    if (usiList == NULL) {
        printf("Failed to allocate memory for USI list\n");
        return;
    }

    maxSize = size;
    currentSize = 0;
}

void addUSISession(int sessionId, const char* authToken, time_t lastActivity, time_t expirationTime) {
    if (currentSize >= maxSize) {
        printf("USI list is full\n");
        return;
    }

    usiList[currentSize].sessionId = sessionId;
    snprintf(usiList[currentSize].authToken, sizeof(usiList[currentSize].authToken), "%s", authToken);
    usiList[currentSize].lastActivity = lastActivity;
    usiList[currentSize].expirationTime = expirationTime;
    currentSize++;
}

void updateUSISession(int sessionId, const char* authToken, time_t lastActivity, time_t expirationTime) {
    for (int i = 0; i < currentSize; i++) {
        if (usiList[i].sessionId == sessionId) {
            snprintf(usiList[i].authToken, sizeof(usiList[i].authToken), "%s", authToken);
            usiList[i].lastActivity = lastActivity;
            usiList[i].expirationTime = expirationTime;
            return;
        }
    }

    printf("Session ID %d not found\n", sessionId);
}

void removeUSISession(int sessionId) {
    for (int i = 0; i < currentSize; i++) {
        if (usiList[i].sessionId == sessionId) {
            for (int j = i; j < currentSize - 1; j++) {
                usiList[j] = usiList[j + 1];
            }
            currentSize--;
            return;
        }
    }

    printf("Session ID %d not found\n", sessionId);
}

void freeUSI() {
    if (usiList != NULL) {
        free(usiList);
        usiList = NULL;
    }
}
