typedef struct {
    DeviceHealthRecord records[MAX_DEVICES];
    int size;
    int capacity;
} DHMList;

DHMList* dhm_list_init() {
    DHMList* list = (DHMList*)malloc(sizeof(DHMList));
    if (!list) {
        return NULL; // Memory allocation failed
    }
    memset(list, 0, sizeof(DHMList));
    list->capacity = MAX_DEVICES;
    return list;
}

int dhm_list_add_record(DHMList* list, DeviceHealthRecord record) {
    if (list->size >= list->capacity) {
        fprintf(stderr, "DHM List is full!\n");
        return -1; // List overflow
    }
    list->records[list->size++] = record;
    return 0;
}

void dhm_list_free(DHMList* list) {
    if (list) {
        free(list);
    }
}

int main() {
    DHMList* dhm_list = dhm_list_init();
    if (!dhm_list) {
        fprintf(stderr, "Failed to initialize DHM List!\n");
        return 1;
    }

    DeviceHealthRecord record = { .device_id = 12345, .health_code = 0, .last_temperature = 25.6f, .battery_level = 85, .last_connection = time(NULL) };
    if (dhm_list_add_record(dhm_list, record) != 0) {
        fprintf(stderr, "Failed to add record to DHM List!\n");
    }

    dhm_list_free(dhm_list);
    return 0;
}
