typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRC_LIST;

void init_crc_list(CRC_LIST* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_or_update_entry(CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == new_data.rnti) {
            // Update existing entry
            current->data = new_data;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    // Add new entry at the beginning of the list
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(CRC_LIST* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void validate_crc_indication(CRC_LIST* list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* entry = get_entry(list, rnti);
    if (entry != NULL && !validate_crc_consistency(entry)) {
        fprintf(stderr, "CRC inconsistency detected for RNTI %d\n", rnti);
        // Handle error
    }
}

void destroy_crc_list(CRC_LIST* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
}

