    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_pdu->next = NULL;
    return new_pdu;
}

void add_crc_pdu(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
