NFAPI_CRC_INDICATION_PDU_T* get_crc_pdu_by_rnti(CRC_LIST *list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
    while (temp != NULL) {
        if (temp->RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return temp;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void update_crc_pdu(CRC_LIST *list, int RNTI, int new_crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = get_crc_pdu_by_rnti(list, RNTI);
    if (pdu != NULL) {
