    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
    while (temp != NULL) {
        fwrite(temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        temp = temp->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void deserialize_crc_list(CRC_LIST *list, FILE *file) {
