```python
import hashlib
import os
from datetime import datetime
import json

def computeMD5Hash(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def calculateMetadata(hash_value, file_path):
    metadata = {
        "file_path": file_path,
        "modification_timestamp": datetime.fromtimestamp(os.path.getmtime(file_path)).isoformat(),
        "hash_value": hash_value,
        "checksum": "checksum_not_implemented",
        "digital_signature": "signature_not_implemented"
    }
    return json.dumps(metadata, indent=4)

def main():
    file_path = "example.txt"
    hash_value = computeMD5Hash(file_path)
    metadata = calculateMetadata(hash_value, file_path)
    print(metadata)

if __name__ == "__main__":
    main()
