#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_INTERFACES 1000

typedef struct {
    char name[32];
    unsigned long packets;
    double error_rate;
    double latency;
} NICStats;

NICStats *nic_stats = NULL;
int nic_count = 0;
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_nic_stats(int count) {
    pthread_mutex_lock(&stats_lock);
    if (nic_count != 0) {
        free(nic_stats);
    }

    nic_count = count;
    nic_stats = (NICStats *)malloc(nic_count * sizeof(NICStats));
    if (nic_stats == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&stats_lock);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < nic_count; i++) {
        snprintf(nic_stats[i].name, sizeof(nic_stats[i].name), "eth%d", i);
        nic_stats[i].packets = rand() % 100000;
        nic_stats[i].error_rate = (double)(rand() % 100) / 100.0;
        nic_stats[i].latency = ((double)rand() / RAND_MAX) * 100.0; // in ms
    }
    pthread_mutex_unlock(&stats_lock);
}

void update_nic_stats(NICStats *new_stats, int count) {
    pthread_mutex_lock(&stats_lock);
    if (nic_count != 0 && nic_count == count) {
        memcpy(nic_stats, new_stats, nic_count * sizeof(NICStats));
    }
    pthread_mutex_unlock(&stats_lock);
}

void aggregate_nic_stats(double *total_packets, double *average_error_rate, double *average_latency) {
    pthread_mutex_lock(&stats_lock);
    *total_packets = 0;
    *average_error_rate = 0;
    *average_latency = 0;

    for (int i = 0; i < nic_count; i++) {
        *total_packets += nic_stats[i].packets;
        *average_error_rate += nic_stats[i].error_rate;
        *average_latency += nic_stats[i].latency;
    }

    if (nic_count > 0) {
        *average_error_rate /= nic_count;
        *average_latency /= nic_count;
    }
    pthread_mutex_unlock(&stats_lock);
}

void *monitor_network(void *arg) {
    int count = *(int *)arg;
    NICStats new_stats[MAX_INTERFACES];

    while (1) {
        // Simulate network stats update
        for (int i = 0; i < count; i++) {
            new_stats[i].packets = rand() % 100000;
            new_stats[i].error_rate = (double)(rand() % 100) / 100.0;
            new_stats[i].latency = ((double)rand() / RAND_MAX) * 100.0; // in ms
        }

        update_nic_stats(new_stats, count);
        sleep(1); // Simulate periodic aggregation interval
    }
}

int main() {
    int num_interfaces = 150;

    initialize_nic_stats(num_interfaces);

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_network, &num_interfaces) != 0) {
        perror("Failed to create monitoring thread");
        return EXIT_FAILURE;
    }

    pthread_join(monitor_thread, NULL);

    free(nic_stats);
    return EXIT_SUCCESS;
}
