#include <pthread.h>

// Define structures for Network Interface Configuration (NIC) and Network Device Health Monitoring (NDHM)
typedef struct {
    int interface_id;
    long packet_counter;
    double throughput_rate;
} NIC;

typedef struct {
    int device_id;
    double error_rate;
    double latency_statistics;
    double temperature_reading;
} NDHM;

// Define a custom lock mechanism using pthreads
typedef struct {
    pthread_mutex_t mutex;
} CustomLock;

void initialize_custom_lock(CustomLock *lock) {
    pthread_mutex_init(&lock->mutex, NULL);
}

void destroy_custom_lock(CustomLock *lock) {
    pthread_mutex_destroy(&lock->mutex);
}

void acquire_lock(CustomLock *lock) {
    pthread_mutex_lock(&lock->mutex);
}

void release_lock(CustomLock *lock) {
    pthread_mutex_unlock(&lock->mutex);
}

// Function to initialize dynamic arrays of NIC and NDHM structures
int initialize_network_metrics(int num_interfaces, int num_devices, NIC **nic_array, NDHM **ndhm_array, CustomLock **nic_lock, CustomLock **ndhm_lock) {
    if (num_interfaces <= 0 || num_devices <= 0) {
        return -1; // Error: Invalid number of interfaces or devices
    }

    *nic_array = (NIC *)malloc(num_interfaces * sizeof(NIC));
    *ndhm_array = (NDHM *)malloc(num_devices * sizeof(NDHM));

    if (*nic_array == NULL || *ndhm_array == NULL) {
        free(*nic_array);
        free(*ndhm_array);
        return -2; // Error: Memory allocation failed
    }

    *nic_lock = (CustomLock *)malloc(sizeof(CustomLock));
    *ndhm_lock = (CustomLock *)malloc(sizeof(CustomLock));

    if (*nic_lock == NULL || *ndhm_lock == NULL) {
        free(*nic_array);
        free(*ndhm_array);
        free(*nic_lock);
        return -3; // Error: Memory allocation failed
    }

    initialize_custom_lock(*nic_lock);
    initialize_custom_lock(*ndhm_lock);

    srand(time(NULL)); // Seed for random number generation

    // Populate structures with random/simulated values
    for (int i = 0; i < num_interfaces; i++) {
        (*nic_array)[i].interface_id = i + 1;
        (*nic_array)[i].packet_counter = rand() % 1000000;
        (*nic_array)[i].throughput_rate = (double)(rand() % 100) / 10.0; // Random double between 0 and 9.9
    }

    for (int i = 0; i < num_devices; i++) {
        (*ndhm_array)[i].device_id = i + 1;
        (*ndhm_array)[i].error_rate = ((double)rand() / RAND_MAX); // Random double between 0 and 1
        (*ndhm_array)[i].latency_statistics = (double)(rand() % 100) / 10.0; // Random double between 0 and 9.9
        (*ndhm_array)[i].temperature_reading = ((double)rand() / RAND_MAX); // Random double between 0 and 1
    }

    return 0; // Success
}

// Example usage
int main() {
    int num_interfaces = 10;
    int num_devices = 5;
    NIC *nic_array = NULL;
    NDHM *ndhm_array = NULL;
    CustomLock *nic_lock = NULL;
    CustomLock *ndhm_lock = NULL;

    if (initialize_network_metrics(num_interfaces, num_devices, &nic_array, &ndhm_array, &nic_lock, &ndhm_lock) == 0) {
        // Use the initialized arrays and locks
        free(nic_array);
        free(ndhm_array);
        destroy_custom_lock(nic_lock);
        destroy_custom_lock(ndhm_lock);
    }

    return 0;
}
