// Define structures for Storage Device Metadata and NIC Statistics
typedef struct {
    char deviceID[50];
    double readPerformance;
    double writePerformance;
} StorageDeviceMetadata;

typedef struct {
    char interfaceID[50];
    unsigned long packetCount;
    double errorRate;
    unsigned long byteCount;
    double latency;
} NICStatistics;

// Define a structure for the data pipeline
typedef struct {
    StorageDeviceMetadata *storageMetadata;
    NICStatistics *NICStats;
    int numStages;
    pthread_mutex_t lock;
} DataPipeline;

// Function to initialize storage and NIC pipeline
DataPipeline* initializeStorageAndNICPipeline(int numDevices, int numInterfaces) {
    // Allocate memory for the data pipeline structure
    DataPipeline *pipeline = (DataPipeline *)malloc(sizeof(DataPipeline));
    if (pipeline == NULL) {
        perror("Failed to allocate memory for pipeline");
        return NULL;
    }

    // Initialize mutex
    pthread_mutex_init(&pipeline->lock, NULL);

    // Allocate and initialize storage metadata array
    pipeline->storageMetadata = (StorageDeviceMetadata *)malloc(numDevices * sizeof(StorageDeviceMetadata));
    if (pipeline->storageMetadata == NULL) {
        perror("Failed to allocate memory for storage metadata");
        free(pipeline);
        return NULL;
    }
    memset(pipeline->storageMetadata, 0, numDevices * sizeof(StorageDeviceMetadata));

    // Allocate and initialize NIC statistics array
    pipeline->NICStats = (NICStatistics *)malloc(numInterfaces * sizeof(NICStatistics));
    if (pipeline->NICStats == NULL) {
        perror("Failed to allocate memory for NIC statistics");
        free(pipeline->storageMetadata);
        free(pipeline);
        return NULL;
    }
    memset(pipeline->NICStats, 0, numInterfaces * sizeof(NICStatistics));

    // Set the number of stages
    pipeline->numStages = 1; // Assuming initial setup

    printf("Storage and NIC pipeline initialized successfully\n");
    return pipeline;
}

// Companion function to initialize NIC statistics with random values
void initializeNICStats(DataPipeline *pipeline, int numInterfaces) {
    pthread_mutex_lock(&pipeline->lock);
    for (int i = 0; i < numInterfaces; i++) {
        snprintf(pipeline->NICStats[i].interfaceID, sizeof(pipeline->NICStats[i].interfaceID), "eth%d", i);
        pipeline->NICStats[i].packetCount = rand() % 10000;
        pipeline->NICStats[i].errorRate = (double)(rand() % 100) / 100.0;
        pipeline->NICStats[i].byteCount = rand() % 1000000;
        pipeline->NICStats[i].latency = (double)(rand() % 1000) / 1000.0;
    }
    pthread_mutex_unlock(&pipeline->lock);
    printf("NIC statistics initialized successfully\n");
}

// Function to flush NIC configuration to disk asynchronously
void flushNICConfig(DataPipeline *pipeline, const char *filename) {
    // Simulate asynchronous file write operation
    pthread_t thread;
    if (pthread_create(&thread, NULL, writeToFile, (void *)pipeline->NICStats) != 0) {
        perror("Failed to create thread for file write");
    }
}

// Dummy function to simulate file writing
void *writeToFile(void *data) {
    NICStatistics *stats = (NICStatistics *)data;
    FILE *file = fopen("nic_config.txt", "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return NULL;
    }
    for (int i = 0; i < 5; i++) { // Assuming 5 interfaces
        fprintf(file, "Interface: %s, Packet Count: %lu, Error Rate: %.2f\n", stats[i].interfaceID, stats[i].packetCount, stats[i].errorRate);
    }
    fclose(file);
    pthread_exit(NULL);
}

// Example usage
int main() {
    DataPipeline *pipeline = initializeStorageAndNICPipeline(10, 5);
    if (pipeline != NULL) {
        initializeNICStats(pipeline, 5);
        flushNICConfig(pipeline, "nic_config.txt");
        // Free allocated memory when done
        free(pipeline->storageMetadata);
        free(pipeline->NICStats);
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline);
    }
    return 0;
}
