        memcpy(context->pdcp_pdus, pdcp_pdus, pdcp_pdu_count * sizeof(PDCP_PDU));
        context->pdcp_pdu_count = pdcp_pdu_count;
        context->session_status = session_status;
        ue_contexts[ue_context_count++] = context;
    } else {
        // Update existing context
        free(context->pdcp_pdus);
        context->pdcp_pdus = (PDCP_PDU*)realloc(context->pdcp_pdus, pdcp_pdu_count * sizeof(PDCP_PDU));
        if (context->pdcp_pdus == NULL) {
            perror("Failed to reallocate memory for PDCP PDUs.");
            return;
        }
        memcpy(context->pdcp_pdus, pdcp_pdus, pdcp_pdu_count * sizeof(PDCP_PDU));
        context->pdcp_pdu_count = pdcp_pdu_count;
        context->session_status = session_status;
    }
}

LTE_UE_Context* get_ue_context(int ue_id) {
    return find_ue_context(ue_id);
}

void free_all_ue_contexts() {
