#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct PDCP_PDU {
    int pdcp_pdu_id;
    // Other fields related to PDCP PDUs
} PDCP_PDU;

typedef struct LTE_UE_Context {
    int ue_id;
    PDCP_PDU *pdcp_pdus;
    int pdcp_pdu_count;
    int session_status; // 0 for inactive, 1 for active
    pthread_mutex_t mutex; // Mutex to protect this context
} LTE_UE_Context;

typedef struct LTE_UE_List {
    LTE_UE_Context **contexts;
    int size;
    int capacity;
    pthread_mutex_t list_mutex; // Mutex to protect the entire list
} LTE_UE_List;

LTE_UE_List* create_lte_ue_list() {
    LTE_UE_List *list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (list == NULL) return NULL;
    list->contexts = (LTE_UE_Context**)malloc(10 * sizeof(LTE_UE_Context*));
    if (list->contexts == NULL) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = 10;
    pthread_mutex_init(&list->list_mutex, NULL);
    return list;
}

LTE_UE_Context* create_lte_ue_context(int ue_id) {
    LTE_UE_Context *context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (context == NULL) return NULL;
    context->ue_id = ue_id;
    context->pdcp_pdus = NULL;
    context->pdcp_pdu_count = 0;
    pthread_mutex_init(&context->mutex, NULL);
    return context;
}

void add_lte_ue_context(LTE_UE_List *list, LTE_UE_Context *context) {
    pthread_mutex_lock(&list->list_mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->contexts = (LTE_UE_Context**)realloc(list->contexts, list->capacity * sizeof(LTE_UE_Context*));
    }
    list->contexts[list->size++] = context;
    pthread_mutex_unlock(&list->list_mutex);
}

LTE_UE_Context* get_lte_ue_context(LTE_UE_List *list, int ue_id) {
    for (int i = 0; i < list->size; i++) {
        pthread_mutex_lock(&list->contexts[i]->mutex);
        if (list->contexts[i]->ue_id == ue_id) {
            LTE_UE_Context *context = list->contexts[i];
            pthread_mutex_unlock(&list->contexts[i]->mutex);
            return context;
        }
        pthread_mutex_unlock(&list->contexts[i]->mutex);
    }
    return NULL;
}

void update_lte_ue_context(LTE_UE_List *list, int ue_id, int new_status) {
    for (int i = 0; i < list->size; i++) {
        pthread_mutex_lock(&list->contexts[i]->mutex);
        if (list->contexts[i]->ue_id == ue_id) {
            list->contexts[i]->session_status = new_status;
            pthread_mutex_unlock(&list->contexts[i]->mutex);
            return;
        }
        pthread_mutex_unlock(&list->contexts[i]->mutex);
    }
}

void free_lte_ue_list(LTE_UE_List *list) {
    for (int i = 0; i < list->size; i++) {
        free(list->contexts[i]);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->list_mutex);
    free(list);
}
