int load_resource_bundle(const char *path, int *num_items) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open resource file");
        return -1;
    }

    // Assuming the format is one item per line
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char *buffer = (char *)malloc(size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for resource buffer");
        fclose(file);
        return -2;
    }

    if (fread(buffer, size, 1, file) != 1) {
        perror("Failed to read resource file");
        free(buffer);
        fclose(file);
        return -3;
    }
    buffer[size] = '\0';
    fclose(file);

    *num_items = 0;
    char *token = strtok(buffer, "\n");
    while (token) {
        (*num_items)++;
        token = strtok(NULL, "\n");
    }

    free(buffer);
    return 0;
}

int main() {
    int num_items;
    if (load_resource_bundle("resource.txt", &num_items) == 0) {
        printf("Number of items in resource bundle: %d\n", num_items);
    } else {
        printf("Failed to load resource bundle\n");
    }
    return 0;
}
