#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACE_NAME_LEN 64
#define DEFAULT_ALLOC_SIZE 10

typedef struct {
    char interface_name[MAX_INTERFACE_NAME_LEN];
    unsigned long packets_sent;
    unsigned long packets_received;
    float error_rate;
    float latency_ms;
} NICStats;

typedef struct {
    NICStats *stats;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t mutex;
} NetworkMonitor;

NetworkMonitor* create_network_monitor(size_t initial_size) {
    NetworkMonitor *monitor = (NetworkMonitor*) malloc(sizeof(NetworkMonitor));
    if (!monitor) {
        fprintf(stderr, "Failed to allocate memory for NetworkMonitor\n");
        return NULL;
    }

    monitor->stats = (NICStats*) malloc(initial_size * sizeof(NICStats));
    if (!monitor->stats) {
        fprintf(stderr, "Failed to allocate memory for NICStats array\n");
        free(monitor);
        return NULL;
    }

    monitor->allocated_size = initial_size;
    monitor->used_count = 0;
    pthread_mutex_init(&monitor->mutex, NULL);

    return monitor;
}

void destroy_network_monitor(NetworkMonitor *monitor) {
    if (monitor) {
        if (monitor->stats) {
            free(monitor->stats);
        }
        pthread_mutex_destroy(&monitor->mutex);
        free(monitor);
    }
}

int add_interface_stats(NetworkMonitor *monitor, const char *interface_name, unsigned long packets_sent, unsigned long packets_received, float error_rate, float latency_ms) {
    pthread_mutex_lock(&monitor->mutex);

    if (monitor->used_count >= monitor->allocated_size) {
        size_t new_size = monitor->allocated_size + DEFAULT_ALLOC_SIZE;
        NICStats *new_stats = (NICStats*) realloc(monitor->stats, new_size * sizeof(NICStats));
        if (!new_stats) {
            fprintf(stderr, "Failed to reallocate memory for NICStats array\n");
            pthread_mutex_unlock(&monitor->mutex);
            return -1;
        }
        monitor->stats = new_stats;
        monitor->allocated_size = new_size;
    }

    strcpy(monitor->stats[monitor->used_count].interface_name, interface_name);
    monitor->stats[monitor->used_count].packets_sent = packets_sent;
    monitor->stats[monitor->used_count].packets_received = packets_received;
    monitor->stats[monitor->used_count].error_rate = error_rate;
    monitor->stats[monitor->used_count].latency_ms = latency_ms;
    monitor->used_count++;

    pthread_mutex_unlock(&monitor->mutex);
    return 0;
}

int main() {
    NetworkMonitor *monitor = create_network_monitor(DEFAULT_ALLOC_SIZE);
    if (!monitor) {
        fprintf(stderr, "Failed to initialize network monitor\n");
        return EXIT_FAILURE;
    }

    // Example usage
    add_interface_stats(monitor, "eth0", 10000, 8000, 0.05, 2.3);
    add_interface_stats(monitor, "eth1", 15000, 12000, 0.03, 1.9);

    // Clean up
    destroy_network_monitor(monitor);

    return EXIT_SUCCESS;
}
```

