#define MAX_INTERFACES 100

typedef struct {
    char name[256];
    unsigned long packets;
    double error_rate;
    double latency;
} NIC_Stats;

NIC_Stats* init_nic_stats(int count, int prealloc_factor) {
    if (count <= 0 || prealloc_factor <= 0) {
        return NULL;
    }

    int alloc_count = count * prealloc_factor;
    if (alloc_count > MAX_INTERFACES) {
        alloc_count = MAX_INTERFACES;
    }

    NIC_Stats* stats = malloc(alloc_count * sizeof(NIC_Stats));
    if (!stats) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < alloc_count; ++i) {
        snprintf(stats[i].name, sizeof(stats[i].name), "eth%d", i);
        stats[i].packets = rand() % 1000000;
        stats[i].error_rate = ((double)rand() / RAND_MAX) * 0.1;
        stats[i].latency = ((double)rand() / RAND_MAX) * 100;
    }

    return stats;
}

void free_nic_stats(NIC_Stats* stats, int count) {
    if (stats) {
        free(stats);
    }
}
