#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_QUEUE_T;

NFAPI_CRC_QUEUE_T* create_crc_queue(size_t initial_capacity) {
    NFAPI_CRC_QUEUE_T *queue = (NFAPI_CRC_QUEUE_T*)malloc(sizeof(NFAPI_CRC_QUEUE_T));
    if (queue == NULL) return NULL;

    queue->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (queue->data == NULL) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;

    if (pthread_mutex_init(&queue->lock, NULL) != 0) {
        free(queue->data);
        free(queue);
        return NULL;
    }

    return queue;
}

void destroy_crc_queue(NFAPI_CRC_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->lock);
    free(queue->data);
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int enqueue_crc_pdu(NFAPI_CRC_QUEUE_T *queue, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity == 0 ? 1 : queue->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(queue->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&queue->lock);
            return -1;
        }
        queue->data = new_data;
        queue->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG};
    queue->data[queue->size++] = new_pdu;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_crc_pdu(NFAPI_CRC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    *pdu = queue->data[0];
    memmove(queue->data, queue->data + 1, (queue->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->size--;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}
