    if (list == NULL) return NULL;

    list->data = (NFAPI_CRC_DATA*)calloc(initial_capacity, sizeof(NFAPI_CRC_DATA));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST* list) {
    if (list != NULL) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_crc_entry(NFAPI_CRC_LIST* list, NFAPI_CRC_DATA entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_DATA* newData = (NFAPI_CRC_DATA*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_DATA));
        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        list->data = newData;
        list->capacity = new_capacity;
    }

    list->data[list->count++] = entry;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

