    int port;
    ConnectionState status;
} ConnectionMetadata;

typedef struct ConnectionStateList {
    ConnectionMetadata** connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionStateList;

void initialize_connection_state_list(ConnectionStateList* list, size_t initial_capacity) {
    list->connections = (ConnectionMetadata**)malloc(initial_capacity * sizeof(ConnectionMetadata*));
    if (!list->connections) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    memset(list->connections, 0, initial_capacity * sizeof(ConnectionMetadata*));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_connection(ConnectionStateList* list, const ConnectionMetadata* metadata) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Double the capacity or handle memory allocation failure
        list->capacity *= 2;
        list->connections = (ConnectionMetadata**)realloc(list->connections, list->capacity * sizeof(ConnectionMetadata*));
        if (!list->connections) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
    }
    list->connections[list->size] = (ConnectionMetadata*)malloc(sizeof(ConnectionMetadata));
    if (!list->connections[list->size]) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }
    memcpy(list->connections[list->size], metadata, sizeof(ConnectionMetadata));
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Implement other functions as per the requirements

void cleanup_connection_state_list(ConnectionStateList* list) {
    for (size_t i = 0; i < list->size; i++) {
        free(list->connections[i]);
    }
    free(list->connections);
    pthread_mutex_destroy(&list->lock);
}
