typedef struct {
    char ip[16];
    int port;
    int status_flags;
} NetworkConnection;

typedef struct {
    NetworkConnection* connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConnectionManager;

void init_connection_manager(ConnectionManager* manager, size_t initial_capacity) {
    manager->connections = malloc(initial_capacity * sizeof(NetworkConnection));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_connection(ConnectionManager* manager, const NetworkConnection* connection) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkConnection* new_connections = realloc(manager->connections, new_capacity * sizeof(NetworkConnection));
        if (new_connections == NULL) {
            // Handle out-of-memory error
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->count++] = *connection;
    pthread_mutex_unlock(&manager->lock);
}

void* get_connection(ConnectionManager* manager, size_t index) {
    if (index >= manager->count) return NULL;
    return &manager->connections[index];
}

// Additional functions for managing connection statuses, handling payloads, monitoring memory usage,
// and providing custom attributes and event handlers can be implemented similarly.
