    pthread_mutex_lock(&lock);
    if (connection_count < MAX_CONNECTIONS) {
        connections[connection_count++] = conn;
    } else {
        printf("Connection list full\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_connection(int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < connection_count) {
        for (int i = index; i < connection_count - 1; i++) {
            connections[i] = connections[i + 1];
        }
        connection_count--;
    } else {
        printf("Invalid connection index\n");
    }
    pthread_mutex_unlock(&lock);
}

ConnectionState* get_connection(int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < connection_count) {
        return &connections[index];
    } else {
        printf("Invalid connection index\n");
        return NULL;
    }
