typedef struct {
    const SSL_METHOD *method;
    const char *cipher_suite;
    int key_size;
    const char *key_file;
    const char *cert_file;
} CryptoConfig;

SSL_CTX* initialize_crypto_session(CryptoConfig config) {
    SSL_CTX *ctx = NULL;

    // Initialize OpenSSL
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    if (config.method == NULL) {
        fprintf(stderr, "Error: No cipher method specified.\n");
        return NULL;
    }

    ctx = SSL_CTX_new(config.method);
    if (ctx == NULL) {
        fprintf(stderr, "Error: Failed to create SSL context.\n");
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Set cipher suite
    if (!SSL_CTX_set_cipher_list(ctx, config.cipher_suite)) {
        fprintf(stderr, "Error: Failed to set cipher list.\n");
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Set key and certificate files from environment variables or config
    const char *key_env = getenv("CRYPTO_KEY_FILE");
    if (config.key_file == NULL) {
        config.key_file = key_env;
    }
    const char *cert_env = getenv("CRYPTO_CERT_FILE");
    if (config.cert_file == NULL) {
        config.cert_file = cert_env;
    }

    if (config.key_file != NULL && !SSL_CTX_use_PrivateKey_file(ctx, config.key_file, SSL_FILETYPE_PEM)) {
        fprintf(stderr, "Error: Failed to load private key.\n");
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    if (config.cert_file != NULL && !SSL_CTX_use_certificate_file(ctx, config.cert_file, SSL_FILETYPE_PEM)) {
        fprintf(stderr, "Error: Failed to load certificate.\n");
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Set key size
    if (config.key_size != 0) {
        if (!SSL_CTX_set_options(ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1)) {
            fprintf(stderr, "Error: Failed to set TLS options.\n");
            ERR_print_errors_fp(stderr);
            SSL_CTX_free(ctx);
            return NULL;
        }
    }

    // Log initialization details
    printf("Crypto session initialized with method: %s, cipher suite: %s\n", config.method->name, config.cipher_suite);

    return ctx;
}
