NetworkManager* create_network_manager(int initial_capacity) {
    NetworkManager* manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    if (!manager) return NULL;

    manager->connections = (NetworkConnection**)calloc(initial_capacity, sizeof(NetworkConnection*));
    manager->devices = (StorageDevice**)calloc(initial_capacity, sizeof(StorageDevice*));
    manager->nic_stats = (NICStatistics*)calloc(initial_capacity, sizeof(NICStatistics));
    manager->stages = (PipelineStage*)calloc(initial_capacity, sizeof(PipelineStage));

    if (!manager->connections || !manager->devices || !manager->nic_stats || !manager->stages) {
        free_network_manager(manager);
        return NULL;
    }

    manager->connection_count = 0;
    manager->device_count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_network_manager(NetworkManager* manager) {
    for (int i = 0; i < manager->connection_count; i++) {
        free(manager->connections[i]);
    }
    for (int i = 0; i < manager->device_count; i++) {
        free(manager->devices[i]);
    }
    free(manager->connections);
    free(manager->devices);
    free(manager->nic_stats);
    free(manager->stages);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

