    if (manager->connection_count >= manager->capacity) {
        // Resize the arrays or handle error
    }
    manager->connections[manager->connection_count++] = connection;
    pthread_mutex_unlock(&manager->lock);
}

void add_device(NetworkManager* manager, StorageDevice* device) {
    pthread_mutex_lock(&manager->lock);
    if (manager->device_count >= manager->capacity) {
        // Resize the arrays or handle error
    }
    manager->devices[manager->device_count++] = device;
    pthread_mutex_unlock(&manager->lock);
}

void process_pipeline(NetworkManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->stage_count; i++) {
        for (int j = 0; j < manager->connection_count; j++) {
            manager->stages[i].process_connection(manager->connections[j]);
        }
        for (int k = 0; k < manager->device_count; k++) {
            manager->stages[i].process_device(manager->devices[k]);
        }
    }
    pthread_mutex_unlock(&manager->lock);
