#include <pthread.h>

typedef struct {
    int user_id;
    char auth_token[256];
    time_t expiration_time;
    void* attributes; // Pointer to dynamically allocated attributes
} UserSession;

typedef struct {
    UserSession** sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} SessionManager;

SessionManager* create_session_manager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_session_manager(SessionManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]->attributes);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void add_session(SessionManager* manager, int user_id, const char* auth_token, time_t expiration_time, void* attributes) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        UserSession** new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession*));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Handle out-of-memory error
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (!session) {
        pthread_mutex_unlock(&manager->mutex);
        return; // Handle out-of-memory error
    }
    session->user_id = user_id;
    strncpy(session->auth_token, auth_token, sizeof(session->auth_token) - 1);
    session->expiration_time = expiration_time;
    session->attributes = attributes;
    manager->sessions[manager->count++] = session;
