    RRC_RECONFIGURING
} RRC_STATE;

typedef struct {
    // PDP context details
} PDP_CONTEXT;

typedef struct {
    char address[16];
} MME_IP_ADDRESS;

typedef struct {
    // S1AP message structure
} S1AP_MESSAGE_T;

typedef struct LTE_UE_Context_Structure {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    MME_IP_ADDRESS mme_ip_address;
    S1AP_MESSAGE_T *s1ap_message;
    int qos_priority;
    struct LTE_UE_Context_Structure *next;
} LTE_UE_Context_Structure;

typedef struct {
    pthread_mutex_t mutex;
    LTE_UE_Context_Structure *head;
    size_t allocated_memory;
    size_t current_size;
} LTE_UE_Context_List;

LTE_UE_Context_List* create_lte_ue_context_list() {
    LTE_UE_Context_List *list = malloc(sizeof(LTE_UE_Context_List));
    if (list == NULL) {
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->allocated_memory = 0;
    list->current_size = 0;
    return list;
}

void destroy_lte_ue_context_list(LTE_UE_Context_List *list) {
    LTE_UE_Context_Structure *node, *next;
    pthread_mutex_lock(&list->mutex);
    for (node = list->head; node != NULL; node = next) {
        next = node->next;
        free(node);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

LTE_UE_Context_Structure* create_lte_ue_context(RRC_STATE rrc_state, PDP_CONTEXT pdp_context, MME_IP_ADDRESS mme_ip_address) {
    LTE_UE_Context_Structure *context = malloc(sizeof(LTE_UE_Context_Structure));
    if (context == NULL) {
        return NULL;
    }
    context->rrc_state = rrc_state;
    context->pdp_context = pdp_context;
    context->mme_ip_address = mme_ip_address;
    context->s1ap_message = malloc(sizeof(S1AP_MESSAGE_T));
    if (context->s1ap_message == NULL) {
        free(context);
        return NULL;
    }
    context->qos_priority = rand() % 256; // Random QoS priority
    context->next = NULL;
    return context;
}

void add_lte_ue_context(LTE_UE_Context_List *list, LTE_UE_Context_Structure *context) {
    pthread_mutex_lock(&list->mutex);
    context->next = list->head;
    list->head = context;
    list->allocated_memory += sizeof(LTE_UE_Context_Structure) + sizeof(S1AP_MESSAGE_T);
    list->current_size++;
    pthread_mutex_unlock(&list->mutex);
}

LTE_UE_Context_Structure* find_lte_ue_context(LTE_UE_Context_List *list, MME_IP_ADDRESS mme_ip_address) {
    LTE_UE_Context_Structure *node;
    pthread_mutex_lock(&list->mutex);
    for (node = list->head; node != NULL; node = node->next) {
        if (strcmp(node->mme_ip_address.address, mme_ip_address.address) == 0) {
            pthread_mutex_unlock(&list->mutex);
            return node;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}
