function extractBibleBooks(text) {
    const bookRegex = /(?:\b[A-Z][a-z]+(?:\s+[A-Z][a-z]*)?\b)/g;
    let matches = text.match(bookRegex);

    if (!matches) return [];

    const bibleOldTestamentBooks = [
        'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
        'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings',
        '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms',
        'Proverbs', 'Ecclesiastes', 'Song of Songs', 'Isaiahus', 'Jeremiah', 'Lamentations',
        'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum',
        'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'
    ];

    return matches.filter(book => bibleOldTestamentBooks.includes(book));
}

// Example usage:
const text = "I read Genesis, Exodus, and Leviticus.";
const books = extractBibleBooks(text);
console.log(books);  // Output: ['Genesis', 'Exodus', 'Leviticus']
