Server* create_server(const char *protocol, const char *config_file) {
    Server *server = (Server*)malloc(sizeof(Server));
    if (!server) return NULL; // Handle memory allocation failure

    curl_global_init(CURL_GLOBAL_DEFAULT);
    server->handle = curl_easy_init();
    if (!server->handle) {
        free(server);
        return NULL; // Handle libcurl initialization failure
    }

    if (strcmp(protocol, "HTTP/1.1") == 0) {
        curl_easy_setopt(server->handle, CURLOPT_HTTP_VERSION, CURL_HTTP_VERSION_1_1);
    } else if (strcmp(protocol, "HTTP/2") == 0) {
        curl_easy_setopt(server->handle, CURLOPT_HTTP_VERSION, CURL_HTTP_VERSION_2_0);
    }

    if (config_file) {
        FILE *file = fopen(config_file, "r");
        if (!file) {
            fprintf(stderr, "Error opening configuration file: %s\n", config_file);
            free(server);
            curl_easy_cleanup(server->handle);
            return NULL; // Handle configuration file error
        }
        // Read and process settings from the file
        fclose(file);
    }

    // Initialize other server settings based on environment variables or defaults

    return server;
}

void destroy_server(Server *server) {
    if (server) {
        curl_easy_cleanup(server->handle);
        free(server);
    }
