    // Allocate memory for the array of LTE_UE_Context pointers
    LTE_UE_Context **ue_contexts = malloc(num_entries * sizeof(LTE_UE_Context *));
    if (ue_contexts == NULL) {
        *allocated_size = 0;
        return NULL; // Handle memory allocation failure
    }
    *allocated_size = num_entries;

    // Initialize each LTE_UE_Context structure
    for (int i = 0; i < num_entries; i++) {
        ue_contexts[i] = malloc(sizeof(LTE_UE_Context));
        if (ue_contexts[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free(ue_contexts[j]);
            }
            free(ue_contexts);
            *allocated_size = 0;
            return NULL; // Handle memory allocation failure
        }

        // Initialize fields with default values or random values
        ue_contexts[i]->rrc_state = DEFAULT_RRC_STATE;
        ue_contexts[i]->pdp_context = DEFAULT_PDP_CONTEXT;
        ue_contexts[i]->mme_ip_address = generate_random_mme_ip();
        ue_contexts[i]->s1ap_message = create_s1ap_message_with_version(S1AP_VERSION_1);
        if (ue_contexts[i]->s1ap_message == NULL) {
            for (int j = 0; j <= i; j++) {
                free(ue_contexts[j]);
            }
            free(ue_contexts);
            *allocated_size = 0;
            return NULL; // Handle memory allocation failure
        }
        ue_contexts[i]->qos_priority = generate_random_qos_priority();
    }

    return ue_contexts;
