#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int CRCFLAG;
    // Add other fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->elements);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_element(DynamicArray* array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid index
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->elements[i] = array->elements[i + 1];
    }
    --array->count;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_element(DynamicArray* array, size_t index, NFAPI_CRC_INDICATION_PDU_T newElement) {
    pthread_mutex_lock(&array->lock);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Invalid index
    }
    array->elements[index] = newElement;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to filter duplicates and update obsolete data
void process_network_update(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T newUpdate) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == newUpdate.RNTI && array->elements[i].CRCFLAG == newUpdate.CRCFLAG) {
            // Update existing entry
            array->elements[i] = newUpdate;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    if (array->count < MAX_ELEMENTS) {
        array->elements[array->count++] = newUpdate;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to compress the array
void compress_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    // Implement compression logic here
    pthread_mutex_unlock(&array->lock);
}

// Function to get statistical information
void get_statistics(DynamicArray* array, size_t* totalElements, double* averageRNTI, int* crcFlagDistribution[]) {
    pthread_mutex_lock(&array->lock);
    *totalElements = array->count;
    *averageRNTI = 0.0;
    for (size_t i = 0; i < array->count; ++i) {
        *averageRNTI += array->elements[i].RNTI;
    }
    if (*totalElements > 0) {
        *averageRNTI /= *totalElements;
    }

    // Initialize CRC flag distribution
    for (int i = 0; i < 2; ++i) { // Assuming binary CRCFLAG values
        crcFlagDistribution[i] = 0;
    }
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].CRCFLAG == 1) {
            ++crcFlagDistribution[1];
        } else if (array->elements[i].CRCFLAG == 0) {
            ++crcFlagDistribution[0];
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Example usage
int main() {
    DynamicArray* array = create_dynamic_array();
    NFAPI_CRC_INDICATION_PDU_T newUpdate;
    // Populate newUpdate with valid data

    process_network_update(array, newUpdate);
    compress_array(array);

    size_t totalElements;
    double averageRNTI;
    int crcFlagDistribution[2];
    get_statistics(array, &totalElements, &averageRNTI, crcFlagDistribution);

    destroy_dynamic_array(array);
    return 0;
}
