} LTE_UE_Context;

LTE_UE_Context** create_UE_context_list(int num_entries, const char* api_config) {
    // Allocate memory for the list of UE contexts
    LTE_UE_Context** ue_contexts = (LTE_UE_Context**)malloc(num_entries * sizeof(LTE_UE_Context*));
    if (!ue_contexts) return NULL;

    // Initialize mutexes for thread-safe access
    pthread_mutex_t* mutexes = (pthread_mutex_t*)calloc(num_entries, sizeof(pthread_mutex_t));
    if (!mutexes) {
        free(ue_contexts);
        return NULL;
    }

    // Configure S1AP message versions and default behavior from API
    int enabled_versions[5];
    parse_api_config(api_config, enabled_versions);

    for (int i = 0; i < num_entries; ++i) {
        ue_contexts[i] = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
        if (!ue_contexts[i]) continue;

        pthread_mutex_init(&mutexes[i], NULL);

        // Initialize RRC_STATE, PDP_CONTEXT, MME_IP_ADDRESS
        initialize_UE_context(ue_contexts[i]);

        // Allocate and initialize S1AP message based on enabled versions
        ue_contexts[i]->S1AP_MESSAGE = create_S1AP_message(enabled_versions);
        if (!ue_contexts[i]->S1AP_MESSAGE) {
            free(ue_contexts[i]);
            continue;
        }

        // Set random QoS priority level
        set_random_QoS_priority(&ue_contexts[i]->QoS_level);
    }

    // Log memory usage and allocation patterns
    log_memory_usage(num_entries);

    return ue_contexts;
}

void destroy_UE_context_list(LTE_UE_Context** ue_contexts, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        if (!ue_contexts[i]) continue;

        // Free S1AP message
        free(ue_contexts[i]->S1AP_MESSAGE);

        // Destroy mutex and free UE context structure
        pthread_mutex_destroy(&mutexes[i]);
        free(ue_contexts[i]);
    }

    // Free the list of pointers
    free(ue_contexts);
}
