ProcessedData* processFile(const char* filePath, const char* option) {
    ProcessedData* result = (ProcessedData*)malloc(sizeof(ProcessedData));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Validate file path and open the file
    struct stat fileStat;
    if (stat(filePath, &fileStat) != 0 || !S_ISREG(fileStat.st_mode)) {
        fprintf(stderr, "Invalid or non-regular file: %s\n", filePath);
        free(result);
        return NULL;
    }

    FILE* file = fopen(filePath, "rb");
    if (!file) {
        perror("Failed to open file");
        free(result);
        return NULL;
    }

    // Determine file type and construct new file name
    char fileType[10];
    strcpy(fileType, getFileExtension(filePath));
    char newFileName[256];
    sprintf(newFileName, "%s_%ld.%s", getBaseName(filePath), time(NULL), fileType);

    // Create unique new file name if necessary
    while (fileExists(newFileName)) {
        sprintf(newFileName, "%s_%ld.%s", getBaseName(filePath), time(NULL), fileType);
    }

    // Load the file into memory using efficient buffering
    result->data = (char*)malloc(fileStat.st_size + 1);
    if (!result->data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        free(result);
        return NULL;
    }
    result->size = fread(result->data, 1, fileStat.st_size, file);
    result->data[result->size] = '\0';
    fclose(file);

    // Process data based on the command line option
    if (strcmp(option, "--option1") == 0) {
        processOption1(result->data, result->size);
    } else if (strcmp(option, "--option2") == 0) {
        processOption2(result->data, result->size);
    }

    return result;
}

// Helper functions
const char* getFileExtension(const char* filePath) {
    const char* dot = strrchr(filePath, '.');
    return dot ? dot + 1 : "";
}

const char* getBaseName(const char* filePath) {
    const char* slash = strrchr(filePath, '/');
    return slash ? slash + 1 : filePath;
}

int fileExists(const char* fileName) {
    FILE* file = fopen(fileName, "r");
    if (file) {
