    MY_CUSTOM_DATA_T data;
    struct node *next;
} NODE_T;

typedef struct {
    NODE_T **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DYNAMIC_HASH_TABLE_T;

DYNAMIC_HASH_TABLE_T* create_hash_table(size_t initial_capacity) {
    DYNAMIC_HASH_TABLE_T *table = (DYNAMIC_HASH_TABLE_T *)malloc(sizeof(DYNAMIC_HASH_TABLE_T));
    if (!table) return NULL;

    table->buckets = (NODE_T **)calloc(initial_capacity, sizeof(NODE_T *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(DYNAMIC_HASH_TABLE_T *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        NODE_T *node = table->buckets[i];
        while (node) {
            NODE_T *next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void insert_data(DYNAMIC_HASH_TABLE_T *table, MY_CUSTOM_DATA_T data) {
    pthread_mutex_lock(&table->lock);

    // Resize logic here if necessary

    size_t index = hash_function(data.ID, table->capacity);
    NODE_T *new_node = (NODE_T *)malloc(sizeof(NODE_T));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    ++table->size;

    pthread_mutex_unlock(&table->lock);
}

void remove_data(DYNAMIC_HASH_TABLE_T *table, int ID) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(ID, table->capacity);
    NODE_T **node_ptr = &table->buckets[index];
    while (*node_ptr) {
        if ((*node_ptr)->data.ID == ID) {
            NODE_T *to_remove = *node_ptr;
            *node_ptr = to_remove->next;
            free(to_remove);
            --table->size;
            break;
        }
        node_ptr = &(*node_ptr)->next;
    }

    pthread_mutex_unlock(&table->lock);
}

MY_CUSTOM_DATA_T* get_data(DYNAMIC_HASH_TABLE_T *table, int ID) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(ID, table->capacity);
    NODE_T *node = table->buckets[index];
    while (node) {
        if (node->data.ID == ID) {
            pthread_mutex_unlock(&table->lock);
            return &node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void *load_config(const char *path) {
