        free(data);
        return NULL; // Handle file open failure
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    data->data = malloc(fileSize + 1);
    if (data->data == NULL) {
        fclose(file);
        free(data);
        return NULL; // Handle memory allocation failure
    }

    size_t bytesRead = fread(data->data, 1, fileSize, file);
    fclose(file);

    if (bytesRead != fileSize) {
        free(data->data);
        free(data);
        return NULL; // Handle file read failure
    }

    data->size = bytesRead;

    // Process the file based on the command line option

    // Return a pointer to the processed data structure
    return data;
}

