LTE_UE_CONTEXT ue_context_pool[MAX_UE_CONTEXTS];
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_ue_context(int *ue_id) {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (!ue_context_pool[i].s1ap_message) {
            ue_context_pool[i].s1ap_message = malloc(sizeof(S1AP_MESSAGE_T));
            if (!ue_context_pool[i].s1ap_message) {
                pthread_mutex_unlock(&pool_mutex);
                return -1;
            }
            *ue_id = i;
            pthread_mutex_unlock(&pool_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return -2; // Pool full
}

void free_ue_context(int ue_id) {
    pthread_mutex_lock(&pool_mutex);
    if (ue_context_pool[ue_id].s1ap_message) {
        free(ue_context_pool[ue_id].s1ap_message);
        memset(&ue_context_pool[ue_id], 0, sizeof(LTE_UE_CONTEXT));
    }
    pthread_mutex_unlock(&pool_mutex);
}

