        contexts[i]->s1ap_message = (S1AP_MESSAGE_T*)malloc(sizeof(S1AP_MESSAGE_T));
        if (!contexts[i]->s1ap_message) {
            for (int j = 0; j <= i; j++) free(contexts[j]);
            free(contexts);
            return NULL;
