        contexts[i]->s1ap_message->version = (S1AP_VERSION)(rand() % 2); // Randomly choose S1AP version
        contexts[i]->qos_priority = rand() % 5 + 1; // Randomly set QoS priority

        // Allocate memory for payload based on max_payload_size
        contexts[i]->s1ap_message->payload = (char*)malloc(max_payload_size);
        if (!contexts[i]->s1ap_message->payload) {
            free(contexts[i]->s1ap_message);
            for (int j = 0; j <= i; j++) free(contexts[j]);
            free(contexts);
            return NULL;
        }
    }

    return contexts;
}

void free_lte_ue_contexts(LTE_UE_CONTEXT** contexts, int num_entries) {
