#include <stdlib.h>
#include <pthread.h>

#define MAX_SDU_SIZE 256

typedef struct {
    uint32_t PREAMBLE;
    uint16_t SEQUENCE_NUMBER;
    uint8_t TRANSMISSION_POWER;
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    uint8_t sdu[MAX_SDU_SIZE];
} MAC_PDU;

typedef struct {
    MAC_PDU* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_create() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void dynamic_array_destroy(DynamicArray* da) {
    if (da->array) free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int dynamic_array_append(DynamicArray* da, MAC_PDU pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        MAC_PDU* new_array = (MAC_PDU*)realloc(da->array, new_capacity * sizeof(MAC_PDU));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failure
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

void dynamic_array_clear(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    if (da->array) free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->lock);
}
