Server* init_server(const char* xml_file_path, const char* protocol, int timeout, int concurrency) {
    Server* server = (Server*)malloc(sizeof(Server));
    if (!server) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    xmlDocPtr doc = xmlReadFile(xml_file_path, NULL, 0);
    if (!doc) {
        fprintf(stderr, "Failed to parse XML file\n");
        free(server);
        return NULL;
    }

    xmlNodePtr root_element = xmlDocGetRootElement(doc);
    if (!root_element || strcmp((char*)root_element->name, "server") != 0) {
        fprintf(stderr, "Invalid XML structure\n");
        xmlFreeDoc(doc);
        free(server);
        return NULL;
    }

    // Extract protocol version using XPath
    char xpath_query[256];
    snprintf(xpath_query, sizeof(xpath_query), "/server/protocol[text()='%s']", protocol);
    xmlXPathContextPtr xpath_context = xmlXPathNewContext(doc);
    xmlXPathObjectPtr xpath_result = xmlXPathEvalExpression((xmlChar*)xpath_query, xpath_context);

    if (!xpath_result || xpath_result->type != XPATH_NODESET) {
        fprintf(stderr, "Protocol version not found or multiple elements match\n");
        xmlXPathFreeObject(xpath_result);
        xmlXPathFreeContext(xpath_context);
        xmlFreeDoc(doc);
        free(server);
        return NULL;
    }

    if (xpath_result->nodesetval->nodeNr != 1) {
        fprintf(stderr, "Multiple protocol versions found\n");
        xmlXPathFreeObject(xpath_result);
        xmlXPathFreeContext(xpath_context);
        xmlFreeDoc(doc);
        free(server);
        return NULL;
    }

    // Assuming the first node is the one we want
    server->protocol_version = atoi((char*)xmlNodeGetContent(xpath_result->nodesetval->nodeTab[0]));

    xmlXPathFreeObject(xpath_result);
    xmlXPathFreeContext(xpath_context);

    // Set other server properties based on command-line arguments or XML configuration

    server->curl = curl_easy_init();
    if (!server->curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        free(server);
        return NULL;
    }

    // Set libcurl options based on server configuration

    xmlFreeDoc(doc);

    printf("Server initialized with protocol version %d, timeout %d, concurrency level %d\n", server->protocol_version, server->timeout, server->concurrency_level);

    return server;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <xml_file_path> <protocol> <timeout> <concurrency>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Server* server = init_server(argv[1], argv[2], atoi(argv[3]), atoi(argv[4]));
    if (!server) {
        fprintf(stderr, "Failed to initialize server\n");
        return EXIT_FAILURE;
    }

    // Start listening for incoming HTTP requests

    curl_easy_cleanup(server->curl);
    free(server);

    return EXIT_SUCCESS;
}
