#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *digest;
    size_t digest_length;
} FileDigestResult;

FileDigestResult* process_file(const char *file_path, int option) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0L, SEEK_SET);

    unsigned char *buffer = malloc(file_size);
    if (buffer == NULL) {
        fclose(file);
        perror("Failed to allocate memory for file content");
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    fclose(file);

    if (bytes_read != file_size) {
        free(buffer);
        perror("Failed to read file completely");
        return NULL;
    }

    FileDigestResult *result = malloc(sizeof(FileDigestResult));
    if (result == NULL) {
        free(buffer);
        perror("Failed to allocate memory for result");
        return NULL;
    }

    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, buffer, bytes_read);
    SHA256_Final(result->digest, &sha256);

    result->digest_length = SHA256_DIGEST_LENGTH;

    free(buffer);

    return result;
}

void free_result(FileDigestResult *result) {
    if (result != NULL) {
        free(result->digest);
        free(result);
    }
}
