#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1024

typedef struct {
    int rnti;
    // PDU sessions list and other data members
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    pthread_mutex_t lock;
} UE_Array;

void init_ue_array(UE_Array *array) {
    array->contexts = malloc(MAX_UE_CONTEXTS * sizeof(LTE_UE_Context));
    if (!array->contexts) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void add_or_update_ue_context(UE_Array *array, LTE_UE_Context context) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].rnti == context.rnti) {
            array->contexts[i] = context;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    if (array->count >= MAX_UE_CONTEXTS) {
        fprintf(stderr, "Array full\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }
    array->contexts[array->count++] = context;
    pthread_mutex_unlock(&array->lock);
}

void remove_inactive_contexts(UE_Array *array, time_t threshold) {
    pthread_mutex_lock(&array->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (time(NULL) - array->contexts[i].timestamp <= threshold) {
            array->contexts[new_count++] = array->contexts[i];
        }
    }
    if (new_count != array->count) {
        array->count = new_count;
    }
    pthread_mutex_unlock(&array->lock);
}

void free_ue_array(UE_Array *array) {
    pthread_mutex_lock(&array->lock);
    free(array->contexts);
    array->contexts = NULL;
    array->count = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
