#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int rnti;
    // List of PDU sessions
    // Timestamp for last activity
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context* contexts;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} Dynamic_Array;

void init_dynamic_array(Dynamic_Array* array, size_t initial_capacity) {
    array->contexts = malloc(initial_capacity * sizeof(LTE_UE_Context));
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_context(Dynamic_Array* array, int rnti) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_UE_Context* new_contexts = realloc(array->contexts, new_capacity * sizeof(LTE_UE_Context));
        if (new_contexts == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }
    array->contexts[array->size].rnti = rnti;
    // Initialize PDU sessions and timestamp
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void update_context(Dynamic_Array* array, int rnti) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        if (array->contexts[i].rnti == rnti) {
            // Update PDU sessions and timestamp
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void remove_inactive_contexts(Dynamic_Array* array, time_t threshold) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size;) {
        if ((time(NULL) - array->contexts[i].timestamp) > threshold) {
            memmove(&array->contexts[i], &array->contexts[i + 1], (array->size - i - 1) * sizeof(LTE_UE_Context));
            array->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void bulk_update_contexts(Dynamic_Array* array, int* rntis, size_t count) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < count; i++) {
        for (size_t j = 0; j < array->size; j++) {
            if (array->contexts[j].rnti == rntis[i]) {
                // Bulk update PDU sessions and timestamp
                break;
            }
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void report_active_contexts(Dynamic_Array* array, void (*report_function)(int)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; i++) {
        report_function(array->contexts[i].rnti);
    }
    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(Dynamic_Array* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->contexts);
}
```
This code defines a dynamic array structure for managing LTE UE Contexts, including functions for initialization, adding new contexts, updating existing ones, removing inactive contexts, bulk updates, reporting active contexts, and freeing the array. Thread-safe access is ensured using a mutex, and memory management techniques like realloc are used to efficiently handle potential reallocations.']

