public class RestClient {
    private RestTemplate restTemplate;
    private ExecutorService executorService;

    public RestClient() {
        this.restTemplate = new RestTemplate();
        this.executorService = Executors.newFixedThreadPool(500);
    }

    public void sendRequest(String url, String method) {
        executorService.submit(() -> {
            try {
                long startTime = System.currentTimeMillis();
                ResponseEntity<String> response = restTemplate.exchange(url, HttpMethod.valueOf(method), null, String.class);
                long endTime = System.currentTimeMillis();
                logRequestDetails(startTime, endTime, response.getStatusCodeValue(), response.getBody().length());
            } catch (Exception e) {
                handleException(e);
            }
        });
    }

    private void handleException(Exception e) {
