        // Use a mock object for ServiceLocator to simulate different service states
    }

    private void logRequestDetails(long startTime, long endTime, int statusCode, int responseSize) {
        // Log start time, end time, status code, and response size
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
