    *graph = (GRAPH_DATA_STRUCT_T*)malloc(sizeof(GRAPH_DATA_STRUCT_T));
    if (*graph == NULL) {
        return -1; // Memory allocation failure
    }

    (*graph)->nodes = (MY_GRAPH_NODE_T**)calloc(initial_size, sizeof(MY_GRAPH_NODE_T*));
    (*graph)->edges = (MY_EDGE_T**)calloc(initial_size, sizeof(MY_EDGE_T*));
    if ((*graph)->nodes == NULL || (*graph)->edges == NULL) {
        free(*graph);
        return -1; // Memory allocation failure
    }

    (*graph)->node_count = 0;
    (*graph)->edge_count = 0;
    (*graph)->max_nodes = initial_size;
    (*graph)->max_edges = initial_size;
    pthread_mutex_init(&(*graph)->mutex, NULL);

