#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *data;
    size_t length;
} ProcessedData;

ProcessedData* process_file(const char *file_path, int option) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char *file_data = (unsigned char *)malloc(file_size);
    if (file_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for file data\n");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(file_data, 1, file_size, file);
    fclose(file);

    if (bytes_read != file_size) {
        fprintf(stderr, "Error reading file: %s\n", file_path);
        free(file_data);
        return NULL;
    }

    ProcessedData *result = (ProcessedData *)malloc(sizeof(ProcessedData));
    if (result == NULL) {
        fprintf(stderr, "Failed to allocate memory for result\n");
        free(file_data);
        return NULL;
    }

    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    if (md_ctx == NULL) {
        fprintf(stderr, "Failed to create EVP_MD_CTX\n");
        free(result);
        free(file_data);
        return NULL;
    }

    if (!EVP_DigestInit_ex(md_ctx, EVP_sha256(), NULL)) {
        fprintf(stderr, "Failed to initialize SHA-256 digest\n");
        EVP_MD_CTX_free(md_ctx);
        free(result);
        free(file_data);
        return NULL;
    }

    if (!EVP_DigestUpdate(md_ctx, file_data, bytes_read)) {
        fprintf(stderr, "Failed to update SHA-256 digest\n");
        EVP_MD_CTX_free(md_ctx);
        free(result);
        free(file_data);
        return NULL;
    }

    unsigned char hash[EVP_MAX_MD_SIZE];
    size_t hash_length;
    if (!EVP_DigestFinal_ex(md_ctx, hash, &hash_length)) {
        fprintf(stderr, "Failed to finalize SHA-256 digest\n");
        EVP_MD_CTX_free(md_ctx);
        free(result);
        free(file_data);
        return NULL;
    }

    EVP_MD_CTX_free(md_ctx);

    result->data = (unsigned char *)malloc(hash_length);
    if (result->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash data\n");
        free(result);
        free(file_data);
        return NULL;
    }

    memcpy(result->data, hash, hash_length);
    result->length = hash_length;

    free(file_data);
    return result;
}
