} NFAPI_CRC_INDICATION_PDU_T;

typedef struct entry_struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct entry_struct *next;
} Entry;

typedef struct {
    Entry **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentHashMap;

ConcurrentHashMap* create_concurrent_hashmap() {
    ConcurrentHashMap *hashmap = (ConcurrentHashMap *)malloc(sizeof(ConcurrentHashMap));
    hashmap->capacity = MAX_ENTRIES;
    hashmap->size = 0;
    hashmap->buckets = (Entry **)calloc(MAX_ENTRIES, sizeof(Entry *));
    pthread_mutex_init(&hashmap->lock, NULL);
    return hashmap;
}

void free_concurrent_hashmap(ConcurrentHashMap *hashmap) {
    for (size_t i = 0; i < hashmap->capacity; i++) {
        Entry *entry = hashmap->buckets[i];
        while (entry != NULL) {
            Entry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(hashmap->buckets);
    pthread_mutex_destroy(&hashmap->lock);
    free(hashmap);
}

size_t hash(RX_UE_INFORMATION_TAG ue_info_tag) {
    // Implement a good hash function here
    return (ue_info_tag.value & 0xFFFFFFFF) % MAX_ENTRIES;
}

Entry* create_entry(RX_UE_INFORMATION_TAG ue_info_tag, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    entry->ue_info_tag = ue_info_tag;
    entry->pdu = pdu;
    entry->next = NULL;
    return entry;
}

void insert_entry(ConcurrentHashMap *hashmap, RX_UE_INFORMATION_TAG ue_info_tag, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&hashmap->lock);
    size_t index = hash(ue_info_tag);
    Entry *entry = hashmap->buckets[index];
    if (entry == NULL) {
        hashmap->buckets[index] = create_entry(ue_info_tag, pdu);
    } else {
        while (entry->next != NULL) {
            entry = entry->next;
        }
        entry->next = create_entry(ue_info_tag, pdu);
    }
    hashmap->size++;
    if ((double)hashmap->size / hashmap->capacity >= LOAD_FACTOR) {
        rehash(hashmap);
    }
    pthread_mutex_unlock(&hashmap->lock);
}

void delete_entry(ConcurrentHashMap *hashmap, RX_UE_INFORMATION_TAG ue_info_tag) {
    pthread_mutex_lock(&hashmap->lock);
    size_t index = hash(ue_info_tag);
    Entry *entry = hashmap->buckets[index];
    if (entry != NULL && entry->ue_info_tag.value == ue_info_tag.value) {
        hashmap->buckets[index] = entry->next;
        free(entry);
    } else {
        while (entry->next != NULL) {
            if (entry->next->ue_info_tag.value == ue_info_tag.value) {
                Entry *temp = entry->next;
                entry->next = temp->next;
                free(temp);
                break;
            }
            entry = entry->next;
        }
    }
    hashmap->size--;
    pthread_mutex_unlock(&hashmap->lock);
}

void rehash(ConcurrentHashMap *hashmap) {
    ConcurrentHashMap *new_hashmap = create_concurrent_hashmap();
    for (size_t i = 0; i < hashmap->capacity; i++) {
        Entry *entry = hashmap->buckets[i];
        while (entry != NULL) {
            insert_entry(new_hashmap, entry->ue_info_tag, entry->pdu);
            Entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    hashmap->capacity = new_hashmap->capacity;
    hashmap->buckets = new_hashmap->buckets;
    pthread_mutex_unlock(&hashmap->lock);
    free_concurrent_hashmap(new_hashmap);
}

void process_data_packet(ConcurrentHashMap *hashmap, RX_UE_INFORMATION_TAG ue_info_tag, NFAPI_CRC_INDICATION_PDU_T pdu) {
    insert_entry(hashmap, ue_info_tag, pdu);
}
