    int session_status;
    pthread_mutex_t mutex;
} LTE_UE_Context;

LTE_UE_Context* ue_contexts[MAX_UE_CONTEXTS] = {NULL};
int num_ue_contexts = 0;
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_or_update_ue_context(int ue_id, int pdu_id) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < num_ue_contexts; ++i) {
        if (ue_contexts[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&global_mutex);
            return;
        }
    }
    if (num_ue_contexts >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&global_mutex);
        fprintf(stderr, "Maximum UE contexts reached\n");
        exit(EXIT_FAILURE);
    }
    LTE_UE_Context* new_context = malloc(sizeof(LTE_UE_Context));
    if (!new_context) {
        pthread_mutex_unlock(&global_mutex);
        perror("Failed to allocate memory for new UE context");
        exit(EXIT_FAILURE);
    }
    new_context->ue_id = ue_id;
    new_context->session_status = 0; // Assuming initial session status
    pthread_mutex_init(&new_context->mutex, NULL);
    PDCP_PDU pdu;
    pdu.pdu_id = pdu_id;
    new_context->pdcp_pdus[0] = pdu;
    num_ue_contexts++;
    ue_contexts[num_ue_contexts - 1] = new_context;
    pthread_mutex_unlock(&global_mutex);
}

LTE_UE_Context* get_ue_context(int ue_id) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < num_ue_contexts; ++i) {
        if (ue_contexts[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&global_mutex);
            return ue_contexts[i];
        }
    }
    pthread_mutex_unlock(&global_mutex);
    return NULL;
}

