typedef struct {
    NFAPI_LTE_PDU *configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LTE_Config_Array;

LTE_Config_Array* create_config_array(size_t initial_capacity) {
    LTE_Config_Array *array = (LTE_Config_Array*)malloc(sizeof(LTE_Config_Array));
    array->configs = (NFAPI_LTE_PDU*)calloc(initial_capacity, sizeof(NFAPI_LTE_PDU));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_config_array(LTE_Config_Array *array) {
    free(array->configs);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_config(LTE_Config_Array *array, NFAPI_LTE_PDU config) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_LTE_PDU *new_configs = (NFAPI_LTE_PDU*)realloc(array->configs, new_capacity * sizeof(NFAPI_LTE_PDU));
        if (!new_configs) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->configs = new_configs;
        array->capacity = new_capacity;
    }
    array->configs[array->count++] = config;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_config(LTE_Config_Array *array, int cell_identity) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].cell_identity == cell_identity) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->configs[j] = array->configs[j + 1];
            }
            --array->count;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Configuration not found
}

int update_config(LTE_Config_Array *array, int cell_identity, NFAPI_LTE_PDU new_config) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->configs[i].cell_identity == cell_identity) {
            array->configs[i] = new_config;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Configuration not found
}
