pthread_mutex_t cell_lock = PTHREAD_MUTEX_INITIALIZER;

void manageDynamicArrayAndNICStats(int operation, int index, int bandwidth, float subcarrier_spacing, int cell_identity) {
    pthread_mutex_lock(&cell_lock);

    switch (operation) {
        case 0: // Add
            if (num_cells >= MAX_DEVICES) {
                fprintf(stderr, "Error: Maximum number of devices reached\n");
                break;
            }
            NFAPI_LTE_PDU* new_cell = (NFAPI_LTE_PDU*)malloc(sizeof(NFAPI_LTE_PDU));
            new_cell->bandwidth = bandwidth;
            new_cell->subcarrier_spacing = subcarrier_spacing;
            new_cell->cell_identity = cell_identity;
            cell_configs[num_cells++] = new_cell;
            break;
        case 1: // Remove
            if (index < 0 || index >= num_cells) {
                fprintf(stderr, "Error: Invalid device index\n");
                break;
            }
            free(cell_configs[index]);
            for (int i = index; i < num_cells - 1; i++) {
                cell_configs[i] = cell_configs[i + 1];
            }
            num_cells--;
            break;
        case 2: // Update
            if (index < 0 || index >= num_cells) {
                fprintf(stderr, "Error: Invalid device index\n");
                break;
            }
            NFAPI_LTE_PDU* updated_cell = (NFAPI_LTE_PDU*)malloc(sizeof(NFAPI_LTE_PDU));
            updated_cell->bandwidth = bandwidth;
            updated_cell->subcarrier_spacing = subcarrier_spacing;
            updated_cell->cell_identity = cell_identity;
            free(cell_configs[index]);
            cell_configs[index] = updated_cell;
            break;
    }

    pthread_mutex_unlock(&cell_lock);
}

