typedef enum {
    PROCESS_SUCCESS,
    PROCESS_ERROR_FILE_NOT_FOUND,
    PROCESS_ERROR_PERMISSIONS,
    PROCESS_ERROR_OTHER
} ProcessResult;

typedef struct {
    void* data;
    size_t length;
    ProcessResult result;
} ProcessingResult;

ProcessingResult process_file_with_options(const char* file_path, int options, bool async, const Config* config) {
    ProcessingResult result = {NULL, 0, PROCESS_SUCCESS};

    // File path validation
    struct stat file_stat;
    if (stat(file_path, &file_stat) != 0 || !S_ISREG(file_stat.st_mode)) {
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_FILE_NOT_FOUND};
    }

    // Check permissions
    if (access(file_path, R_OK | W_OK) != 0) {
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_PERMISSIONS};
    }

    // Perform file processing using OpenSSL library
    int fd = open(file_path, O_RDWR);
    if (fd == -1) {
        perror("Failed to open file");
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    // Initialize cipher
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, config->key, config->iv)) {
        perror("Failed to initialize cipher");
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    // Allocate memory for the output data
    size_t input_length = file_stat.st_size;
    result.data = malloc(input_length + EVP_CIPHER_block_size(ctx));
    if (!result.data) {
        perror("Failed to allocate memory");
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    // Read data from file and process
    size_t bytes_read = read(fd, result.data, input_length);
    if (bytes_read != input_length) {
        perror("Failed to read file");
        free(result.data);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    int output_length;
    if (!EVP_EncryptUpdate(ctx, (unsigned char*)(result.data + bytes_read), &output_length, result.data, input_length)) {
        perror("Failed to update cipher");
        free(result.data);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    if (!EVP_EncryptFinal_ex(ctx, (unsigned char*)(result.data + bytes_read + output_length), &output_length)) {
        perror("Failed to finalize cipher");
        free(result.data);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return (ProcessingResult){NULL, 0, PROCESS_ERROR_OTHER};
    }

    result.length = bytes_read + output_length;
    EVP_CIPHER_CTX_free(ctx);
    close(fd);

    return result;
}
