#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

// Function to compile command-line arguments into an executable command string
char* compile_command(int argc, char* argv[]) {
    size_t cmd_len = 0;
    for (int i = 0; i < argc; ++i) {
        cmd_len += strlen(argv[i]) + 1;
    }
    char* cmd = malloc(cmd_len);
    if (!cmd) return NULL;

    *cmd = '\0';
    for (int i = 0; i < argc; ++i) {
        strcat(cmd, argv[i]);
        if (i < argc - 1) strcat(cmd, " ");
    }

    // Validate the command for common shell injection patterns
    if (strchr(cmd, ';') || strchr(cmd, '|') || strchr(cmd, '&')) {
        fprintf(stderr, "Warning: Suspicious characters detected in command\n");
    }

    return cmd;
}

// Function to execute a compiled command securely
int execute_command(const char* cmd) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 127; // Command execution failed
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return 127; // Command execution failed
    } else if (pid == 0) {
        // Child process: execute the command
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);

        execl("/bin/sh", "sh", "-c", cmd, NULL);
        perror("exec");
        exit(127); // Command execution failed
    } else {
        // Parent process: wait for the command to complete
        close(pipefd[1]);
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        } else if (WIFSIGNALED(status)) {
            return -WTERMSIG(status);
        }
    }

    close(pipefd[0]);
    return 127; // Command execution failed
}

// Example usage of the compile_command and execute_command functions
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s command [arg...]\n", argv[0]);
        return 1;
    }

    char* cmd = compile_command(argc - 1, &argv[1]);
    if (!cmd) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return 127; // Command execution failed
    }

    int result = execute_command(cmd);
    free(cmd);

    printf("Command returned %d\n", result);
    return result;
}
