#include <openssl/rand.h>

#define MAX_THREADS 10

typedef struct {
    const char *file_path;
    int option;
} FileTask;

void* process_file(void *arg) {
    FileTask *task = (FileTask*) arg;
    // Implement file processing logic using OpenSSL and thread-specific resources
    free(task);
    return NULL;
}

void process_directory(const char *directory_path, int option) {
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        perror("opendir");
        return;
    }

    pthread_t threads[MAX_THREADS];
    FileTask task_queue[MAX_THREADS];

    int queue_index = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            char full_path[1024];
            snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);
            if (process_directory(full_path, option)) continue;
        } else {
            if (queue_index >= MAX_THREADS) {
                for (int i = 0; i < queue_index; i++) {
                    pthread_join(threads[i], NULL);
                }
                queue_index = 0;
            }

            FileTask *task = malloc(sizeof(FileTask));
            task->file_path = strdup(full_path);
            task->option = option;
            task_queue[queue_index++] = *task;

            if (pthread_create(&threads[queue_index - 1], NULL, process_file, &task_queue[queue_index - 1]) != 0) {
                perror("pthread_create");
                free(task);
            }
        }
    }

    while (queue_index > 0) {
        pthread_join(threads[--queue_index], NULL);
    }

    closedir(dir);
}
