typedef struct {
    uint64_t TIMESTAMP;
    int EVENT_TYPE;
    char* EVENT_DATA;
    unsigned long EVENT_ID;
} CustomNetworkEvent_T;

typedef struct Node {
    CustomNetworkEvent_T* event;
    struct Node* next;
} Node_T;

typedef struct {
    Node_T* head;
    pthread_mutex_t mutex;
} EventList_T;

void init_event_list(EventList_T* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_event(EventList_T* list, CustomNetworkEvent_T* event) {
    Node_T* new_node = (Node_T*)malloc(sizeof(Node_T));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node_T* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_event_list(EventList_T* list) {
    pthread_mutex_lock(&list->mutex);
    Node_T* current = list->head;
    while (current != NULL) {
        Node_T* next = current->next;
        free(current->event->EVENT_DATA);
        free(current->event);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

