#include <stdlib.h>
#include <pthread.h>

// Define the structure for LTE UE Context
typedef struct {
    int RNTI;
    // List of PDU sessions (not shown)
    time_t lastActivity;
} LTE_UE_Context;

// Define the dynamic array structure
typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->contexts = malloc(initial_capacity * sizeof(LTE_UE_Context));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

// Add a new context to the dynamic array
void add_context(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_UE_Context *new_contexts = realloc(array->contexts, new_capacity * sizeof(LTE_UE_Context));
        if (!new_contexts) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }
    array->contexts[array->count].RNTI = RNTI;
    array->contexts[array->count].lastActivity = time(NULL);
    array->count++;
    pthread_mutex_unlock(&array->lock);
}

// Update an existing context
void update_context(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        if (array->contexts[i].RNTI == RNTI) {
            array->contexts[i].lastActivity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Remove inactive contexts older than a specified threshold
void remove_inactive_contexts(DynamicArray *array, time_t threshold) {
    pthread_mutex_lock(&array->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (time(NULL) - array->contexts[i].lastActivity <= threshold) {
            array->contexts[new_count++] = array->contexts[i];
        }
    }
    if (new_count != array->count) {
        memmove(array->contexts, array->contexts + new_count, (array->count - new_count) * sizeof(LTE_UE_Context));
        array->count -= array->count - new_count;
    }
    pthread_mutex_unlock(&array->lock);
}

// Pause and resume operations on the dynamic array
void pause_operations(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
}

void resume_operations(DynamicArray *array) {
    pthread_mutex_unlock(&array->lock);
}

// Clean up the dynamic array
void cleanup_dynamic_array(DynamicArray *array) {
    free(array->contexts);
    pthread_mutex_destroy(&array->lock);
}
