// RESTful client using RestTemplate
import org.springframework.web.client.RestTemplate;
import java.util.concurrent.CompletableFuture;

public class RestClient {
    private final RestTemplate restTemplate = new RestTemplate();

    public String makeSyncRequest(String url) {
        // Log start time
        long startTime = System.currentTimeMillis();
        try {
            String response = restTemplate.getForObject(url, String.class);
            // Log end time and size of response
            long endTime = System.currentTimeMillis();
            System.out.println("Success: " + (endTime - startTime) + " ms, Size: " + response.length());
            return response;
        } catch (Exception e) {
            // Log failure status
            long endTime = System.currentTimeMillis();
            System.out.println("Failure: " + (endTime - startTime) + " ms");
            throw e;
        }
    }

    public CompletableFuture<String> makeAsyncRequest(String url) {
        // Log start time
        long startTime = System.currentTimeMillis();
        return CompletableFuture.supplyAsync(() -> {
            try {
                String response = restTemplate.getForObject(url, String.class);
                // Log end time and size of response
                long endTime = System.currentTimeMillis();
                System.out.println("Success: " + (endTime - startTime) + " ms, Size: " + response.length());
                return response;
            } catch (Exception e) {
                // Log failure status
                long endTime = System.currentTimeMillis();
                System.out.println("Failure: " + (endTime - startTime) + " ms");
                throw e;
            }
        });
    }
}

