        contexts[i].pdp_context = rand() % 100 + 1; // Example PDP context IDs
        snprintf(contexts[i].mme_ip_address, sizeof(contexts[i].mme_ip_address), "192.168.%d.%d", rand() % 254 + 1, rand() % 254 + 1);
        contexts[i].s1ap_message = malloc(1024); // Example S1AP message allocation
        if (!contexts[i].s1ap_message) {
            fprintf(stderr, "Failed to allocate memory for S1AP message.\n");
            free(contexts);
            return NULL;
        }
        contexts[i].qos_priority = rand() % 5; // Example QoS priority levels
