int main(int argc, char **argv) {
    int optionIndex = 2; // Start index for options
    int limitLines = -1;
    FILE *outputFile = stdout;
    int compressOutput = 0;
    const char *pluginPath = NULL;

    while (optionIndex < argc && argv[optionIndex][0] == '-') {
        if (strcmp(argv[optionIndex], "--manpage") == 0) {
            displayManpage();
            return 0;
        } else if (strcmp(argv[optionIndex], "-cs") == 0) {
            compressOutput = 1;
        } else if (strcmp(argv[optionIndex], "-o") == 0 && optionIndex + 1 < argc) {
            outputFile = fopen(argv[optionIndex + 1], "w");
            if (!outputFile) {
                perror("Error opening output file");
                return EXIT_FAILURE;
            }
            optionIndex += 2;
        } else if (strcmp(argv[optionIndex], "-l") == 0 && optionIndex + 1 < argc) {
            limitLines = atoi(argv[optionIndex + 1]);
            optionIndex += 2;
        } else if (strcmp(argv[optionIndex], "--plugin-path") == 0 && optionIndex + 1 < argc) {
            pluginPath = argv[optionIndex + 1];
            optionIndex += 2;
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[optionIndex]);
            return EXIT_FAILURE;
        }
    }

    if (argc - optionIndex == 0) {
        displayManpage();
        return 0;
    }

    PriorityQueue *pq = createPriorityQueue();
    FileEntry files[MAX_FILES];
    int fileCount = 0;

    for (; optionIndex < argc; optionIndex++) {
        FILE *file = fopen(argv[optionIndex], "r");
        if (!file) {
            perror("Error opening input file");
            continue;
        }

        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        fclose(file);

        if (fileSize > 5L * 1024 * 1024 * 1024) {
            fprintf(stderr, "File size exceeds limit: %s\n", argv[optionIndex]);
            continue;
        }

        files[fileCount].file_path = argv[optionIndex];
        files[fileCount].file_size = fileSize;
        enqueue(pq, files[fileCount]);
        fileCount++;
    }

    time_t startTime = time(NULL);

    while (pq->size > 0 && (limitLines == -1 || limitLines-- > 0)) {
        FileEntry entry = dequeue(pq);
        processFile(entry.file_path, limitLines);
    }

    fclose(outputFile);
    destroyPriorityQueue(pq);

    time_t endTime = time(NULL);
    printf("Processing time: %ld seconds\n", difftime(endTime, startTime));

    return 0;
}
