#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    MME_IP_ADDRESS mme_ip_address;
    S1AP_MESSAGE_T *s1ap_message;
    int qos_priority;
} LTE_UE_CONTEXT;

typedef struct {
    LTE_UE_CONTEXT **pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} UE_CONTEXT_POOL;

void init_ue_context_pool(UE_CONTEXT_POOL *pool, size_t initial_size) {
    pool->pool = malloc(initial_size * sizeof(LTE_UE_CONTEXT *));
    if (pool->pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

LTE_UE_CONTEXT *allocate_ue_context(UE_CONTEXT_POOL *pool) {
    LTE_UE_CONTEXT *context = malloc(sizeof(LTE_UE_CONTEXT));
    if (context == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&pool->lock);
    if (pool->used_count >= pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        LTE_UE_CONTEXT **new_pool = realloc(pool->pool, new_size * sizeof(LTE_UE_CONTEXT *));
        if (new_pool == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }
    pool->pool[pool->used_count++] = context;
    pthread_mutex_unlock(&pool->lock);

    // Initialize the LTE_UE_CONTEXT fields
    // ...

    return context;
}

void free_ue_context(UE_CONTEXT_POOL *pool, LTE_UE_CONTEXT *context) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used_count; ++i) {
        if (pool->pool[i] == context) {
            pool->pool[i] = pool->pool[--pool->used_count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);

    // Free the LTE_UE_CONTEXT fields
    // ...

    free(context);
}

void destroy_ue_context_pool(UE_CONTEXT_POOL *pool) {
    for (size_t i = 0; i < pool->used_count; ++i) {
        free(pool->pool[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
}
