    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *file_content = (char *)malloc(file_size + 1);
    if (!file_content) {
        fclose(fp);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    size_t bytes_read = fread(file_content, 1, file_size, fp);
    fclose(fp);

    if (bytes_read != file_size) {
        free(file_content);
        fprintf(stderr, "Error reading file\n");
        return NULL;
    }
    file_content[bytes_read] = '\0';

    CipherObject *cipher_obj = (CipherObject *)malloc(sizeof(CipherObject));
    if (!cipher_obj) {
        free(file_content);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    cipher_obj->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_obj->ctx) {
        free(file_content);
        free(cipher_obj);
        fprintf(stderr, "Error creating OpenSSL context\n");
        return NULL;
    }

    int iv_length = 0;
    switch (mode) {
        case EVP_ENCRYPT:
            iv_length = EVP_CIPHER_iv_length(EVP_aes_256_ecb());
            break;
        default:
            iv_length = 16; // Assuming AES block size for CBC and CFB
            break;
    }

    unsigned char *iv = (unsigned char *)malloc(iv_length);
    if (!iv) {
        free(file_content);
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    switch (mode) {
        case EVP_ENCRYPT:
            // Generate random IV for ECB
            if (RAND_bytes(iv, iv_length) != 1) {
                free(file_content);
                free(iv);
                EVP_CIPHER_CTX_free(cipher_obj->ctx);
                free(cipher_obj);
                fprintf(stderr, "Error generating random IV\n");
                return NULL;
            }
            break;
        default:
            // Use the first 16 bytes of file content as IV for CBC and CFB
            memcpy(iv, file_content, iv_length);
            break;
    }

    if (EVP_EncryptInit_ex(cipher_obj->ctx, EVP_aes_256_ecb(), NULL, (unsigned char *)key, iv) != 1) {
        free(file_content);
        free(iv);
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        fprintf(stderr, "Error initializing encryption\n");
        return NULL;
    }

    int encrypted_length = 0;
    if (EVP_EncryptUpdate(cipher_obj->ctx, NULL, &encrypted_length, file_content, bytes_read) != 1) {
        free(file_content);
        free(iv);
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
        fprintf(stderr, "Error encrypting data\n");
        return NULL;
    }

    encrypted_length += encrypted_length; // Placeholder for actual length
    cipher_obj->mode = mode;

    free(file_content);
    free(iv);

    return cipher_obj;
}

void free_cipher_object(CipherObject *cipher_obj) {
    if (cipher_obj) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        free(cipher_obj);
    }
}
