#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void freeDynamicArray(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int addElement(DynamicArray* array, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    pthread_mutex_lock(&array->mutex);
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly generate CRC flag
    newNode->next = array->head;
    array->head = newNode;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getElement(DynamicArray* array, int RNTI) {
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&array->mutex);
            NFAPI_CRC_INDICATION_PDU_T* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!result) {
                pthread_mutex_unlock(&array->mutex);
                return NULL; // Memory allocation failed
            }
            *result = current->data;
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
        current = current->next;
    }
    return NULL;
}

int removeElement(DynamicArray* array, int RNTI) {
    Node* current = array->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_lock(&array->mutex);
            if (prev == NULL) array->head = current->next;
            else prev->next = current->next;
            free(current);
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    return -1; // Element not found
}
