#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_FILES 10

typedef struct {
    char *filename;
    int line_count;
    int total_chars;
} FileData;

void* process_file(void* arg) {
    FileData *data = (FileData*)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Error opening file");
        pthread_exit(NULL);
    }

    int line_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        data->total_chars += strlen(buffer);
    }
    fclose(file);

    data->line_count = line_count;
    pthread_exit(NULL);
}

void display_usage() {
    printf("Usage: program [-c] [-s] [-o output_file] [--manpage]\n");
    printf("-c\tCount the total number of lines across all input files.\n");
    printf("-s\tCalculate the average line length for each input file.\n");
    printf("-o output_file\tSpecify an output file for saving the results.\n");
    printf("--manpage\tDisplay detailed usage information.\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        display_usage();
        return 1;
    }

    int opt;
    int count_lines = 0;
    int calc_avg_length = 0;
    const char *output_file = NULL;

    while ((opt = getopt(argc, argv, "cs:o--manpage")) != -1) {
        switch (opt) {
            case 'c':
                count_lines = 1;
                break;
            case 's':
                calc_avg_length = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case '--manpage':
                display_usage();
                return 0;
            default:
                fprintf(stderr, "Unknown option: %c\n", optopt);
                display_usage();
                return 1;
        }
    }

    if (argc - optind > MAX_FILES) {
        fprintf(stderr, "Too many input files. Maximum allowed is %d.\n", MAX_FILES);
        return 1;
    }

    pthread_t threads[MAX_FILES];
    FileData data[MAX_FILES];

    for (int i = optind; i < argc && i < optind + MAX_FILES; i++) {
        data[i - optind].filename = argv[i];
        if (pthread_create(&threads[i - optind], NULL, process_file, &data[i - optind]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < argc - optind && i < MAX_FILES; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            return 1;
        }
    }

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("Error opening output file");
            return 1;
        }
        // Write results to output file
        fclose(out);
    } else {
        // Print results to standard output
        for (int i = 0; i < argc - optind && i < MAX_FILES; i++) {
            printf("File: %s, Lines: %d, Total Chars: %d\n", data[i].filename, data[i].line_count, data[i].total_chars);
        }
    }

    return 0;
}
