#define MAX_KEYS 100000
#define KEY_SIZE 256
#define VALUE_SIZE 1024

typedef struct {
    char key[KEY_SIZE];
    unsigned long timestamp;
    char value[VALUE_SIZE];
} KeyValue;

typedef struct {
    KeyValue *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MY_KEY_VALUE_STORE;

MY_KEY_VALUE_STORE myKeyValueStore;

void initKeyValueStore() {
    myKeyValueStore.data = (KeyValue *)malloc(MAX_KEYS * sizeof(KeyValue));
    if (myKeyValueStore.data == NULL) {
        perror("Failed to allocate memory for key-value store");
        exit(EXIT_FAILURE);
    }
    myKeyValueStore.count = 0;
    myKeyValueStore.capacity = MAX_KEYS;
    pthread_mutex_init(&myKeyValueStore.lock, NULL);
}

int addOrUpdateKeyValue(const char *key, const char *value) {
    pthread_mutex_lock(&myKeyValueStore.lock);
    for (size_t i = 0; i < myKeyValueStore.count; ++i) {
        if (strcmp(myKeyValueStore.data[i].key, key) == 0) {
            strcpy(myKeyValueStore.data[i].value, value);
            pthread_mutex_unlock(&myKeyValueStore.lock);
            return 1;
        }
    }
    if (myKeyValueStore.count >= myKeyValueStore.capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&myKeyValueStore.lock);
        return -1;
    }
    strcpy(myKeyValueStore.data[myKeyValueStore.count].key, key);
    strcpy(myKeyValueStore.data[myKeyValueStore.count].value, value);
    myKeyValueStore.data[myKeyValueStore.count].timestamp = time(NULL);
    ++myKeyValueStore.count;
    pthread_mutex_unlock(&myKeyValueStore.lock);
    return 1;
}

int getValueByKey(const char *key, char *buffer) {
    pthread_mutex_lock(&myKeyValueStore.lock);
    for (size_t i = 0; i < myKeyValueStore.count; ++i) {
        if (strcmp(myKeyValueStore.data[i].key, key) == 0) {
            strcpy(buffer, myKeyValueStore.data[i].value);
            pthread_mutex_unlock(&myKeyValueStore.lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&myKeyValueStore.lock);
    return -1;
}

void clearKeyValueStore() {
    pthread_mutex_lock(&myKeyValueStore.lock);
    free(myKeyValueStore.data);
    myKeyValueStore.data = NULL;
    myKeyValueStore.count = 0;
    myKeyValueStore.capacity = MAX_KEYS;
    pthread_mutex_unlock(&myKeyValueStore.lock);
}

