typedef struct {
    int ID;
    int PRIORITY;
} MY_GRAPH_NODE_T;

typedef struct {
    int startNodeID;
    int endNodeID;
} MY_EDGE_T;

typedef struct {
    MY_GRAPH_NODE_T** nodes;
    MY_EDGE_T** edges;
    size_t nodeCount;
    size_t edgeCount;
    pthread_mutex_t mutex;
} GRAPH_T;

GRAPH_T* createGraph(size_t initialCapacity) {
    GRAPH_T* graph = (GRAPH_T*)malloc(sizeof(GRAPH_T));
    if (!graph) return NULL;

    graph->nodes = (MY_GRAPH_NODE_T**)calloc(initialCapacity, sizeof(MY_GRAPH_NODE_T*));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    graph->edges = (MY_EDGE_T**)calloc(initialCapacity, sizeof(MY_EDGE_T*));
    if (!graph->edges) {
        free(graph->nodes);
        free(graph);
        return NULL;
    }

    graph->nodeCount = 0;
    graph->edgeCount = 0;
    pthread_mutex_init(&graph->mutex, NULL);

    return graph;
}

void destroyGraph(GRAPH_T* graph) {
    if (!graph) return;

    for (size_t i = 0; i < graph->nodeCount; ++i) {
        free(graph->nodes[i]);
    }

    for (size_t i = 0; i < graph->edgeCount; ++i) {
