int addNode(GRAPH_T* graph, int ID, int PRIORITY) {
    if (!graph) return -1;

    pthread_mutex_lock(&graph->mutex);

    // Check for duplicate node ID
    for (size_t i = 0; i < graph->nodeCount; ++i) {
        if (graph->nodes[i]->ID == ID) {
            pthread_mutex_unlock(&graph->mutex);
            return -2;
        }
    }

    // Resize nodes array if needed
    if (graph->nodeCount >= capacity / 2) {
        MY_GRAPH_NODE_T** newNodes = (MY_GRAPH_NODE_T**)realloc(graph->nodes, capacity * 2 * sizeof(MY_GRAPH_NODE_T*));
        if (!newNodes) {
            pthread_mutex_unlock(&graph->mutex);
            return -3;
        }
        graph->nodes = newNodes;
    }

    // Add node
    graph->nodes[graph->nodeCount] = (MY_GRAPH_NODE_T*)malloc(sizeof(MY_GRAPH_NODE_T));
    if (!graph->nodes[graph->nodeCount]) {
        pthread_mutex_unlock(&graph->mutex);
        return -3;
    }
    graph->nodes[graph->nodeCount]->ID = ID;
    graph->nodes[graph->nodeCount]->PRIORITY = PRIORITY;
    ++graph->nodeCount;

    pthread_mutex_unlock(&graph->mutex);
    return 0;
}

