NFAP_CRC_INDICATION_PDU_T* createAndPopulateList(int N) {
    srand(time(0));
    NFAP_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    int rntiCache[10000] = {0}; // Assuming max unique RNTIs won't exceed 10000

    for (int i = 0; i < N; ++i) {
        NFAP_CRC_INDICATION_PDU_T *newNode = (NFAP_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAP_CRC_INDICATION_PDU_T));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        newNode->RNTI = rand() % 10000; // Generate random RNTI for simplicity
        while (rntiCache[newNode->RNTI]) {
