#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct DeviceConfig {
    char ipAddress[16];
    int port;
    int configFlags;
} DeviceConfig;

typedef struct Node {
    DeviceConfig *config;
    struct Node *next;
} Node;

typedef struct ConfigManager {
    Node *head;
    pthread_mutex_t mutex;
} ConfigManager;

ConfigManager *initConfigManager() {
    ConfigManager *manager = (ConfigManager *)malloc(sizeof(ConfigManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void addDevice(ConfigManager *manager, DeviceConfig *config) {
    pthread_mutex_lock(&manager->mutex);
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->config = config;
    newNode->next = manager->head;
    manager->head = newNode;
    pthread_mutex_unlock(&manager->mutex);
}

void removeDevice(ConfigManager *manager, char *ipAddress) {
    pthread_mutex_lock(&manager->mutex);
    Node *current = manager->head;
    Node *previous = NULL;

    while (current != NULL) {
        if (strcmp(current->config->ipAddress, ipAddress) == 0) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

DeviceConfig *getDevice(ConfigManager *manager, char *ipAddress) {
    pthread_mutex_lock(&manager->mutex);
    Node *current = manager->head;

    while (current != NULL) {
        if (strcmp(current->config->ipAddress, ipAddress) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return current->config;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void freeConfigManager(ConfigManager *manager) {
    Node *current = manager->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->config);
        free(temp);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
