void* create_and_populate_pdu_list(int N, int log_details) {
    if (N > MAX_LIST_SIZE) {
        return NULL; // Error: Exceeds maximum list size
    }

    NFAPI_CRC_INDICATION_PDU_T** pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        return NULL; // Error: Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int created_count = 0;

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        if (log_details) {
            printf("Creating structure %d\n", i);
        }

        pdu_list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list[i]) {
            pthread_mutex_unlock(&mutex);
            if (log_details) {
                printf("Error: Memory allocation failed for structure %d\n", i);
            }
            break;
        }

        // Generate unique RNTI and random CRCFLAG
        int rnti = rand() % 1024; // Assuming RNTI range is from 0 to 1023
        while (i > 0 && pdu_list[i-1]->RNTI == rnti) {
            rnti = rand() % 1024;
        }
        pdu_list[i]->RNTI = rnti;

        pdu_list[i]->CRCFLAG = (rand() % 2) ? '1' : '0';

        if (log_details) {
            printf("Created structure with RNTI: %d, CRCFLAG: %c\n", rnti, pdu_list[i]->CRCFLAG);
        }
        created_count++;
        pthread_mutex_unlock(&mutex);
    }

    if (created_count == 0) {
        free(pdu_list);
        return NULL; // Error: No structures were created
    }

    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_list, created_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        free(pdu_list);
        return NULL; // Error: Memory reallocation failed
    }

    pthread_mutex_destroy(&mutex);

    return pdu_list;
}

int main() {
    int N = 5;
    int log_details = 1;

    void** result = create_and_populate_pdu_list(N, log_details);
    if (result) {
        printf("Successfully created %d structures\n", N);
        // Free allocated memory here
