CipherContext* init_aes_cbc(const char* password) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    // Derive the key using SHA-1
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), hash);

    // Set key and IV for AES-256-CBC
    memcpy(ctx->key.enc, hash, sizeof(AES_KEY));
    memset(ctx->iv, 0, AES_BLOCK_SIZE); // Initialize IV to zero

    // Enable the cipher
    if (AES_set_encrypt_key(hash, 256, &ctx->key) != 0) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(CipherContext* ctx) {
    if (ctx) {
        AES_set_encrypt_key(NULL, 0, &ctx->key); // Disable the cipher
        free(ctx);
    }
}
