int resolve_dns(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        printf("DNS resolution failed: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* h = (struct sockaddr_in*)p->ai_addr;
        memcpy(ip_address, &(h->sin_addr), sizeof(u_char) * 4);
        break;
    }

    freeaddrinfo(res);
    return 0;
}

void cleanup_pdus(NFAPI_L2_PDU_T** pdus, int n) {
    for (int i = 0; i < n; i++) {
        if (pdus[i] != NULL) {
            // Free any dynamically allocated memory within each PDU
            free(pdus[i]);
        }
    }

    free(pdus);
    printf("PDUs cleaned up.\n");
}

