        u_char ip_address[4];
        const char* hostname = "example.com";

        if (resolve_dns(hostname, ip_address) == 0) {
            printf("Resolved IP address: %d.%d.%d.%d\n", ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
        }

        // Simulate using the PDUs

        cleanup_pdus(pdus, n);
    }

    return 0;
}
