#include <stdlib.h>
#include <stdbool.h>

typedef struct LTE_UE_Context {
    EUtranUeIdentity_t ue_identity;
    RLC_Status_t rlc_status;
    struct LTE_UE_Context* next;
} LTE_UE_Context;

typedef struct LTE_UE_List {
    LTE_UE_Context* head;
    size_t unique_ue_count;
} LTE_UE_List;

LTE_UE_List* create_ue_list() {
    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (list) {
        list->head = NULL;
        list->unique_ue_count = 0;
    }
    return list;
}

void free_ue_list(LTE_UE_List* list) {
    LTE_UE_Context* current = list->head;
    while (current) {
        LTE_UE_Context* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

bool add_ue_context(LTE_UE_List* list, EUtranUeIdentity_t ue_identity, RLC_Status_t rlc_status) {
    if (!list) return false;

    LTE_UE_Context* new_context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!new_context) return false;

    new_context->ue_identity = ue_identity;
    new_context->rlc_status = rlc_status;
    new_context->next = list->head;

    // Ensure no two consecutive contexts share the same UE identity
    LTE_UE_Context* current = list->head;
    if (current && current->ue_identity == ue_identity) {
        free(new_context);
        return false;
    }

    list->head = new_context;

    // Update unique UE count
    bool is_unique = true;
    while (current) {
        if (current->ue_identity == ue_identity) {
            is_unique = false;
            break;
        }
        current = current->next;
    }

    if (is_unique) list->unique_ue_count++;

    return true;
}

bool remove_ue_context(LTE_UE_List* list, EUtranUeIdentity_t ue_identity) {
    if (!list || !list->head) return false;

    LTE_UE_Context* current = list->head;
    LTE_UE_Context* prev = NULL;

    while (current) {
        if (current->ue_identity == ue_identity) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->unique_ue_count--;
            return true;
        }
        prev = current;
        current = current->next;
    }

    return false;
}

size_t get_unique_ue_count(LTE_UE_List* list) {
    if (!list) return 0;
    return list->unique_ue_count;
}
