typedef struct LTE_UE_Context_Structure {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    MME_IP_ADDRESS mme_ip_address;
    S1AP_MESSAGE_T s1ap_message;
    int qos_priority;
    pthread_mutex_t lock;
    struct LTE_UE_Context_Structure *next;
} LTE_UE_Context;

// Function to create a new UE context
LTE_UE_Context* create_UE_context(RRC_STATE rrc_state, PDP_CONTEXT pdp_context, MME_IP_ADDRESS mme_ip_address, S1AP_MESSAGE_T s1ap_message, int qos_priority) {
    LTE_UE_Context *new_context = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
    if (new_context == NULL) {
        perror("Failed to allocate memory for UE context");
        return NULL;
    }
    new_context->rrc_state = rrc_state;
    new_context->pdp_context = pdp_context;
    new_context->mme_ip_address = mme_ip_address;
    new_context->s1ap_message.data = malloc(s1ap_message.length);
    if (new_context->s1ap_message.data == NULL) {
        perror("Failed to allocate memory for S1AP message");
        free(new_context);
        return NULL;
    }
    memcpy(new_context->s1ap_message.data, s1ap_message.data, s1ap_message.length);
    new_context->s1ap_message.length = s1ap_message.length;
    new_context->qos_priority = qos_priority;
    pthread_mutex_init(&new_context->lock, NULL);
    new_context->next = NULL;
    return new_context;
}

// Function to free an UE context
void free_UE_context(LTE_UE_Context *context) {
    if (context != NULL) {
        free(context->s1ap_message.data);
        pthread_mutex_destroy(&context->lock);
        free(context);
    }
}

// Function to add a new UE context to the list
void add_UE_context(LTE_UE_Context **head, LTE_UE_Context *new_context) {
    pthread_mutex_lock(&(*head)->lock);
    new_context->next = *head;
    *head = new_context;
    pthread_mutex_unlock(&(*head)->lock);
}

// Function to remove an UE context from the list
void remove_UE_context(LTE_UE_Context **head, LTE_UE_Context *context) {
    pthread_mutex_lock(&(*head)->lock);
    if (*head == context) {
        *head = context->next;
    } else {
        LTE_UE_Context *current = *head;
        while (current != NULL && current->next != context) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = context->next;
        }
    }
    pthread_mutex_unlock(&(*head)->lock);
    free_UE_context(context);
}

// Function to find an UE context by its MME IP address
LTE_UE_Context* find_UE_context_by_MME_ip(LTE_UE_Context *head, MME_IP_ADDRESS mme_ip_address) {
    LTE_UE_Context *current = head;
    while (current != NULL) {
        if (strcmp(current->mme_ip_address.address, mme_ip_address.address) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

