        // Allocate and populate CRC_INDICATION_REL8_TAG
        (*array)[i].crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if ((*array)[i].crc_indication_rel8_tag == NULL) {
            for (int j = 0; j < i; j++) {
                free((*array)[j].crc_indication_rel8_tag);
