    for (int i = 0; i < *data_size; i++) {
        free((*array)[i].crc_indication_rel8_tag);
    }
    free(*array);

    return NULL;
}

int main() {
    pthread_t threads[MAX_ELEMENTS];
    int data_sizes[MAX_ELEMENTS];

    // Initialize data sizes
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        data_sizes[i] = rand() % 1000 + 1;
    }

    // Create and start threads
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        pthread_create(&threads[i], NULL, process_array, &data_sizes[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
