#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef enum { RRC_IDLE, RRC_CONNECTED } RRC_STATE;
typedef struct pdp_context {
    // Define PDP context structure
} PDP_CONTEXT;

typedef struct s1ap_message_t {
    int version;
    void* payload;
    size_t payload_size;
} S1AP_MESSAGE_T;

typedef struct lte_ue_context_struct {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    char mme_ip_address[16];
    S1AP_MESSAGE_T* s1ap_message;
    int qos_priority;
} LTE_UE_CONTEXT_STRUCT;

typedef struct lte_ue_context_list {
    LTE_UE_CONTEXT_STRUCT** contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_UE_CONTEXT_LIST;

LTE_UE_CONTEXT_LIST* create_lte_ue_context_list(size_t initial_capacity) {
    LTE_UE_CONTEXT_LIST* list = (LTE_UE_CONTEXT_LIST*)malloc(sizeof(LTE_UE_CONTEXT_LIST));
    if (list == NULL) {
        return NULL;
    }
    list->contexts = (LTE_UE_CONTEXT_STRUCT**)calloc(initial_capacity, sizeof(LTE_UE_CONTEXT_STRUCT*));
    if (list->contexts == NULL) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_lte_ue_context_list(LTE_UE_CONTEXT_LIST* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->contexts[i]);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

LTE_UE_CONTEXT_STRUCT* create_lte_ue_context(RRC_STATE rrc_state, PDP_CONTEXT pdp_context, const char* mme_ip_address, S1AP_MESSAGE_T* s1ap_message, int qos_priority) {
    LTE_UE_CONTEXT_STRUCT* context = (LTE_UE_CONTEXT_STRUCT*)malloc(sizeof(LTE_UE_CONTEXT_STRUCT));
    if (context == NULL) {
        return NULL;
    }
    context->rrc_state = rrc_state;
    context->pdp_context = pdp_context;
    snprintf(context->mme_ip_address, 16, "%s", mme_ip_address);
    context->s1ap_message = s1ap_message;
    context->qos_priority = qos_priority;
    return context;
}

void destroy_lte_ue_context(LTE_UE_CONTEXT_STRUCT* context) {
    free(context);
}

int add_lte_ue_context(LTE_UE_CONTEXT_LIST* list, LTE_UE_CONTEXT_STRUCT* context) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LTE_UE_CONTEXT_STRUCT** new_contexts = (LTE_UE_CONTEXT_STRUCT**)realloc(list->contexts, new_capacity * sizeof(LTE_UE_CONTEXT_STRUCT*));
        if (new_contexts == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }
    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

LTE_UE_CONTEXT_STRUCT* get_lte_ue_context(LTE_UE_CONTEXT_LIST* list, size_t index) {
    if (index >= list->count) {
        return NULL;
