#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_DYNAMIC_ARRAY {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_DYNAMIC_ARRAY;

void log_operation(const char *operation, time_t timestamp) {
    printf("%s at %ld\n", operation, timestamp);
}

NFAPI_DYNAMIC_ARRAY* create_dynamic_array() {
    NFAPI_DYNAMIC_ARRAY *array = (NFAPI_DYNAMIC_ARRAY*)malloc(sizeof(NFAPI_DYNAMIC_ARRAY));
    if (array == NULL) {
        log_operation("Failed to allocate memory for dynamic array", time(NULL));
        return NULL;
    }
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->data == NULL) {
        log_operation("Failed to allocate memory for dynamic array data", time(NULL));
        free(array);
        return NULL;
    }
    array->capacity = MAX_ELEMENTS;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    log_operation("Dynamic array created successfully", time(NULL));
    return array;
}

void destroy_dynamic_array(NFAPI_DYNAMIC_ARRAY *array) {
    if (array != NULL) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        free(array);
        log_operation("Dynamic array destroyed successfully", time(NULL));
    }
}

int insert_into_dynamic_array(NFAPI_DYNAMIC_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (array == NULL || pdu == NULL) {
        return -1;
    }
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        log_operation("Failed to insert into dynamic array due to insufficient capacity", time(NULL));
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    array->data[array->size++] = *pdu;
    pthread_mutex_unlock(&array->mutex);
    log_operation("Element inserted into dynamic array successfully", time(NULL));
    return 0;
}

int iterate_dynamic_array(NFAPI_DYNAMIC_ARRAY *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (array == NULL || callback == NULL) {
        return -1;
    }
    pthread_mutex_lock(&array->mutex);
    for (size_t i = array->size - 1; i >= 0; i--) {
        callback(array->data[i]);
    }
    pthread_mutex_unlock(&array->mutex);
    log_operation("Dynamic array iterated successfully", time(NULL));
    return 0;
}

int main() {
    NFAPI_DYNAMIC_ARRAY *array = create_dynamic_array();
    if (array == NULL) {
        return -1;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 123;
    pdu.RNTI = 456;
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

    insert_into_dynamic_array(array, &pdu);

    iterate_dynamic_array(array, [](NFAPI_CRC_INDICATION_PDU_T pdu) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
    });

    destroy_dynamic_array(array);

    return 0;
}
