int computeMD5Hash(const char* filePath, unsigned char* hashDigest) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return -1;

    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    const size_t bufferSize = 1024 * 1024; // 1MB buffer
    unsigned char buffer[bufferSize];
    size_t bytesRead;

    while ((bytesRead = fread(buffer, 1, bufferSize, file)) > 0) {
        MD5_Update(&md5Context, buffer, bytesRead);
    }

    fclose(file);

    if (ferror(file)) return -2;
    MD5_Final(hashDigest, &md5Context);

    return 0;
}
