#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define N 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_T;

typedef struct {
    RX_UE_INFORMATION_T *rx_ue_info;
    CRC_INDICATION_REL8_T *crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_crc_pdu(int N) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_ue_info = (RX_UE_INFORMATION_T*)malloc(sizeof(RX_UE_INFORMATION_T));
        if (!pdu_list[i].rx_ue_info) {
            perror("Memory allocation failed");
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(pdu_list[j].rx_ue_info);
            }
            free(pdu_list);
            return NULL;
        }

        pdu_list[i].crc_ind_rel8 = (CRC_INDICATION_REL8_T*)malloc(sizeof(CRC_INDICATION_REL8_T));
        if (!pdu_list[i].crc_ind_rel8) {
            perror("Memory allocation failed");
            // Clean up previously allocated memory
            for (int j = 0; j <= i; j++) {
                free(pdu_list[j].rx_ue_info);
                free(pdu_list[j].crc_ind_rel8);
            }
            free(pdu_list);
            return NULL;
        }

        // Populate structures with random values and valid tags
        pthread_mutex_lock(&mutex);
        pdu_list[i].rx_ue_info->RX_UE_INFORMATION_TAG = i + 1; // Example tag generation
        pdu_list[i].rx_ue_info->RNTI = rand() % 1000; // Random RNTI value
        pdu_list[i].crc_ind_rel8->CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Random CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

    return pdu_list;
}

// Function to validate the integrity of the allocated structures
int validate_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int N) {
    for (int i = 1; i < N; i++) {
        if (pdu_list[i].rx_ue_info->RNTI == pdu_list[i - 1].rx_ue_info->RNTI) {
            printf("Duplicate RNTI found: %d\n", pdu_list[i].rx_ue_info->RNTI);
            return 0;
        }
    }
    return 1;
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_and_populate_crc_pdu(N);
    if (pdu_list) {
        if (validate_crc_pdu(pdu_list, N)) {
            printf("All structures are valid.\n");
        } else {
            printf("Validation failed.\n");
        }
        // Free allocated memory
        for (int i = 0; i < N; i++) {
            free(pdu_list[i].rx_ue_info);
            free(pdu_list[i].crc_ind_rel8);
        }
        free(pdu_list);
    }
    return 0;
}
