typedef struct {
    int routing_table_entry;
    void* tcp_connection_object; // Assuming a generic TCP connection object type
    unsigned int retransmission_timeout;
} NetworkNode;

typedef struct {
    NetworkNode** nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NodeList;

void initialize_node_list(NodeList* list, size_t initial_capacity) {
    list->nodes = (NetworkNode**)malloc(initial_capacity * sizeof(NetworkNode*));
    if (!list->nodes) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_node(NodeList* list, NetworkNode* node) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->nodes = (NetworkNode**)realloc(list->nodes, list->capacity * sizeof(NetworkNode*));
        if (!list->nodes) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
    }
    list->nodes[list->size++] = node;
    pthread_mutex_unlock(&list->lock);
}

NetworkNode* create_network_node(int routing_table_entry, void* tcp_connection_object, unsigned int retransmission_timeout) {
    NetworkNode* node = (NetworkNode*)malloc(sizeof(NetworkNode));
    if (!node) {
        // Handle memory allocation failure
        return NULL;
    }
    node->routing_table_entry = routing_table_entry;
    node->tcp_connection_object = tcp_connection_object; // Assuming proper initialization of the TCP connection object
    node->retransmission_timeout = retransmission_timeout;
    return node;
}

void free_network_node(NetworkNode* node) {
    if (node) {
        free(node);
    }
}

void free_node_list(NodeList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        free_network_node(list->nodes[i]);
    }
    free(list->nodes);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
