} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRC_Indication_List_T;

CRC_Indication_List_T* create_crc_indication_list(size_t initial_capacity) {
    CRC_Indication_List_T* list = (CRC_Indication_List_T*)malloc(sizeof(CRC_Indication_List_T));
    if (!list) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;

    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        free(list->pdus);
        free(list);
        return NULL;
    }

    return list;
}

void destroy_crc_indication_list(CRC_Indication_List_T* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->pdus[i]);
    }
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication_pdu(CRC_Indication_List_T* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_pdus = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_pdus) return -1;

