#include <vector>
#include <thread>
#include <queue>
#include <mutex>

struct Task {
    // Define task properties here
};

class WorkerThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<Task*> tasks;
    std::mutex queueMutex;

public:
    WorkerThreadPool(int numWorkers) : workers(numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workers[i] = std::thread(&WorkerThreadPool::worker, this);
        }
    }

    ~WorkerThreadPool() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            tasks.push(nullptr); // Signal threads to stop
        }
        for (std::thread &w : workers) {
            w.join();
        }
    }

    void addTask(Task* task) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            tasks.push(task);
        }
    }

private:
    void worker() {
        while (true) {
            Task* task;
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                if (tasks.empty()) {
                    continue; // No tasks, sleep or yield
                }
                task = tasks.front();
                tasks.pop();
            }

            if (task == nullptr) {
                break; // Stop signal received
            }

            // Process task
        }
    }
};
