void init_queue(PendingQueue* q, int capacity) {
    q->queue = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->front = q->rear = -1;
    q->size = 0;
    q->capacity = capacity;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

void enqueue(PendingQueue* q, NFAPI_CRC_INDICATION_PDU_T item) {
    if (q->size == q->capacity) {
        // Handle queue full condition
    } else {
        q->rear = (q->rear + 1) % q->capacity;
        q->queue[q->rear] = item;
        q->size++;
        pthread_cond_signal(&q->not_empty);
    }
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PendingQueue* q) {
    NFAPI_CRC_INDICATION_PDU_T item;
    if (q->size == 0) {
        // Handle queue empty condition
    } else {
        item = q->queue[q->front];
        q->front = (q->front + 1) % q->capacity;
        q->size--;
    }
    return item;
}

