    int opt;
    while ((opt = getopt(argc, argv, "hc:o:")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [-c <cipher_option>] -i <input_file> [-o <output_file>]\n", argv[0]);
