typedef struct {
    // Define fields for RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, etc.
    int rx_ue_info_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crc_flag;  // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t count;
    size_t allocated;
} NFAPI_BUFFER_INFO;

NFAPI_BUFFER_INFO* generate_nfaapi_crc_indication_pdu(size_t desired_count, int log_level) {
    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }

    NFAPI_BUFFER_INFO *info = (NFAPI_BUFFER_INFO *)malloc(sizeof(NFAPI_BUFFER_INFO));
    if (!info) {
        return NULL;  // Handle memory allocation failure
    }
    info->count = 0;
    info->allocated = desired_count;

    info->buffer = (NFAPI_CRC_INDICATION_PDU_T *)calloc(desired_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!info->buffer) {
        free(info);
        return NULL;  // Handle memory allocation failure
    }

    for (size_t i = 0; i < desired_count; ++i) {
        info->buffer[i].rx_ue_info_tag = rand();
        info->buffer[i].rnti = rand();
        info->buffer[i].crc_indication_rel8_tag = rand();
        info->buffer[i].crc_flag = (rand() % 2);  // Randomly set to 0 or 1

        if (log_level > 0) {
            printf("Generated PDU %zu: RX_UE_Info_Tag=%d, RNTI=%d, CRC_Indication_Rel8_Tag=%d, CRC_Flag=%d\n",
                   i, info->buffer[i].rx_ue_info_tag, info->buffer[i].rnti,
                   info->buffer[i].crc_indication_rel8_tag, info->buffer[i].crc_flag);
        }
    }

    info->count = desired_count;
    return info;
}

// Example usage:
int main() {
    NFAPI_BUFFER_INFO *info = generate_nfaapi_crc_indication_pdu(1000, 1);  // Generate 1000 PDUs with logging
    if (info) {
        printf("Generated %zu PDUs successfully.\n", info->count);
        free(info->buffer);
        free(info);
    } else {
        printf("Failed to generate PDUs.\n");
    }
    return 0;
}
