} NDHM_Metric;

NDHM_Metric* init_ndhm_metrics(int N, pthread_mutex_t* mutex) {
    if (N <= 0 || N > 10000) {
        return NULL; // Invalid array size
    }

    NDHM_Metric* metrics = malloc(N * sizeof(NDHM_Metric));
    if (metrics == NULL) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_init(mutex, NULL); // Initialize mutex

    for (int i = 0; i < N; i++) {
        memset(&metrics[i], 0, sizeof(NDHM_Metric));
    }

    return metrics;
}

void destroy_ndhm_metrics(NDHM_Metric* metrics, int N, pthread_mutex_t* mutex) {
    if (metrics != NULL && N > 0 && N <= 10000) {
        pthread_mutex_lock(mutex);
        free(metrics);
        pthread_mutex_unlock(mutex);
    }
}
