#define MAX_IP_LEN 16

typedef enum {
    DEVICE_TYPE_UNKNOWN,
    DEVICE_TYPE_SERVER,
    DEVICE_TYPE_WORKSTATION,
    DEVICE_TYPE_ROUTER
} DEVICE_TYPE;

typedef struct {
    int DEVICE_ID;
    char IP_ADDRESS[MAX_IP_LEN];
    int PORT_NUMBER;
    int CONNECTION_STATUS;
    DEVICE_TYPE DEVICE_TYPE_IDENTIFIER;
    // Add more fields as needed
    unsigned long UPTIME;
} NETWORK_DEVICE_T;

struct NetworkDeviceAllocator {
    NETWORK_DEVICE_T *devices;
    size_t allocated_count;
    size_t used_count;
};

struct NetworkDeviceAllocator* initialize_device_allocator(size_t initial_capacity) {
    struct NetworkDeviceAllocator *allocator = (struct NetworkDeviceAllocator*)malloc(sizeof(struct NetworkDeviceAllocator));
    if (!allocator) return NULL;

    allocator->devices = (NETWORK_DEVICE_T*)malloc(initial_capacity * sizeof(NETWORK_DEVICE_T));
    if (!allocator->devices) {
        free(allocator);
        return NULL;
    }

    allocator->allocated_count = initial_capacity;
    allocator->used_count = 0;

    return allocator;
}

int add_device(struct NetworkDeviceAllocator *allocator, int device_id, const char *ip_address, int port_number, int connection_status, DEVICE_TYPE device_type_identifier) {
    if (allocator->used_count >= allocator->allocated_count) {
        size_t new_capacity = allocator->allocated_count ? allocator->allocated_count * 2 : 16;
        NETWORK_DEVICE_T *new_devices = (NETWORK_DEVICE_T*)realloc(allocator->devices, new_capacity * sizeof(NETWORK_DEVICE_T));
        if (!new_devices) return -1;

        allocator->devices = new_devices;
        allocator->allocated_count = new_capacity;
    }

    NETWORK_DEVICE_T *device = &allocator->devices[allocator->used_count++];
    device->DEVICE_ID = device_id;
    strncpy(device->IP_ADDRESS, ip_address, MAX_IP_LEN);
    device->PORT_NUMBER = port_number;
    device->CONNECTION_STATUS = connection_status;
    device->DEVICE_TYPE_IDENTIFIER = device_type_identifier;

    return 0;
}

void free_device_allocator(struct NetworkDeviceAllocator *allocator) {
    free(allocator->devices);
    free(allocator);
}
