        fprintf(stderr, "Invalid number of devices\n");
        return NULL;
    }

    NETWORK_DEVICE_T** deviceArray = (NETWORK_DEVICE_T**)malloc(numDevices * sizeof(NETWORK_DEVICE_T*));
    if (!deviceArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < numDevices; i++) {
        deviceArray[i] = (NETWORK_DEVICE_T*)malloc(sizeof(NETWORK_DEVICE_T));
        if (!deviceArray[i]) {
            fprintf(stderr, "Memory allocation failed for device %d\n", i);
            // Free previously allocated devices
            for (int j = 0; j < i; j++) {
                free(deviceArray[j]);
            }
            free(deviceArray);
            return NULL;
        }

        // Initialize device fields with default values or user input
        memset(deviceArray[i], 0, sizeof(NETWORK_DEVICE_T));
        deviceArray[i]->DEVICE_ID = i + 1; // Example initialization
    }

    return deviceArray;
