typedef struct {
    void **nodes;
    int node_count;
    int max_nodes;
    void **edges;
    int edge_count;
    int max_edges;
    // Other graph attributes can be added here
} MY_GRAPH_T;

MY_GRAPH_T* create_graph(int initial_nodes, int initial_edges) {
    MY_GRAPH_T *graph = (MY_GRAPH_T *)malloc(sizeof(MY_GRAPH_T));
    if (!graph) {
        return NULL;  // Memory allocation failed
    }
    graph->nodes = (void **)calloc(initial_nodes, sizeof(void *));
    if (!graph->nodes) {
        free(graph);
        return NULL;  // Memory allocation failed
    }
    graph->node_count = 0;
    graph->max_nodes = initial_nodes;

    graph->edges = (void **)calloc(initial_edges, sizeof(void *));
    if (!graph->edges) {
        free(graph->nodes);
        free(graph);
        return NULL;  // Memory allocation failed
    }
    graph->edge_count = 0;
    graph->max_edges = initial_edges;

    return graph;
}

void free_graph(MY_GRAPH_T *graph) {
    for (int i = 0; i < graph->node_count; i++) {
        // Free node-specific resources if necessary
        free(graph->nodes[i]);
    }
    free(graph->nodes);

    for (int i = 0; i < graph->edge_count; i++) {
        // Free edge-specific resources if necessary
        free(graph->edges[i]);
    }
    free(graph->edges);
    free(graph);
}

void add_node(MY_GRAPH_T *graph, MY_GRAPH_NODE_T *node) {
    if (graph->node_count >= graph->max_nodes) {
        // Resize nodes array if necessary
        graph->nodes = realloc(graph->nodes, 2 * graph->max_nodes * sizeof(void *));
        if (!graph->nodes) {
            return;  // Memory reallocation failed
        }
        graph->max_nodes *= 2;
    }
    graph->nodes[graph->node_count++] = node;
}

void add_edge(MY_GRAPH_T *graph, MY_EDGE_T *edge) {
    if (graph->edge_count >= graph->max_edges) {
        // Resize edges array if necessary
        graph->edges = realloc(graph->edges, 2 * graph->max_edges * sizeof(void *));
        if (!graph->edges) {
            return;  // Memory reallocation failed
        }
        graph->max_edges *= 2;
    }
    graph->edges[graph->edge_count++] = edge;
}

