    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} CRC_INDICATION_T;

typedef struct {
    RX_UE_INFORMATION_T rx_ue_info;
    CRC_INDICATION_T crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    time_t timeout;
} CRC_INDICATION_LIST_T;

void initialize_crc_list(CRC_INDICATION_LIST_T *list, time_t timeout) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->timeout = timeout;
}

int add_entry(CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_T rx_ue_info, CRC_INDICATION_T crc_indication) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of memory
    }
    list->entries[list->count].rx_ue_info = rx_ue_info;
    list->entries[list->count].crc_indication = crc_indication;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void prune_old_entries(CRC_INDICATION_LIST_T *list) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ) {
        if ((current_time - list->entries[i].rx_ue_info.rx_ue_information_tag) > list->timeout) {
            memmove(&list->entries[i], &list->entries[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

size_t get_memory_usage(CRC_INDICATION_LIST_T *list) {
    return sizeof(CRC_INDICATION_LIST_T) + (list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

