#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1024

typedef struct CacheEntry {
    char *key;
    char *data;
    size_t data_size;
    struct CacheEntry *next;
    struct CacheEntry *prev;
} CacheEntry;

typedef struct Cache {
    CacheEntry **entries;
    CacheEntry *head;
    CacheEntry *tail;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} Cache;

Cache* cache_create(size_t max_entries) {
    Cache *cache = (Cache *)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->entries = (CacheEntry **)calloc(max_entries, sizeof(CacheEntry *));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }

    cache->head = NULL;
    cache->tail = NULL;
    cache->size = max_entries;
    cache->count = 0;

    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void cache_destroy(Cache *cache) {
    CacheEntry *entry, *next;
    for (size_t i = 0; i < cache->size; ++i) {
        entry = cache->entries[i];
        while (entry) {
            next = entry->next;
            free(entry->key);
            free(entry->data);
            free(entry);
            entry = next;
        }
    }
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void cache_insert(Cache *cache, const char *key, const char *data, size_t data_size) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count >= cache->size) {
        CacheEntry *evict = cache->tail;
        cache->entries[hash(evict->key)] = NULL;
        free(evict->key);
        free(evict->data);
        free(evict);
        cache->count--;
    }

    CacheEntry *entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    if (!entry) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }
    entry->key = strdup(key);
    entry->data = (char *)malloc(data_size);
    memcpy(entry->data, data, data_size);
    entry->data_size = data_size;

    cache->entries[hash(key)] = entry;
    if (!cache->head) {
        cache->head = cache->tail = entry;
        entry->next = entry->prev = NULL;
    } else {
        entry->next = cache->head;
        entry->prev = NULL;
        cache->head->prev = entry;
        cache->head = entry;
    }
    cache->count++;

    pthread_mutex_unlock(&cache->lock);
}

void *cache_get(Cache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);

    CacheEntry *entry = cache->entries[hash(key)];
    if (entry && strcmp(entry->key, key) == 0) {
        if (entry != cache->head) {
            if (entry->prev) entry->prev->next = entry->next;
            if (entry->next) entry->next->prev = entry->prev;
            entry->next = cache->head;
            entry->prev = NULL;
            cache->head->prev = entry;
            cache->head = entry;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return entry ? entry->data : NULL;
}

// Helper functions for hashing, evicting, and other operations
```

