    sdc_array[id].read_io += rand() % 50;
    sdc_array[id].write_io += rand() % 25;

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void fallback_mechanism(int new_size) {
    if (new_size <= 0 || new_size > MAX_DEVICE_COUNT) {
        fprintf(stderr, "Invalid array size for fallback\n");
        return;
    }

    StorageDeviceConfig* temp_sdc = (StorageDeviceConfig*)realloc(sdc_array, new_size * sizeof(StorageDeviceConfig));
    DiskHealthMonitoring* temp_dhm = (DiskHealthMonitoring*)realloc(dhm_array, new_size * sizeof(DiskHealthMonitoring));

    if (!temp_sdc || !temp_dhm) {
        fprintf(stderr, "Memory reallocation failed for fallback\n");
        free(temp_sdc);
        free(temp_dhm);
        return;
    }

    sdc_array = temp_sdc;
    dhm_array = temp_dhm;
    array_size = new_size;

    printf("Fallback mechanism applied with %d devices\n", array_size);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <array size>\n", argv[0]);
        return 1;
    }

