    pthread_t threads[size];
    int ids[size];

    for (int i = 0; i < size; i++) {
        ids[i] = i;
        if (pthread_create(&threads[i], NULL, update_metrics, &ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }

    // Simulate large-scale scenario
    if (array_size > 512) {
        fallback_mechanism(256);
    }

    free(sdc_array);
    free(dhm_array);

    return 0;
}
