typedef struct {
    char *operation;
    char *key;
    char *iv;
    char *mode;
} ConfigCommand;

// Define a structure for encryption/decryption results
typedef struct {
    int status;
    char *output;
} ResultObject;

// Function to process a single command (to be implemented)
void process_command(ConfigCommand cmd, ResultObject *result) {
    // Placeholder implementation
    if (strcmp(cmd.operation, "encrypt") == 0) {
        result->status = 1; // Simulate success
        result->output = strdup("Encrypted data");
    } else if (strcmp(cmd.operation, "decrypt") == 0) {
        result->status = 0; // Simulate failure
        result->output = NULL;
    }
}

// Function to execute multiple commands from a configuration file
int execute_config_file(const char *filename, ResultObject **results, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return -1; // File open error
    }

    ConfigCommand cmd;
    int result_count = 0;
    while (fscanf(file, "%s %ms %ms %ms", cmd.operation, &cmd.key, &cmd.iv, &cmd.mode) == 4) {
        ResultObject *result = malloc(sizeof(ResultObject));
        if (!result) {
            fclose(file);
            return -1; // Memory allocation error
        }
        process_command(cmd, result);
        results[result_count++] = result;
    }

    *count = result_count;
    fclose(file);
    return 0; // Success
}

// Thread-safe version of execute_config_file
int thread_safe_execute_config_file(const char *filename, ResultObject ***results, int *count) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    int status = execute_config_file(filename, (ResultObject **)malloc(sizeof(ResultObject *) * 10), count); // Assuming max 10 commands
    if (status != 0) {
        pthread_mutex_unlock(&lock);
        return status; // Error occurred
    }

    *results = malloc(*count * sizeof(ResultObject *));
    for (int i = 0; i < *count; i++) {
        (*results)[i] = malloc(sizeof(ResultObject));
        memcpy((*results)[i], results[i], sizeof(ResultObject));
        free(results[i]);
    }

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

// Example usage
int main() {
    ResultObject **results;
    int count;

    int status = thread_safe_execute_config_file("config.txt", &results, &count);
    if (status != 0) {
        printf("Error executing configuration file.\n");
        return 1;
    }

    for (int i = 0; i < count; i++) {
        if (results[i]->status == 0) {
            printf("Command %d failed: No output\n", i);
        } else {
            printf("Command %d output: %s\n", i, results[i]->output);
        }
        free(results[i]->output);
        free(results[i]);
    }
    free(results);

    return 0;
}
