#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkConnection {
    int id;
    time_t timestamp;
    double bandwidth_usage;
    int error_count;
    struct NetworkConnection* next;
} NetworkConnection;

typedef struct Cache {
    NetworkConnection** connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Cache;

Cache* cache_create(size_t initial_capacity) {
    Cache* cache = malloc(sizeof(Cache));
    if (cache == NULL) {
        return NULL;
    }
    cache->connections = calloc(initial_capacity, sizeof(NetworkConnection*));
    if (cache->connections == NULL) {
        free(cache);
        return NULL;
    }
    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

void cache_destroy(Cache* cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        NetworkConnection* conn = cache->connections[i];
        while (conn != NULL) {
            NetworkConnection* next = conn->next;
            free(conn);
            conn = next;
        }
    }
    free(cache->connections);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

void cache_insert(Cache* cache, int id, time_t timestamp, double bandwidth_usage, int error_count) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size >= cache->capacity) {
        NetworkConnection** new_connections = realloc(cache->connections, cache->capacity * 2 * sizeof(NetworkConnection*));
        if (new_connections == NULL) {
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
        cache->connections = new_connections;
        cache->capacity *= 2;
    }
    NetworkConnection* new_conn = malloc(sizeof(NetworkConnection));
    if (new_conn == NULL) {
        pthread_mutex_unlock(&cache->mutex);
        return;
    }
    new_conn->id = id;
    new_conn->timestamp = timestamp;
    new_conn->bandwidth_usage = bandwidth_usage;
    new_conn->error_count = error_count;
    new_conn->next = NULL;
    cache->connections[cache->size++] = new_conn;
    pthread_mutex_unlock(&cache->mutex);
}

NetworkConnection* cache_lookup(Cache* cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->size; ++i) {
        NetworkConnection* conn = cache->connections[i];
        while (conn != NULL) {
            if (conn->id == id) {
                pthread_mutex_unlock(&cache->mutex);
                return conn;
            }
            conn = conn->next;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

void cache_delete(Cache* cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->size; ++i) {
        NetworkConnection** conn_ptr = &cache->connections[i];
        while (*conn_ptr != NULL) {
            if ((*conn_ptr)->id == id) {
                NetworkConnection* to_delete = *conn_ptr;
                *conn_ptr = (*conn_ptr)->next;
                free(to_delete);
                pthread_mutex_unlock(&cache->mutex);
                return;
            }
            conn_ptr = &(*conn_ptr)->next;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

void cache_prune(Cache* cache, time_t timeout) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->size;) {
        NetworkConnection** conn_ptr = &cache->connections[i];
        if ((*conn_ptr)->timestamp + timeout < time(NULL)) {
            NetworkConnection* to_delete = *conn_ptr;
            *conn_ptr = (*conn_ptr)->next;
            free(to_delete);
            --i;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

void cache_set_timeout(Cache* cache, time_t timeout) {
    // Placeholder for dynamic reconfiguration of the timeout period
}

size_t cache_get_size(Cache* cache) {
    size_t size;
    pthread_mutex_lock(&cache->mutex);
    size = cache->size;
    pthread_mutex_unlock(&cache->mutex);
    return size;
}
