#define N 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG;
}

void validate_list(NFAPI_CRC_INDICATION_PDU_T **list, int size) {
    for (int i = 0; i < size - 1; i++) {
        if (list[i]->RNTI == list[i+1]->RNTI) {
            fprintf(stderr, "Duplicate RNTI found at index %d\n", i);
            exit(EXIT_FAILURE);
        }
        if (generate_checksum(list[i]) != generate_checksum(list[i+1])) {
            fprintf(stderr, "Checksum mismatch at index %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void *process_data(void *arg) {
    int thread_id = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!list) {
        fprintf(stderr, "Memory allocation failed for thread %d\n", thread_id);
        return NULL;
    }

    srand(time(NULL) + thread_id); // Seed random number generator

    for (int i = 0; i < N; i++) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!list[i]) {
            fprintf(stderr, "Memory allocation failed for element %d in thread %d\n", i, thread_id);
            free_memory(list, i);
            return NULL;
        }

        list[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i]->RNTI = rand() % 500;
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    validate_list(list, N);

    // Process data here...

    free_memory(list, N);
    return NULL;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T **list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    free(list);
}

int main() {
    pthread_t threads[N];
    int thread_ids[N];

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_data, &thread_ids[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < N; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Thread join failed\n");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
