typedef struct LTE_UERadioResourceConfigDedicated_s {
    int cellID;
    int bandwidthPart;
    // Other relevant fields
} LTE_UERadioResourceConfigDedicated_t;

typedef struct ListEntry_s {
    LTE_UERadioResourceConfigDedicated_t data;
    struct ListEntry_s* next;
} ListEntry_t;

typedef struct {
    ListEntry_t* head;
    pthread_mutex_t lock;
} LTE_RRM_List_t;

void LTE_RRM_Init(LTE_RRM_List_t* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

LTE_UERadioResourceConfigDedicated_t* LTE_RRM_Add(LTE_RRM_List_t* list, int cellID, int bandwidthPart) {
    ListEntry_t* newEntry = (ListEntry_t*)malloc(sizeof(ListEntry_t));
    if (!newEntry) return NULL; // Handle out-of-memory error

    newEntry->data.cellID = cellID;
    newEntry->data.bandwidthPart = bandwidthPart;
    newEntry->next = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = newEntry;
    pthread_mutex_unlock(&list->lock);

    return &newEntry->data;
}

int LTE_RRM_Delete(LTE_RRM_List_t* list, int cellID) {
    ListEntry_t* current = list->head;
    ListEntry_t* previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.cellID == cellID) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Successfully deleted
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Cell ID not found
}

LTE_UERadioResourceConfigDedicated_t* LTE_RRM_Get(LTE_RRM_List_t* list, int cellID) {
    ListEntry_t* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.cellID == cellID) {
            pthread_mutex_unlock(&list->lock);
            return &current->data; // Found and returned
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Cell ID not found
}

void LTE_RRM_Destroy(LTE_RRM_List_t* list) {
    ListEntry_t* current = list->head;
    ListEntry_t* next;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
