} NFAPI_CRC_INDICATION_PDU_T;

void initList(NFAPI_CRC_INDICATION_PDU_T *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

RX_UE_INFORMATION_TAG* createNode(int rnti, int crcFlag) {
    RX_UE_INFORMATION_TAG *node = (RX_UE_INFORMATION_TAG *)malloc(sizeof(RX_UE_INFORMATION_TAG));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    node->value = rnti;
    node->crcIndicationRel8Tag = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!node->crcIndicationRel8Tag) {
        fprintf(stderr, "Memory allocation failed\n");
        free(node);
        return NULL;
    }
    node->crcIndicationRel8Tag->CRCFLAG = crcFlag;
    node->next = NULL;
    return node;
}

void addToQueue(NFAPI_CRC_INDICATION_PDU_T *list, int rnti, int crcFlag) {
    pthread_mutex_lock(&list->lock);
    RX_UE_INFORMATION_TAG *newNode = createNode(rnti, crcFlag);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        RX_UE_INFORMATION_TAG *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanupList(NFAPI_CRC_INDICATION_PDU_T *list) {
    pthread_mutex_lock(&list->lock);
    RX_UE_INFORMATION_TAG *current = list->head;
    while (current != NULL) {
        RX_UE_INFORMATION_TAG *temp = current;
        current = current->next;
        free(temp->crcIndicationRel8Tag);
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

// Add unit tests and error handling code here

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T myList;
    initList(&myList);

    for (int i = 0; i < MAX_UEs; i++) {
        int rnti = rand();
        int crcFlag = (rand() % 2 == 0) ? 1 : 0;
        addToQueue(&myList, rnti, crcFlag);
    }

    cleanupList(&myList);

    return 0;
}
