#define MAX_CONNECTIONS 1000
#define CACHE_SIZE 500

typedef struct {
    char CLIENT_IP[16];
    char SERVER_IP[16];
    long BYTES_TRANSFERRED;
    double Mbps_RATE;
} TCP_CONNECTION_STATS;

typedef struct {
    TCP_CONNECTION_STATS *cache[CACHE_SIZE];
    int count;
    pthread_mutex_t lock;
} ConnectionCache;

void initializeCache(ConnectionCache *cache) {
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

TCP_CONNECTION_STATS* getFreeSlot(ConnectionCache *cache) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache->cache[i] == NULL) {
            return cache->cache[i];
        }
    }
    return NULL;
}

void addConnection(ConnectionCache *cache, TCP_CONNECTION_STATS *newStats) {
    pthread_mutex_lock(&cache->lock);
    TCP_CONNECTION_STATS *freeSlot = getFreeSlot(cache);
    if (freeSlot != NULL) {
        *freeSlot = *newStats;
        cache->count++;
    } else {
        printf("Error: Cache full, cannot add new connection.\n");
    }
    pthread_mutex_unlock(&cache->lock);
}

void cleanupCache(ConnectionCache *cache) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache->cache[i] != NULL) {
            free(cache->cache[i]);
            cache->cache[i] = NULL;
        }
    }
    cache->count = 0;
    pthread_mutex_unlock(&cache->lock);
}

void *threadFunction(void *arg) {
    ConnectionCache *cache = (ConnectionCache *)arg;
    // Simulate adding connections
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        TCP_CONNECTION_STATS *newStats = malloc(sizeof(TCP_CONNECTION_STATS));
        snprintf(newStats->CLIENT_IP, sizeof(newStats->CLIENT_IP), "192.168.%d.%d", i % 256, i / 256);
        snprintf(newStats->SERVER_IP, sizeof(newStats->SERVER_IP), "10.0.%d.%d", i % 256, i / 256);
        newStats->BYTES_TRANSFERRED = rand() % 100000000;
        newStats->Mbps_RATE = (double)newStats->BYTES_TRANSFERRED / 1048576.0; // Simplified calculation
        addConnection(cache, newStats);
    }
    return NULL;
}

int main() {
    ConnectionCache cache;
    initializeCache(&cache);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, threadFunction, &cache);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanupCache(&cache);

    return 0;
}
```

