#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256
#define MIN_ACCESS_INTERVAL 1

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    time_t access_timestamp;
    size_t total_bytes_read;
    size_t bytes_per_sec;
} FILE_ACCESS_STATS;

typedef struct {
    FILE_ACCESS_STATS *cache;
    size_t capacity;
    size_t size;
    size_t oldest_index;
} AccessCache;

AccessCache* create_access_cache(size_t initial_capacity) {
    AccessCache* cache = malloc(sizeof(AccessCache));
    if (cache == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cache->cache = calloc(initial_capacity, sizeof(FILE_ACCESS_STATS));
    if (cache->cache == NULL) {
        free(cache);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cache->capacity = initial_capacity;
    cache->size = 0;
    cache->oldest_index = 0;
    return cache;
}

void destroy_access_cache(AccessCache* cache) {
    if (cache != NULL) {
        free(cache->cache);
        free(cache);
    }
}

int add_file_access(AccessCache* cache, const char* filename, size_t bytes_read) {
    if (filename == NULL || strlen(filename) >= MAX_FILENAME_LENGTH) {
        fprintf(stderr, "Invalid filename\n");
        return -1;
    }
    time_t now = time(NULL);
    if (cache->size > 0 && difftime(now, cache->cache[cache->oldest_index].access_timestamp) < MIN_ACCESS_INTERVAL) {
        fprintf(stderr, "Too frequent access to %s\n", filename);
        return -1;
    }
    size_t index = (cache->oldest_index + cache->size) % cache->capacity;
    if (cache->size == cache->capacity) {
        cache->oldest_index = (cache->oldest_index + 1) % cache->capacity;
        cache->size--;
    }
    strncpy(cache->cache[index].filename, filename, MAX_FILENAME_LENGTH);
    cache->cache[index].access_timestamp = now;
    cache->cache[index].total_bytes_read += bytes_read;
    cache->size++;
    return 0;
}

void update_cache_stats(AccessCache* cache) {
    for (size_t i = 0; i < cache->size; i++) {
        time_t now = time(NULL);
        double elapsed_time = difftime(now, cache->cache[i].access_timestamp);
        if (elapsed_time > 0) {
            cache->cache[i].bytes_per_sec = cache->cache[i].total_bytes_read / elapsed_time;
        } else {
            cache->cache[i].bytes_per_sec = 0;
        }
    }
}

// Additional functions for thread safety, error logging, unit tests, dynamic cache size adjustment, and frequency tracking can be implemented here.

int main() {
    AccessCache* cache = create_access_cache(100);
    if (cache == NULL) {
        return 1;
    }

    add_file_access(cache, "file1.txt", 1024);
    add_file_access(cache, "file2.txt", 2048);
    update_cache_stats(cache);

    destroy_access_cache(cache);
    return 0;
}
