typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples_count;
} ImageInfo;

ImageInfo* parse_tiff_and_extract_info(const char* tiff_file_path) {
    TIFF* tif = TIFFOpen(tiff_file_path, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file.\n");
        return NULL;
    }

    uint16_t bits_per_sample, samples_per_pixel, extra_samples_count;
    TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
    TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    TIFFGetFieldDefaulted(tif, TIFFTAG_EXTRASAMPLES, &extra_samples_count);

    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        fprintf(stderr, "Unsupported bits per sample: %d\n", bits_per_sample);
        TIFFClose(tif);
        return NULL;
    }

    ImageInfo* info = (ImageInfo*)malloc(sizeof(ImageInfo));
    if (!info) {
        fprintf(stderr, "Memory allocation failed.\n");
        TIFFClose(tif);
        return NULL;
    }

    info->bits_per_sample = bits_per_sample;
    info->samples_per_pixel = samples_per_pixel;
    info->extra_samples_count = extra_samples_count;

    TIFFClose(tif);
    return info;
}

