    uint8_t* buffer;
} MediaStream_t;

typedef struct MemoryAllocator {
    size_t poolSize;
    size_t allocatedSize;
    void* memoryPool;
} MemoryAllocator;

MemoryAllocator* createMemoryAllocator(size_t initialSize) {
    MemoryAllocator* allocator = (MemoryAllocator*)malloc(sizeof(MemoryAllocator));
    allocator->poolSize = initialSize;
    allocator->allocatedSize = 0;
    allocator->memoryPool = malloc(initialSize);
    return allocator;
}

void destroyMemoryAllocator(MemoryAllocator* allocator) {
    free(allocator->memoryPool);
    free(allocator);
}

void* allocateFromMemoryAllocator(MemoryAllocator* allocator, size_t size) {
    if (allocator->allocatedSize + size > allocator->poolSize) {
        // Resize the pool
        allocator->poolSize *= 2;
        allocator->memoryPool = realloc(allocator->memoryPool, allocator->poolSize);
    }
    void* ptr = ((uint8_t*)allocator->memoryPool) + allocator->allocatedSize;
    allocator->allocatedSize += size;
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* createUEContext(MemoryAllocator* allocator) {
    NFAPI_CRC_INDICATION_PDU_T* ueContext = (NFAPI_CRC_INDICATION_PDU_T*)allocateFromMemoryAllocator(allocator, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize fields with valid values
    return ueContext;
}

