    if (monitor->size >= monitor->capacity) {
        size_t new_capacity = monitor->capacity * GROWTH_FACTOR;
        monitor->stats = (DiskIOStats*)realloc(monitor->stats, new_capacity * sizeof(DiskIOStats));
        if (!monitor->stats) {
            pthread_mutex_unlock(&monitor->lock);
            return; // Handle memory allocation failure
        }
        monitor->capacity = new_capacity;
    }
