int myGraphCreate(MY_GRAPH_T** graph) {
    *graph = (MY_GRAPH_T*)malloc(sizeof(MY_GRAPH_T));
    if (*graph == NULL) {
        return -1; // Memory allocation failed
    }
    memset(*graph, 0, sizeof(MY_GRAPH_T));
    pthread_mutex_init(&((*graph)->mutex), NULL);
    return 0;
}

void myGraphDestroy(MY_GRAPH_T* graph) {
    for (int i = 0; i < graph->nodeCount; i++) {
        free(graph->nodes[i]);
    }
    for (int i = 0; i < graph->edgeCount; i++) {
        free(graph->edges[i]);
    }
    pthread_mutex_destroy(&graph->mutex);
    free(graph);
}

void myGraphAddNode(MY_GRAPH_T* graph, MY_GRAPH_NODE_T* node) {
    pthread_mutex_lock(&graph->mutex);
    if (graph->nodeCount < MAX_NODES) {
        graph->nodes[graph->nodeCount++] = node;
    } else {
        // Handle error: Maximum nodes reached
    }
    pthread_mutex_unlock(&graph->mutex);
}

void myGraphAddEdge(MY_GRAPH_T* graph, MY_EDGE_T* edge) {
    pthread_mutex_lock(&graph->mutex);
    if (graph->edgeCount < MAX_EDGES) {
        graph->edges[graph->edgeCount++] = edge;
    } else {
        // Handle error: Maximum edges reached
    }
    pthread_mutex_unlock(&graph->mutex);
}

