#define RESOURCE_MAGIC 0x12345678
#define STATE_MAGIC 0x87654321

typedef enum {
    ITEM_TYPE_INT,
    ITEM_TYPE_FLOAT,
    ITEM_TYPE_STRING
} ItemType;

typedef struct Item {
    ItemType type;
    size_t size;
    void* data;
} Item;

typedef struct ResourceBundle {
    int itemCount;
    Item** items;
} ResourceBundle;

typedef struct StateObject {
    // Define the state object structure based on your requirements
} StateObject;

int loadResourceBundle(const char* filename, ResourceBundle* bundle) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open resource bundle file");
        return -1;
    }

    uint32_t magic;
    if (fread(&magic, sizeof(magic), 1, file) != 1 || magic != RESOURCE_MAGIC) {
        fprintf(stderr, "Invalid resource bundle file format\n");
        fclose(file);
        return -2;
    }

    uint32_t version;
    if (fread(&version, sizeof(version), 1, file) != 1) {
        perror("Failed to read version from resource bundle file");
        fclose(file);
        return -3;
    }

    uint32_t itemCount;
    if (fread(&itemCount, sizeof(itemCount), 1, file) != 1) {
        perror("Failed to read item count from resource bundle file");
        fclose(file);
        return -4;
    }

    bundle->itemCount = itemCount;
    bundle->items = malloc(itemCount * sizeof(Item*));
    if (!bundle->items) {
        perror("Failed to allocate memory for items in resource bundle");
        fclose(file);
        return -5;
    }

    for (int i = 0; i < itemCount; i++) {
        Item item;
        if (fread(&item.type, sizeof(item.type), 1, file) != 1) {
            perror("Failed to read item type from resource bundle file");
            goto cleanup;
        }

        if (fread(&item.size, sizeof(item.size), 1, file) != 1) {
            perror("Failed to read item size from resource bundle file");
            goto cleanup;
        }

        item.data = malloc(item.size);
        if (!item.data) {
            perror("Failed to allocate memory for item data in resource bundle");
            goto cleanup;
        }

        if (fread(item.data, item.size, 1, file) != 1) {
            perror("Failed to read item data from resource bundle file");
            free(item.data);
            goto cleanup;
        }

        bundle->items[i] = malloc(sizeof(Item));
        if (!bundle->items[i]) {
            perror("Failed to allocate memory for item in resource bundle");
            free(item.data);
            goto cleanup;
        }
        memcpy(bundle->items[i], &item, sizeof(Item));
    }

    fclose(file);
    return 0;

cleanup:
    for (int i = 0; i < itemCount && bundle->items[i]; i++) {
        free(bundle->items[i]->data);
        free(bundle->items[i]);
    }
    free(bundle->items);
    fclose(file);
    return -6;
}

StateObject* loadStateObject(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open state object file");
        return NULL;
    }

    uint32_t magic;
    if (fread(&magic, sizeof(magic), 1, file) != 1 || magic != STATE_MAGIC) {
        fprintf(stderr, "Invalid state object file format\n");
        fclose(file);
        return NULL;
    }

    uint32_t version;
    if (fread(&version, sizeof(version), 1, file) != 1) {
        perror("Failed to read version from state object file");
        fclose(file);
        return NULL;
    }

    // Implement state object loading logic here
    // ...

    fclose(file);
    return NULL;
}

int main() {
    ResourceBundle bundle;
    if (loadResourceBundle("resource.bundle", &bundle) != 0) {
        fprintf(stderr, "Failed to load resource bundle\n");
        return EXIT_FAILURE;
    }

    StateObject* state = loadStateObject("state.object");
    if (!state) {
        fprintf(stderr, "Failed to load state object\n");
        return EXIT_FAILURE;
    }

    // Process the loaded resources here

    freeResourceBundle(&bundle);
    freeStateObject(state);

    return EXIT_SUCCESS;
}

void freeResourceBundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->itemCount && bundle->items[i]; i++) {
        free(bundle->items[i]->data);
        free(bundle->items[i]);
    }
    free(bundle->items);
    memset(bundle, 0, sizeof(ResourceBundle));
}

void freeStateObject(StateObject* state) {
    // Implement state object memory deallocation logic here
    // ...
}
