    int RNTI;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createLinkedList(int N) {
    if (N > 10000) {
        printf("Error: N cannot be greater than 10,000\n");
        return NULL;
    }

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            printf("Error: Memory allocation failed\n");
            return head;
        }

        newNode->RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        newNode->RNTI = rand() % 100 + 1;
        newNode->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0;

        if (!head) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    return head;
}

void freeLinkedList(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
}

void resetLinkedList(NFAPI_CRC_INDICATION_PDU_T **head) {
    if (*head) {
        freeLinkedList(*head);
        *head = NULL;
    }
}
