#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int data;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    pthread_mutex_t mutex;
} CRC_LIST_T;

CRC_LIST_T* create_crc_list() {
    CRC_LIST_T* list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) {
        return NULL;
    }
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_crc_list(CRC_LIST_T* list) {
    while (list->head) {
        NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_to_crc_list(CRC_LIST_T* list, int data) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Insertion successful
}

void traverse_crc_list(CRC_LIST_T* list, void (*callback)(int)) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
