#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/stat.h>
#include <openssl/md5.h>

#define BUFFER_SIZE 4096

void print_usage() {
    printf("Usage: program [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage       Display detailed usage information\n");
    printf("  -cs             Compress output lines using a simple algorithm\n");
    printf("  -o output_file  Redirect output to specified file\n");
    printf("  -l limit_lines  Limit the number of lines processed\n");
}

int process_file(const char *filename, int limit_lines) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) != 0) {
        perror("Error getting file size");
        fclose(file);
        return 1;
    }

    MD5_CTX md5_context;
    unsigned char hash[MD5_DIGEST_LENGTH];
    char buffer[BUFFER_SIZE];

    MD5_Init(&md5_context);

    size_t bytes_read = fread(buffer, 1, BUFFER_SIZE, file);
    while (bytes_read > 0) {
        MD5_Update(&md5_context, buffer, bytes_read);
        bytes_read = fread(buffer, 1, BUFFER_SIZE, file);
    }

    MD5_Final(hash, &md5_context);

    fclose(file);

    printf("MD5 hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    int limit_lines = -1;
    int compress_output = 0;
    const char *output_file = NULL;

    while ((opt = getopt(argc, argv, "cs:o:l:")) != -1) {
        switch (opt) {
            case 'c':
                compress_output = 1;
                break;
            case 's':
                output_file = optarg;
                break;
            case 'l':
                limit_lines = atoi(optarg);
                if (limit_lines <= 0) {
                    fprintf(stderr, "Invalid line limit\n");
                    return 1;
                }
                break;
            default:
                print_usage();
                return 1;
        }
    }

    if (optind != argc - 1) {
        print_usage();
        return 1;
    }

    const char *filename = argv[optind];
    if (!filename) {
        fprintf(stderr, "No input file provided\n");
        return 1;
    }

    int result = process_file(filename, limit_lines);
    if (result != 0) {
        fprintf(stderr, "Error processing file: %s\n", filename);
        return result;
    }

    return 0;
}
