    double error_rate;
    double latency;
    double packet_loss_percentage;
    double throughput;
} NicStats;

typedef struct {
    NicStats *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NicStatsArray;

void initialize_nic_stats(NicStatsArray *array, size_t initial_size) {
    array->capacity = initial_size;
    array->size = 0;
    array->data = (NicStats *)malloc(initial_size * sizeof(NicStats));
    pthread_mutex_init(&array->lock, NULL);
}

void resize_nic_stats_array(NicStatsArray *array) {
    NicStats *new_data = (NicStats *)realloc(array->data, array->capacity * 2 * sizeof(NicStats));
    if (new_data != NULL) {
        array->data = new_data;
        array->capacity *= 2;
    }
}

void add_nic_stats(NicStatsArray *array, NicStats nic_stats) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_nic_stats_array(array);
    }
    array->data[array->size++] = nic_stats;
    pthread_mutex_unlock(&array->lock);
}

void update_nic_stats(NicStatsArray *array, size_t index, NicStats new_stats) {
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        array->data[index] = new_stats;
    }
    pthread_mutex_unlock(&array->lock);
}

NicStats get_nic_stats(NicStatsArray *array, size_t index) {
    NicStats nic_stats = {0};
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        nic_stats = array->data[index];
    }
    pthread_mutex_unlock(&array->lock);
    return nic_stats;
}

void free_nic_stats_array(NicStatsArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
}
