#define MAX_CELL_ID 1000

typedef struct LTE_UERadioResourceConfigDedicated_t {
    int cell_id;
    int bwp;
    int *dl_bandwidth_part_list;
    int dl_bandwidth_part_count;
} LTE_UERadioResourceConfigDedicated_t;

typedef struct {
    LTE_UERadioResourceConfigDedicated_t **list;
    int count;
    pthread_mutex_t mutex;
} LTE_ResourceManager_t;

LTE_ResourceManager_t *create_resource_manager(int N) {
    LTE_ResourceManager_t *manager = malloc(sizeof(LTE_ResourceManager_t));
    manager->list = malloc(N * sizeof(LTE_UERadioResourceConfigDedicated_t *));
    for (int i = 0; i < N; i++) {
        manager->list[i] = malloc(sizeof(LTE_UERadioResourceConfigDedicated_t));
        memset(manager->list[i], 0, sizeof(LTE_UERadioResourceConfigDedicated_t));
    }
    manager->count = N;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void add_resource(LTE_ResourceManager_t *manager, int cell_id, int bwp, int *dl_bandwidth_part_list, int dl_bandwidth_part_count) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->list[i]->cell_id == 0) { // Assuming 0 is a default value for unused entries
            manager->list[i]->cell_id = cell_id;
            manager->list[i]->bwp = bwp;
            manager->list[i]->dl_bandwidth_part_list = malloc(dl_bandwidth_part_count * sizeof(int));
            memcpy(manager->list[i]->dl_bandwidth_part_list, dl_bandwidth_part_list, dl_bandwidth_part_count * sizeof(int));
            manager->list[i]->dl_bandwidth_part_count = dl_bandwidth_part_count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void delete_resource(LTE_ResourceManager_t *manager, int cell_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->list[i]->cell_id == cell_id) {
            free(manager->list[i]->dl_bandwidth_part_list);
            memset(manager->list[i], 0, sizeof(LTE_UERadioResourceConfigDedicated_t));
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

LTE_UERadioResourceConfigDedicated_t *get_resource(LTE_ResourceManager_t *manager, int cell_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        if (manager->list[i]->cell_id == cell_id) {
            LTE_UERadioResourceConfigDedicated_t *resource = malloc(sizeof(LTE_UERadioResourceConfigDedicated_t));
            memcpy(resource, manager->list[i], sizeof(LTE_UERadioResourceConfigDedicated_t));
            pthread_mutex_unlock(&manager->mutex);
            return resource;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void free_resource_manager(LTE_ResourceManager_t *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->list[i]->dl_bandwidth_part_list);
        free(manager->list[i]);
    }
    free(manager->list);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
