        this.executorService = Executors.newFixedThreadPool(CONNECTION_POOL_SIZE);
        this.operationQueue = new LinkedBlockingQueue<>();
        this.cache = Collections.synchronizedMap(new HashMap<>());
        this.logger = Logger.getLogger(FileSystemClient.class.getName());
    }

    public String manageFileSystemClient(Pokemon pokemon) throws IOException, InterruptedException {
        if (cache.containsKey(pokemon.getName())) {
            return cache.get(pokemon.getName()).toString();
        }

        int attempts = 0;
        while (attempts < RETRY_LIMIT) {
            try {
                String weaknesses = determineWeaknesses(pokemon);
                addToCache(pokemon.getName(), weaknesses, CACHE_EXPIRATION_MINUTES);
                logger.info("Operation successful: " + pokemon.getName() + ", Weaknesses: " + weaknesses);
                return weaknesses;
            } catch (Exception e) {
                attempts++;
                if (attempts == RETRY_LIMIT) {
                    logger.severe("Operation failed after " + RETRY_LIMIT + " attempts: " + pokemon.getName());
                    throw new IOException("Failed to determine Pokemon weaknesses after retries", e);
                }
                Thread.sleep((long) Math.pow(2, attempts) * 100); // Exponential backoff
            }
        }

        return null;
    }

    private String determineWeaknesses(Pokemon pokemon) {
        String type = getPokemonType(pokemon);
        switch (type) {
            case "Fire":
                return "Water, Ground";
            case "Water":
                return "Electric, Grass";
