            case "Electric":
                return "Ground";
            case "Ice":
                return "Fire, Rock, Steel, Fighting";
            case "Fighting":
                return "Flying, Psychology, Bug, Rock, Ghost";
            case "Poison":
                return "Psychology, Ground";
            case "Ground":
                return "Water, Ice, Grass, Electric, Fairy";
            case "Flying":
                return "Electric, Ice, Rock";
            case "Psychology":
                return "Bug, Dark";
            case "Bug":
                return "Fire, Flying, Psychology, Rock";
            case "Rock":
                return "Water, Fire, Grass, Fighting, Steel";
            case "Ghost":
                return "Dark, Bug";
            case "Dragon":
                return "Electric, Ice, Fairy";
            case "Steel":
                return "Psychology, Fire, Rock";
            case "Fairy":
                return "Poison, Steel";
            default:
                return "";
        }
    }

    private String getPokemonType(Pokemon pokemon) {
        // Simulate getting the Pokemon's type from a database or external API
        return "Fire"; // Example type
    }

    private void addToCache(String name, String weaknesses, int expirationMinutes) {
        cache.put(name, Arrays.asList(weaknesses.split(", ")));
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.schedule(() -> cache.remove(name), expirationMinutes, TimeUnit.MINUTES);
    }
}

