// Function to initialize the OpenSSL library and set up the encryption context
EVP_CIPHER_CTX *init_ctx(const char *mode, const char *key, const char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)key, (unsigned char *)iv)) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to encrypt or decrypt data
int process_data(EVP_CIPHER_CTX *ctx, const unsigned char *in, int in_len, unsigned char *out, int *out_len) {
    if (1 != EVP_EncryptUpdate(ctx, out, out_len, in, in_len)) {
        fprintf(stderr, "Failed to encrypt/decrypt data\n");
        return 0;
    }

    int final_len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, out + *out_len, &final_len)) {
        fprintf(stderr, "Failed to finalize encryption/decryption\n");
        return 0;
    }

    *out_len += final_len;
    return 1;
}

// Main function to handle command-line options and process data
int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <mode> <key> <iv>\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];
    const char *key = argv[2];
    const char *iv = argv[3];

    // Initialize OpenSSL
    if (!RAND_load_file("/dev/urandom", 1024)) {
        fprintf(stderr, "Failed to load random data\n");
        return 1;
    }

    // Process input string
    unsigned char plaintext[] = "This is a secret message";
    int in_len = strlen((char *)plaintext);
    unsigned char ciphertext[128];
    int out_len = 0;

    EVP_CIPHER_CTX *ctx = init_ctx(mode, key, iv);
    if (!ctx) {
        return 1;
    }

    if (!process_data(ctx, (unsigned char *)plaintext, in_len, ciphertext, &out_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Output the result
    printf("Ciphertext: ");
    for (int i = 0; i < out_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    return 0;
}
