typedef struct nfaapi_crc_indication_list {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

void nfaapi_init_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t initial_capacity) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        // Handle allocation failure
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void nfaapi_free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

int nfaapi_insert_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            // Handle allocation failure
            return -1;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count++] = *new_entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

bool nfaapi_delete_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti == rnti) {
            for (size_t j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

