#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILES 50

typedef struct {
    char *filename;
    FILE *file;
    int line_count;
    double total_length;
} FileData;

void* process_file(void* arg) {
    FileData *data = (FileData*)arg;
    char buffer[1024];
    int length = 0;

    while (fgets(buffer, sizeof(buffer), data->file)) {
        data->line_count++;
        length += strlen(buffer);
    }

    data->total_length = (double)length / data->line_count;
    fclose(data->file);

    return NULL;
}

void display_usage() {
    printf("Usage: program [-c] [-s] [-o output_file] [--manpage]\n");
    printf("Options:\n");
    printf("  -c              Count the total number of lines across all input files\n");
    printf("  -s              Calculate the average line length for each input file\n");
    printf("  -o output_file  Specify an output file for saving the results\n");
    printf("  --manpage       Display detailed usage information\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        display_usage();
        return 1;
    }

    int count_lines = 0, calc_average_length = 0;
    FILE *output_file = NULL;
    pthread_t threads[MAX_FILES];
    FileData file_data[MAX_FILES];

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0) {
            count_lines = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            calc_average_length = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                fprintf(stderr, "Error opening output file: %s\n", argv[i]);
                return 1;
            }
        } else if (strcmp(argv[i], "--manpage") == 0) {
            display_usage();
            return 0;
        } else if (i + 1 < argc) {
            file_data[argc - i - 2].filename = argv[i];
            file_data[argc - i - 2].file = fopen(argv[i], "r");
            if (!file_data[argc - i - 2].file) {
                fprintf(stderr, "Error opening file: %s\n", argv[i]);
                return 1;
            }
        } else {
            display_usage();
            return 1;
        }
    }

    int num_files = argc - 2;

    if (num_files > MAX_FILES) {
        fprintf(stderr, "Too many input files. Maximum allowed is %d.\n", MAX_FILES);
        return 1;
    }

    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, &file_data[i]);
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    if (count_lines) {
        for (int i = 0; i < num_files; i++) {
            printf("File %s has %d lines.\n", file_data[i].filename, file_data[i].line_count);
        }
    }

    if (calc_average_length) {
        for (int i = 0; i < num_files; i++) {
            printf("File %s average line length: %.2f\n", file_data[i].filename, file_data[i].total_length);
        }
    }

    if (output_file) {
        fclose(output_file);
    }

    return 0;
}
