        return NULL;
    }
    if (pthread_mutex_init(&cache->lock, NULL) != 0) {
        free(cache);
        perror("Failed to initialize mutex");
        return NULL;
    }
    cache->count = 0;
    return cache;
}

int cache_add(CACHE_T *cache, char *key, void *value) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count >= MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&cache->lock);
        fprintf(stderr, "Cache is full\n");
        return -1;
    }
    cache->items[cache->count].key = strdup(key);
    cache->items[cache->count].value = value;
    cache->items[cache->count].timestamp = time(NULL);
    cache->count++;
    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void *cache_get(CACHE_T *cache, char *key) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; i++) {
        if (strcmp(cache->items[i].key, key) == 0) {
            pthread_mutex_unlock(&cache->lock);
            return cache->items[i].value;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    fprintf(stderr, "Key not found in cache\n");
    return NULL;
}

void cache_free(CACHE_T *cache) {
    for (size_t i = 0; i < cache->count; i++) {
        free(cache->items[i].key);
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}
