#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the user-defined data structure
typedef struct {
    int ID;
    time_t TIMESTAMP;
} MY_CUSTOM_DATA_T;

// Define the hash table entry structure
typedef struct HashTableEntry {
    MY_CUSTOM_DATA_T *data;
    struct HashTableEntry *next;
} HashTableEntry;

// Define the hash table structure
typedef struct {
    HashTableEntry **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} HashTable;

// Function to create a new hash table
HashTable* createHashTable(size_t initialSize) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for the hash table");
        return NULL;
    }
    table->size = initialSize;
    table->count = 0;
    table->buckets = (HashTableEntry**)calloc(initialSize, sizeof(HashTableEntry*));
    if (!table->buckets) {
        perror("Failed to allocate memory for the buckets");
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to insert data into the hash table
int insertData(HashTable *table, int ID, time_t TIMESTAMP) {
    pthread_mutex_lock(&table->mutex);
    size_t index = (size_t)ID % table->size;
    HashTableEntry *entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!entry) {
        perror("Failed to allocate memory for the hash table entry");
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    entry->data = (MY_CUSTOM_DATA_T*)malloc(sizeof(MY_CUSTOM_DATA_T));
    if (!entry->data) {
        perror("Failed to allocate memory for the user-defined data structure");
        free(entry);
        pthread_mutex_unlock(&table->mutex);
        return -1;
    }
    entry->data->ID = ID;
    entry->data->TIMESTAMP = TIMESTAMP;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    table->count++;
    pthread_mutex_unlock(&table->mutex);
    return 0;
}

// Function to retrieve data from the hash table
MY_CUSTOM_DATA_T* getData(HashTable *table, int ID) {
    pthread_mutex_lock(&table->mutex);
    size_t index = (size_t)ID % table->size;
    HashTableEntry *entry = table->buckets[index];
    while (entry) {
        if (entry->data->ID == ID) {
            pthread_mutex_unlock(&table->mutex);
            return entry->data;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

// Function to delete data from the hash table
int deleteData(HashTable *table, int ID) {
    pthread_mutex_lock(&table->mutex);
    size_t index = (size_t)ID % table->size;
    HashTableEntry *entry = table->buckets[index];
    HashTableEntry *prev = NULL;
    while (entry) {
        if (entry->data->ID == ID) {
            if (prev) {
                prev->next = entry->next;
            } else {
                table->buckets[index] = entry->next;
            }
            free(entry->data);
            free(entry);
            table->count--;
            pthread_mutex_unlock(&table->mutex);
            return 0;
        }
        prev = entry;
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return -1;
}

// Function to clear and free all allocated resources
void clearHashTable(HashTable *table) {
    for (size_t i = 0; i < table->size; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *next = entry->next;
            free(entry->data);
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&table->mutex);
    free(table->buckets);
    free(table);
}
```

This code snippet provides a basic implementation of a thread-safe dynamic hash table for storing user-defined data structures (`MY_CUSTOM_DATA_T`). The `createHashTable` function initializes the hash table, `insertData`, `getData`, and `deleteData` functions manage the insertion, retrieval, and deletion of data, respectively. The `clearHashTable` function is used to free all allocated resources when no longer needed.

This implementation uses a mutex for thread synchronization, ensuring that only one thread can access or modify the hash table at a time. This approach guarantees correctness but may lead to performance degradation under high load due to contention.

To optimize performance in a highly concurrent environment, alternative approaches such as lock-free data structures could be considered. However, implementing lock-free algorithms is more complex and requires careful consideration of race conditions and memory consistency issues.

This code does not include features for dynamic resizing, monitoring memory usage, serialization/deserialization, or automatically adjusting the initial capacity based on historical data load patterns. These additional features would require significant enhancements to the implementation and are beyond the scope of this basic example.']

