} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_List;

CRC_Indication_List* create_crc_indication_list(size_t initial_capacity) {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_indication_list(CRC_Indication_List* list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_indication(CRC_Indication_List* list, int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count].ue_info.RX_UE_INFORMATION_TAG = rx_ue_tag;
    list->entries[list->count].ue_info.RNTI = rnti;
    list->entries[list->count].crc_flag = (CRC_FLAG)(rand() % 2);
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to handle CRC indications
void process_crc_indications(CRC_Indication_List* list) {
    for (size_t i = 0; i < list->count; i++) {
        // Simulate processing
        if (list->entries[i].crc_flag == CRCFLAG_VALID) {
            printf("CRC Indication %zu: Valid\n", i);
        } else {
            printf("CRC Indication %zu: Invalid\n", i);
        }
    }
}

// Example usage
int main() {
    CRC_Indication_List* crc_list = create_crc_indication_list(10);
    for (int i = 0; i < 20; i++) {
        add_crc_indication(crc_list, i, i * 10);
    }
    process_crc_indications(crc_list);
    destroy_crc_indication_list(crc_list);
    return 0;
}
```

