void initialize_nic_stats(int count) {
    pthread_mutex_init(&nic_mutex, NULL);
    nic_count = count;
    nic_stats = (NIC_Statistics *)malloc(nic_count * sizeof(NIC_Statistics));
    if (!nic_stats) {
        fprintf(stderr, "Failed to allocate memory for NIC statistics\n");
        exit(1);
    }
}

void populate_nic_stats() {
    pthread_mutex_lock(&nic_mutex);
    // Populate NIC stats with random values
    for (int i = 0; i < nic_count; i++) {
        sprintf(nic_stats[i].interface_name, "eth%d", i % 5); // Simplified interface naming
        nic_stats[i].packet_count = rand() % 100000;
        nic_stats[i].error_rate = (double)(rand() % 100) / 100.0;
        nic_stats[i].latency = (double)(rand() % 1000) / 1000.0;
        nic_stats[i].packet_loss_percentage = nic_stats[i].error_rate * 100;
        nic_stats[i].throughput = nic_stats[i].packet_count / nic_stats[i].latency;
    }
    pthread_mutex_unlock(&nic_mutex);
}

