NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(int N) {
    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize random seed for generating random numbers
    srand(time(NULL));

    // Populate the array
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example range
        array[i].RNTI = rand() % 500 + 1; // Example range
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
    }

    return array;
}

// Function to check the integrity of the array
void check_integrity(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    for (int i = 0; i < N - 1; i++) {
        if (array[i].RNTI == array[i + 1].RNTI) {
            fprintf(stderr, "Duplicate RNTI found\n");
            // Handle duplicate RNTI
        }

        if (array[i].RX_UE_INFORMATION_TAG != array[i].CRC_INDICATION_REL8_TAG) {
            fprintf(stderr, "Invalid link between RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG\n");
            // Handle invalid link
        }
    }
}

int main() {
