#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DEVICES 1000
#define RETRY_DELAY 500 // milliseconds

typedef struct {
    int device_id;
    int health_status_code;
    double last_temperature;
    double battery_level;
    time_t last_connection_time;
} DHMRecord;

typedef struct {
    DHMRecord records[MAX_DEVICES];
    int count;
} DeviceList;

void initialize_device_list(DeviceList *list) {
    list->count = 0;
}

int add_device(DeviceList *list, int device_id, int health_status_code, double last_temperature, double battery_level, time_t last_connection_time) {
    if (list->count >= MAX_DEVICES) {
        return -1; // List is full
    }
    list->records[list->count].device_id = device_id;
    list->records[list->count].health_status_code = health_status_code;
    list->records[list->count].last_temperature = last_temperature;
    list->records[list->count].battery_level = battery_level;
    list->records[list->count].last_connection_time = last_connection_time;
    list->count++;
    return 0;
}

int update_device(DeviceList *list, int device_id, int health_status_code, double last_temperature, double battery_level, time_t last_connection_time) {
    for (int i = 0; i < list->count; i++) {
        if (list->records[i].device_id == device_id) {
            list->records[i].health_status_code = health_status_code;
            list->records[i].last_temperature = last_temperature;
            list->records[i].battery_level = battery_level;
            list->records[i].last_connection_time = last_connection_time;
            return 0;
        }
    }
    return -1; // Device not found
}

void print_device_list(DeviceList *list) {
    for (int i = 0; i < list->count; i++) {
        printf("Device ID: %d, Health Status Code: %d, Last Temperature: %.2f, Battery Level: %.2f, Last Connection Time: %s\n",
               list->records[i].device_id,
               list->records[i].health_status_code,
               list->records[i].last_temperature,
               list->records[i].battery_level,
               ctime(&list->records[i].last_connection_time));
    }
}

int main() {
    DeviceList dhm_list;
    initialize_device_list(&dhm_list);

    // Example usage
    add_device(&dhm_list, 101, 200, 37.5, 85.0, time(NULL));
    update_device(&dhm_list, 101, 201, 38.0, 84.5, time(NULL));

    print_device_list(&dhm_list);

    return 0;
}
