    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file_path> <options>\n", argv[0]);
        return 1;
    }

    const char* file_path = argv[1];
    const char* options = argv[2];
    Config config = { .log_level = 1 };
    Metrics metrics;

    Result* result = process_file_with_options(file_path, options, 0, config, &metrics);
    if (!result) {
        fprintf(stderr, "Failed to process file\n");
        return 1;
    }

    // Process the result
    // ...

    free(result);

    // Create and start background thread for monitoring file permissions
    pthread_t perm_thread;
    if (pthread_create(&perm_thread, NULL, background_thread_func, &config) != 0) {
        fprintf(stderr, "Failed to create permission monitor thread\n");
        return 1;
    }

    pthread_join(perm_thread, NULL);

    return 0;
}
