    RX_UE_INFORMATION_TAG *rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** create_and_populate_cnfapi_pdu_list(uint32_t n, uint32_t max_n) {
    if (n > max_n || n == 0) {
        return NULL; // Handle invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T **pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!pdu_list) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (uint32_t i = 0; i < n; ++i) {
        pdu_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list[i]) {
            // Clean up previously allocated memory
            for (uint32_t j = 0; j < i; ++j) {
                free(pdu_list[j]);
            }
            free(pdu_list);
            return NULL; // Memory allocation failed
        }

        pthread_mutex_init(&pdu_list[i]->mutex, NULL);

        pdu_list[i]->rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!pdu_list[i]->rx_ue_info) {
            // Clean up previously allocated memory
            for (uint32_t j = 0; j <= i; ++j) {
                pthread_mutex_destroy(&pdu_list[j]->mutex);
                free(pdu_list[j]->rx_ue_info);
                free(pdu_list[j]);
            }
            free(pdu_list);
            return NULL; // Memory allocation failed
        }

        pdu_list[i]->rx_ue_info->RNTI = rand() % MAX_UE_INFO;

        pdu_list[i]->crc_indication_rel8.CRCFLAG = (rand() % 2 == 0);

        // Log creation event
        printf("Created NFAPI_CRC_INDICATION_PDU_T with RNTI: %u, CRCFLAG: %d\n", pdu_list[i]->rx_ue_info->RNTI, pdu_list[i]->crc_indication_rel8.CRCFLAG);
    }

    return pdu_list;
}
