    size_t count;
    pthread_mutex_t mutex;
    sem_t available_space;
} DHMArray;

void initializeDHMArray(DHMArray *array, size_t initial_capacity) {
    array->records = (DeviceHealthRecord *)malloc(initial_capacity * sizeof(DeviceHealthRecord));
    if (array->records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    sem_init(&array->available_space, 0, initial_capacity);
}

void addRecord(DHMArray *array, DeviceHealthRecord record) {
    pthread_mutex_lock(&array->mutex);
    sem_wait(&array->available_space);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DeviceHealthRecord *new_records = realloc(array->records, new_capacity * sizeof(DeviceHealthRecord));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(1);
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->records[array->count] = record;
    array->count++;
    pthread_mutex_unlock(&array->mutex);
}

void updateRecord(DHMArray *array, size_t index, DeviceHealthRecord new_record) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->count) {
        array->records[index] = new_record;
        sem_post(&array->available_space);
    }
    pthread_mutex_unlock(&array->mutex);
}

