#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_DEVICES 1000
#define THRESHOLD 500

typedef struct {
    int id;
    float sensor_data;
    int operational_metrics;
    char maintenance_logs[256];
} DeviceHealthMonitor;

typedef struct {
    DeviceHealthMonitor *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DHMArray;

void dhm_array_init(DHMArray *array) {
    array->records = (DeviceHealthMonitor *)malloc(MAX_DEVICES * sizeof(DeviceHealthMonitor));
    if (!array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = MAX_DEVICES;
    pthread_mutex_init(&array->lock, NULL);
}

void dhm_array_add(DHMArray *array, DeviceHealthMonitor record) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DeviceHealthMonitor *new_records = realloc(array->records, new_capacity * sizeof(DeviceHealthMonitor));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }
    array->records[array->count++] = record;
    pthread_mutex_unlock(&array->lock);
}

void dhm_array_update(DHMArray *array, int id, DeviceHealthMonitor new_record) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i].id == id) {
            array->records[i] = new_record;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void dhm_array_delete(DHMArray *array, int id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i].id == id) {
            memmove(&array->records[i], &array->records[i + 1], (array->count - i - 1) * sizeof(DeviceHealthMonitor));
            --array->count;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void dhm_array_serialize(DHMArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(array->records, sizeof(DeviceHealthMonitor), array->count, file);
    fclose(file);
}

void dhm_array_deserialize(DHMArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    size_t count = fread(array->records, sizeof(DeviceHealthMonitor), array->capacity, file);
    array->count = count > array->capacity ? array->capacity : count;
    fclose(file);
}

