#define TABLE_SIZE 1000000
MY_CUSTOM_DATA_T *hash_table[TABLE_SIZE];
pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;

int hash_function(int id) {
    return id % TABLE_SIZE;
}

void insert_data(int id, time_t timestamp) {
    pthread_mutex_lock(&table_lock);
    int index = hash_function(id);
    while (hash_table[index] != NULL && hash_table[index]->ID != -1) {
        index = (index + 1) % TABLE_SIZE;
    }
    if (hash_table[index] == NULL) {
        hash_table[index] = (MY_CUSTOM_DATA_T *)malloc(sizeof(MY_CUSTOM_DATA_T));
        if (hash_table[index] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    }
    hash_table[index]->ID = id;
    hash_table[index]->TIMESTAMP = timestamp;
    pthread_mutex_unlock(&table_lock);
}

MY_CUSTOM_DATA_T *retrieve_data(int id) {
    pthread_mutex_lock(&table_lock);
    int index = hash_function(id);
    while (hash_table[index] != NULL) {
        if (hash_table[index]->ID == id) {
            MY_CUSTOM_DATA_T *data = (MY_CUSTOM_DATA_T *)malloc(sizeof(MY_CUSTOM_DATA_T));
            if (data == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&table_lock);
                return NULL;
            }
            data->ID = hash_table[index]->ID;
            data->TIMESTAMP = hash_table[index]->TIMESTAMP;
            pthread_mutex_unlock(&table_lock);
            return data;
        } else if (hash_table[index]->ID == -1) {
            break;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    pthread_mutex_unlock(&table_lock);
    return NULL;
}

void clear_and_free() {
    pthread_mutex_lock(&table_lock);
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (hash_table[i] != NULL && hash_table[i]->ID != -1) {
            free(hash_table[i]);
        }
    }
    pthread_mutex_unlock(&table_lock);
}

