    S1AP_MSG_TYPE_1,
    S1AP_MSG_TYPE_2
} S1AP_MESSAGE_TYPE_E;

typedef struct s1ap_message_t {
    S1AP_MESSAGE_TYPE_E type;
    // Define message fields based on type
} S1AP_MESSAGE_T;

typedef struct ue_context_s {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    MME_IP_ADDRESS mme_ip_address;
    S1AP_MESSAGE_T* s1ap_message;
    int qos_priority;
    pthread_mutex_t lock;
} UE_CONTEXT_S;

typedef struct nic_statistics_s {
    char interface_name[64];
    uint64_t packet_counters;
    double error_rates;
    uint64_t byte_counts;
    double latency;
} NIC_STATISTICS_S;

UE_CONTEXT_S** generate_ue_contexts(int num_entries, int s1ap_version) {
    UE_CONTEXT_S** ue_contexts = malloc(num_entries * sizeof(UE_CONTEXT_S*));
    if (!ue_contexts) return NULL;

    for (int i = 0; i < num_entries; ++i) {
        ue_contexts[i] = malloc(sizeof(UE_CONTEXT_S));
        if (!ue_contexts[i]) {
            for (int j = 0; j < i; ++j) free(ue_contexts[j]);
            free(ue_contexts);
            return NULL;
        }

        // Initialize UE context fields
        ue_contexts[i]->rrc_state = RRC_IDLE;
        // Initialize PDP_CONTEXT and MME_IP_ADDRESS
        memset(&ue_contexts[i]->pdp_context, 0, sizeof(PDP_CONTEXT));
        memset(&ue_contexts[i]->mme_ip_address, 0, sizeof(MME_IP_ADDRESS));
        ue_contexts[i]->s1ap_message = malloc(sizeof(S1AP_MESSAGE_T));
        if (!ue_contexts[i]->s1ap_message) {
            free(ue_contexts[i]);
            for (int j = 0; j < i; ++j) free(ue_contexts[j]);
            free(ue_contexts);
            return NULL;
        }
        ue_contexts[i]->s1ap_message->type = s1ap_version == 1 ? S1AP_MSG_TYPE_1 : S1AP_MSG_TYPE_2;
        // Initialize QoS priority
        ue_contexts[i]->qos_priority = rand() % 100;

        pthread_mutex_init(&ue_contexts[i]->lock, NULL);
    }

    return ue_contexts;
}

void free_ue_contexts(UE_CONTEXT_S** ue_contexts, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(ue_contexts[i]->s1ap_message);
        pthread_mutex_destroy(&ue_contexts[i]->lock);
        free(ue_contexts[i]);
    }
    free(ue_contexts);
}

NIC_STATISTICS_S** generate_nic_statistics(int num_interfaces, char* interface_names[], int max_packet_counters, double error_rates_range, uint64_t max_byte_counts, double latency_range) {
    NIC_STATISTICS_S** nic_stats = malloc(num_interfaces * sizeof(NIC_STATISTICS_S*));
    if (!nic_stats) return NULL;

    for (int i = 0; i < num_interfaces; ++i) {
        nic_stats[i] = malloc(sizeof(NIC_STATISTICS_S));
        if (!nic_stats[i]) {
            for (int j = 0; j < i; ++j) free(nic_stats[j]);
            free(nic_stats);
            return NULL;
        }

        // Validate and set interface name
        strncpy(nic_stats[i]->interface_name, interface_names[i], sizeof(nic_stats[i]->interface_name) - 1);
        nic_stats[i]->interface_name[sizeof(nic_stats[i]->interface_name) - 1] = '\0';

        // Initialize packet counters, error rates, byte counts, and latency
        nic_stats[i]->packet_counters = rand() % max_packet_counters;
        nic_stats[i]->error_rates = ((double)rand() / RAND_MAX) * error_rates_range;
        nic_stats[i]->byte_counts = (uint64_t)((double)rand() / RAND_MAX) * max_byte_counts;
        nic_stats[i]->latency = ((double)rand() / RAND_MAX) * latency_range;
    }

    return nic_stats;
}

void free_nic_statistics(NIC_STATISTICS_S** nic_stats, int num_interfaces) {
    for (int i = 0; i < num_interfaces; ++i) {
        free(nic_stats[i]);
    }
    free(nic_stats);
}
