    if (strcmp(mode, "ECB") == 0) cipher = EVP_des_ecb();
    else if (strcmp(mode, "EDE") == 0) cipher = EVP_des_ede();
    else if (strcmp(mode, "EDE3") == 0) cipher = EVP_des_ede3();
    else if (strcmp(mode, "CFB") == 0) cipher = EVP_des_cfb8();
    else return -1; // Invalid cipher mode

    if ((key_len < 56 || key_len > 112) && strcmp(mode, "NULL") != 0) return -2; // Unsupported key length

    cipher_ctx = EVP_CIPHER_CTX_new();
    if (cipher_ctx == NULL) return -3;

    int padding = 1;
    int iv_len = EVP_CIPHER_iv_length(cipher);
    unsigned char *iv = malloc(iv_len);
    if (!RAND_bytes(iv, iv_len)) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free(iv);
        return -4;
    }

    if (strcmp(mode, "NULL") != 0) {
        int init_result = EVP_EncryptInit_ex(cipher_ctx, cipher, NULL, key, iv);
        if (!init_result) {
            EVP_CIPHER_CTX_free(cipher_ctx);
            free(iv);
            return -5;
        }
    } else {
        EVP_CIPHER_CTX_set_key_length(cipher_ctx, 0); // Null encryption
        EVP_CIPHER_CTX_set_padding(cipher_ctx, padding);
    }

    free(iv);
    return 0;
}

int encrypt(unsigned char *data, size_t data_len) {
    int len, ciphertext_len;
    if (!EVP_EncryptUpdate(cipher_ctx, NULL, &len, data, data_len)) return -1;
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(cipher_ctx, data + len, &len)) return -2;
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt(unsigned char *data, size_t data_len) {
    int len, plaintext_len;
    if (!EVP_DecryptUpdate(cipher_ctx, NULL, &len, data, data_len)) return -1;
    plaintext_len = len;

    if (!EVP_DecryptFinal_ex(cipher_ctx, data + len, &len)) return -2;
    plaintext_len += len;

    return plaintext_len;
}

int verify_integrity(unsigned char *data, size_t data_len, unsigned char *checksum) {
    unsigned char calculated_checksum[SHA_DIGEST_LENGTH];
    SHA1(data, data_len, calculated_checksum);
    return memcmp(calculated_checksum, checksum, sizeof(calculated_checksum)) == 0 ? 1 : 0;
}

void cleanup() {
    if (cipher_ctx != NULL) EVP_CIPHER_CTX_free(cipher_ctx);
}
