} CipherState;

EVP_CIPHER_CTX* get_cipher_context(int cipher_mode, int key_size) {
    switch (cipher_mode) {
        case 0: // ECB
            return EVP_CIPHER_CTX_new();
        case 1: // EDE
            return EVP_CIPHER_CTX_new();
        case 2: // EDE3
            return EVP_CIPHER_CTX_new();
        case 3: // CFB
            return EVP_CIPHER_CTX_new();
        default:
            fprintf(stderr, "Unsupported cipher mode\n");
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
    }
}

void initialize_cipher_state(CipherState *state, int cipher_mode, const unsigned char *key, int key_size) {
    state->ctx = get_cipher_context(cipher_mode, key_size);
    memcpy(state->key, key, key_size);
    if (cipher_mode == 3) { // CFB
        memcpy(state->iv, key + key_size, sizeof(state->iv));
    }
}

void generate_secure_key(unsigned char *key, int key_size) {
    if (!RAND_bytes(key, key_size)) {
        fprintf(stderr, "Failed to generate secure random key\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
}

int encrypt_data(const CipherState *state, unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = state->ctx;
    if (EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, state->key, NULL) != 1) {
        fprintf(stderr, "Failed to initialize encryption\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        fprintf(stderr, "Encryption failed\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    int ciphertext_len = len;
    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        fprintf(stderr, "Failed to finalize encryption\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    ciphertext_len += len;
    return ciphertext_len;
}

int decrypt_data(const CipherState *state, unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = state->ctx;
    if (EVP_DecryptInit_ex(ctx, EVP_des_ecb(), NULL, state->key, NULL) != 1) {
        fprintf(stderr, "Failed to initialize decryption\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    int len;
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        fprintf(stderr, "Decryption failed\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    int plaintext_len = len;
    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
        fprintf(stderr, "Failed to finalize decryption\n");
        ERR_print_errors_fp(stderr);
        return -1;
    }
    plaintext_len += len;
    return plaintext_len;
}

void free_cipher_state(CipherState *state) {
    EVP_CIPHER_CTX_free(state->ctx);
}
