#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB,
    NULL_ENCRYPTION
} CipherMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    CipherMode mode;
    unsigned char key[16];
    unsigned char iv[8];
    pthread_mutex_t mutex;
} CryptoContext;

CryptoContext* create_cipher_context(CipherMode mode, const unsigned char *key, int key_len) {
    CryptoContext *ctx = malloc(sizeof(CryptoContext));
    if (!ctx) return NULL;

    memset(ctx, 0, sizeof(CryptoContext));
    ctx->mode = mode;
    pthread_mutex_init(&ctx->mutex, NULL);

    if (key_len > 16) {
        memcpy(ctx->key, key, 16);
    } else {
        memcpy(ctx->key, key, key_len);
        // Pad key with zeros
        memset(ctx->key + key_len, 0, 16 - key_len);
    }

    switch (mode) {
        case ECB:
            ctx->ctx = EVP_CIPHER_CTX_new();
            if (!ctx->ctx || !EVP_EncryptInit_ex(ctx->ctx, EVP_des_ede3_ecb(), NULL, ctx->key, NULL)) {
                free(ctx);
                return NULL;
            }
            break;
        case EDE:
            // Implement EDE initialization
            break;
        case EDE3:
            // Implement EDE3 initialization
            break;
        case CFB:
            memcpy(ctx->iv, key + 16, 8); // Use part of the key for IV
            ctx->ctx = EVP_CIPHER_CTX_new();
            if (!ctx->ctx || !EVP_EncryptInit_ex(ctx->ctx, EVP_des_cfb64(), NULL, ctx->key, ctx->iv)) {
                free(ctx);
                return NULL;
            }
            break;
        case NULL_ENCRYPTION:
            ctx->ctx = NULL; // Null encryption context
            break;
        default:
            free(ctx);
            return NULL;
    }

    return ctx;
}

void destroy_cipher_context(CryptoContext *ctx) {
    if (ctx->ctx) EVP_CIPHER_CTX_free(ctx->ctx);
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx);
}

int encrypt_data(CryptoContext *ctx, const unsigned char *in, int in_len, unsigned char *out, int out_len) {
    pthread_mutex_lock(&ctx->mutex);
    int len;
    int ciphertext_len = 0;
    switch (ctx->mode) {
        case ECB:
            if (!EVP_EncryptUpdate(ctx->ctx, out, &len, in, in_len)) {
                pthread_mutex_unlock(&ctx->mutex);
                return -1;
            }
            ciphertext_len += len;
            break;
        case EDE:
            // Implement EDE encryption
            break;
        case EDE3:
            // Implement EDE3 encryption
            break;
        case CFB:
            if (!EVP_EncryptUpdate(ctx->ctx, out, &len, in, in_len)) {
                pthread_mutex_unlock(&ctx->mutex);
                return -1;
            }
            ciphertext_len += len;
            break;
        case NULL_ENCRYPTION:
            memcpy(out, in, in_len);
            ciphertext_len = in_len;
            break;
        default:
            pthread_mutex_unlock(&ctx->mutex);
            return -1;
    }
    if (!EVP_EncryptFinal_ex(ctx->ctx, out + len, &len)) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    ciphertext_len += len;
    pthread_mutex_unlock(&ctx->mutex);
    return ciphertext_len;
}

int decrypt_data(CryptoContext *ctx, const unsigned char *in, int in_len, unsigned char *out, int out_len) {
    // Implement decryption using the same logic as encryption
    return encrypt_data(ctx, in, in_len, out, out_len);
}
