                    unsigned char *ciphertext, unsigned char *key, unsigned char *iv) {
    if (EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Encryption initialization failed\n");
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        fprintf(stderr, "Encryption update failed\n");
        return -1;
    }
    ciphertext += len;

    int ciphertext_len;
    if (EVP_EncryptFinal_ex(ctx, ciphertext, &ciphertext_len) != 1) {
        fprintf(stderr, "Encryption finalization failed\n");
        return -1;
    }

