        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_name, "DES-EDE") == 0) {
        cipher = EVP_des_ede_cbc();
    } else if (strcmp(cipher_name, "DES-EDE3") == 0) {
        cipher = EVP_des_ede3_cbc();
    } else if (strcmp(cipher_name, "DES-CFB") == 0) {
        cipher = EVP_des_cfb8();
    }

    if (cipher && key_length != EVP_CIPHER_key_length(cipher)) {
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    if (block_size != EVP_CIPHER_block_size(cipher)) {
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    return cipher;
}

void encrypt_decrypt(EVP_CIPHER* cipher, const unsigned char* key, int key_length,
                     const unsigned char* iv, int iv_length,
                     const unsigned char* in_data, size_t in_len,
                     unsigned char** out_data, size_t* out_len,
                     int mode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle allocation failure
        return;
    }

    if (EVP_Init_ex(ctx, cipher, NULL, key, iv) != 1 ||
        EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, mode) != 1) {
        // Handle initialization failure
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *out_len = (in_len + EVP_CIPHER_block_size(cipher)) / EVP_CIPHER_block_size(cipher) * EVP_CIPHER_block_size(cipher);
    *out_data = malloc(*out_len);
    if (!*out_data) {
        // Handle allocation failure
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int len;
    if (EVP_CipherUpdate(ctx, *out_data, &len, in_data, in_len) != 1 ||
        EVP_CipherFinal_ex(ctx, (*out_data) + len, &len) != 1) {
        // Handle encryption/decryption failure
        free(*out_data);
        *out_data = NULL;
    }

    *out_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

