typedef struct {
    DES_cblock key;
    int mode;
    int blockSize;
} CryptoContext;

CryptoContext* createCryptoContext(const char* keyHex, int mode, int blockSize) {
    CryptoContext* ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    if (!ctx) return NULL;

    if (strlen(keyHex) != 2 * DES_KEY_LENGTH) {
        free(ctx);
        return NULL;
    }

    for (int i = 0; i < DES_KEY_LENGTH; i++) {
        sscanf(&keyHex[i*2], "%2hhx", &ctx->key[i]);
    }

    ctx->mode = mode;
    ctx->blockSize = blockSize;

    return ctx;
}

void freeCryptoContext(CryptoContext* ctx) {
    free(ctx);
}

int encryptData(const CryptoContext* ctx, const unsigned char* input, int length, unsigned char* output) {
    DES_key_schedule keysched[3];
    switch (ctx->mode) {
        case ECB:
            DES_set_odd_parity(&ctx->key);
            DES_set_key_unchecked(&ctx->key, &keysched[0]);
            for (int i = 0; i < length / ctx->blockSize; i++) {
                DES_ecb_encrypt(&input[i*ctx->blockSize], &output[i*ctx->blockSize], &keysched[0], DES_ENCRYPT);
            }
            break;
        // Add other modes here
        default:
            return -1;
    }
    return 0;
}

int decryptData(const CryptoContext* ctx, const unsigned char* input, int length, unsigned char* output) {
    DES_key_schedule keysched[3];
    switch (ctx->mode) {
        case ECB:
            DES_set_odd_parity(&ctx->key);
            DES_set_key_unchecked(&ctx->key, &keysched[0]);
            for (int i = 0; i < length / ctx->blockSize; i++) {
                DES_ecb_encrypt(&input[i*ctx->blockSize], &output[i*ctx->blockSize], &keysched[0], DES_DECRYPT);
            }
            break;
        // Add other modes here
        default:
            return -1;
    }
    return 0;
}

int main() {
    const char* keyHex = "0123456789abcdef";
    int mode = ECB;
    int blockSize = DES_BLOCK_SIZE;

    CryptoContext* ctx = createCryptoContext(keyHex, mode, blockSize);
    if (!ctx) return 1;

    unsigned char plaintext[16] = "Hello, World!";
    unsigned char ciphertext[16];
    unsigned char decryptedtext[16];

    encryptData(ctx, plaintext, sizeof(plaintext), ciphertext);
    decryptData(ctx, ciphertext, sizeof(ciphertext), decryptedtext);

    printf("Decrypted: %s\n", decryptedtext);

    freeCryptoContext(ctx);

    return 0;
}
