#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex;
NFAPI_CRC_INDICATION_PDU_T** pdu_list;
int list_size;
int allocated_size;

void init_pdu_list() {
    pthread_mutex_init(&mutex, NULL);
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) exit(EXIT_FAILURE);
    list_size = 0;
    allocated_size = 10;
}

void expand_pdu_list() {
    NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(pdu_list, allocated_size * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!new_list) exit(EXIT_FAILURE);
    pdu_list = new_list;
    allocated_size *= 2;
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) exit(EXIT_FAILURE);

    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() % 2;

    return pdu;
}

void add_pdu_to_list() {
    pthread_mutex_lock(&mutex);
    if (list_size == allocated_size) expand_pdu_list();
    pdu_list[list_size++] = generate_pdu();
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= list_size) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = pdu_list[index];
    pthread_mutex_unlock(&mutex);
    return pdu;
}

void free_pdu_list() {
    for (int i = 0; i < list_size; i++) {
        free(pdu_list[i]);
    }
    free(pdu_list);
    pthread_mutex_destroy(&mutex);
}
