#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int session_id;
    char peer_address[16];
    enum ConnectionState {
        ESTABLISHED,
        CLOSING,
        CLOSED
    } state;
    time_t last_activity;
} ConnectionContext;

typedef struct Node {
    ConnectionContext context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool* create_connection_pool() {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_connection_pool(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    Node* current = pool->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pool->head = NULL;
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int insert_connection(ConnectionPool* pool, ConnectionContext context) {
    pthread_mutex_lock(&pool->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    new_node->context = context;
    new_node->next = pool->head;
    pool->head = new_node;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

ConnectionContext* find_connection(ConnectionPool* pool, int session_id) {
    pthread_mutex_lock(&pool->lock);
    Node* current = pool->head;
    while (current) {
        if (current->context.session_id == session_id) {
            ConnectionContext* context_copy = (ConnectionContext*)malloc(sizeof(ConnectionContext));
            if (!context_copy) {
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }
            *context_copy = current->context;
            pthread_mutex_unlock(&pool->lock);
            return context_copy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void update_connection(ConnectionPool* pool, int session_id, ConnectionContext new_context) {
    pthread_mutex_lock(&pool->lock);
    Node* current = pool->head;
    while (current) {
        if (current->context.session_id == session_id) {
            current->context = new_context;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);
}

void log_connection_activity(ConnectionPool* pool, int session_id) {
    ConnectionContext* context = find_connection(pool, session_id);
    if (context) {
        printf("Session ID: %d, State: %s, Last Activity: %ld\n", context->session_id, 
               context->state == ESTABLISHED ? "ESTABLISHED" : "CLOSED", context->last_activity);
        free(context);
    }
}

void* manage_connection_pool(void* arg) {
    ConnectionPool* pool = (ConnectionPool*)arg;
    // Simulate connection management tasks
    return NULL;
}
