Config* initialize_config(const char* option) {
    void* handle = dlopen(option, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return NULL;
    }

    Config (*create_config)();
    *(void**)(&create_config) = dlsym(handle, "create_config");
    const char* dlsym_error = dlerror();
    if (dlsym_error) {
        fprintf(stderr, "Error loading symbol: %s\n", dlsym_error);
        dlclose(handle);
        return NULL;
    }

    Config* config = create_config();
    if (!config) {
        fprintf(stderr, "Failed to initialize configuration.\n");
        dlclose(handle);
        return NULL;
    }

    return config;
}
