    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(*num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < *num_elements; i++) {
        (*list)[i].rx_ue_information_tag = rand() % 1000;
        (*list)[i].rnti = rand() % 65536;
        (*list)[i].crc_indication_rel8_tag = rand() % 2; // Randomly set CRCFLAG
    }

    return 0; // Success
}

int serialize_list_to_file(NFAPI_CRC_INDICATION_PDU_T *list, int num_elements, const char *filename) {
    if (list == NULL || filename == NULL) {
        return -1; // Invalid input
    }

    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        return -2; // File I/O error
    }

    size_t result = fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, file);
    fclose(file);

