NetworkEvent event_list[MAX_EVENTS];
int event_count = 0;

void add_event(time_t ts, const char *src_ip, const char *dest_ip, size_t size, int processed) {
    if (event_count < MAX_EVENTS) {
        event_list[event_count].timestamp = ts;
        strncpy(event_list[event_count].source_ip, src_ip, sizeof(event_list[event_count].source_ip));
        strncpy(event_list[event_count].destination_ip, dest_ip, sizeof(event_list[event_count].destination_ip));
        event_list[event_count].packet_size = size;
        event_list[event_count].processed = processed;
        event_count++;
    }
}

void clean_old_events(time_t threshold) {
    for (int i = 0; i < event_count; ) {
        if (event_list[i].timestamp + threshold < time(NULL)) {
            for (int j = i; j < event_count - 1; j++) {
                event_list[j] = event_list[j + 1];
            }
            event_count--;
        } else {
            i++;
        }
    }
}

void process_events() {
    // Simulate processing events
    for (int i = 0; i < event_count; i++) {
        if (!event_list[i].processed) {
            // Perform some processing
            event_list[i].processed = 1;
        }
    }
}

int main() {
    // Example usage
    time_t current_time = time(NULL);
    add_event(current_time, "192.168.1.1", "10.0.0.1", 1500, 0);
    process_events();
    clean_old_events(3600); // Clean events older than 1 hour
    return 0;
