#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_EVENTS 50000

typedef enum { LOW, MEDIUM, HIGH } PacketPriority;

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int packet_size;
    PacketPriority priority;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

EventManager event_manager = { .capacity = 0, .count = 0 };

void init_event_manager() {
    event_manager.capacity = MAX_EVENTS;
    event_manager.events = malloc(event_manager.capacity * sizeof(NetworkEvent));
    pthread_mutex_init(&event_manager.lock, NULL);
}

void add_event(const NetworkEvent *event) {
    pthread_mutex_lock(&event_manager.lock);
    if (event_manager.count >= event_manager.capacity) {
        size_t new_capacity = event_manager.capacity * 2;
        event_manager.events = realloc(event_manager.events, new_capacity * sizeof(NetworkEvent));
        event_manager.capacity = new_capacity;
    }
    memcpy(&event_manager.events[event_manager.count], event, sizeof(NetworkEvent));
    event_manager.count++;
    pthread_mutex_unlock(&event_manager.lock);
}

void cleanup_old_events(time_t cutoff_time) {
    pthread_mutex_lock(&event_manager.lock);
    size_t i = 0;
    while (i < event_manager.count && event_manager.events[i].timestamp < cutoff_time) {
        memmove(&event_manager.events[i], &event_manager.events[i + 1], (event_manager.count - i - 1) * sizeof(NetworkEvent));
        i++;
    }
    event_manager.count = i;
    pthread_mutex_unlock(&event_manager.lock);
}

void log_event_processing(const NetworkEvent *event, int success, const char *error_message) {
    printf("Event: %s -> %s, Size: %d, Priority: %s\n", event->source_ip, event->destination_ip, event->packet_size,
           event->priority == LOW ? "Low" : event->priority == MEDIUM ? "Medium" : "High");
    printf("Success: %s, Error: %s\n", success ? "Yes" : "No", error_message);
}

void *process_events(void *arg) {
    // Simulate event processing
    NetworkEvent event = { .timestamp = time(NULL), .packet_size = rand() % 1500, .priority = rand() % 3 };
    pthread_mutex_lock(&event_manager.lock);
    add_event(&event);
    pthread_mutex_unlock(&event_manager.lock);

    log_event_processing(&event, rand() % 2 == 0, rand() % 2 == 0 ? "Success" : "Error");

    return NULL;
}

void *monitor_stats(void *arg) {
    // Simulate statistics collection
    while (1) {
        pthread_mutex_lock(&event_manager.lock);
        printf("Events processed: %zu\n", event_manager.count);
        pthread_mutex_unlock(&event_manager.lock);

        sleep(5);  // Collect stats every 5 seconds
    }

    return NULL;
}

int main() {
    init_event_manager();

    pthread_t thread_ids[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&thread_ids[i], NULL, process_events, NULL);
    }

    pthread_t monitor_id;
    pthread_create(&monitor_id, NULL, monitor_stats, NULL);

    for (int i = 0; i < 10; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    cleanup_old_events(time(NULL) - 3600);  // Cleanup events older than 1 hour

    return 0;
}
```

This code snippet defines a `NetworkEvent` structure to hold metadata about network traffic events and an `EventManager` structure to manage a list of such events. It includes functions for initializing the event manager, adding events, cleaning up old events, logging event processing, and simulating concurrent event processing and statistics collection using multi-threading. The main function demonstrates creating threads to process events concurrently and monitor statistics.']

