#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct ConfigParam {
    int value;
    struct ConfigParam *next;
} ConfigParam;

typedef struct ConfigProfile {
    ConfigParam *head;
    ConfigParam *tail;
    pthread_mutex_t lock;
} ConfigProfile;

ConfigProfile* initConfigProfile() {
    ConfigProfile *profile = (ConfigProfile*)malloc(sizeof(ConfigProfile));
    if (profile == NULL) return NULL;

    profile->head = profile->tail = NULL;
    pthread_mutex_init(&profile->lock, NULL);

    return profile;
}

void addParamToEnd(ConfigProfile *profile, int value) {
    pthread_mutex_lock(&profile->lock);
    ConfigParam *newParam = (ConfigParam*)malloc(sizeof(ConfigParam));
    if (newParam == NULL) {
        pthread_mutex_unlock(&profile->lock);
        return;
    }

    newParam->value = value;
    newParam->next = NULL;

    if (profile->tail != NULL) {
        profile->tail->next = newParam;
    } else {
        profile->head = newParam;
    }
    profile->tail = newParam;

    pthread_mutex_unlock(&profile->lock);
}

ConfigProfile* findSubsequence(ConfigProfile *profile, int start, int end, bool includeFilter) {
    ConfigProfile *newProfile = initConfigProfile();
    if (newProfile == NULL) return NULL;

    ConfigParam *current = profile->head;
    while (current != NULL) {
        if (includeFilter ? current->value >= start && current->value <= end : true) {
            addParamToEnd(newProfile, current->value);
        }
        current = current->next;
    }

    return newProfile;
}

void freeConfigProfile(ConfigProfile *profile) {
    ConfigParam *current = profile->head;
    while (current != NULL) {
        ConfigParam *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&profile->lock);
    free(profile);
}
