#define NFAPI_CRC_INDICATION_PDU_T struct { /* Define your structure here */ }
#define RX_UE_INFORMATION_TAG uint32_t
#define RNTI uint16_t
#define CRC_INDICATION_REL8_TAG uint8_t

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* create_node(RX_UE_INFORMATION_TAG rx_id, RNTI rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data.RX_UE_INFORMATION_TAG = rx_id;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);

    return new_node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        pthread_mutex_destroy(&current->mutex);
        free(current);
        current = next;
    }
}

int serialize_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    Node* current = head;
    while (current != NULL) {
        pthread_mutex_lock(&current->mutex);
        if (fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            fclose(file);
            return -1;
        }
        pthread_mutex_unlock(&current->mutex);
        current = current->next;
    }

    fclose(file);
    return 0;
}

Node* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    Node* head = NULL;
    Node** tail = &head;

    while (!feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) break;

        Node* new_node = create_node(data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG);
        if (!new_node) {
            free_list(head);
            fclose(file);
            return NULL;
        }

        *tail = new_node;
        tail = &new_node->next;
    }

    fclose(file);
    return head;
}

// Example usage
int main() {
    srand(time(NULL));

    Node* list_head = create_node(1, 2, (CRC_INDICATION_REL8_TAG)rand());
    // Add more nodes as needed

    if (!serialize_list(list_head, "nfa_pi.crc_indication_pdu")) {
        printf("Serialization successful.\n");
    } else {
        printf("Serialization failed.\n");
    }

    Node* deserialized_head = deserialize_list("nfa_pi.crc_indication_pdu");
    if (deserialized_head) {
        printf("Deserialization successful.\n");
        free_list(deserialized_head);
    } else {
        printf("Deserialization failed.\n");
    }

    return 0;
}
