#define MAX_EVENTS 50000
#define CACHE_SIZE 1000

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int packet_size;
    int priority;
} NetworkEvent;

typedef struct {
    NetworkEvent events[MAX_EVENTS];
    int size;
    pthread_mutex_t lock;
} EventList;

typedef struct {
    NetworkEvent events[CACHE_SIZE];
    int head;
    int tail;
    pthread_mutex_t lock;
} EventCache;

EventList event_list;
EventCache event_cache;
time_t cleanup_threshold = time(NULL) - 3600; // Events older than 1 hour
int packet_loss_count = 0;
double total_processing_time = 0.0;
int processing_attempts = 0;

void initialize_event_system() {
    pthread_mutex_init(&event_list.lock, NULL);
    pthread_mutex_init(&event_cache.lock, NULL);
}

void add_event_to_list(NetworkEvent event) {
    pthread_mutex_lock(&event_list.lock);
    if (event_list.size < MAX_EVENTS) {
        event_list.events[event_list.size++] = event;
    }
    pthread_mutex_unlock(&event_list.lock);
}

void* process_events(void* arg) {
    while (1) {
        NetworkEvent event;
        time_t current_time = time(NULL);

        pthread_mutex_lock(&event_list.lock);
        if (event_list.size > 0 && event_list.events[0].timestamp < cleanup_threshold) {
            event = event_list.events[0];
            memmove(event_list.events, event_list.events + 1, sizeof(NetworkEvent) * (event_list.size - 1));
            event_list.size--;
        } else if (event_list.size > 0) {
            event = event_list.events[0];
            memmove(event_list.events, event_list.events + 1, sizeof(NetworkEvent) * (event_list.size - 1));
            event_list.size--;
            pthread_mutex_unlock(&event_list.lock);
            break;
        } else {
            pthread_mutex_unlock(&event_list.lock);
            sleep(1);
        }

        double start_time = (double)clock() / CLOCKS_PER_SEC;
        // Process the event
        if (!process_event(event)) {
            packet_loss_count++;
        }
        double end_time = (double)clock() / CLOCKS_PER_SEC;
        total_processing_time += end_time - start_time;
        processing_attempts++;

        pthread_mutex_lock(&event_cache.lock);
        if ((event_cache.tail + 1) % CACHE_SIZE != event_cache.head) {
            event_cache.events[event_cache.tail] = event;
            event_cache.tail = (event_cache.tail + 1) % CACHE_SIZE;
        }
        pthread_mutex_unlock(&event_cache.lock);

        upload_statistics();
    }
    return NULL;
}

int process_event(NetworkEvent event) {
    // Event processing logic here
    // Return 0 for success, -1 for failure
    return 0;
}

void upload_statistics() {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        char *json_data = create_json_statistics();

        curl_easy_setopt(curl, CURLOPT_URL, "http://monitoring.example.com/statistics");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

char* create_json_statistics() {
