typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void serialize_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        log_error("Failed to open file for writing");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node* temp = list->head;
    while (temp != NULL) {
        if (fwrite(&temp->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            log_error("Error writing to file");
            fclose(file);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        temp = temp->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
}

void deserialize_list(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        log_error("Failed to open file for reading");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        add_node(list, data);
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* temp = list->head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}
