#include <stdlib.h>
#include <pthread.h>

typedef struct MCSObject {
    int modulation;
    int codingScheme;
    // Other fields as needed
} MCSObject;

typedef struct MCSCollection {
    MCSObject** objects;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MCSCollection;

MCSCollection* createMCS_COLLECTION(size_t initialCapacity) {
    MCSCollection* collection = malloc(sizeof(MCSCollection));
    if (collection == NULL) return NULL;

    collection->objects = calloc(initialCapacity, sizeof(MCSObject*));
    if (collection->objects == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroyMCS_COLLECTION(MCSCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->objects[i]);
    }
    free(collection->objects);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int addMCS_OBJECT(MCSCollection* collection, MCSObject* object) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        MCSObject** newObjects = realloc(collection->objects, newCapacity * sizeof(MCSObject*));
        if (newObjects == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->objects = newObjects;
        collection->capacity = newCapacity;
    }

    collection->objects[collection->size++] = object;
    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int removeMCS_OBJECT(MCSCollection* collection, int modulation, int codingScheme) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->objects[i]->modulation == modulation && 
            collection->objects[i]->codingScheme == codingScheme) {
            free(collection->objects[i]);
            for (size_t j = i; j < collection->size - 1; ++j) {
                collection->objects[j] = collection->objects[j + 1];
            }
            --collection->size;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return -1; // Object not found
}

MCSObject* getMCS_OBJECT(MCSCollection* collection, int modulation, int codingScheme) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->objects[i]->modulation == modulation && 
            collection->objects[i]->codingScheme == codingScheme) {
            MCSObject* object = collection->objects[i];
            pthread_mutex_unlock(&collection->lock);
            return object;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL; // Object not found
}
