using System;
using System.Collections.Concurrent;

public class DynamicValueGenerator
{
    private Random _random;
    private ConcurrentDictionary<string, double> _cache = new ConcurrentDictionary<string, double>();
    private double _minIntRange = 0;
    private double _maxIntRange = 100;
    private double _minFloatRange = 0.0;
    private double _maxFloatRange = 1.0;

    public DynamicValueGenerator(long seed = 42)
    {
        _random = new Random(seed);
    }

    public void SetIntRange(double min, double max)
    {
        if (min < max)
        {
            _minIntRange = min;
            _maxIntRange = max;
        }
        else
        {
            Console.WriteLine("Warning: Invalid integer range. Using default [0, 100].");
            _minIntRange = 0;
            _maxIntRange = 100;
        }
    }

    public void SetFloatRange(double min, double max)
    {
        if (min < max)
        {
            _minFloatRange = min;
            _maxFloatRange = max;
        }
        else
        {
            Console.WriteLine("Warning: Invalid float range. Using default [0.0, 1.0].");
            _minFloatRange = 0.0;
            _maxFloatRange = 1.0;
        }
    }

    public int GenerateRandomInt(bool includeMax = true)
    {
        return _random.Next((int)_minIntRange, includeMax ? (int)Math.Ceiling(_maxIntRange) : (int)_maxIntRange);
    }

    public float GenerateRandomFloat(DistributionType distribution = DistributionType.Uniform)
    {
        double value;
        switch (distribution)
        {
            case DistributionType.Normal:
                do
                {
                    value = _random.NextDouble() * 2 - 1;
                    value *= Math.Sqrt(-2.0 * Math.Log(_random.NextDouble()));
                } while (value >= 1 || value < -1);
                return (float)(_minFloatRange + (value / 2) * (_maxFloatRange - _minFloatRange));
            default:
                return (float)(_minFloatRange + _random.NextDouble() * (_maxFloatRange - _minFloatRange));
        }
    }

    public int[] GenerateRandomIntBatch(int batchSize, bool includeMax = true)
    {
        if (batchSize <= 0) throw new ArgumentException("Batch size must be greater than zero.");
        var batch = new int[batchSize];
        for (int i = 0; i < batchSize; i++)
        {
            batch[i] = GenerateRandomInt(includeMax);
        }
        return batch;
    }

    public float[] GenerateRandomFloatBatch(int batchSize, DistributionType distribution = DistributionType.Uniform)
    {
        if (batchSize <= 0) throw new ArgumentException("Batch size must be greater than zero.");
        var batch = new float[batchSize];
        for (int i = 0; i < batchSize; i++)
        {
            batch[i] = GenerateRandomFloat(distribution);
        }
        return batch;
    }

    public enum DistributionType
    {
        Uniform,
        Normal
    }
}
