#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef struct {
    int setting1;
    char* setting2;
} Config;

Config* load_config(int argc, char* argv[]) {
    Config* config = (Config*)malloc(sizeof(Config));
    if (!config) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize default values
    config->setting1 = 0;
    config->setting2 = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            char* lib_name = argv[++i];
            void* handle = dlopen(lib_name, RTLD_LAZY);
            if (!handle) {
                fprintf(stderr, "Failed to load library: %s\n", dlerror());
                continue;
            }

            // Load functions from the library (example function)
            int (*get_setting1)();
            char** get_setting2();
            *(void**)(&get_setting1) = dlsym(handle, "get_setting1");
            *(void**)(&get_setting2) = dlsym(handle, "get_setting2");

            if (!get_setting1 || !get_setting2) {
                fprintf(stderr, "Failed to load symbols from library: %s\n", dlerror());
                dlclose(handle);
                continue;
            }

            // Update configuration with values from the library
            config->setting1 = get_setting1();
            free(config->setting2);
            config->setting2 = strdup(get_setting2()[0]);
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            char* env_var_value = getenv(argv[++i]);
            if (env_var_value) {
                // Update configuration with environment variable value
                free(config->setting2);
                config->setting2 = strdup(env_var_value);
            }
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Override setting from command line argument
            sscanf(argv[++i], "%d", &config->setting1);
        }
    }

    return config;
}

int main(int argc, char* argv[]) {
    Config* config = load_config(argc, argv);
    if (config) {
        printf("Setting1: %d\n", config->setting1);
        printf("Setting2: %s\n", config->setting2);
        free(config->setting2);
        free(config);
    }

    return 0;
}
