#define MAX_EVENTS 50000
#define CACHE_SIZE 1024

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int packet_size;
    int priority;
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
} EventList;

EventList *event_list = NULL;
pthread_mutex_t global_lock;

void initialize_event_manager() {
    event_list = (EventList *)malloc(sizeof(EventList));
    memset(event_list, 0, sizeof(EventList));
    pthread_mutex_init(&global_lock, NULL);
}

void add_event(Event event) {
    pthread_mutex_lock(&global_lock);
    if (event_list->count < MAX_EVENTS) {
        event_list->events[event_list->count++] = event;
    }
    pthread_mutex_unlock(&global_lock);
}

void clean_old_events(time_t cutoff) {
    pthread_mutex_lock(&global_lock);
    for (int i = 0; i < event_list->count; ) {
        if (event_list->events[i].timestamp < cutoff) {
            memmove(&event_list->events[i], &event_list->events[i + 1], sizeof(Event) * (event_list->count - i - 1));
            event_list->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&global_lock);
}

void process_events() {
    for (int i = 0; i < event_list->count; i++) {
        Event event = event_list->events[i];
        // Process the event here
    }
}

void* worker_thread(void *arg) {
    while (1) {
        process_events();
        clean_old_events(time(NULL) - 3600); // Clean events older than 1 hour
        sleep(1);
    }
    return NULL;
}

int main() {
    initialize_event_manager();

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, worker_thread, NULL);

    // Simulate adding events
    for (int i = 0; i < MAX_EVENTS; i++) {
        Event event;
        memset(&event, 0, sizeof(Event));
        event.timestamp = time(NULL);
        snprintf(event.source_ip, 16, "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(event.destination_ip, 16, "10.0.%d.%d", rand() % 256, rand() % 256);
        event.packet_size = rand() % 1400;
        event.priority = rand() % 3;
        add_event(event);
    }

    pthread_join(thread_id, NULL);

    return 0;
}
