#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the configuration parameter structure
typedef struct config_param {
    char *key;
    void *value;
    size_t value_size;
    struct config_param *next;
} ConfigParam;

// Define the configuration profile structure
typedef struct config_profile {
    ConfigParam *head;
    ConfigParam *tail;
    size_t count;
    pthread_mutex_t lock;
} ConfigProfile;

// Function to initialize a new configuration profile
ConfigProfile* init_config_profile() {
    ConfigProfile *profile = (ConfigProfile*)malloc(sizeof(ConfigProfile));
    if (!profile) return NULL;
    profile->head = profile->tail = NULL;
    profile->count = 0;
    pthread_mutex_init(&profile->lock, NULL);
    return profile;
}

// Function to add a new parameter to the configuration profile
void add_config_param(ConfigProfile *profile, char *key, void *value, size_t value_size) {
    pthread_mutex_lock(&profile->lock);
    ConfigParam *param = (ConfigParam*)malloc(sizeof(ConfigParam));
    if (!param) {
        pthread_mutex_unlock(&profile->lock);
        return;
    }
    param->key = strdup(key);
    param->value = malloc(value_size);
    if (!param->value) {
        free(param->key);
        free(param);
        pthread_mutex_unlock(&profile->lock);
        return;
    }
    memcpy(param->value, value, value_size);
    param->value_size = value_size;
    param->next = NULL;

    if (profile->tail) {
        profile->tail->next = param;
        profile->tail = param;
    } else {
        profile->head = profile->tail = param;
    }
    profile->count++;
    pthread_mutex_unlock(&profile->lock);
}

// Function to find a contiguous subsequence of configuration parameters
ConfigParam* find_config_subseq(ConfigProfile *profile, char *start_key, char *end_key) {
    ConfigParam *current = profile->head;
    while (current && strcmp(current->key, start_key) != 0) current = current->next;

    if (!current || !current->next) return NULL;

    ConfigParam *subseq_head = current;
    while (current && strcmp(current->key, end_key) <= 0) {
        current = current->next;
    }

    if (current) subseq_head->next = NULL;
    else profile->tail = subseq_head;

    return subseq_head;
}

// Function to dynamically manage a highly configurable network device profile
ConfigProfile* manage_config_profile(ConfigProfile *profile, char *start_key, char *end_key, int filter_flag) {
    ConfigParam *subseq = find_config_subseq(profile, start_key, end_key);
    if (!subseq) return NULL;

    ConfigProfile *new_profile = init_config_profile();
    if (!new_profile) return NULL;

    ConfigParam *current = subseq;
    while (current) {
        if (filter_flag && current->key[0] == 'X') continue; // Example filter logic
        add_config_param(new_profile, current->key, current->value, current->value_size);
        current = current->next;
    }

    return new_profile;
}

// Function to clean up the configuration profile and free memory
void cleanup_config_profile(ConfigProfile *profile) {
    pthread_mutex_lock(&profile->lock);
    ConfigParam *current = profile->head;
    while (current) {
        ConfigParam *temp = current;
        current = current->next;
        free(temp->key);
        free(temp->value);
        free(temp);
    }
    profile->head = profile->tail = NULL;
    profile->count = 0;
    pthread_mutex_unlock(&profile->lock);
    pthread_mutex_destroy(&profile->lock);
    free(profile);
}
