#include <stdbool.h>

#define MAX_STRUCTURES 50000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
    time_t timestamp;
    uint8_t status_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *generate_crc_indications(int n) {
    NFAPI_CRC_INDICATION_PDU_T *indicators = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indicators == NULL) {
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        indicators[i].RX_UE_INFORMATION_TAG = rand();
        indicators[i].RNTI = (uint16_t)(rand() % 16384);
        indicators[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        indicators[i].CRCFLAG = rand() % 2;
        indicators[i].timestamp = time(NULL);
        indicators[i].status_flag = 0; // Assuming all start as not processed
    }

    return indicators;
}

void process_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indicators, int n) {
    for (int i = 0; i < n; i++) {
        if (indicators[i].CRCFLAG == 1) {
            // Simulate processing
            indicators[i].status_flag = 1; // Processing successful
        } else {
            indicators[i].status_flag = 2; // Processing error
        }
    }
}

void *update_thread(void *arg) {
    int n = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *indicators;

    while (true) {
        indicators = generate_crc_indications(n);
        if (indicators != NULL) {
            process_crc_indications(indicators, n);
            free(indicators);
        }
        // Simulate periodic updates
        sleep(10);
    }

    return NULL;
}

void *retry_thread(void *arg) {
    int *update_interval = (int *)arg;

    while (true) {
        if (*update_interval > 5) {
            printf("Max retry interval reached\n");
            break;
        }
        pthread_mutex_t lock;
        pthread_mutex_init(&lock, NULL);
        pthread_mutex_lock(&lock);

        // Simulate processing
        *update_interval *= 2;

        pthread_mutex_unlock(&lock);
        sleep(*update_interval + rand() % (*update_interval / 4));
    }

    return NULL;
}

int main() {
    int update_interval = 10; // Initial interval in seconds

    pthread_t update_tid, retry_tid;
    pthread_create(&update_tid, NULL, update_thread, &MAX_STRUCTURES);
    pthread_create(&retry_tid, NULL, retry_thread, &update_interval);

    pthread_join(update_tid, NULL);
    pthread_join(retry_tid, NULL);

    return 0;
}
