#include <pthread.h>

#define MAX_STRUCTURES 50000

typedef struct {
    int crcflag;
    time_t timestamp;
    int status_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list[MAX_STRUCTURES];
    int count;
} CRC_QUEUE_T;

void generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu, int *length) {
    *length = rand() % (MAX_STRUCTURES + 1);
    *pdu = malloc(*length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < *length; i++) {
        (*pdu)[i].crcflag = rand() % 2;
        (*pdu)[i].timestamp = time(NULL);
        (*pdu)[i].status_flag = 0;
    }
}

void enqueue_crc_indication_pdu(CRC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T *pdu, int length) {
    pthread_mutex_lock(&queue->lock);
    for (int i = 0; i < length; i++) {
        queue->pdu_list[queue->count++] = &pdu[i];
    }
    pthread_mutex_unlock(&queue->lock);
}

void* periodic_update_thread(void *arg) {
    CRC_QUEUE_T *queue = (CRC_QUEUE_T *)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu;
        int length;
        generate_crc_indication_pdu(&pdu, &length);

        // Simulate network delay
        usleep(rand() % 100000 + 50000);

        enqueue_crc_indication_pdu(queue, pdu, length);

        free(pdu);
    }
    return NULL;
}

int main() {
    CRC_QUEUE_T queue;
    pthread_t thread;

    pthread_mutex_init(&queue.lock, NULL);
    queue.count = 0;

    pthread_create(&thread, NULL, periodic_update_thread, &queue);

    // Main program logic to process the queue

    pthread_join(thread, NULL);
    pthread_mutex_destroy(&queue.lock);

    return 0;
}
