void* generate_and_populate_structs(void* arg) {
    int n = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* structs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!structs) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        structs[i].RX_UE_INFORMATION_TAG = rand();
        structs[i].RNTI = rand() % 65536;
        structs[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        structs[i].timestamp = (uint32_t)time(NULL);
        structs[i].status_flag = 0; // Assume success initially
    }

    free(structs);
    return NULL;
}

void retry_with_exponential_backoff(void (*task)(void*), void* arg, int max_retries) {
    int delay = 1; // Initial delay in milliseconds
    for (int i = 0; i <= max_retries; i++) {
        task(arg);
        if (/* Task completed successfully */) break;
        sleep(delay / 1000); // Convert to seconds

        // Exponential backoff with jitter
        delay *= 2;
        int jitter = rand() % (delay / 4);
        delay += jitter;

        if (delay > 60000) { // Limit maximum delay to 1 minute
            delay = 60000;
        }
    }
}

void* thread_function(void* arg) {
    int n = *(int*)arg;
    retry_with_exponential_backoff(generate_and_populate_structs, arg, 3);
    return NULL;
}

int main() {
    pthread_t threads[10];
    int args[10];

    for (int i = 0; i < 10; i++) {
        args[i] = MAX_STRUCTS / 10;
        pthread_create(&threads[i], NULL, thread_function, &args[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
