typedef enum {
    STATE_CONNECTED,
    STATE_DISCONNECTED,
    STATE_ERROR
} ConnectionState;

typedef struct State {
    char ip[16];
    int port;
    ConnectionState status;
    struct State* next;
    pthread_mutex_t lock;
} State;

State* head = NULL;

void add_state(const char* ip, int port, ConnectionState status) {
    pthread_mutex_lock(&head->lock);
    State* new_state = (State*)malloc(sizeof(State));
    strcpy(new_state->ip, ip);
    new_state->port = port;
    new_state->status = status;
    new_state->next = head;
    pthread_mutex_init(&new_state->lock, NULL);
    head = new_state;
    pthread_mutex_unlock(&head->lock);
}

void remove_state(const char* ip) {
    pthread_mutex_lock(&head->lock);
    State* current = head;
    State* prev = NULL;

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            pthread_mutex_destroy(&current->lock);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&head->lock);
}

State* get_state(const char* ip) {
    pthread_mutex_lock(&head->lock);
    State* current = head;

    while (current != NULL) {
        if (strcmp(current->ip, ip) == 0) {
            pthread_mutex_unlock(&head->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&head->lock);
    return NULL;
}

int main() {
    // Example usage
    add_state("192.168.1.1", 80, STATE_CONNECTED);
    State* state = get_state("192.168.1.1");
    if (state) {
        printf("State found: IP=%s, Port=%d, Status=%d\n", state->ip, state->port, state->status);
    }
    remove_state("192.168.1.1");

    return 0;
}
