#include <pthread.h>

#define MAX_STATES 1024

typedef struct {
    char ip[16];
    int port;
    int connection_status_flags;
} State;

typedef struct {
    State states[MAX_STATES];
    int size;
    pthread_mutex_t lock;
} FSAList;

void init_FSAList(FSAList *list) {
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_state(FSAList *list, const char *ip, int port, int flags) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_STATES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    strcpy(list->states[list->size].ip, ip);
    list->states[list->size].port = port;
    list->states[list->size].connection_status_flags = flags;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int get_state(FSAList *list, int index, State *state) {
    pthread_mutex_lock(&list->lock);
    if (index < 0 || index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid index
    }
    strcpy(state->ip, list->states[index].ip);
    state->port = list->states[index].port;
    state->connection_status_flags = list->states[index].connection_status_flags;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

