} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} TrafficList;

TrafficList *create_traffic_list(size_t initial_capacity) {
    TrafficList *list = (TrafficList *)malloc(sizeof(TrafficList));
    list->events = (TrafficEvent *)calloc(initial_capacity, sizeof(TrafficEvent));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    return list;
}

void destroy_traffic_list(TrafficList *list) {
    free(list->events);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

int add_event(TrafficList *list, TrafficEvent event) {
    pthread_mutex_lock(&list->lock);
    while (list->size == list->capacity) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }
    if (list->size < list->capacity) {
        list->events[list->size++] = event;
        pthread_cond_signal(&list->cond_var);
        pthread_mutex_unlock(&list->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }
}

void cleanup_old_events(TrafficList *list, time_t cutoff_time) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0, j = 0;
    while (j < list->size && list->events[j].timestamp < cutoff_time) {
        j++;
    }
    if (j < list->size) {
        memmove(list->events, &list->events[j], (list->size - j) * sizeof(TrafficEvent));
        list->size -= j;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_statistics(TrafficList *list) {
    // Implement statistics updating logic here
}

void *traffic_processor(void *arg) {
    TrafficList *list = (TrafficList *)arg;
    while (1) {
        TrafficEvent event;
        if (add_event(list, event) == 0) {
            // Process the event
            pthread_mutex_lock(&list->lock);
            update_statistics(list);
            pthread_mutex_unlock(&list->lock);
        }
        // Sleep or wait for new events
    }
}

int main() {
    TrafficList *traffic_list = create_traffic_list(10000);
    pthread_t processors[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&processors[i], NULL, traffic_processor, traffic_list);
    }
    // Simulate adding events
    TrafficEvent new_event;
    new_event.timestamp = time(NULL);
    strcpy(new_event.source_ip, "192.168.1.1");
    strcpy(new_event.destination_ip, "10.0.0.1");
    new_event.packet_size = 1500;
    new_event.processed_successfully = 1;
    add_event(traffic_list, new_event);
    // Cleanup old events periodically
    time_t now = time(NULL);
    cleanup_old_events(traffic_list, now - 60);
    // Join threads and clean up
    for (int i = 0; i < 10; i++) {
        pthread_join(processors[i], NULL);
    }
    destroy_traffic_list(traffic_list);
    return 0;
}
