} StateMetadata;

// Define a node in the dynamic list of states
typedef struct Node {
    StateMetadata data;
    struct Node* next;
} ListNode;

// Define the dynamic list of states
ListNode* state_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new state to the list
void add_state(StateMetadata metadata) {
    pthread_mutex_lock(&list_mutex);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        return;
    }
    new_node->data = metadata;
    new_node->next = state_list;
    state_list = new_node;
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove a state from the list
void remove_state(StateMetadata metadata) {
    pthread_mutex_lock(&list_mutex);
    ListNode* current = state_list;
    ListNode* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->data.ip_address, metadata.ip_address) == 0 &&
            current->data.port == metadata.port) {
            if (previous == NULL) {
                state_list = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to search for a state in the list
ListNode* find_state(StateMetadata metadata) {
    pthread_mutex_lock(&list_mutex);
    ListNode* current = state_list;

    while (current != NULL) {
        if (strcmp(current->data.ip_address, metadata.ip_address) == 0 &&
            current->data.port == metadata.port) {
            pthread_mutex_unlock(&list_mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

// Function to free the entire list of states
void free_state_list() {
    pthread_mutex_lock(&list_mutex);
    ListNode* current = state_list;

    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }

    state_list = NULL;
    pthread_mutex_unlock(&list_mutex);
}
