void init_event_list(EventList* list) {
    list->events = (TrafficEvent*)malloc(sizeof(TrafficEvent) * 1024);
    list->size = 0;
    list->capacity = 1024;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_event_list(EventList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->events);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int add_event(EventList* list, TrafficEvent event) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(list->events, sizeof(TrafficEvent) * new_capacity);
        if (!new_events) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }
    list->events[list->size++] = event;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void remove_obsolete_events(EventList* list, time_t cutoff_time) {
    pthread_mutex_lock(&list->mutex);
    size_t new_size = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->events[i].timestamp >= cutoff_time) {
            list->events[new_size++] = list->events[i];
        }
    }
    list->size = new_size;
    pthread_mutex_unlock(&list->mutex);
}

void* process_events(void* arg) {
    EventList* list = (EventList*)arg;
    // Simulate event processing logic
    while (1) {
        TrafficEvent event;
        if (remove_event(list, time(NULL) - 60)) { // Remove events older than 1 minute
            break; // No more events to process
        }
        // Process the event
        printf("Processing event at %ld from %s to %s\n", event.timestamp, event.source_ip, event.destination_ip);
    }
    return NULL;
}

int main() {
    EventList list;
    init_event_list(&list);

    pthread_t thread;
    pthread_create(&thread, NULL, process_events, &list);

    // Simulate adding events
    for (size_t i = 0; i < MAX_EVENTS; ++i) {
        TrafficEvent event = {time(NULL), "192.168.1." + (rand() % 256), "192.168.1." + (rand() % 256), rand() % 1024, 0};
        add_event(&list, event);
    }

    pthread_join(thread, NULL);
    free_event_list(&list);

    return 0;
}
