#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char ip[16];
    int port;
    unsigned long status_flags;
    char session_history[256];
    time_t last_accessed;
} StateMetadata;

typedef struct Node {
    StateMetadata data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicStateList;

DynamicStateList* create_list() {
    DynamicStateList* list = (DynamicStateList*)malloc(sizeof(DynamicStateList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicStateList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_state(DynamicStateList* list, StateMetadata metadata) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle out-of-memory error
    new_node->data = metadata;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

StateMetadata* get_state(DynamicStateList* list, int index) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; current && i < index; i++) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    StateMetadata* result = &current->data;
    pthread_mutex_unlock(&list->lock);
    return result;
}

void update_state(DynamicStateList* list, int index, StateMetadata new_data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (int i = 0; current && i < index; i++) {
        current = current->next;
    }
    if (current) {
        current->data = new_data;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_state(DynamicStateList* list, int index) {
    pthread_mutex_lock(&list->lock);
    Node** current_ptr = &list->head;
    for (int i = 0; *current_ptr && i < index; i++) {
        current_ptr = &(*current_ptr)->next;
    }
    if (*current_ptr) {
        Node* temp = *current_ptr;
        *current_ptr = (*current_ptr)->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
}

