    int validity_flag;
} USER_AUTHENTICATION_EVENT_T;

typedef struct node {
    USER_AUTHENTICATION_EVENT_T event;
    struct node* next;
} NODE_T;

typedef struct {
    pthread_mutex_t mutex;
    NODE_T* head;
    NODE_T* tail;
    int count;
} LIST_T;

LIST_T* create_list() {
    LIST_T* list = (LIST_T*)malloc(sizeof(LIST_T));
    if (list == NULL) return NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

void add_event(LIST_T* list, USER_AUTHENTICATION_EVENT_T event) {
    NODE_T* new_node = (NODE_T*)malloc(sizeof(NODE_T));
    if (new_node == NULL) return;
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->tail != NULL) list->tail->next = new_node;
    else list->head = new_node;
    list->tail = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void* clean_expired_events(void* arg) {
    LIST_T* list = (LIST_T*)arg;
    while (1) {
        sleep(60); // Check every minute
        pthread_mutex_lock(&list->mutex);
        NODE_T* current = list->head;
        NODE_T* prev = NULL;
        while (current != NULL) {
            if (current->event.validity_flag == 0) {
                if (prev == NULL) list->head = current->next;
                else prev->next = current->next;
                if (current->next == NULL) list->tail = prev;
                free(current);
                list->count--;
            } else {
                prev = current;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&list->mutex);
    }
}

void* update_statistics(void* arg) {
    LIST_T* list = (LIST_T*)arg;
    while (1) {
        sleep(300); // Update every five minutes
        int total_events = 0, success_count = 0;
        long total_duration = 0;
        pthread_mutex_lock(&list->mutex);
        NODE_T* current = list->head;
        while (current != NULL) {
            total_events++;
            if (current->event.auth_status == 1) success_count++;
            total_duration += current->event.session_duration;
            current = current->next;
        }
        pthread_mutex_unlock(&list->mutex);
        printf("Authentication Success Rate: %.2f%%\n", (float)success_count / total_events * 100);
        printf("Average Session Duration: %ld seconds\n", total_duration / total_events);
    }
}

USER_AUTHENTICATION_EVENT_T* create_event_array(int N, int* error_code) {
    USER_AUTHENTICATION_EVENT_T* array = (USER_AUTHENTICATION_EVENT_T*)malloc(N * sizeof(USER_AUTHENTICATION_EVENT_T));
    if (array == NULL) {
        *error_code = 1;
        return NULL;
    }
    for (int i = 0; i < N; i++) {
        // Initialize each event with valid data
        array[i].user_id = i + 1;
        array[i].auth_timestamp = time(NULL);
        array[i].auth_status = rand() % 2;
        array[i].session_duration = rand() % 3600 + 60; // Between 1 and 60 minutes
        array[i].validity_flag = 1;
    }
    *error_code = 0;
    return array;
}

int validate_event_array(USER_AUTHENTICATION_EVENT_T* array, int N) {
    for (int i = 1; i < N; i++) {
        if (array[i].user_id == array[i - 1].user_id) return 0; // Duplicate user ID found
    }
    return 1;
}
