#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for each state in the FSA
typedef struct {
    char ip[16];
    int port;
    int connection_status;
} State;

// Define a node for the dynamic list of states
typedef struct Node {
    State data;
    struct Node* next;
} Node;

// Define the dynamic list itself
typedef struct {
    Node* head;
    pthread_mutex_t mutex; // Mutex for thread-safe access
} DynamicList;

// Function to initialize the dynamic list
void init_list(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a new state to the list
void add_state(DynamicList* list, State new_state) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = new_state;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a state from the list
void remove_state(DynamicList* list, char* ip, int port) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && (strcmp(current->data.ip, ip) != 0 || current->data.port != port)) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // State not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&list->mutex);
}

// Function to find a state in the list by IP and port
State* find_state(DynamicList* list, char* ip, int port) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;

    while (current != NULL && (strcmp(current->data.ip, ip) != 0 || current->data.port != port)) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // State not found
    }

    pthread_mutex_unlock(&list->mutex);
    return &current->data;
}

// Function to destroy the dynamic list and free all allocated memory
void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
}
