#include <stdlib.h>

typedef struct FSA {
    int *transitions;
    int numTransitions;
} FSA;

typedef struct StateList {
    int state;
    struct StateList *next;
} StateList;

StateList* constructSubStateList(int *states, int numStates, FSA *fsa, int lastState, int maxNewSize) {
    if (numStates <= 0 || maxNewSize <= 0) return NULL;

    StateList *newHead = NULL, **current = &newHead;
    for (int i = 0; i < numStates && newHead != NULL; ++i) {
        StateList *newState = (StateList*)malloc(sizeof(StateList));
        if (!newState) return NULL; // Insufficient memory

        newState->state = states[i];
        newState->next = NULL;

        *current = newState;
        current = &(*current)->next;
    }

    if (*current != NULL) {
        *current = NULL; // Truncate list if exceeds maxNewSize
    }

    if (lastState >= 0 && fsa->numTransitions > 0) {
        int index = lastState % fsa->numTransitions;
        for (; *current != NULL; ++index, *current = (*current)->next) {
            if (index == fsa->transitions[*current]->state) break;
        }

        if (*current != NULL && *current->next != NULL) {
            StateList *temp = (*current)->next;
            (*current)->next = newHead;
            free(temp);
