} USER_AUTH_EVENTS_LIST_T;

USER_AUTH_EVENTS_LIST_T* create_user_auth_events_list(size_t initial_capacity) {
    USER_AUTH_EVENTS_LIST_T *list = (USER_AUTH_EVENTS_LIST_T*)malloc(sizeof(USER_AUTH_EVENTS_LIST_T));
    if (!list) return NULL;

    list->events = (USER_AUTHENTICATION_EVENT_PDU_T*)calloc(initial_capacity, sizeof(USER_AUTHENTICATION_EVENT_PDU_T));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_user_auth_events_list(USER_AUTH_EVENTS_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->events);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_event_to_list(USER_AUTH_EVENTS_LIST_T *list, USER_AUTHENTICATION_EVENT_PDU_T event) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        USER_AUTHENTICATION_EVENT_PDU_T *new_events = (USER_AUTHENTICATION_EVENT_PDU_T*)realloc(list->events, new_capacity * sizeof(USER_AUTHENTICATION_EVENT_PDU_T));
        if (!new_events) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    list->events[list->size++] = event;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_event_from_list(USER_AUTH_EVENTS_LIST_T *list, int user_id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->events[i].user_id == user_id) {
            memmove(&list->events[i], &list->events[i + 1], (list->size - i - 1) * sizeof(USER_AUTHENTICATION_EVENT_PDU_T));
            --list->size;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

bool validate_list_integrity(USER_AUTH_EVENTS_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 1; i < list->size; ++i) {
        if (list->events[i].user_id == list->events[i - 1].user_id) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}
