#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int task_id;
    int priority_level;
    int timeout;
} ASYNC_TASK_T;

typedef struct EventQueue {
    ASYNC_TASK_T** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} EventQueue;

EventQueue* create_event_queue(size_t initial_capacity) {
    EventQueue* queue = (EventQueue*)malloc(sizeof(EventQueue));
    if (!queue) return NULL;

    queue->tasks = (ASYNC_TASK_T**)calloc(initial_capacity, sizeof(ASYNC_TASK_T*));
    if (!queue->tasks) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);

    return queue;
}

void destroy_event_queue(EventQueue* queue) {
    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->tasks[i]);
    }
    free(queue->tasks);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

int enqueue_task(EventQueue* queue, ASYNC_TASK_T* task) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    if (queue->size < queue->capacity) {
        queue->tasks[queue->size++] = task;
        pthread_cond_signal(&queue->cond);
    } else {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is full
    }

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

ASYNC_TASK_T* dequeue_task(EventQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    ASYNC_TASK_T* task = queue->tasks[--queue->size];
    pthread_cond_signal(&queue->cond);

    pthread_mutex_unlock(&queue->lock);
    return task;
}

void resize_event_queue(EventQueue* queue, size_t new_capacity) {
    pthread_mutex_lock(&queue->lock);
    if (new_capacity > queue->capacity) {
        ASYNC_TASK_T** new_tasks = (ASYNC_TASK_T**)realloc(queue->tasks, new_capacity * sizeof(ASYNC_TASK_T*));
        if (!new_tasks) {
            pthread_mutex_unlock(&queue->lock);
            return; // Realloc failed
        }
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
    }
    pthread_mutex_unlock(&queue->lock);
}

