    pub fn add_or_update_context(&self, ue_id: u32, pdcp_pdus: Vec<Vec<u8>>, session_status: bool) -> Result<(), Box<dyn Error>> {
        let mut contexts = self.contexts.write().unwrap();
        contexts.insert(ue_id, LteUeContext { ue_id, pdcp_pdus, session_status });
