#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef enum {
    WORD_COUNT,
    LINE_COUNT,
    CHARACTER_COUNT
} QueryType;

void processFile(const char *inputFile, const char *outputFile, QueryType query, int verbose) {
    FILE *file = fopen(inputFile, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    long totalLines = 0;
    long totalWords = 0;
    long totalChars = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        totalLines++;
        char *token = strtok(line, " \n");
        while (token) {
            totalWords++;
            token = strtok(NULL, " \n");
        }
        totalChars += strlen(line);
    }

    fclose(file);

    FILE *output = fopen(outputFile, "w");
    if (output == NULL) {
        perror("Error opening output file");
        return;
    }

    switch (query) {
        case WORD_COUNT:
            fprintf(output, "Total words: %ld\n", totalWords);
            break;
        case LINE_COUNT:
            fprintf(output, "Total lines: %ld\n", totalLines);
            break;
        case CHARACTER_COUNT:
            fprintf(output, "Total characters: %ld\n", totalChars);
            break;
    }

    fclose(output);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input file> <output file> <query> <verbose>\n", argv[0]);
        return 1;
    }

    const char *inputFile = argv[1];
    const char *outputFile = argv[2];
    QueryType query;
    int verbose;

    if (strcmp(argv[3], "words") == 0) {
        query = WORD_COUNT;
    } else if (strcmp(argv[3], "lines") == 0) {
        query = LINE_COUNT;
    } else if (strcmp(argv[3], "characters") == 0) {
        query = CHARACTER_COUNT;
    } else {
        fprintf(stderr, "Invalid query\n");
        return 1;
    }

    verbose = atoi(argv[4]);

    processFile(inputFile, outputFile, query, verbose);

    return 0;
}
