        fprintf(stderr, "Error: Number of entries exceeds maximum allowed.\n");
        return NULL;
    }

    LTE_UE_CONTEXT *ue_contexts = malloc(num_entries * sizeof(LTE_UE_CONTEXT));
    if (!ue_contexts) {
        perror("Failed to allocate memory for UE contexts.");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_entries; ++i) {
        // Initialize each context with default values
        ue_contexts[i].rrc_state = RRC_IDLE;
        ue_contexts[i].pdp_context = create_pdp_context(); // Assume function to create PDP context
        strcpy(ue_contexts[i].mme_ip_address, get_random_mme_ip()); // Assume function to get random MME IP

        ue_contexts[i].s1ap_message = allocate_s1ap_message(S1AP_VERSION_1); // Allocate S1AP message for version 1
        if (!ue_contexts[i].s1ap_message) {
            perror("Failed to allocate memory for S1AP message.");
            free(ue_contexts);
            return NULL;
        }

        ue_contexts[i].qos_params.priority = rand() % 10; // Random priority between 0 and 9
    }

    pthread_mutex_destroy(&lock);

    return ue_contexts;
}

// Function to validate interface name (example implementation)
int is_valid_interface_name(const char *name) {
    if (!isalpha(name[0])) return 0;
    for (size_t i = 1; i < strlen(name); ++i) {
        if (!isalnum(name[i]) && name[i] != '-') return 0;
    }
    return 1;
}

// Function to initialize NIC statistics
NIC_STATS *initialize_nic_stats(int num_interfaces, const char **interface_names) {
    if (num_interfaces > MAX_INTERFACES) {
        fprintf(stderr, "Error: Number of interfaces exceeds maximum allowed.\n");
        return NULL;
    }

    NIC_STATS *nic_stats = malloc(num_interfaces * sizeof(NIC_STATS));
    if (!nic_stats) {
        perror("Failed to allocate memory for NIC statistics.");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_interfaces; ++i) {
        if (!is_valid_interface_name(interface_names[i])) {
            fprintf(stderr, "Error: Invalid interface name '%s'.\n", interface_names[i]);
            free(nic_stats);
            return NULL;
        }

        // Initialize each NIC statistics structure
        strcpy(nic_stats[i].interface_name, interface_names[i]);
        nic_stats[i].packet_counters = rand() % 100000; // Random packet count between 0 and 99999
        nic_stats[i].error_rates = (double)rand() / RAND_MAX; // Random error rate between 0.0 and 1.0
        nic_stats[i].byte_counts = rand() % 100000000; // Random byte count between 0 and 99,999,999
        nic_stats[i].latency = (double)rand() / RAND_MAX * 100; // Random latency between 0.0 and 100 milliseconds
    }

    pthread_mutex_destroy(&lock);

    return nic_stats;
}

// Example usage
