#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int cipher_mode;
    unsigned char key[32];
    unsigned char iv[16];
} EncryptionContext;

EncryptionContext* create_encryption_context(int cipher_mode, const unsigned char* key, size_t key_len) {
    EncryptionContext* ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    if (key_len < 56 || key_len > 256) {
        free(ctx);
        return NULL;
    }

    memset(ctx, 0, sizeof(EncryptionContext));

    if (!RAND_bytes(ctx->iv, EVP_CIPHER_iv_length(EVP_aes_128_cbc()))) {
        free(ctx);
        return NULL;
    }

    memcpy(ctx->key, key, key_len);

    ctx->cipher_mode = cipher_mode;

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_encryption_context(EncryptionContext* ctx) {
    if (ctx->ctx) EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int encrypt_data(const EncryptionContext* ctx, const unsigned char* plaintext, size_t plaintext_len, unsigned char** ciphertext, size_t* ciphertext_len) {
    *ciphertext = (unsigned char*)malloc(*ciphertext_len);
    if (!*ciphertext) return -1;

    int len;
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_128_cbc(), NULL, ctx->key, ctx->iv)) return -1;
    if (!EVP_EncryptUpdate(ctx->ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        free(*ciphertext);
        return -1;
    }

    int final_len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, (*ciphertext) + len, &final_len)) {
        free(*ciphertext);
        return -1;
    }

    *ciphertext_len = len + final_len;

    return 0;
}

int decrypt_data(const EncryptionContext* ctx, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char** plaintext, size_t* plaintext_len) {
    *plaintext = (unsigned char*)malloc(*plaintext_len);
    if (!*plaintext) return -1;

    int len;
    if (!EVP_DecryptInit_ex(ctx->ctx, EVP_aes_128_cbc(), NULL, ctx->key, ctx->iv)) return -1;
    if (!EVP_DecryptUpdate(ctx->ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        free(*plaintext);
        return -1;
    }

    int final_len;
    if (!EVP_DecryptFinal_ex(ctx->ctx, (*plaintext) + len, &final_len)) {
        free(*plaintext);
        return -1;
    }

    *plaintext_len = len + final_len;

    return 0;
}
