#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int cipher_mode;
    int key_size;
} EncryptionContext;

EncryptionContext* create_encryption_context(int cipher_mode, int key_size) {
    if (cipher_mode != EVP_ENCRYPT && cipher_mode != EVP_DECRYPT) {
        fprintf(stderr, "Invalid cipher mode\n");
        return NULL;
    }
    if (key_size < 56 || key_size > 256 || key_size % 8 != 0) {
        fprintf(stderr, "Invalid key size\n");
        return NULL;
    }

    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    ctx->cipher_mode = cipher_mode;
    ctx->key_size = key_size;

    return ctx;
}

int encrypt_data(EncryptionContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        fprintf(stderr, "Error initializing encryption\n");
        return -1;
    }
    int len = 0;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Error encrypting data\n");
        return -1;
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        return -1;
    }
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt_data(EncryptionContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (!EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        fprintf(stderr, "Error initializing decryption\n");
        return -1;
    }
    int len = 0;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error decrypting data\n");
        return -1;
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        return -1;
    }
    plaintext_len += len;

    return plaintext_len;
}

void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
