    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_interfaces; ++i) {
        nic_stats[i] = malloc(sizeof(NIC_STATISTICS));
        if (!nic_stats[i]) {
            log_error("Memory allocation failed for NIC Statistics %d", i);
            for (int j = 0; j < i; ++j)
                free(nic_stats[j]);
            pthread_mutex_unlock(&lock);
            *out_num_interfaces = i;
            return nic_stats;
        }

        // Initialize fields with random or default values
        generate_random_nic_statistics(nic_stats[i]);
    }

    pthread_mutex_unlock(&lock);
    *out_num_interfaces = num_interfaces;
    return nic_stats;
