    free(manager->services);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_service(ServiceManager* manager, ServiceInstance* service) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        ServiceInstance** new_services = realloc(manager->services, new_capacity * sizeof(ServiceInstance*));
        if (new_services == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->services = new_services;
        manager->capacity = new_capacity;
    }
    manager->services[manager->count++] = service;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

