    if (!service) return NULL;

    strncpy(service->name, name, MAX_SERVICE_NAME_LENGTH - 1);
    service->config = config;
    service->cpu_utilization = 0.0;
    service->memory_usage = 0.0;
    service->io_throughput = 0.0;
    service->error_rate = 0.0;
    service->children = NULL;
    service->num_children = 0;
    pthread_mutex_init(&service->lock, NULL);

    return service;
}

void destroy_service(Service* service) {
    if (service) {
        for (int i = 0; i < service->num_children; ++i) {
            destroy_service(service->children[i]);
        }
        free(service->children);
        pthread_mutex_destroy(&service->lock);
        free(service);
    }
}

void add_child_service(Service* parent, Service* child) {
    pthread_mutex_lock(&parent->lock);
    Service** new_children = (Service**)realloc(parent->children, (parent->num_children + 1) * sizeof(Service*));
    if (new_children) {
        parent->children = new_children;
        parent->children[parent->num_children++] = child;
    }
    pthread_mutex_unlock(&parent->lock);
}

void remove_child_service(Service* parent, Service* child) {
    pthread_mutex_lock(&parent->lock);
    for (int i = 0; i < parent->num_children; ++i) {
        if (parent->children[i] == child) {
            parent->children[i] = parent->children[--parent->num_children];
            break;
        }
    }
    pthread_mutex_unlock(&parent->lock);
}

