} S1AP_MESSAGE_T;

typedef struct LTE_UE_CONTEXT {
    RRC_STATE rrc_state;
    PDP_CONTEXT pdp_context;
    MME_IP_ADDRESS mme_ip_address;
    S1AP_MESSAGE_T *s1ap_message;
    int qos_priority;
    // Add other fields as needed
} LTE_UE_CONTEXT;

LTE_UE_CONTEXT ue_contexts[MAX_UE_CONTEXTS];
int context_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* generate_ue_contexts(void *arg) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        LTE_UE_CONTEXT *ue_context = &ue_contexts[i];
        // Initialize RRC state, PDP context, and MME IP address
        ue_context->rrc_state = RRC_IDLE;
        strcpy(ue_context->pdp_context.apn, "apn.example.com");
        ue_context->pdp_context.pdp_id = i + 1;
        snprintf(ue_context->mme_ip_address.ip_address, sizeof(ue_context->mme_ip_address.ip_address), "192.168.0.%d", i + 1);

        // Dynamically allocate S1AP message
        ue_context->s1ap_message = (S1AP_MESSAGE_T *)malloc(sizeof(S1AP_MESSAGE_T));
        if (ue_context->s1ap_message) {
            ue_context->s1ap_message->version = rand() % 3; // Example: version 0, 1, or 2
            ue_context->s1ap_message->payload = malloc(1024); // Allocate buffer for payload
            if (ue_context->s1ap_message->payload) {
                memset(ue_context->s1ap_message->payload, 0, 1024);
                ue_context->s1ap_message->payload_size = rand() % 1024;
                ue_context->qos_priority = rand() % 10; // Random QoS priority
            }
        }

        context_count++;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* monitor_memory_usage(void *arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < context_count; i++) {
            LTE_UE_CONTEXT *ue_context = &ue_contexts[i];
            printf("Context %d: RRC State=%d, PDP APN=%s, MME IP=%s, QoS Priority=%d\n",
                   i, ue_context->rrc_state, ue_context->pdp_context.apn,
                   ue_context->mme_ip_address.ip_address, ue_context->qos_priority);
        }
        pthread_mutex_unlock(&lock);
        sleep(10); // Monitor every 10 seconds
    }
    return NULL;
}

int main() {
    pthread_t context_thread, monitor_thread;

    if (pthread_create(&context_thread, NULL, generate_ue_contexts, NULL) != 0) {
        perror("Failed to create context generation thread");
        return EXIT_FAILURE;
    }

    if (pthread_create(&monitor_thread, NULL, monitor_memory_usage, NULL) != 0) {
        perror("Failed to create memory monitoring thread");
        return EXIT_FAILURE;
    }

    pthread_join(context_thread, NULL);
    pthread_join(monitor_thread, NULL);

    return EXIT_SUCCESS;
}
