    FILE* file = fopen(filepath, "rb");
    if (!file) {
        if (error_mode == VERBOSE) {
            fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        }
        return NULL;
    }

    // Perform file processing
    Cipher* cipher = allocate_cipher(); // Assume this function allocates a new Cipher object
    if (!cipher) {
        fclose(file);
        if (error_mode == VERBOSE) {
            fprintf(stderr, "Failed to allocate memory for cipher\n");
        }
        return NULL;
    }

    // Read file content
    size_t file_size = get_file_size(file); // Assume this function returns the size of the file
    char* buffer = (char*)malloc(file_size + 1);
    if (!buffer) {
        free_cipher(cipher); // Assume this function frees the cipher object
        fclose(file);
        if (error_mode == VERBOSE) {
            fprintf(stderr, "Failed to allocate memory for buffer\n");
        }
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        free_cipher(cipher);
        free(buffer);
        fclose(file);
        if (error_mode == VERBOSE) {
            fprintf(stderr, "Failed to read file\n");
        }
        return NULL;
    }

    // Process file content based on mode
    if (mode == ENCRYPT) {
        encrypt_file_content(cipher, buffer, bytes_read); // Assume this function handles encryption
    } else if (mode == DECRYPT) {
        decrypt_file_content(cipher, buffer, bytes_read); // Assume this function handles decryption
    }

    // Write processed content back to file
    fseek(file, 0, SEEK_SET);
    size_t bytes_written = fwrite(buffer, 1, bytes_read, file);
    if (bytes_written != bytes_read) {
        free_cipher(cipher);
        free(buffer);
        fclose(file);
        if (error_mode == VERBOSE) {
            fprintf(stderr, "Failed to write file\n");
        }
        return NULL;
    }

    // Free resources
    free(buffer);
    fclose(file);

    return cipher;
}
