#include "logging_library.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->count = 0;
    array->capacity = initial_capacity;
    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array->elements) free(array->elements);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element_to_array(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int load_resource_bundle(const char *path, size_t *item_count) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    // Assume the file contains one item per line
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    char *buffer = (char*)malloc(file_size + 1);
    if (!buffer) {
        fclose(file);
        return -1;
    }

    fread(buffer, 1, file_size, file);
    buffer[file_size] = '\0';
    fclose(file);

    // Count items
    *item_count = 1; // Simplified for demonstration
    free(buffer);
    return 0;
}

void* get_certificate_from_oauth_request(const char *oauth_request) {
    // Assume the OAuth request specifies the private key and certificate locations
    const char *private_key_path = oauth_request; // Example path
    const char *certificate_path = oauth_request; // Example path

    FILE *key_file = fopen(private_key_path, "r");
    if (!key_file) return NULL;

    FILE *cert_file = fopen(certificate_path, "r");
    if (!cert_file) {
        fclose(key_file);
        return NULL;
    }

    // Combine key and certificate into a single PEM file
    char *pem_buffer = (char*)malloc(1024); // Example buffer size
    if (!pem_buffer) {
        fclose(key_file);
        fclose(cert_file);
        return NULL;
    }

    fread(pem_buffer, 1, 1024, key_file);
    fclose(key_file);

    fseek(cert_file, 0, SEEK_END);
    size_t cert_size = ftell(cert_file);
    rewind(cert_file);

    fread(pem_buffer + 1024 - cert_size, 1, cert_size, cert_file);
    fclose(cert_file);

    pem_buffer[1024] = '\0'; // Null-terminate the buffer

    return pem_buffer;
}
