#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>

#define BUFFER_SIZE 4096

void print_usage() {
    printf("Usage: %s [options] input_file\n", argv[0]);
    printf("Options:\n");
    printf("  --manpage        Print detailed usage information\n");
    printf("  -cs              Compress output lines using a simple algorithm\n");
    printf("  -o output_file   Redirect output to a specified file instead of stdout\n");
    printf("  -l limit_lines   Limit the number of lines processed from the input file\n");
}

void log_error(const char *message, int code) {
    fprintf(stderr, "Error: %s (code: %d)\n", message, code);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    // Parse command line arguments
    char *input_file = argv[1];
    int compress_output = 0;
    const char *output_file = NULL;
    long limit_lines = -1;

    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-cs") == 0) {
            compress_output = 1;
        } else if (strncmp(argv[i], "-o ", 3) == 0) {
            output_file = argv[i] + 3;
        } else if (strncmp(argv[i], "-l ", 3) == 0) {
            limit_lines = atol(argv[i] + 3);
        }
    }

    // Open input file
    FILE *file = fopen(input_file, "r");
    if (!file) {
        log_error("Cannot open input file", EXIT_FAILURE);
        return EXIT_FAILURE;
    }

    // Initialize MD5 hash context
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);

    // Read file line by line
    char buffer[BUFFER_SIZE];
    int line_count = 0;
    while (fgets(buffer, BUFFER_SIZE, file) != NULL) {
        line_count++;
        if (limit_lines >= 0 && line_count > limit_lines) {
            break;
        }
        MD5_Update(&md5_ctx, buffer, strlen(buffer));
    }

    // Finalize MD5 hash
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &md5_ctx);

    // Print number of lines and MD5 hash
    printf("Number of lines: %d\n", line_count);
    printf("MD5 Hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", digest[i]);
    }
    printf("\n");

    // Close input file
    fclose(file);

    return EXIT_SUCCESS;
}
