        // Handle error
        return NULL;
    }

    NIC_STATS* nic_stats = initialize_nic_stats(num_resource_items);
    if (nic_stats == NULL) {
        free_resource_bundle(resource_items);
        free_state_object(state_items);
        // Handle error
        return NULL;
    }

    for (int i = 0; i < num_resource_items; i++) {
        strcpy(nic_stats[i].interface_name, resource_items[i].name);
        nic_stats[i].packet_counter = state_items[i].value;
        nic_stats[i].error_rate = (double)rand() / RAND_MAX;
        nic_stats[i].byte_count = rand() % 1000000000;
        nic_stats[i].latency = ((double)rand() / RAND_MAX) * 1000; // in milliseconds
    }

    free_resource_bundle(resource_items);
    free_state_object(state_items);

    return nic_stats;
}

void free_nic_stats(NIC_STATS* stats, int num_interfaces) {
