void log_statistics(int success, double processing_time, size_t memory_usage, size_t peak_memory) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        char time_str[80];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "[%s] - Success: %s, Time: %.2f seconds, Memory Usage: %zu bytes, Peak Memory: %zu bytes\n",
                time_str, success ? "Yes" : "No", processing_time, memory_usage, peak_memory);
        fclose(log_file);
    }
}

void process_file(const char* input_file, const char* output_file, int limit_lines, int compress_output) {
    FILE* file = fopen(input_file, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", input_file);
        return;
    }

    clock_t start_time = clock();
    size_t memory_usage = 0, peak_memory = 0;

    char line[MAX_LINE_LENGTH];
    int line_count = 0;
    while (fgets(line, sizeof(line), file) != NULL && (limit_lines == -1 || line_count < limit_lines)) {
        if (compress_output) {
            size_t output_length = 0;
            char* compressed_line = compress_string(line, &output_length);
            if (compressed_line != NULL) {
                // Write compressed line to output
                free(compressed_line);
            }
        } else {
            // Write original line to output
        }

        memory_usage += strlen(line);
        peak_memory = (memory_usage > peak_memory) ? memory_usage : peak_memory;
        line_count++;
    }

    clock_t end_time = clock();
    double processing_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    fclose(file);

    log_statistics(1, processing_time, memory_usage, peak_memory);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_manpage();
        return 0;
    }

    const char* input_file = NULL;
    const char* output_file = NULL;
    int limit_lines = -1;
    int compress_output = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_manpage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            compress_output = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limit_lines = atoi(argv[++i]);
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (input_file == NULL) {
        fprintf(stderr, "Error: No input file provided.\n");
        print_manpage();
        return 0;
    }

    process_file(input_file, output_file, limit_lines, compress_output);

    return 0;
}
