#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        perror("Failed to allocate memory for DynamicArray");
        return NULL;
    }
    array->elements = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->elements == NULL) {
        perror("Failed to allocate memory for elements");
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->elements);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_elements == NULL) {
            perror("Failed to reallocate memory for elements");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }
    array->elements[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int load_resource_bundle(const char* path, NFAPI_CRC_INDICATION_PDU_T** bundle) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        perror("Failed to open resource bundle file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    NFAPI_CRC_INDICATION_PDU_T* temp_bundle = malloc(file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp_bundle == NULL) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return -1;
    }

    size_t count = fread(temp_bundle, sizeof(NFAPI_CRC_INDICATION_PDU_T), file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    if (count != file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Failed to read resource bundle");
        free(temp_bundle);
        fclose(file);
        return -1;
    }

    *bundle = temp_bundle;
    fclose(file);
    return count;
}

int main() {
    DynamicArray* array = create_dynamic_array();
    if (array == NULL) {
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T element;
    element.RX_UE_INFORMATION_TAG = 12345;
    element.RNTI = 67890;
    srand(time(NULL));
    element.CRC_INDICATION_REL8_TAG = rand() % 2;

    if (add_element(array, element) != 0) {
        destroy_dynamic_array(array);
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* bundle;
    int count = load_resource_bundle("path_to_resource_file", &bundle);
    if (count < 0) {
        destroy_dynamic_array(array);
        return 1;
    }

    // Process the bundle...

    free(bundle);
    destroy_dynamic_array(array);

    return 0;
}
