    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ThreadSafeDynamicArray;

ThreadSafeDynamicArray* createThreadSafeDynamicArray(size_t initialCapacity) {
    ThreadSafeDynamicArray* array = (ThreadSafeDynamicArray*)malloc(sizeof(ThreadSafeDynamicArray));
    if (array == NULL) {
        // Log memory allocation failure
        return NULL;
    }

    array->array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (array->array == NULL) {
        // Log memory allocation failure and free the allocated structure
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroyThreadSafeDynamicArray(ThreadSafeDynamicArray* array) {
    if (array == NULL || array->array == NULL) {
        return;
    }

    for (size_t i = 0; i < array->count; ++i) {
        free(array->array[i]);
    }

    pthread_mutex_destroy(&array->lock);
    free(array->array);
    free(array);
}

void* getEvent(ThreadSafeDynamicArray* array, size_t index) {
    if (array == NULL || array->array == NULL || index >= array->count) {
        // Log invalid access
        return NULL;
    }

    pthread_mutex_lock(&array->lock);
    NFAPI_CRC_INDICATION_PDU_T* event = array->array[index];
    pthread_mutex_unlock(&array->lock);

    return event;
}

void addEvent(ThreadSafeDynamicArray* array, NFAPI_CRC_INDICATION_PDU_T* event) {
    if (array == NULL || array->array == NULL || event == NULL) {
        // Log invalid access
        return;
    }

    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** newArray = (NFAPI_CRC_INDICATION_PDU_T**)realloc(array->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (newArray == NULL) {
            // Log memory allocation failure
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->array = newArray;
        array->capacity = newCapacity;
    }

    array->array[array->count++] = event;
    pthread_mutex_unlock(&array->lock);
}

