typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} ThreadSafeNFAPIArray;

int initializeThreadSafeNFAPIArray(ThreadSafeNFAPIArray* array, size_t initial_capacity) {
    array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->array == NULL) {
        return -1; // Memory allocation failed
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

void destroyThreadSafeNFAPIArray(ThreadSafeNFAPIArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

int addElementToNFAPIArray(ThreadSafeNFAPIArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory reallocation failed
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int loadResourceBundle(const char* path, void** bundle) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        return -1; // File open failed
    }
    fseek(file, 0, SEEK_END);
    size_t length = ftell(file);
    fseek(file, 0, SEEK_SET);

    void* memory = malloc(length + 1);
    if (memory == NULL) {
        fclose(file);
        return -2; // Memory allocation failed
    }

    fread(memory, 1, length, file);
    fclose(file);

    ((char*)memory)[length] = '\0'; // Null-terminate the string

    *bundle = memory;
    return length;
}
