import hashlib
import os
import logging

logging.basicConfig(level=logging.DEBUG)

def calculate_md5(file_path, chunk_size=1024*1024, temp_dir='./temp_md5', reference_hash=None):
    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)

    def hash_chunk(chunk):
        return hashlib.md5(chunk).hexdigest()

    def merge_hashes(hashes):
        merged_hash = hashlib.md5()
        for h in hashes:
            merged_hash.update(bytes.fromhex(h))
        return merged_hash.hexdigest()

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    file_size = os.path.getsize(file_path)
    num_chunks = (file_size + chunk_size - 1) // chunk_size

    temp_hashes = []
    for i in range(num_chunks):
        with open(file_path, 'rb') as f:
            f.seek(i * chunk_size)
            chunk = f.read(chunk_size)
            if not chunk:
                break
            hash_value = hash_chunk(chunk)
            temp_hashes.append(hash_value)

    final_hash = merge_hashes(temp_hashes)

    if reference_hash and reference_hash != final_hash:
        raise ValueError(f"Hash mismatch: Expected {reference_hash}, got {final_hash}")

    return final_hash
```

This code defines a function `calculate_md5` that calculates the MD5 hash of a large file. It reads the file in fixed-size chunks, computes the hash for each chunk, and stores the intermediate hashes on disk. If provided, it also verifies the final hash against a reference hash value. The function handles interruptions by storing partial progress in temporary files and merging them upon completion.']

