#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define a structure for sensor telemetry events
typedef struct {
    int device_id;
    time_t timestamp;
    char sensor_type[50];
    double reading_value;
    char *metadata_units; // Optional metadata
    int quality_indicator; // Quality indicator (e.g., 1 - good, 2 - bad)
    void *binary_data_payload; // Optional binary data payload
} SensorEvent;

// Define a structure for the dynamic array of sensor events
typedef struct {
    SensorEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} EventArray;

// Initialize the event array with initial capacity
void init_event_array(EventArray *array, size_t initial_capacity) {
    array->events = (SensorEvent *)malloc(initial_capacity * sizeof(SensorEvent));
    if (!array->events) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

// Resize the event array when capacity is exceeded
void resize_event_array(EventArray *array) {
    size_t new_capacity = array->capacity * 2;
    SensorEvent *new_events = (SensorEvent *)realloc(array->events, new_capacity * sizeof(SensorEvent));
    if (!new_events) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    array->events = new_events;
    array->capacity = new_capacity;
}

// Add a sensor event to the dynamic array
void add_sensor_event(EventArray *array, SensorEvent event) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        resize_event_array(array);
    }
    array->events[array->size++] = event;
    pthread_mutex_unlock(&array->lock);
}

// Periodically clean up old events
void cleanup_old_events(EventArray *array, time_t max_age) {
    pthread_mutex_lock(&array->lock);
    size_t i = 0;
    while (i < array->size) {
        if ((time(NULL) - array->events[i].timestamp) > max_age) {
            // Log the event being removed
            printf("Removing old event with timestamp: %ld\n", array->events[i].timestamp);
            // Remove the event from the array
            memmove(&array->events[i], &array->events[i + 1], (array->size - i - 1) * sizeof(SensorEvent));
            array->size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Clean up resources and free memory
void cleanup_event_array(EventArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->events);
    pthread_mutex_destroy(&array->lock);
}
```

