import hashlib
import os
import tempfile
import logging

def calculate_md5_in_chunks(file_path, chunk_size=64*1024):
    md5 = hashlib.md5()
    try:
        with open(file_path, 'rb') as file:
            for chunk in iter(lambda: file.read(chunk_size), b''):
                md5.update(chunk)
    except IOError as e:
        logging.error(f"Error reading file {file_path}: {e}")
        return None
    return md5.hexdigest()

def write_hash_to_temp_dir(temp_dir, hash_value):
    temp_file = tempfile.NamedTemporaryFile(delete=False, dir=temp_dir)
    try:
        with open(temp_file.name, 'wb') as f:
            f.write(hash_value.encode('utf-8'))
    except IOError as e:
        logging.error(f"Error writing hash to temporary directory: {e}")
        return None
    return temp_file.name

def merge_hashes_from_temp_dir(temp_dir):
    total_hash = hashlib.md5()
    try:
        for filename in os.listdir(temp_dir):
            if filename.endswith('.md5'):
                with open(os.path.join(temp_dir, filename), 'rb') as f:
                    hash_value = f.read().decode('utf-8')
                    total_hash.update(hashlib.md5(hash_value.encode('utf-8')).digest())
    except IOError as e:
        logging.error(f"Error reading hash files from temporary directory: {e}")
        return None
    return total_hash.hexdigest()

def calculate_md5_with_temp_storage(file_path, temp_dir):
    intermediate_hashes = []
    try:
        for chunk in read_file_in_chunks(file_path, chunk_size=64*1024):
            md5_chunk = hashlib.md5(chunk)
            temp_hash_path = write_hash_to_temp_dir(temp_dir, md5_chunk.hexdigest())
            if temp_hash_path:
                intermediate_hashes.append(temp_hash_path)
    except Exception as e:
        logging.error(f"Error processing file: {e}")
        return None
    final_hash = merge_hashes_from_temp_dir(temp_dir)
    for hash_file in intermediate_hashes:
        try:
            os.unlink(hash_file)
        except IOError as e:
            logging.warning(f"Failed to remove temporary hash file {hash_file}: {e}")
    return final_hash

def read_file_in_chunks(file_path, chunk_size=64*1024):
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            yield data
