// Define the custom data structure for sensor telemetry events
typedef struct {
    int device_id;
    time_t timestamp;
    char type[50];
    double reading;
    char metadata[256];
    unsigned char *binary_data;
    size_t binary_size;
} SensorEvent;

// Define the dynamic array management structure
typedef struct {
    SensorEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventArray;

// Function to initialize the event array
void init_event_array(EventArray *array) {
    array->count = 0;
    array->capacity = 16; // Initial capacity
    array->events = (SensorEvent *)malloc(array->capacity * sizeof(SensorEvent));
    if (!array->events) {
        fprintf(stderr, "Memory allocation failed for event array\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

// Function to add a sensor event to the dynamic array
void add_sensor_event(EventArray *array, SensorEvent *event) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        // Resize the array dynamically
        size_t new_capacity = array->capacity * 2;
        SensorEvent *new_events = (SensorEvent *)realloc(array->events, new_capacity * sizeof(SensorEvent));
        if (!new_events) {
            fprintf(stderr, "Memory allocation failed for resizing event array\n");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }
    memcpy(&array->events[array->count], event, sizeof(SensorEvent));
    array->count++;
    pthread_mutex_unlock(&array->lock);
}

// Function to clean up old events
void cleanup_old_events(EventArray *array, time_t cutoff) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ) {
        if (array->events[i].timestamp < cutoff) {
            // Free binary data and remove the event
            free(array->events[i].binary_data);
            memmove(&array->events[i], &array->events[i + 1], (array->count - i - 1) * sizeof(SensorEvent));
            array->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to log event processing details
void log_event_processing(SensorEvent *event, int status) {
    time_t now = time(NULL);
    printf("Event ID: %d, Timestamp: %s, Type: %s, Reading: %.2f, Status: %s\n",
           event->device_id, ctime(&now), event->type, event->reading,
           (status == 0) ? "Success" : "Failure");
}

// Function to handle dynamic configuration updates
void update_configuration(EventArray *array, int new_policy) {
    pthread_mutex_lock(&array->lock);
    // Update the configuration policy
    array->capacity = new_policy;
    pthread_mutex_unlock(&array->lock);
}

// Function to implement rate-limiting
int apply_rate_limit(int current_requests, int max_requests_per_second) {
    static time_t last_reset_time = 0;
    static int request_count = 0;

    time_t now = time(NULL);
    if (now != last_reset_time) {
        // Reset the count at each second boundary
        request_count = 1;
        last_reset_time = now;
    } else {
        request_count++;
    }

    if (request_count > max_requests_per_second) {
        return -1; // Rate limit exceeded
    }
    return 0; // Success
}

// Function to implement garbage collection
void perform_garbage_collection(EventArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ) {
        if (array->events[i].binary_data == NULL) {
            memmove(&array->events[i], &array->events[i + 1], (array->count - i - 1) * sizeof(SensorEvent));
            array->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to integrate with external event storage service
void store_event(EventArray *array, SensorEvent *event) {
