int decryptAES_CBC(const unsigned char* ciphertext, size_t ciphertext_len, const unsigned char* key, const unsigned char* iv, unsigned char* plaintext) {
    AES_KEY aes_key;
    int padding_length;

    if (AES_set_decrypt_key(key, 128, &aes_key) != 0) return -1; // Handle decryption key setup failure

    memset(plaintext, 0, ciphertext_len); // Initialize plaintext buffer
    AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &aes_key, iv, AES_DECRYPT);

    // Extract padding length and remove it from the plaintext
    padding_length = plaintext[ciphertext_len - 1];
    if (padding_length > ciphertext_len) return -1; // Handle invalid padding
    memcpy(plaintext + ciphertext_len - padding_length, "\0", padding_length);

    return ciphertext_len - padding_length;
}
