int main(int argc, char** argv) {
    std::string apiKey;
    std::vector<std::string> locations;
    std::string displayOptions;
    bool useFile = (argc > 1 && std::string(argv[1]) == "--file");

    loadConfig(apiKey, locations, displayOptions, useFile);

    sqlite3* db;
    int rc = sqlite3_open("weather.db", &db);
    if (rc) {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return 1;
    }

    for (const auto& location : locations) {
        fetchWeatherData(apiKey, location);
        cacheWeatherData(location, "Sample Data");
        saveHistoricalData(db, location, "Sample Data");
    }

    sqlite3_close(db);
    return 0;
}
