#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_STRUCTURES 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t next_index;
} ThreadSafePool;

void init_thread_safe_pool(ThreadSafePool *pool, size_t initial_size) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->pool_size = initial_size;
    pool->next_index = 0;
}

void destroy_thread_safe_pool(ThreadSafePool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structures(ThreadSafePool *pool, size_t N) {
    if (N > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Requested more than %zu structures.\n", MAX_STRUCTURES);
        return NULL;
    }

    pthread_mutex_lock(&pool->mutex);

    if (pool->next_index + N > pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        while (new_size < pool->next_index + N)
            new_size *= 2;

        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = &pool->pool[pool->next_index];
    pool->next_index += N;

    pthread_mutex_unlock(&pool->mutex);

    return result;
}

void populate_structures(NFAPI_CRC_INDICATION_PDU_T *structures, size_t N, unsigned int seed) {
    srand(seed);

    for (size_t i = 0; i < N; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        structures[i].RNTI = (unsigned short)rand();
        structures[i].CRC_INDICATION_REL8_TAG = (unsigned char)(rand() % 2);
    }
}

int main() {
    ThreadSafePool pool;
    init_thread_safe_pool(&pool, 100);

    size_t N = 5000; // Example number of structures
    unsigned int seed = time(NULL); // Use current time as seed for reproducibility

    NFAPI_CRC_INDICATION_PDU_T *structures = allocate_structures(&pool, N);
    if (structures) {
        populate_structures(structures, N, seed);

        // Process the structures...

        destroy_thread_safe_pool(&pool);
    }

    return 0;
}
