    void* metadata; // Example metadata pointer
} PipelineStage;

PipelineStage pipelineStages[MAX_STAGES];
NFAPDU** pduBuffers[MAX_STAGES];
pthread_mutex_t mutexes[MAX_STAGES];

void initializeNFAPipeline(int N, uint32_t seed) {
    if (N > MAX_PDUS || N <= 0) {
        fprintf(stderr, "Invalid number of PDUs. Must be between 1 and %d.\n", MAX_PDUS);
        return;
    }

    srand(seed);

    for (int i = 0; i < MAX_STAGES; i++) {
        pthread_mutex_lock(&mutexes[i]);
        if (pipelineStages[i].metadata == NULL) {
            pipelineStages[i].metadata = malloc(sizeof(PipelineStage));
            if (pipelineStages[i].metadata == NULL) {
                fprintf(stderr, "Failed to allocate memory for stage %d\n", i);
                pthread_mutex_unlock(&mutexes[i]);
                return;
            }
        }

        if (pduBuffers[i] == NULL) {
            pduBuffers[i] = malloc(sizeof(NFAPDU*) * N);
            if (pduBuffers[i] == NULL) {
                fprintf(stderr, "Failed to allocate memory for PDU buffer for stage %d\n", i);
                free(pipelineStages[i].metadata);
                pipelineStages[i].metadata = NULL;
                pthread_mutex_unlock(&mutexes[i]);
                return;
            }
        }

        for (int j = 0; j < N; j++) {
            pduBuffers[i][j] = malloc(sizeof(NFAPDU));
            if (pduBuffers[i][j] == NULL) {
                fprintf(stderr, "Failed to allocate memory for PDU at index %d in stage %d\n", j, i);
                for (int k = 0; k < j; k++) {
                    free(pduBuffers[i][k]);
                }
                free(pduBuffers[i]);
                pipelineStages[i].metadata = NULL;
                pthread_mutex_unlock(&mutexes[i]);
                return;
            }

            pduBuffers[i][j]->RNTI = (uint16_t)rand();
            pduBuffers[i][j]->CRCFLAG = (uint8_t)(rand() % 2);
        }
        pthread_mutex_unlock(&mutexes[i]);
    }

    printf("NFAPipeline initialized with %d PDUs across %d stages.\n", N, MAX_STAGES);
}

void initializeNICStats(int deviceCount) {
    // Implementation for initializing NIC stats
}

int main() {
    uint32_t seed = time(NULL); // Use current time as the seed for reproducibility
    initializeNFAPipeline(5000, seed);
    return 0;
}
