#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_FRAME_INFO {
    int frame_number;
    time_t timestamp;
    struct L1_RX_STATS_TAG *stats;
    size_t stats_count;
} LTE_PHY_RX_FRAME_INFO;

typedef struct L1_RX_STATS_TAG {
    // Define the structure for Layer 1 statistics
} L1_RX_STATS_TAG;

typedef struct ListNode {
    LTE_PHY_RX_FRAME_INFO data;
    struct ListNode *next;
} ListNode;

typedef struct List {
    pthread_mutex_t lock;
    ListNode *head;
    size_t size;
} List;

List* list_init() {
    List *list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

void list_destroy(List *list) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int list_add(List *list, LTE_PHY_RX_FRAME_INFO frame_info) {
    pthread_mutex_lock(&list->lock);
    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Allocation failed
    }
    new_node->data = frame_info;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_update(List *list, int frame_number, LTE_PHY_RX_FRAME_INFO new_frame_info) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current) {
        if (current->data.frame_number == frame_number) {
            current->data = new_frame_info;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Frame not found
}

int list_remove(List *list, int frame_number) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    ListNode *prev = NULL;
    while (current) {
        if (current->data.frame_number == frame_number) {
            if (prev) prev->next = current->next;
            else list->head = current->next;
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Frame not found
}

void list_iterate(List *list, void (*callback)(LTE_PHY_RX_FRAME_INFO)) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
