#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDUS 10000

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *pdus;
    size_t pdu_count;
    pthread_mutex_t lock;
} NFADevicePipeline;

NFADevicePipeline* initializeNFADevicePipeline(size_t N, uint64_t seed) {
    if (N > MAX_PDUS) {
        printf("Error: Maximum number of PDUs per call exceeded.\n");
        return NULL;
    }

    NFADevicePipeline *pipeline = (NFADevicePipeline*)malloc(sizeof(NFADevicePipeline));
    if (!pipeline) {
        printf("Error: Failed to allocate memory for pipeline.\n");
        return NULL;
    }

    pipeline->pdus = realloc(pipeline->pdus, N * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pipeline->pdus) {
        printf("Error: Failed to reallocate memory for PDUs.\n");
        free(pipeline);
        return NULL;
    }

    pipeline->pdu_count = N;
    pthread_mutex_init(&pipeline->lock, NULL);

    srand(seed);

    pthread_mutex_lock(&pipeline->lock);
    for (size_t i = 0; i < N; ++i) {
        pipeline->pdus[i].RX_UE_INFORMATION_TAG = rand();
        pipeline->pdus[i].RNTI = rand() % 65536;
        pipeline->pdus[i].CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&pipeline->lock);

    printf("Success: NFADevicePipeline initialized with %zu PDUs.\n", N);
    return pipeline;
}

void destroyNFADevicePipeline(NFADevicePipeline *pipeline) {
    if (pipeline) {
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline->pdus);
        free(pipeline);
        printf("Success: NFADevicePipeline destroyed.\n");
    }
}
```

