typedef struct {
    void* data;
    size_t size;
    size_t capacity;
} DynamicArray;

void initDynamicArray(DynamicArray* array, size_t initialCapacity) {
    array->data = malloc(initialCapacity * sizeof(void*));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initialCapacity;
}

void resizeDynamicArray(DynamicArray* array, size_t newCapacity) {
    void* newData = realloc(array->data, newCapacity * sizeof(void*));
    if (!newData) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->data = newData;
    array->capacity = newCapacity;
}

void addElement(DynamicArray* array, void* element) {
    if (array->size >= array->capacity) {
        resizeDynamicArray(array, array->capacity * 2);
    }
    array->data[array->size++] = element;
}

PDU* createPDU(int rxTag, int rnti, int crcFlag) {
    PDU* pdu = malloc(sizeof(PDU));
