    int SENDER_ID;
    int RECIPIENT_ID;
    char *MESSAGE_CONTENT;
} CUSTOM_MESSAGE_PDU_T;

typedef struct Node {
    CUSTOM_MESSAGE_PDU_T message;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} MessageList;

void initMessageList(MessageList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int addMessageToQueue(MessageList *list, CUSTOM_MESSAGE_PDU_T message) {
    pthread_mutex_lock(&list->lock);
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    newNode->message = message;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void validateMessageList(MessageList *list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        // Perform checksum validation
        int checksum = current->message.MESSAGE_ID + current->message.SENDER_ID + current->message.RECIPIENT_ID;
        for (int i = 0; current->message.MESSAGE_CONTENT[i] != '\0'; i++) {
            checksum += current->message.MESSAGE_CONTENT[i];
        }
        // Checksum validation logic here
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanupMessageList(MessageList *list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->message.MESSAGE_CONTENT);
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void *processMessageList(void *arg) {
    MessageList *list = (MessageList *)arg;
    while (1) {
        // Process messages from the queue
        CUSTOM_MESSAGE_PDU_T message;
        if (/* Check if there are messages in the queue */) {
            /* Dequeue and process a message */
        }
        pthread_mutex_lock(&list->lock);
        validateMessageList(list);
        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

int main() {
    MessageList list;
    initMessageList(&list);

    // Example usage
    CUSTOM_MESSAGE_PDU_T exampleMessage = {1, 2, 3, "Hello, world!"};
    addMessageToQueue(&list, exampleMessage);

    pthread_t thread;
    pthread_create(&thread, NULL, processMessageList, &list);
    pthread_join(thread, NULL);

    cleanupMessageList(&list);

    return 0;
}
