    storage_devices = (StorageDeviceMetadata**) malloc(MAX_DEVICES * sizeof(StorageDeviceMetadata*));
    nic_stats = (NICStatistics**) malloc(MAX_INTERFACES * sizeof(NICStatistics*));

    if (!storage_devices || !nic_stats) {
        perror("Failed to allocate memory for storage and NIC stats");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_DEVICES; i++) {
        storage_devices[i] = (StorageDeviceMetadata*) malloc(sizeof(StorageDeviceMetadata));
        if (!storage_devices[i]) {
            perror("Failed to allocate memory for storage device metadata");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_INTERFACES; i++) {
        nic_stats[i] = (NICStatistics*) malloc(sizeof(NICStatistics));
        if (!nic_stats[i]) {
            perror("Failed to allocate memory for NIC statistics");
            exit(EXIT_FAILURE);
        }
    }

    num_storage_devices = 0;
    num_nic_stats = 0;
}

void free_storage_and_nic_stats() {
    for (int i = 0; i < num_storage_devices; i++) {
        free(storage_devices[i]);
    }

    for (int i = 0; i < num_nic_stats; i++) {
        free(nic_stats[i]);
    }

    free(storage_devices);
    free(nic_stats);

    storage_devices = NULL;
    nic_stats = NULL;
}

void add_storage_device(const char* name, int device_type) {
    if (num_storage_devices >= MAX_DEVICES) {
        fprintf(stderr, "Maximum number of storage devices reached\n");
        return;
    }

    strcpy(storage_devices[num_storage_devices]->name, name);
    storage_devices[num_storage_devices]->device_type = device_type;
    num_storage_devices++;
}

void add_nic_stats(const char* name, int interface_type) {
    if (num_nic_stats >= MAX_INTERFACES) {
        fprintf(stderr, "Maximum number of NIC interfaces reached\n");
        return;
    }

    strcpy(nic_stats[num_nic_stats]->name, name);
    nic_stats[num_nic_stats]->interface_type = interface_type;
    num_nic_stats++;
}

