#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    LogLevel level;
    char *message;
} LogEntry;

typedef struct {
    LogLevel threshold;
    FILE *outputFile;
    pthread_mutex_t logMutex;
    pthread_cond_t logCond;
    int maxLogsPerSecond;
    int currentLogCount;
    time_t lastFlushTime;
} Logger;

Logger logger = {LOG_INFO, NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 10, 0, 0};

void* logThread(void* arg) {
    while (1) {
        pthread_mutex_lock(&logger.logMutex);
        if (logger.outputFile && logger.currentLogCount > 0) {
            time_t now = time(NULL);
            if (now - logger.lastFlushTime >= 5 || logger.currentLogCount >= 1000) { // Flush every 5 seconds or when 1000 logs are buffered
                fflush(logger.outputFile);
                logger.lastFlushTime = now;
            }
        }
        pthread_cond_wait(&logger.logCond, &logger.logMutex);
    }
    return NULL;
}

void initLogger(const char* configPath) {
    pthread_t logThreadID;
    pthread_create(&logThreadID, NULL, logThread, NULL);

    // Load configuration from file or environment variables
    // For simplicity, we'll use a hardcoded threshold and output file
    logger.threshold = LOG_INFO;
    logger.outputFile = fopen("app.log", "a");
}

void logMessage(LogLevel level, const char* message) {
    if (level >= logger.threshold) {
        pthread_mutex_lock(&logger.logMutex);
        fprintf(logger.outputFile, "[%s] %s\n", getLogLevelString(level), message);
        logger.currentLogCount++;
        pthread_cond_signal(&logger.logCond);
        pthread_mutex_unlock(&logger.logMutex);

        // Limit logs per second
        if (logger.maxLogsPerSecond > 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            long ns = ((long)ts.tv_sec * 1000000000L) + (ts.tv_nsec + 999999999L / logger.maxLogsPerSecond) % 1000000000L;
            ts.tv_sec = ns / 1000000000L;
            ts.tv_nsec = ns % 1000000000L;
            nanosleep(&ts, NULL);
        }
    }
}

void closeLogger() {
    pthread_mutex_lock(&logger.logMutex);
    if (logger.outputFile) {
        fclose(logger.outputFile);
        logger.outputFile = NULL;
    }
    pthread_mutex_unlock(&logger.logMutex);
}

const char* getLogLevelString(LogLevel level) {
    switch (level) {
        case LOG_DEBUG: return "DEBUG";
        case LOG_INFO:  return "INFO";
        case LOG_WARNING: return "WARNING";
        case LOG_ERROR:   return "ERROR";
        default:        return "UNKNOWN";
    }
}
