#include <pthread.h>

// Function prototypes
void generate_key(unsigned char *key, int key_length);
void encrypt_data(const unsigned char *input, unsigned char *output, const unsigned char *key, DES_mode mode);
int main(int argc, char *argv[]);

// Global variables
DES_key_schedule schedule;
unsigned char iv[DES_BLOCK_SIZE];
pthread_mutex_t key_lock;

int main(int argc, char *argv[]) {
    // Initialize the mutex
    pthread_mutex_init(&key_lock, NULL);

    // Check for valid arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file> <mode>\n", argv[0]);
        return 1;
    }

    // Open the file
    FILE *file = fopen(argv[1], "rb");
    if (!file) {
        perror("Failed to open file");
        return 1;
    }

    // Generate a random key and IV
    generate_key(schedule.key, DES_KEY_SIZE);
    RAND_bytes(iv, sizeof(iv));

    // Encrypt the data
    encrypt_data(file, stdout, schedule.key, (DES_mode)atoi(argv[2]));

    // Close the file
    fclose(file);

    // Clean up
    pthread_mutex_destroy(&key_lock);

    return 0;
}

void generate_key(unsigned char *key, int key_length) {
    pthread_mutex_lock(&key_lock);
    RAND_bytes(key, key_length);
    pthread_mutex_unlock(&key_lock);
}

void encrypt_data(const unsigned char *input, unsigned char *output, const unsigned char *key, DES_mode mode) {
    DES_cblock des_key = {0};
    memcpy(des_key, key, sizeof(DES_cblock));

    DES_set_odd_parity(&des_key);
    DES_set_key_checked(&des_key, &schedule);

    switch (mode) {
        case ECB:
            while (*input) {
                DES_ecb_encrypt((DES_cblock *)input, (DES_cblock *)output, &schedule, DES_ENCRYPT);
                input += DES_BLOCK_SIZE;
                output += DES_BLOCK_SIZE;
            }
            break;
        // Implement other modes similarly
    }
}
