    pthread_mutex_lock(&monitor->mutex);
    free(monitor->crc_indication_array);
    free(monitor->nic_stats_array);
    pthread_mutex_unlock(&monitor->mutex);
    pthread_mutex_destroy(&monitor->mutex);
    free(monitor);
}

int add_crc_indication(NetworkMonitor_T* monitor, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&monitor->mutex);
    if (monitor->current_size >= monitor->allocated_size) {
        size_t new_size = (monitor->allocated_size == 0) ? 1 : monitor->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(monitor->crc_indication_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&monitor->mutex);
            return -1; // Memory allocation failure
        }
        monitor->crc_indication_array = new_array;
        monitor->allocated_size = new_size;
    }
    monitor->crc_indication_array[monitor->current_size++] = pdu;
    pthread_mutex_unlock(&monitor->mutex);
    return 0;
}

int add_nic_stats(NetworkMonitor_T* monitor, NIC_STATS_T stats) {
    // Similar to adding CRC indication
    pthread_mutex_lock(&monitor->mutex);
    if (monitor->current_size >= monitor->allocated_size) {
        size_t new_size = (monitor->allocated_size == 0) ? 1 : monitor->allocated_size * 2;
        NIC_STATS_T* new_array = realloc(monitor->nic_stats_array, new_size * sizeof(NIC_STATS_T));
        if (!new_array) {
            pthread_mutex_unlock(&monitor->mutex);
            return -1; // Memory allocation failure
        }
        monitor->nic_stats_array = new_array;
        monitor->allocated_size = new_size;
    }
    monitor->nic_stats_array[monitor->current_size++] = stats;
    pthread_mutex_unlock(&monitor->mutex);
    return 0;
}

