    uint8_t payload[1500]; // Assuming maximum payload size of 1500 bytes for Ethernet frames
    uint16_t sequence_number;
} MAC_PDU_T;

typedef enum {
    IPv4,
    IPv6
} IP_PROTOCOL_T;

typedef struct {
    pthread_mutex_t lock;
    MAC_PDU_T *packets;
    int count;
    int capacity;
    IP_PROTOCOL_T protocol;
} PacketBuffer_T;

PacketBuffer_T* create_packet_buffer(IP_PROTOCOL_T protocol) {
    PacketBuffer_T *buffer = (PacketBuffer_T*)malloc(sizeof(PacketBuffer_T));
    if (!buffer) return NULL;

    buffer->protocol = protocol;
    buffer->packets = (MAC_PDU_T*)calloc(MAX_PACKETS, sizeof(MAC_PDU_T));
    if (!buffer->packets) {
        free(buffer);
        return NULL;
    }

    buffer->count = 0;
    buffer->capacity = MAX_PACKETS;
    pthread_mutex_init(&buffer->lock, NULL);

    return buffer;
}

int add_packet(PacketBuffer_T *buffer, const MAC_PDU_T *packet) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count >= buffer->capacity) {
        int new_capacity = buffer->capacity * 2;
        MAC_PDU_T *new_packets = (MAC_PDU_T*)realloc(buffer->packets, new_capacity * sizeof(MAC_PDU_T));
        if (!new_packets) {
            pthread_mutex_unlock(&buffer->lock);
            return -1; // Allocation failed
        }
        buffer->packets = new_packets;
        buffer->capacity = new_capacity;
    }

    memcpy(&buffer->packets[buffer->count], packet, sizeof(MAC_PDU_T));
    buffer->count++;
    pthread_mutex_unlock(&buffer->lock);
    return 0; // Success
}

void destroy_packet_buffer(PacketBuffer_T *buffer) {
    if (buffer) {
        pthread_mutex_destroy(&buffer->lock);
        free(buffer->packets);
        free(buffer);
    }
}
