#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define RX_UE_INFORMATION_TAG 1
#define RNTI 12345
#define CRCFLAG 0x01

typedef struct nfaapi_crc_indication_pdu_t {
    int rx_ue_information_tag;
    int rnti;
    char crc_indication_rel8_tag[2];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return;

    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void serialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, NFAPI_CRC_INDICATION_PDU_T_SIZE, 1, file);
        current = current->next;
    }

    fclose(file);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
