import logging
from functools import wraps

# Configure logging
logging.basicConfig(level=logging.INFO)

async def async_json_load(file_path):
    try:
        with open(file_path, 'r') as file:
            return await asyncio.to_thread(json.load, file)
    except FileNotFoundError:
        logging.error(f"File not found: {file_path}")
        raise
    except json.JSONDecodeError:
        logging.error(f"Syntax error in JSON file: {file_path}")
        raise

def atomic_update(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        try:
            result = await func(*args, **kwargs)
            logging.info("Atomic update successful")
            return result
        except Exception as e:
            logging.error(f"Atomic update failed: {e}")
            raise
    return wrapper

def monitor_performance(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        start_time = time.time()
        result = await func(*args, **kwargs)
        end_time = time.time()
        logging.info(f"Performance metrics - Response Time: {end_time - start_time}s")
        return result
    return wrapper

@asyncio.coroutine
def load_server_settings(config_file_path):
    config_data = yield from async_json_load(config_file_path)

    # Apply settings to the web server instance here
    for setting, value in config_data.items():
        if setting == 'timeout':
            set_timeout(value)
        elif setting == 'cache_size':
            set_cache_size(value)
        # Handle other settings...

@asyncio.coroutine
def main():
    try:
        yield from load_server_settings('server_config.json')
        logging.info("Server settings loaded successfully")
    except Exception as e:
        logging.error(f"Error loading server settings: {e}")

if __name__ == "__main__":
    asyncio.run(main())
