#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG ue_info_tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void appendNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

void processBatch(LinkedList* list, int batchSize, int retryInterval) {
    while (1) {
        pthread_mutex_lock(&list->lock);
        Node* current = list->head;
        for (int i = 0; i < batchSize && current != NULL; i++) {
            // Process each item in the batch
            printf("Processing: UE %d, RNTI %d, CRCFLAG %d\n", 
                   current->data.ue_info_tag, current->data.RNTI, current->data.CRCFLAG);
            Node* temp = current;
            current = current->next;
            free(temp); // Free the processed node
        }
        list->head = current; // Update head after processing
        pthread_mutex_unlock(&list->lock);

        if (current == NULL) {
            break; // No more nodes to process, exit loop
        }

        // Wait before processing the next batch
        sleep(retryInterval);
    }
}

void* threadFunction(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        // Simulate receiving data and adding to the list
        NFAPI_CRC_INDICATION_PDU_T new_data = { /* Initialize with valid values */ };
        appendNode(list, new_data);
        sleep(1); // Simulate delay between data arrivals
    }
    return NULL;
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    pthread_t threadID;
    if (pthread_create(&threadID, NULL, threadFunction, &list) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(1);
    }

    // Process batches with a configurable size and retry interval
    int batchSize = 10;
    int retryInterval = 2; // in seconds
    processBatch(&list, batchSize, retryInterval);

    pthread_join(threadID, NULL);
    return 0;
}
