    if (ptr == NULL) {
        fprintf(stderr, "%s\n", error_message);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T** create_dynamic_array(uint32_t N, const char* error_message) {
