    for (uint32_t i = 0; i < N; ++i) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), error_message);
        array[i]->RX_UE_INFORMATION_TAG = rand();
        array[i]->RNTI = rand() % 1024;
        array[i]->CRC_INDICATION_REL8_TAG = (rand() & 1) ? 1 : 0;
    }
    return array;
}

void clear_and_free_array(NFAPI_CRC_INDICATION_PDU_T** array, uint32_t N) {
    for (uint32_t i = 0; i < N; ++i) {
