#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024

void displayHelp() {
    printf("Usage: program [options] input_file\n");
    printf("Options:\n");
    printf("  --help         Display this help information\n");
    printf("  -cs [algorithm] Specify compression algorithm (gzip, bzip2)\n");
    printf("  -o [output_file] Redirect output to specified file\n");
    printf("  -l [limit_lines] Limit the number of lines processed\n");
}

void processFile(const char* input_file, const char* output_file, int limit_lines) {
    FILE* infile = fopen(input_file, "r");
    if (infile == NULL) {
        perror("Error opening input file");
        return;
    }

    FILE* outfile = stdout;
    if (output_file != NULL) {
        outfile = fopen(output_file, "w");
        if (outfile == NULL) {
            perror("Error opening output file");
            fclose(infile);
            return;
        }
    }

    char line[MAX_LINE_LENGTH];
    int processed_lines = 0;

    clock_t start_time = clock();
    while (fgets(line, sizeof(line), infile) != NULL && processed_lines < limit_lines) {
        // Process each line here
        fprintf(outfile, "%s", line);
        processed_lines++;
    }
    clock_t end_time = clock();

    fclose(infile);
    if (output_file != NULL) {
        fclose(outfile);
    }

    printf("Processed %d lines in %.2f seconds\n", processed_lines, (double)(end_time - start_time) / CLOCKS_PER_SEC);
}

int main(int argc, char* argv[]) {
    const char* input_file = NULL;
    const char* output_file = NULL;
    const char* compression_algorithm = NULL;
    int limit_lines = INT_MAX;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            displayHelp();
            return 0;
        } else if (strncmp(argv[i], "-cs", 3) == 0 && argv[i][3] != '\0') {
            compression_algorithm = argv[i] + 4;
        } else if (strncmp(argv[i], "-o", 2) == 0 && argv[i][2] != '\0') {
            output_file = argv[i] + 3;
        } else if (strncmp(argv[i], "-l", 2) == 0 && argv[i][2] != '\0') {
            limit_lines = atoi(argv[i] + 3);
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (input_file == NULL) {
        displayHelp();
        return 1;
    }

    processFile(input_file, output_file, limit_lines);

    return 0;
}
