#define MAX_EVENTS 1024
#define LOG_BUFFER_SIZE 512

typedef struct {
    int device_id;
    time_t timestamp;
    char sensor_type[32];
    double sensor_reading;
    char *metadata;
} SensorEvent;

typedef struct {
    SensorEvent *events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
} EventArray;

void init_event_array(EventArray *array) {
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

int add_sensor_event(EventArray *array, SensorEvent event) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_EVENTS) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    array->events[array->count] = malloc(sizeof(SensorEvent));
    if (!array->events[array->count]) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failed
    }
    *array->events[array->count] = event;
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void free_event_array(EventArray *array) {
    for (int i = 0; i < array->count; i++) {
        if (array->events[i]) {
            free(array->events[i]);
        }
    }
    pthread_mutex_destroy(&array->lock);
}

void log_event_processing(int status, double elapsed_time, const char *error) {
    char log_buffer[LOG_BUFFER_SIZE];
    if (status == 0) {
        snprintf(log_buffer, LOG_BUFFER_SIZE, "Event processing successful. Elapsed time: %.2f seconds", elapsed_time);
    } else {
        snprintf(log_buffer, LOG_BUFFER_SIZE, "Event processing failed. Error: %s. Elapsed time: %.2f seconds", error, elapsed_time);
    }
    // Log the buffer to a file or console
}

void *process_events(void *arg) {
    EventArray *array = (EventArray *)arg;
    double start_time = clock();
    for (int i = 0; i < array->count; i++) {
        if (add_sensor_event(array, *array->events[i]) != 0) {
            log_event_processing(-1, (clock() - start_time) / CLOCKS_PER_SEC, "Memory allocation failed");
            break;
        }
    }
    double elapsed_time = (clock() - start_time) / CLOCKS_PER_SEC;
    log_event_processing(0, elapsed_time, NULL);
    return NULL;
}

int main() {
    EventArray array;
    init_event_array(&array);

    // Simulate adding sensor events
    for (int i = 0; i < MAX_EVENTS; i++) {
        SensorEvent event = { .device_id = i, .timestamp = time(NULL), .sensor_type = "Temperature", .sensor_reading = i * 1.5 };
        add_sensor_event(&array, event);
    }

    // Process events in a separate thread
    pthread_t thread;
    pthread_create(&thread, NULL, process_events, &array);
    pthread_join(thread, NULL);

    free_event_array(&array);
    return 0;
}
