#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENT_SIZE 1024

typedef struct {
    int device_id;
    time_t timestamp;
    char sensor_type[50];
    double sensor_value;
    char *metadata_units;
    int quality_indicator;
} TelemetryEvent;

typedef struct {
    TelemetryEvent *events;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicTelemetryArray;

DynamicTelemetryArray* create_dynamic_array(size_t initial_capacity) {
    DynamicTelemetryArray *array = (DynamicTelemetryArray *)malloc(sizeof(DynamicTelemetryArray));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for dynamic array.\n");
        return NULL;
    }

    array->events = (TelemetryEvent *)calloc(initial_capacity, sizeof(TelemetryEvent));
    if (!array->events) {
        free(array);
        fprintf(stderr, "Memory allocation failed for telemetry events.\n");
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicTelemetryArray *array) {
    if (array->events) {
        free(array->events);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_event(DynamicTelemetryArray *array, TelemetryEvent event) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        TelemetryEvent *new_events = (TelemetryEvent *)realloc(array->events, new_capacity * sizeof(TelemetryEvent));
        if (!new_events) {
            pthread_mutex_unlock(&array->lock);
            fprintf(stderr, "Memory reallocation failed for dynamic array.\n");
            return -1;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }

    array->events[array->size++] = event;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to handle other required features such as dynamic configuration updates,
// rate-limiting, garbage collection, and external data integration.

int main() {
    DynamicTelemetryArray *array = create_dynamic_array(10);
    if (array) {
        TelemetryEvent event;
        event.device_id = 12345;
        event.timestamp = time(NULL);
        strcpy(event.sensor_type, "Temperature");
        event.sensor_value = 25.6;
        event.metadata_units = strdup("Celsius");
        event.quality_indicator = 98;

        if (add_event(array, event) == 0) {
            printf("Event added successfully.\n");
        } else {
            printf("Failed to add event.\n");
        }

        destroy_dynamic_array(array);
    }
    return 0;
}
