@log_stats
def calculate_density(quadtree):
    total_events = sum(len(node.events) for node in quadtree.query(((0, 0), (360, 180))))
    return total_events / (DEFAULT_SPATIAL_RESOLUTION * 360 * DEFAULT_SPATIAL_RESOLUTION * 180)

@log_stats
def calculate_avg_distance(quadtree):
    events = [event for node in quadtree.query(((0, 0), (360, 180))) for event in node.events]
    if len(events) < 2:
        return 0
    total_distance = sum(distance(events[i], events[i + 1]) for i in range(len(events) - 1))
    return total_distance / (len(events) - 1)

@log_stats
def calculate_event_frequency(quadtree):
    events_per_hour = defaultdict(int)
    for node in quadtree.query(((0, 0), (360, 180))):
        for event in node.events:
            hour = event[2].replace(minute=0, second=0, microsecond=0)
            events_per_hour[hour] += 1
    return {hour: count / len(quadtree.query(((0, 0), (360, 180)))) for hour, count in events_per_hour.items()}

@log_stats
