#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TX_POWER_REPORT_INFO_TAG;
    int RNTI;
    int CELL_ID;
} TX_POWER_REPORT_PDU_T;

typedef struct {
    TX_POWER_REPORT_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    FILE* log_file;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(TX_POWER_REPORT_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    // Open log file for writing
    array->log_file = fopen("dynamic_array_log.txt", "w");
    if (!array->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        free(array->data);
        free(array);
        return NULL;
    }

    return array;
}

void destroyDynamicArray(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);

    // Free all allocated memory
    free(array->data);
    fclose(array->log_file);
    pthread_mutex_unlock(&array->lock);
    free(array);
}

int insertIntoArray(DynamicArray* array, TX_POWER_REPORT_PDU_T item) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        // Double the capacity
        size_t new_capacity = array->capacity * 2;
        TX_POWER_REPORT_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(TX_POWER_REPORT_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = item;

    // Log insertion operation
    fprintf(array->log_file, "Inserted at index %zu: TX_POWER_REPORT_INFO_TAG=%d, RNTI=%d, CELL_ID=%d\n",
            array->size - 1, item.TX_POWER_REPORT_INFO_TAG, item.RNTI, item.CELL_ID);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int iterateInReverse(DynamicArray* array, int (*callback)(TX_POWER_REPORT_PDU_T)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = array->size - 1; i >= 0; --i) {
        if (!callback(array->data[i])) {
            pthread_mutex_unlock(&array->lock);
            return 0; // Stop iteration
        }
    }

    pthread_mutex_unlock(&array->lock);
    return 1; // Continue iteration
}

// Example callback function to print elements
int printElement(TX_POWER_REPORT_PDU_T item) {
    printf("TX_POWER_REPORT_INFO_TAG=%d, RNTI=%d, CELL_ID=%d\n",
           item.TX_POWER_REPORT_INFO_TAG, item.RNTI, item.CELL_ID);
    return 1; // Continue iteration
}
