#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define BUFFER_SIZE 4096

typedef struct {
    unsigned char *data;
    size_t capacity;
} PrefixLeaf;

typedef struct {
    PrefixLeaf **prefix_leafs;
    size_t capacity;
} DataArray;

typedef struct {
    size_t feature_size;
    size_t num_leaf_nodes;
    DataArray data_array;
} Octree;

void init_octree(Octree *octree, size_t feature_size, size_t num_leaf_nodes) {
    octree->feature_size = feature_size;
    octree->num_leaf_nodes = num_leaf_nodes;
    octree->data_array.capacity = 0;
    octree->data_array.prefix_leafs = NULL;
}

void allocate_memory(Octree *octree, size_t data_capacity) {
    // Allocate memory for prefix leafs and data arrays
    octree->data_array.capacity = data_capacity;
    octree->data_array.prefix_leafs = (PrefixLeaf **)malloc(data_capacity * sizeof(PrefixLeaf *));
}

void update_capacity(Octree *octree, size_t new_capacity) {
    // Update the capacity of the octree if necessary
    if (new_capacity > octree->data_array.capacity) {
        allocate_memory(octree, new_capacity);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] input_file\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    Octree octree;
    init_octree(&octree, 32, 1024);
    allocate_memory(&octree, 512);

    char buffer[BUFFER_SIZE];
    size_t line_count = 0;

    while (fgets(buffer, BUFFER_SIZE, file) != NULL) {
        // Process each line
        line_count++;
        if (line_count == octree.data_array.capacity) {
            update_capacity(&octree, line_count * 2);
        }
        // Allocate memory for prefix leaf and store data
        PrefixLeaf *prefix_leaf = malloc(sizeof(PrefixLeaf));
        prefix_leaf->data = (unsigned char *)malloc(strlen(buffer) + 1);
        strcpy((char *)prefix_leaf->data, buffer);
        octree.data_array.prefix_leafs[line_count - 1] = prefix_leaf;
    }

    fclose(file);

    printf("Processed %zu lines\n", line_count);

    // Free allocated memory
    for (size_t i = 0; i < line_count; i++) {
        free(octree.data_array.prefix_leafs[i]->data);
        free(octree.data_array.prefix_leafs[i]);
    }
    free(octree.data_array.prefix_leafs);

    return EXIT_SUCCESS;
}
