        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            return NULL;
        }

        // Parse line and populate pdu fields

        pthread_mutex_lock(&mutex);
        array[count++] = pdu;
        pthread_mutex_unlock(&mutex);
    }

    fclose(file);
    return NULL;
}

void print_usage() {
    printf("Usage: program [--manpage] -cs <input_file> [-o output_file]\n");
    printf("--manpage: Display help information\n");
    printf("-cs: Specify input file for CRC indication PDU data\n");
    printf("-o: Optional output file to store processed data\n");
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
        switch (opt) {
            case 'c':
                if (strcmp(optarg, "manpage") == 0) {
                    print_usage();
                    return 0;
                } else {
                    printf("Invalid option: %s\n", optarg);
                    return 1;
                }
            case 's':
                pthread_t thread;
                if (pthread_create(&thread, NULL, read_file, optarg)) {
                    fprintf(stderr, "Error creating thread\n");
                    return 1;
                }

                if (pthread_join(thread, NULL)) {
                    fprintf(stderr, "Error joining thread\n");
                    return 1;
                }
                break;
            case 'o':
                // Handle output file
                break;
            default:
                printf("Invalid option: %c\n", optopt);
                print_usage();
                return 1;
        }
    }

    if (count == 0) {
        printf("No data processed\n");
    } else {
        printf("%d lines processed\n", count);
    }

    // Free allocated memory

    pthread_mutex_destroy(&mutex);
    return 0;
}
