    const char *auth_token = NULL;
    const char *output_format = "json";
    int rate_limit_delay = 1000; // milliseconds
    int max_retries = 3;
    int cache_enabled = 1;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--api-endpoint") == 0 && i + 1 < argc) {
            api_endpoint = argv[++i];
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            auth_token = argv[++i];
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            output_format = argv[++i];
        }
    }

    if (!api_endpoint) {
        print_usage();
        return EXIT_FAILURE;
    }

    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

