        headers = curl_slist_append(headers, "Content-Type: application/json");

        if (auth_token) {
            char auth_header[256];
            snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", auth_token);
            headers = curl_slist_append(headers, auth_header);
        }

        for (int attempt = 0; attempt < max_retries; ++attempt) {
            curl_easy_setopt(curl, CURLOPT_URL, api_endpoint);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            if(cache_enabled && /* Check cache and data is fresh */) {
                // Use cached data
                break;
            }

            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
                sleep(rate_limit_delay / 1000);
            } else {
                // Process response and cache data if needed
                break;
            }
        }

        if(res == CURLE_OK) {
            // Output based on format
            if (strcmp(output_format, "json") == 0) {
                /* Output JSON */
            } else if (strcmp(output_format, "csv") == 0) {
                /* Output CSV */
            } else {
                /* Output plain text */
            }
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    return EXIT_SUCCESS;
}
