void initialize_nic_stats(int count) {
    if (count > MAX_NIC_STATS) {
        fprintf(stderr, "Error: Exceeds maximum allowed NIC stats count.\n");
        return;
    }

    pthread_mutex_init(&nic_stats_lock, NULL);
