    nic_stats_array = malloc(count * sizeof(NIC_STATS));
    if (nic_stats_array == NULL) {
        perror("Memory allocation failed for NIC stats array.");
        exit(EXIT_FAILURE);
    }
}

void populate_nic_stats() {
    srand(time(NULL));

    pthread_mutex_lock(&nic_stats_lock);
    for (int i = 0; i < nic_stats_count; ++i) {
        snprintf(nic_stats_array[i].interface_name, sizeof(nic_stats_array[i].interface_name), "eth%d", i);
        nic_stats_array[i].packet_count = rand() % 100000;
        nic_stats_array[i].error_rate = (double)(rand() % 100) / 100.0;
        nic_stats_array[i].latency = (double)(rand() % 1000) / 100.0;
    }
    pthread_mutex_unlock(&nic_stats_lock);
}

void free_nic_stats() {
    if (nic_stats_array != NULL) {
        free(nic_stats_array);
        nic_stats_array = NULL;
    }
    pthread_mutex_destroy(&nic_stats_lock);
}
