typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} ThreadSafeArray;

ThreadSafeArray* create_thread_safe_array() {
    ThreadSafeArray *array = (ThreadSafeArray *)malloc(sizeof(ThreadSafeArray));
    if (!array) {
        perror("Failed to allocate memory for thread-safe array");
        return NULL;
    }
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        perror("Failed to allocate memory for array elements");
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_thread_safe_array(ThreadSafeArray *array) {
    if (!array) {
        return;
    }
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element_to_array(ThreadSafeArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for array elements");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

