NICStats *nicStatsArray = NULL;
int nicCount = 0;
int bufferSize = 0;

pthread_mutex_t statsMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t dataCond = PTHREAD_COND_INITIALIZER;
pthread_cond_t spaceCond = PTHREAD_COND_INITIALIZER;

void initializeNICStats(int maxNICs) {
    if (maxNICs > MAX_NIC_STATS) {
        fprintf(stderr, "Error: Maximum NIC count exceeds limit.\n");
        return;
    }

    nicStatsArray = (NICStats *)malloc(maxNICs * sizeof(NICStats));
    if (!nicStatsArray) {
        fprintf(stderr, "Error: Memory allocation failed for NIC stats array.\n");
        return;
    }
    nicCount = maxNICs;

    srand(time(NULL));

    pthread_mutex_lock(&statsMutex);
    for (int i = 0; i < nicCount; ++i) {
        snprintf(nicStatsArray[i].interfaceName, sizeof(nicStatsArray[i].interfaceName), "eth%d", i);
        nicStatsArray[i].packetCounter = rand() % 1000000;
        nicStatsArray[i].errorRate = (double)(rand() % 100) / 100.0;
    }
    pthread_mutex_unlock(&statsMutex);

    bufferSize = BUFFER_SIZE;
}

void updateNICStats() {
    pthread_mutex_lock(&statsMutex);
    for (int i = 0; i < nicCount; ++i) {
        nicStatsArray[i].packetCounter += rand() % 1000;
        nicStatsArray[i].errorRate = (double)(rand() % 100) / 100.0;
    }
    pthread_mutex_unlock(&statsMutex);
}

void *dataProcessingThread(void *arg) {
    while (1) {
        pthread_mutex_lock(&statsMutex);
        while (bufferSize == 0) {
            pthread_cond_wait(&spaceCond, &statsMutex);
        }

        // Process data here
        bufferSize -= BUFFER_SIZE;
        pthread_cond_signal(&dataCond);

        pthread_mutex_unlock(&statsMutex);

        // Simulate processing time
        sleep(1);
    }
}

int main(int argc, char *argv[]) {
    initializeNICStats(10);

    pthread_t threadId;
    pthread_create(&threadId, NULL, dataProcessingThread, NULL);

    while (1) {
        updateNICStats();
        sleep(5);
    }

    return 0;
}
