        fprintf(stderr, "Error: Maximum number of NICs exceeds limit\n");
        exit(EXIT_FAILURE);
    }

    nic_stats = malloc(max_nics * sizeof(NICStat));
    if (!nic_stats) {
        perror("Failed to allocate memory for NIC statistics");
        exit(EXIT_FAILURE);
    }
    nic_count = max_nics;

    srand(time(NULL)); // Seed the random number generator
}

void* updateNICStats(void* arg) {
    while (1) {
        pthread_mutex_lock(&nic_mutex);
        while (buffer_head == buffer_tail) {
            pthread_cond_wait(&nic_cond, &nic_mutex);
        }

        NICStat nic = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;

        // Update the statistics for the interface
        for (size_t i = 0; i < nic_count; ++i) {
            if (strcmp(nic_stats[i].interface_name, nic.interface_name) == 0) {
                nic_stats[i] = nic;
                break;
            }
        }

        pthread_mutex_unlock(&nic_mutex);
    }
    return NULL;
}

void addNICStat(NICStat nic) {
    pthread_mutex_lock(&nic_mutex);
    buffer[buffer_head] = nic;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    // Signal the update thread that new data is available
    pthread_cond_signal(&nic_cond);

    pthread_mutex_unlock(&nic_mutex);
}

void freeNICStats() {
    if (nic_stats) {
        free(nic_stats);
        nic_stats = NULL;
        nic_count = 0;
    }
}
