                struct timespec delay = {retry_delay / 1000, (retry_delay % 1000) * 1000000};
                nanosleep(&delay, NULL);

                if (send_to_server(list, 50000)) { // Replace with actual function
                    printf("Update successful after retry %d\n", retry_count);
                    free_nfaapi_crc_indication_pdu_list(list, 50000);
                    break;
                }

                retry_delay += jitter_factor * (rand() % retry_delay);
                retry_count++;
