                printf("Update failed after maximum retries\n");
                free_nfaapi_crc_indication_pdu_list(list, 50000);
                break;
            }
        }

        // Sleep for a period before the next update
        struct timespec sleep_time = {10, 0}; // 10 seconds
        nanosleep(&sleep_time, NULL);
    }

    return NULL;
}

