NetworkPerformanceMonitor* init_network_monitor(size_t size) {
    NetworkPerformanceMonitor *monitor = malloc(sizeof(NetworkPerformanceMonitor));
    if (!monitor) return NULL;

    monitor->allocated_size = (size > MAX_INTERFACES) ? size : MAX_INTERFACES;
    monitor->used_size = 0;
    monitor->nis_list = realloc(monitor->nis_list, monitor->allocated_size * sizeof(NetworkInterfaceStatistics));
    if (!monitor->nis_list) {
        free(monitor);
        return NULL;
