void add_to_crc_indication_list(CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->list_size <= list->total_memory_allocated / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Resize the list if necessary
        size_t new_size = list->total_memory_allocated * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->pdu_list, new_size);
        if (new_list == NULL) {
            perror("Failed to reallocate memory for CRC indication list");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->pdu_list = new_list;
        list->total_memory_allocated = new_size;
    }
    list->pdu_list[list->list_size++] = *pdu;
    pthread_mutex_unlock(&list->mutex);
}

