#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TBS_VERSIONS 10
typedef enum { TBS_V1, TBS_V2, TBS_DEFAULT } TbsVersion;

typedef struct {
    int cellID;
    int pdschID;
    int tbsSize;
    TbsVersion version;
} PdschAllocation;

typedef struct {
    PdschAllocation *allocations;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    int debugEnabled;
} PdschManager;

PdschManager* pdsch_manager_init() {
    PdschManager *manager = (PdschManager*)malloc(sizeof(PdschManager));
    if (!manager) return NULL;
    manager->allocations = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->debugEnabled = 0;
    return manager;
}

void pdsch_manager_free(PdschManager *manager) {
    if (manager->allocations) free(manager->allocations);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int pdsch_manager_add(PdschManager *manager, int cellID, int pdschID, int tbsSize, TbsVersion version) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        PdschAllocation *new_allocations = (PdschAllocation*)realloc(manager->allocations, new_capacity * sizeof(PdschAllocation));
        if (!new_allocations) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->allocations = new_allocations;
        manager->capacity = new_capacity;
    }

    int found_duplicate = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->allocations[i].cellID == cellID && manager->allocations[i].pdschID == pdschID) {
            found_duplicate = 1;
            break;
        }
    }

    if (found_duplicate) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Duplicate PDSCH ID
    }

    manager->allocations[manager->count].cellID = cellID;
    manager->allocations[manager->count].pdschID = pdschID;
    manager->allocations[manager->count].tbsSize = tbsSize;
    manager->allocations[manager->count].version = version;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void pdsch_manager_enable_debug(PdschManager *manager) {
    pthread_mutex_lock(&manager->lock);
    manager->debugEnabled = 1;
    pthread_mutex_unlock(&manager->lock);
}

void pdsch_manager_disable_debug(PdschManager *manager) {
    pthread_mutex_lock(&manager->lock);
    manager->debugEnabled = 0;
    pthread_mutex_unlock(&manager->lock);
}
