// Function to fetch and process data asynchronously using cURL
void* fetch_and_process_data(void *params) {
    Config *config = (Config *)params;
    CURL *curl;
    CURLcode res;

    // Initialize a new cURL session
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        // Set the URL for the request
        curl_easy_setopt(curl, CURLOPT_URL, config->server_url);

        // Perform the asynchronous HTTP request
        if(config->async_flag) {
            curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1);
            curl_multi_perform(curl, &res);
        } else {
            res = curl_easy_perform(curl);
        }

        // Check for errors and handle them
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        // Clean up the cURL session
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    // Allocate memory for the result and return it
    return malloc(sizeof(char)); // Placeholder for actual data structure
}

