['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TAGS 1024

typedef struct {
    int tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_TAGS];
    size_t count;
    pthread_mutex_t mutex;
} CRC_ARRAY_MANAGER_T;

CRC_ARRAY_MANAGER_T *create_crc_manager() {
    CRC_ARRAY_MANAGER_T *manager = malloc(sizeof(CRC_ARRAY_MANAGER_T));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

int add_crc_indication(CRC_ARRAY_MANAGER_T *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->tag == pdu->tag) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Tag already exists
        }
    }
    if (manager->count >= MAX_TAGS) {
        pthread_mutex_unlock(&manager->mutex);
        return -2; // Array is full
    }
    manager->array[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int remove_crc_indication(CRC_ARRAY_MANAGER_T *manager, int tag) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->tag == tag) {
            free(manager->array[i]);
            for (; i + 1 < manager->count; ++i) {
                manager->array[i] = manager->array[i + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Tag not found
}

int serialize_crc_array(CRC_ARRAY_MANAGER_T *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        fwrite(manager->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
    return 0;
}

int deserialize_crc_array(CRC_ARRAY_MANAGER_T *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fclose(file);
            return -2;
        }
        fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        add_crc_indication(manager, pdu);
    }

    fclose(file);
    return 0;
}
