['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LTE_TRANSPORT_CONTEXT {
    int id;
    void *PHY_LAYER_STATS;
    void *MAC_LAYER_STATS;
    struct LTE_TRANSPORT_CONTEXT *next;
} LTE_TRANSPORT_CONTEXT_T;

typedef struct TRANSPORT_LIST {
    pthread_mutex_t lock;
    LTE_TRANSPORT_CONTEXT_T *head;
} TRANSPORT_LIST_T;

TRANSPORT_LIST_T transport_list = {PTHREAD_MUTEX_INITIALIZER, NULL};

LTE_TRANSPORT_CONTEXT_T* create_transport_context(int id) {
    LTE_TRANSPORT_CONTEXT_T *new_context = malloc(sizeof(LTE_TRANSPORT_CONTEXT_T));
    if (!new_context) return NULL;
    new_context->id = id;
    new_context->PHY_LAYER_STATS = NULL;
    new_context->MAC_LAYER_STATS = NULL;
    new_context->next = NULL;
    return new_context;
}

int insert_transport_context(int id, void *phy_stats, void *mac_stats) {
    pthread_mutex_lock(&transport_list.lock);
    LTE_TRANSPORT_CONTEXT_T *new_context = create_transport_context(id);
    if (!new_context) {
        pthread_mutex_unlock(&transport_list.lock);
        return -1; // Memory allocation failed
    }

    new_context->PHY_LAYER_STATS = phy_stats;
    new_context->MAC_LAYER_STATS = mac_stats;

    if (transport_list.head == NULL || transport_list.head->id >= id) {
        new_context->next = transport_list.head;
        transport_list.head = new_context;
    } else {
        LTE_TRANSPORT_CONTEXT_T *current = transport_list.head;
        while (current->next != NULL && current->next->id < id) {
            current = current->next;
        }
        new_context->next = current->next;
        current->next = new_context;
    }

    pthread_mutex_unlock(&transport_list.lock);
    return 0; // Success
}

void serialize_transport_list(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    LTE_TRANSPORT_CONTEXT_T *current = transport_list.head;
    while (current != NULL) {
        fwrite(&current->id, sizeof(int), 1, file);
        // Serialize PHY_LAYER_STATS and MAC_LAYER_STATS
        fwrite(current->PHY_LAYER_STATS, sizeof(char), /* size */, file);
        fwrite(current->MAC_LAYER_STATS, sizeof(char), /* size */, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_transport_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    int id;
    while (fread(&id, sizeof(int), 1, file) == 1) {
        // Deserialize PHY_LAYER_STATS and MAC_LAYER_STATS
        void *phy_stats = malloc(/* size */);
        void *mac_stats = malloc(/* size */);
        fread(phy_stats, sizeof(char), /* size */, file);
        fread(mac_stats, sizeof(char), /* size */, file);

        insert_transport_context(id, phy_stats, mac_stats);
    }
    fclose(file);
}
