typedef enum {
    ERROR_NONE,
    ERROR_INVALID_INPUT,
    ERROR_MEMORY_ALLOCATION_FAILED
} ErrorCode;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    pthread_mutex_t mutex;
} NFAPICRCArray;

ErrorCode createNFAPICRCArray(NFAPICRCArray* array, size_t N) {
    if (N == 0 || N > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return ERROR_INVALID_INPUT;
    }

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->array == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    array->size = N;
    pthread_mutex_init(&array->mutex, NULL);

    for (size_t i = 0; i < N; ++i) {
        array->array[i].RX_UE_INFORMATION_TAG = rand();
        array->array[i].RNTI = rand() % 65536;
        array->array[i].CRC_INDICATION_REL8.CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    return ERROR_NONE;
}

void destroyNFAPICRCArray(NFAPICRCArray* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->array);
    array->array = NULL;
    array->size = 0;
}

ErrorCode getNFAPICRCArrayElement(const NFAPICRCArray* array, size_t index, NFAPI_CRC_INDICATION_PDU_T** element) {
    if (index >= array->size) {
        return ERROR_INVALID_INPUT;
    }

    pthread_mutex_lock(&array->mutex);
    *element = &array->array[index];
    pthread_mutex_unlock(&array->mutex);

    return ERROR_NONE;
}
