#define MAX_SERVICE_NAME_LENGTH 128

typedef struct NetworkService {
    char id[MAX_SERVICE_NAME_LENGTH];
    char connection_name[MAX_SERVICE_NAME_LENGTH];
    double bandwidth_usage;
    double error_rate;
    double packet_loss;
    double throughput;
    double latency;
} NetworkService;

typedef struct ServiceMetadata {
    NetworkService *services;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ServiceMetadata;

void init_service_metadata(ServiceMetadata *metadata, size_t initial_capacity) {
    metadata->services = (NetworkService *)malloc(initial_capacity * sizeof(NetworkService));
    if (!metadata->services) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    metadata->count = 0;
    metadata->capacity = initial_capacity;
    pthread_mutex_init(&metadata->mutex, NULL);
}

void add_service(ServiceMetadata *metadata, NetworkService service) {
    pthread_mutex_lock(&metadata->mutex);
    if (metadata->count >= metadata->capacity) {
        size_t new_capacity = metadata->capacity == 0 ? 1 : metadata->capacity * 2;
        NetworkService *new_services = (NetworkService *)realloc(metadata->services, new_capacity * sizeof(NetworkService));
        if (!new_services) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        metadata->services = new_services;
        metadata->capacity = new_capacity;
    }
    memcpy(&metadata->services[metadata->count++], &service, sizeof(NetworkService));
    pthread_mutex_unlock(&metadata->mutex);
}

void update_service_metadata(ServiceMetadata *metadata) {
    // Simulate load test and update service metrics
    for (size_t i = 0; i < metadata->count; ++i) {
        // Update metrics based on simulated load
        metadata->services[i].bandwidth_usage += 0.1;
        metadata->services[i].error_rate += 0.01;
        metadata->services[i].packet_loss += 0.02;
        metadata->services[i].throughput += 0.5;
        metadata->services[i].latency += 1.0;

        // Normalize metrics
        if (metadata->services[i].bandwidth_usage > 100) {
            metadata->services[i].bandwidth_usage = 100;
        }
