typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_init() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void dynamic_array_free(DynamicArray* array) {
    if (array->data) free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int dynamic_array_push(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void dynamic_array_clear(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    if (array->data) free(array->data);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->lock);
}
