// Function to convert hexadecimal string to binary data
unsigned char* hex_to_binary(const char* hex, size_t* out_len) {
    *out_len = strlen(hex) / 2;
    unsigned char* binary = (unsigned char*)malloc(*out_len);
    if (!binary) return NULL;

    for (size_t i = 0; i < *out_len; ++i) {
        sscanf(&hex[i * 2], "%2hhx", &binary[i]);
    }

    return binary;
}

// Function to convert binary data to hexadecimal string
char* binary_to_hex(const unsigned char* binary, size_t len) {
    char* hex = (char*)malloc(len * 2 + 1);
    if (!hex) return NULL;

    for (size_t i = 0; i < len; ++i) {
        sprintf(&hex[i * 2], "%02hhx", binary[i]);
    }
    hex[len * 2] = '\0';

    return hex;
}

// Function to encrypt data using DES ECB mode
int des_ecb_encrypt(const unsigned char* key, size_t key_len,
                     const unsigned char* plaintext, size_t plaintext_len,
                     unsigned char** ciphertext) {
    DES_key_schedule ks;
    if (DES_set_key_checked((const_DES_cblock*)key, &ks)) return -1;

    *ciphertext = (unsigned char*)malloc(plaintext_len);
    if (!*ciphertext) return -2;

    DES_ecb_encrypt((const_DES_cblock*)plaintext, (DES_cblock*)(*ciphertext), &ks, DES_ENCRYPT);

    return 0;
}

// Function to decrypt data using DES ECB mode
int des_ecb_decrypt(const unsigned char* key, size_t key_len,
                     const unsigned char* ciphertext, size_t ciphertext_len,
                     unsigned char** plaintext) {
    DES_key_schedule ks;
    if (DES_set_key_checked((const_DES_cblock*)key, &ks)) return -1;

    *plaintext = (unsigned char*)malloc(ciphertext_len);
    if (!*plaintext) return -2;

    DES_ecb_encrypt((const_DES_cblock*)ciphertext, (DES_cblock*)(*plaintext), &ks, DES_DECRYPT);

    return 0;
}

// Example usage
int main() {
    const char* hex_key = "0123456789abcdef";
    size_t key_len;
    unsigned char* binary_key = hex_to_binary(hex_key, &key_len);
    if (!binary_key) {
        printf("Memory allocation failed\n");
        return 1;
    }

    const unsigned char plaintext[] = "Hello, world!";
    size_t plaintext_len = strlen((char*)plaintext);

    unsigned char* ciphertext;
    if (des_ecb_encrypt(binary_key, key_len, plaintext, plaintext_len, &ciphertext) != 0) {
        printf("Encryption failed\n");
        free(binary_key);
        return 1;
    }

    char* hex_ciphertext = binary_to_hex(ciphertext, plaintext_len);
    if (!hex_ciphertext) {
        printf("Memory allocation failed\n");
        free(binary_key);
        free(ciphertext);
        return 1;
    }

    printf("Ciphertext: %s\n", hex_ciphertext);

    // Decryption
    unsigned char* decrypted_text;
    if (des_ecb_decrypt(binary_key, key_len, ciphertext, plaintext_len, &decrypted_text) != 0) {
        printf("Decryption failed\n");
        free(binary_key);
        free(ciphertext);
        free(hex_ciphertext);
        return 1;
    }

    printf("Decrypted text: %s\n", decrypted_text);

    // Clean up
    free(binary_key);
    free(ciphertext);
    free(hex_ciphertext);
    free(decrypted_text);

    return 0;
}
```

