#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

#define MD5_BLOCK_SIZE 64
#define MAX_FILE_SIZE (1024 * 1024 * 1024) // 1GB

typedef struct {
    unsigned char data[MD5_DIGEST_LENGTH];
} MD5_HASH;

void calculate_md5(const unsigned char *data, size_t length, MD5_HASH *hash) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, length);
    MD5_Final(hash->data, &md5);
}

int read_file_and_hash(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) != 0) {
        perror("Error getting file stats");
        fclose(file);
        return -1;
    }

    size_t file_size = file_stat.st_size;
    if (file_size > MAX_FILE_SIZE) {
        fprintf(stderr, "File is too large\n");
        fclose(file);
        return -1;
    }

    MD5_HASH hash;
    unsigned char buffer[MD5_BLOCK_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        calculate_md5(buffer, bytes_read, &hash);
    }

    fclose(file);

    // Print the MD5 hash
    printf("MD5: %x%x%x%x%x%x%x%x%x%x%x%x\n",
           hash.data[0], hash.data[1], hash.data[2], hash.data[3],
           hash.data[4], hash.data[5], hash.data[6], hash.data[7],
           hash.data[8], hash.data[9], hash.data[10], hash.data[11],
           hash.data[12], hash.data[13], hash.data[14], hash.data[15]);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    const char *filename = argv[1];
    return read_file_and_hash(filename);
}
```

