    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

int add_element_to_array(DynamicArray *arr, const NFAPI_CRC_INDICATION_PDU_T *new_elem) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity ? arr->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Memory allocation failure
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    arr->array[arr->size++] = *new_elem;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void clear_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->mutex);
    arr->size = 0;
    pthread_mutex_unlock(&arr->mutex);
