typedef enum {
    PKCS7_PADDING,
    ANSI_X9_23_PADDING,
    NO_PADDING
} PaddingType;

const EVP_CIPHER *GetCipherWithModes(CipherMode mode, PaddingType padding, int ivLength) {
    if (mode == HybridMode) {
        return EVP_aes_256_gcm();
    } else if (mode == CBC_MODE) {
        switch (padding) {
            case PKCS7_PADDING: return EVP_aes_256_cbc();
            case ANSI_X9_23_PADDING: return EVP_aes_256_cbc();
            case NO_PADDING: return EVP_aes_256_cbc_no_padding();
            default: return NULL;
        }
    } else if (mode == GCM_MODE) {
        switch (padding) {
            case PKCS7_PADDING: return EVP_aes_256_gcm();
            case ANSI_X9_23_PADDING: return EVP_aes_256_gcm();
            case NO_PADDING: return EVP_aes_256_gcm();
            default: return NULL;
        }
    } else if (mode == CTR_MODE) {
        switch (padding) {
            case PKCS7_PADDING: return EVP_aes_256_ctr();
            case ANSI_X9_23_PADDING: return EVP_aes_256_ctr();
            case NO_PADDING: return EVP_aes_256_ctr();
            default: return NULL;
        }
    } else {
        return NULL;
    }
}
