    RRC_NAS_Message rrc_nas_message;
    S1_UPLINK_NAS_TRANSPORT s1_uplink_nas_transport;
    time_t timestamp;
    int status_flag;
} LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T *entries;
    size_t count;
    size_t capacity;
} LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_T;

// Function to initialize the queue
void LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Init(LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_T *queue, size_t initial_capacity) {
    pthread_mutex_init(&queue->mutex, NULL);
    queue->entries = (LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T *)malloc(initial_capacity * sizeof(LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T));
    if (!queue->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    queue->count = 0;
    queue->capacity = initial_capacity;
}

// Function to add an entry to the queue
void LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_AddEntry(LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_T *queue, RRC_NAS_Message *rrc_nas_message, S1_UPLINK_NAS_TRANSPORT *s1_uplink_nas_transport) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->capacity) {
        // Resize the queue
        queue->entries = realloc(queue->entries, queue->capacity * 2 * sizeof(LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T));
        if (!queue->entries) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        queue->capacity *= 2;
    }
    memcpy(&queue->entries[queue->count].rrc_nas_message, rrc_nas_message, sizeof(RRC_NAS_Message));
    memcpy(&queue->entries[queue->count].s1_uplink_nas_transport, s1_uplink_nas_transport, sizeof(S1_UPLINK_NAS_TRANSPORT));
    queue->entries[queue->count].timestamp = time(NULL);
    queue->entries[queue->count].status_flag = 0; // Initialize status flag
    queue->count++;
    pthread_mutex_unlock(&queue->mutex);
}

// Function to free the queue and its contents
void LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Free(LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->mutex);
    free(queue->entries);
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
}

// Example usage
int main() {
    LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_T queue;
    LTE_RRC_CU_DOWNLINK_MESSAGE_TRANSFER_PDU_T entry;

    // Initialize the queue
    LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Init(&queue, 100);

    // Populate the queue with entries
    for (int i = 0; i < 100; i++) {
        RRC_NAS_Message rrc_nas_message;
        S1_UPLINK_NAS_TRANSPORT s1_uplink_nas_transport;

        // Initialize and populate rrc_nas_message and s1_uplink_nas_transport
        // ...

        LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_AddEntry(&queue, &rrc_nas_message, &s1_uplink_nas_transport);
    }

    // Free the queue
    LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Free(&queue);

    return 0;
}
```

This code provides a basic framework for a thread-safe queue of LTE RRC messages. The `LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Init` function initializes the queue with a given initial capacity, ensuring that memory allocation is handled efficiently. The `LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_AddEntry` function adds new entries to the queue, resizing it as needed and using thread-safe operations to ensure concurrent access without race conditions. Finally, the `LTE_RRC_CU_DOWNLINK_MESSAGE_QUEUE_Free` function cleans up the allocated memory when it is no longer needed.

