#include <condition_variable>

struct Task {
    // Define the structure for a task
    // ...
};

class WorkerThreadPool {
public:
    WorkerThreadPool(size_t numThreads, bool logEnabled = false) : stop(false), logEnabled(logEnabled) {
        workers.reserve(numThreads);
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] { workerFunc(); });
        }
    }

    ~WorkerThreadPool() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (std::thread& w : workers)
            w.join();
    }

    void addTask(const Task& task) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push(task);
        }
        cv.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<Task> tasks;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop;
    bool logEnabled;

    void workerFunc() {
        while (true) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !tasks.empty() || stop; });
                if (stop && tasks.empty())
                    return;
                task = std::move(tasks.front());
                tasks.pop();
            }
            // Process the task
        }
    }

    void logCPUUsageAndMemory() {
        // Implement CPU usage and memory logging logic
    }
};

// Example usage:
int main() {
    WorkerThreadPool pool(4);
    pool.addTask(Task{ /* initialize task */ });
    return 0;
}
