typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    pthread_mutex_unlock(&array->mutex);
    free(array);
}

void dynamic_array_append(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        array->data = realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->capacity * 2));
        array->capacity *= 2;
    }
    array->data[array->size++] = value;
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_clear(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    array->data = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 100); // Assuming initial capacity of 100
    array->capacity = 100;
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}
