    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populate_crc_indications(int N, NFAPI_CRC_INDICATION_PDU_T** pdus) {
    if (N <= 0 || pdus == NULL) {
        return -1; // Invalid input
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int unique_rnti = 1000; // Start with a base RNTI
    int last_crc_tag = -1;

    for (int i = 0; i < N; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*pdus)[i].RNTI = unique_rnti++;
        do {
            (*pdus)[i].CRC_INDICATION_REL8_TAG = rand() % 10000; // Random CRC tag
        } while ((*pdus)[i].CRC_INDICATION_REL8_TAG == last_crc_tag);
        last_crc_tag = (*pdus)[i].CRC_INDICATION_REL8_TAG;
    }

    return N;
}
