#include <openssl/rand.h>

typedef enum {
    ECB,
    CBC,
    CFB,
    OFB,
    GCM
} CipherMode;

typedef struct {
    EVP_CIPHER *cipher;
    void *key;
    int key_size;
    CipherMode mode;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} EncryptionLibrary;

EncryptionLibrary* create_encryption_library(CipherMode mode, const unsigned char *key, int key_size) {
    EncryptionLibrary *lib = (EncryptionLibrary*)malloc(sizeof(EncryptionLibrary));
    lib->cipher = NULL;
    switch (mode) {
        case ECB: lib->cipher = EVP_aes_256_ecb(); break;
        case CBC: lib->cipher = EVP_aes_256_cbc(); break;
        case CFB: lib->cipher = EVP_aes_256_cfb128(); break;
        case OFB: lib->cipher = EVP_aes_256_ofb(); break;
        case GCM: lib->cipher = EVP_aes_256_gcm(); break;
    }
    if (!lib->cipher) {
        free(lib);
        return NULL;
    }
    lib->mode = mode;
    lib->key_size = key_size;
    lib->key = malloc(key_size);
    memcpy(lib->key, key, key_size);
    if (mode == GCM) {
        lib->iv[0] = 0; // Initialize IV for GCM
    } else {
        if (!RAND_bytes(lib->iv, EVP_CIPHER_iv_length(lib->cipher))) {
            free(lib->key);
            EVP_CIPHER_free(lib->cipher);
            free(lib);
            return NULL;
        }
    }
    return lib;
}

void encrypt(EncryptionLibrary *lib, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, lib->cipher, NULL, lib->key, lib->iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int len;
    if (lib->mode == GCM) {
        EVP_GCM_CTX *gcm_ctx = EVP_CIPHER_CTX_get0_gcmctx(ctx);
        if (!EVP_EncryptInit_ex(gcm_ctx, NULL, NULL, lib->key, lib->iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
    }
    if (plaintext_len > 0) {
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
        ciphertext += len;
    }
    int ciphertext_len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext, &ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(EncryptionLibrary *lib, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, lib->cipher, NULL, lib->key, lib->iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int len;
    if (lib->mode == GCM) {
        EVP_GCM_CTX *gcm_ctx = EVP_CIPHER_CTX_get0_gcmctx(ctx);
        if (!EVP_DecryptInit_ex(gcm_ctx, NULL, NULL, lib->key, lib->iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
    }
    if (ciphertext_len > 0) {
        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
        plaintext += len;
    }
    int plaintext_len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext, &plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    EVP_CIPHER_CTX_free(ctx);
}

void destroy_encryption_library(EncryptionLibrary *lib) {
    free(lib->key);
    EVP_CIPHER_free(lib->cipher);
    free(lib);
}
