#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <openssl/evp.h>

// Function to securely generate an IV for the given cipher mode
void generate_iv(unsigned char *iv, int iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Error generating IV\n");
        exit(EXIT_FAILURE);
    }
}

// Function to encrypt data using the specified cipher and key
int encrypt(const unsigned char *key, int key_len, const unsigned char *iv, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context\n");
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using the specified cipher and key
int decrypt(const unsigned char *key, int key_len, const unsigned char *iv, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error creating cipher context\n");
        return 0;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Function to generate a secure key of the specified length
void generate_key(unsigned char *key, int key_len) {
    if (!RAND_bytes(key, key_len)) {
        fprintf(stderr, "Error generating key\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    unsigned char key[32]; // 256-bit key
    unsigned char iv[16];  // 128-bit IV for AES
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[1024];
    unsigned char decryptedtext[1024];

    generate_key(key, sizeof(key));
    generate_iv(iv, sizeof(iv));

    int len = encrypt(key, sizeof(key), iv, plaintext, strlen((char *)plaintext), ciphertext);
    if (len < 0) {
        fprintf(stderr, "Encryption failed\n");
        return EXIT_FAILURE;
    }

    len = decrypt(key, sizeof(key), iv, ciphertext, len, decryptedtext);
    if (len < 0) {
        fprintf(stderr, "Decryption failed\n");
        return EXIT_FAILURE;
    }

    decryptedtext[len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    return EXIT_SUCCESS;
}
```

This code snippet provides a basic implementation of an encryption library in C using OpenSSL. It includes functions for generating secure IVs, encrypting and decrypting data, and generating secure keys. The example demonstrates AES-256-CBC mode, but the library can be extended to support other modes and key sizes as needed.']

