#include <pthread.h>

#define MAX_SESSIONS 1024
#define SESSION_TOKEN_LENGTH 64

typedef struct {
    char token[SESSION_TOKEN_LENGTH];
    time_t expiration;
    bool active;
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;

pthread_mutex_t session_lock;

void init_sessions() {
    pthread_mutex_init(&session_lock, NULL);
}

Session* create_session(const char* user_id) {
    if (session_count >= MAX_SESSIONS) return NULL;

    Session* new_session = &sessions[session_count];
    new_session->active = true;
    time_t now = time(NULL);
    new_session->expiration = now + 3600; // 1 hour expiration

    SHA256((unsigned char*)user_id, strlen(user_id), (unsigned char*)new_session->token);

    pthread_mutex_lock(&session_lock);
    session_count++;
    pthread_mutex_unlock(&session_lock);

    return new_session;
}

bool validate_session(Session* session) {
    if (!session || !session->active) return false;

    pthread_mutex_lock(&session_lock);
    time_t now = time(NULL);
    if (now >= session->expiration) {
        session->active = false;
    }
    pthread_mutex_unlock(&session_lock);

    return session->active;
}

void* load_balancer_task(void* arg) {
    // Simulate task processing
    sleep(1);
    return NULL;
}

int main() {
    init_sessions();

    Session* session = create_session("user123");
    if (validate_session(session)) {
        printf("Session is valid\n");
    } else {
        printf("Session is invalid\n");
    }

    pthread_t load_balancer_thread;
    pthread_create(&load_balancer_thread, NULL, load_balancer_task, NULL);
    pthread_join(load_balancer_thread, NULL);

    return 0;
}
