class CommandExecutor {
public:
    static std::string executeCommand(const std::vector<std::string>& args) {
        // Validate input arguments for shell injection patterns
        for (const auto& arg : args) {
            if (arg.find_first_of(";|&`*?{}[]()$\\<>!\'\"\\")) != std::string::npos) {
                std::cerr << "Warning: Suspicious characters in argument: " << arg << std::endl;
            }
        }

        // Construct the command string
        std::string command = args[0];
        for (size_t i = 1; i < args.size(); ++i) {
            command += " " + args[i];
        }

        // Execute the command securely and return the output
        std::unique_ptr<char[], void(*)(char*)> buffer(nullptr, free);
        char* result = nullptr;
        int status = system(command.c_str());
        if (status == 0) {
            result = strdup("Command executed successfully");
        } else {
            result = strdup("Command execution failed with status: " + std::to_string(status));
        }
        buffer.reset(result);
        return std::string(buffer.get());
    }
};
