    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", file_path);
        return -1; // File not found or other I/O error
    }

    // Validate file header and version
    char header[256];
    if (fgets(header, sizeof(header), file) == NULL) {
        fprintf(stderr, "Error: Invalid file format\n");
        fclose(file);
        return -2; // Invalid file format
    }
    if (strcmp(header, "COMPONENT_CONFIG_V1\n") != 0) {
        fprintf(stderr, "Error: Unsupported file version\n");
        fclose(file);
        return -3; // Unsupported file version
    }

    int component_count = 0;
    while (component_count < MAX_COMPONENTS && fscanf(file, "%s %d", report->components[component_count].name, &report->components[component_count].init_func) == 2) {
        // Dynamically allocate memory for parameters if needed
        report->components[component_count].params = malloc(sizeof(void*));
        if (!report->components[component_count].params) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            fclose(file);
            return -4; // Memory allocation failure
        }

        // Call initialization function and handle errors
        void* component_instance = ((void* (*)(void*))report->components[component_count].init_func)(report->components[component_count].params);
        if (!component_instance) {
            fprintf(stderr, "Error: Failed to initialize component %s\n", report->components[component_count].name);
            free(report->components[component_count].params);
        } else {
            // Successfully initialized component
            report->components[component_count].init_func = component_instance;
            component_count++;
        }
    }

    fclose(file);
    report->count = component_count;
    return 0; // Success
