    int PACKET_IDENTIFIER;
    time_t TRANSMIT_TIME;
    int CELL_ID;
} TX_CELLULAR_PACKET_T;

typedef struct {
    TX_CELLULAR_PACKET_T *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full;
    pthread_cond_t cond_not_empty;
} PacketManager;

void initPacketManager(PacketManager *pm) {
    pm->capacity = 10; // Initial capacity
    pm->size = 0;
    pm->packets = malloc(pm->capacity * sizeof(TX_CELLULAR_PACKET_T));
    if (!pm->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pm->mutex, NULL);
    pthread_cond_init(&pm->cond_not_full, NULL);
    pthread_cond_init(&pm->cond_not_empty, NULL);
}

void freePacketManager(PacketManager *pm) {
    pthread_mutex_lock(&pm->mutex);
    pthread_cond_broadcast(&pm->cond_not_full); // Wake up all waiting threads
    pthread_cond_broadcast(&pm->cond_not_empty);
    pthread_mutex_unlock(&pm->mutex);

    pthread_mutex_destroy(&pm->mutex);
    pthread_cond_destroy(&pm->cond_not_full);
    pthread_cond_destroy(&pm->cond_not_empty);

    free(pm->packets);
}

int addPacket(PacketManager *pm, TX_CELLULAR_PACKET_T packet) {
    pthread_mutex_lock(&pm->mutex);
    while (pm->size == pm->capacity) {
        pthread_cond_wait(&pm->cond_not_full, &pm->mutex);
    }

    if (pm->size < MAX_PACKETS) {
        pm->packets[pm->size++] = packet;
        pthread_cond_signal(&pm->cond_not_empty);
    } else {
        fprintf(stderr, "PacketManager is full\n");
        pthread_mutex_unlock(&pm->mutex);
        return -1; // Error: PacketManager is full
    }

    pthread_mutex_unlock(&pm->mutex);
    return 0;
}

int removePacket(PacketManager *pm, TX_CELLULAR_PACKET_T *packet) {
    pthread_mutex_lock(&pm->mutex);
    while (pm->size == 0) {
        pthread_cond_wait(&pm->cond_not_empty, &pm->mutex);
    }

    if (pm->size > 0) {
        *packet = pm->packets[--pm->size];
        pthread_cond_signal(&pm->cond_not_full);
    } else {
        fprintf(stderr, "PacketManager is empty\n");
        pthread_mutex_unlock(&pm->mutex);
        return -1; // Error: PacketManager is empty
    }

    pthread_mutex_unlock(&pm->mutex);
    return 0;
}

int resizePacketManager(PacketManager *pm, size_t new_capacity) {
    pthread_mutex_lock(&pm->mutex);
    if (new_capacity > MAX_PACKETS) {
        fprintf(stderr, "New capacity exceeds maximum allowed\n");
        pthread_mutex_unlock(&pm->mutex);
        return -1; // Error: New capacity exceeds maximum allowed
    }

    TX_CELLULAR_PACKET_T *new_packets = realloc(pm->packets, new_capacity * sizeof(TX_CELLULAR_PACKET_T));
    if (!new_packets) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&pm->mutex);
        return -1; // Error: Memory allocation failed
    }

    pm->packets = new_packets;
    pm->capacity = new_capacity;
    pthread_cond_signal(&pm->cond_not_full); // Notify any waiting threads about the change in capacity

    pthread_mutex_unlock(&pm->mutex);
    return 0;
}
```

This code snippet provides a basic implementation of a thread-safe dynamic array for managing `TX_CELLULAR_PACKET_T` structures. It includes functions to initialize, add, remove, and resize the packet manager while ensuring thread safety using mutexes and condition variables. Error handling is included for memory allocation failures and other potential issues. The resize function allows the array to dynamically adjust its size as needed, maintaining performance under varying loads.']

