#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef enum {
    LOW,
    MEDIUM,
    HIGH
} Priority;

typedef struct Task {
    char description[256];
    Priority priority;
    bool status;
    struct Task *next;
} Task;

typedef struct {
    Task *head;
} TaskList;

void initTaskList(TaskList *list) {
    list->head = NULL;
}

void addTask(TaskList *list, const char *description, Priority priority, bool status) {
    Task *newTask = (Task *)malloc(sizeof(Task));
    if (newTask == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    strcpy(newTask->description, description);
    newTask->priority = priority;
    newTask->status = status;
    newTask->next = list->head;
    list->head = newTask;
}

void updateTask(TaskList *list, const char *description, Priority newPriority, bool newStatus) {
    Task *current = list->head;
    while (current != NULL) {
        if (strcmp(current->description, description) == 0) {
            current->priority = newPriority;
            current->status = newStatus;
            return;
        }
        current = current->next;
    }
}

void listTasks(TaskList *list) {
    Task *current = list->head;
    while (current != NULL) {
        printf("Task: %s, Priority: %d, Status: %s\n", current->description, current->priority, current->status ? "Done" : "Pending");
        current = current->next;
    }
}

void serializeTasks(TaskList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    Task *current = list->head;
    while (current != NULL) {
        fwrite(&current->priority, sizeof(Priority), 1, file);
        fwrite(&current->status, sizeof(bool), 1, file);
        size_t len = strlen(current->description);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->description, sizeof(char), len, file);
        current = current->next;
    }

    fclose(file);
}

void deserializeTasks(TaskList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    while (!feof(file)) {
        Priority priority;
        bool status;
        size_t len;

        fread(&priority, sizeof(Priority), 1, file);
        fread(&status, sizeof(bool), 1, file);
        fread(&len, sizeof(size_t), 1, file);

        if (feof(file)) break;

        char *description = (char *)malloc(len + 1);
        if (description == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        fread(description, sizeof(char), len, file);
        description[len] = '\0';

        addTask(list, description, priority, status);
        free(description);
    }

    fclose(file);
}

void freeTasks(TaskList *list) {
    Task *current = list->head;
    while (current != NULL) {
        Task *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
}
