#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_TASKS 1024

typedef enum {
    LOW_PRIORITY,
    MEDIUM_PRIORITY,
    HIGH_PRIORITY
} TaskPriority;

typedef struct {
    char description[256];
    TaskPriority priority;
    bool status;
} Task;

Task* task_list[MAX_TASKS];
int task_count = 0;
pthread_mutex_t lock;

void init_task_manager() {
    pthread_mutex_init(&lock, NULL);
}

void add_task(const char* description, TaskPriority priority) {
    if (task_count >= MAX_TASKS) return; // Handle overflow
    pthread_mutex_lock(&lock);
    task_list[task_count] = (Task*)malloc(sizeof(Task));
    strncpy(task_list[task_count]->description, description, sizeof(task_list[task_count]->description));
    task_list[task_count]->priority = priority;
    task_list[task_count]->status = false;
    task_count++;
    pthread_mutex_unlock(&lock);
}

void update_task(int index, const char* description, TaskPriority priority) {
    if (index < 0 || index >= task_count) return; // Handle invalid index
    pthread_mutex_lock(&lock);
    strncpy(task_list[index]->description, description, sizeof(task_list[index]->description));
    task_list[index]->priority = priority;
    pthread_mutex_unlock(&lock);
}

void list_tasks_by_priority() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < task_count - 1; i++) {
        for (int j = i + 1; j < task_count; j++) {
            if (task_list[i]->priority < task_list[j]->priority) {
                Task* temp = task_list[i];
                task_list[i] = task_list[j];
                task_list[j] = temp;
            }
        }
    }
    for (int i = 0; i < task_count; i++) {
        printf("Task %d: %s, Priority: %d, Status: %d\n", i, task_list[i]->description, task_list[i]->priority, task_list[i]->status);
    }
    pthread_mutex_unlock(&lock);
}

void serialize_tasks(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return; // Handle file open error
    fwrite(&task_count, sizeof(int), 1, file);
    for (int i = 0; i < task_count; i++) {
        fwrite(task_list[i], sizeof(Task), 1, file);
    }
    fclose(file);
}

void deserialize_tasks(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return; // Handle file open error
    int count;
    fread(&count, sizeof(int), 1, file);
    for (int i = 0; i < count && task_count < MAX_TASKS; i++) {
        task_list[task_count] = (Task*)malloc(sizeof(Task));
        fread(task_list[task_count], sizeof(Task), 1, file);
        task_count++;
    }
    fclose(file);
}

void free_task_manager() {
    for (int i = 0; i < task_count; i++) {
        free(task_list[i]);
    }
    pthread_mutex_destroy(&lock);
}
