    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_QUEUE;

NFAPI_CRC_QUEUE* nfapi_crc_queue_create(size_t initial_capacity) {
    NFAPI_CRC_QUEUE *queue = (NFAPI_CRC_QUEUE*)malloc(sizeof(NFAPI_CRC_QUEUE));
    if (!queue) {
        log_error("Memory allocation failed for CRC queue");
        return NULL;
    }

    queue->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->array) {
        log_error("Memory allocation failed for CRC queue array");
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;

    if (pthread_mutex_init(&queue->mutex, NULL) != 0) {
        log_error("Failed to initialize mutex for CRC queue");
        free(queue->array);
        free(queue);
        return NULL;
    }

    return queue;
}

void nfapi_crc_queue_destroy(NFAPI_CRC_QUEUE *queue) {
    if (queue) {
        pthread_mutex_lock(&queue->mutex);
        free(queue->array);
        pthread_mutex_unlock(&queue->mutex);
        pthread_mutex_destroy(&queue->mutex);
        free(queue);
    }
}

int nfapi_crc_queue_push(NFAPI_CRC_QUEUE *queue, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity ? queue->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(queue->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            log_error("Memory allocation failed for resizing CRC queue");
            pthread_mutex_unlock(&queue->mutex);
            return -1;
        }
        queue->array = new_array;
        queue->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &queue->array[queue->size++];
    new_pdu->rx_ue_information_tag = ue_info_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag = generate_random_crc_flag();

    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

int nfapi_crc_queue_pop(NFAPI_CRC_QUEUE *queue, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is empty
    }

    *pdu = &queue->array[queue->size--];

    pthread_mutex_unlock(&queue->mutex);

    return 0;
}

void nfapi_crc_queue_clear(NFAPI_CRC_QUEUE *queue) {
    pthread_mutex_lock(&queue->mutex);
    queue->size = 0;
    pthread_mutex_unlock(&queue->mutex);
}
