    if (manager->devices == NULL) {
        perror("Failed to allocate memory for device instances");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_device(DeviceManager *manager, const NetworkDeviceInstance *new_device) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkDeviceInstance *new_devices = realloc(manager->devices, new_capacity * sizeof(NetworkDeviceInstance));
        if (new_devices == NULL) {
            perror("Failed to reallocate memory for device instances");
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }
        manager->devices = new_devices;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->devices[manager->count], new_device, sizeof(NetworkDeviceInstance));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void destroy_device_manager(DeviceManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->devices);
