#include <pthread.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for dynamic array and mutex
NFAPI_CRC_INDICATION_PDU_T *array = NULL;
int size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the dynamic array
void addElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mutex);
    if (size == 10000) {
        fprintf(stderr, "Array is full\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    array[size++] = *element;
    pthread_mutex_unlock(&mutex);
}

// Function to clear and free all allocated resources
void clearResources() {
    pthread_mutex_lock(&mutex);
    free(array);
    array = NULL;
    size = 0;
    pthread_mutex_unlock(&mutex);
}

// Function to serialize the linked list into a binary file
void serializeLinkedList(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    pthread_mutex_lock(&mutex);
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Function to deserialize the binary file into a linked list
void deserializeLinkedList(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    pthread_mutex_lock(&mutex);
    array = realloc(array, 10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        fclose(file);
        return;
    }
    size_t bytesRead = fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), 10000, file);
    size = (bytesRead < 10000) ? bytesRead : 10000;
    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T element;
    // Initialize element with valid values

    addElement(&element);

    clearResources();

    serializeLinkedList("crc_indication.dat");

    deserializeLinkedList("crc_indication.dat");

    return 0;
}
