    while (1) {
        pthread_mutex_lock(&frames_lock);
        while (frame_count == 0) {
            pthread_cond_wait(&frames_cv, &frames_lock);
        }
        NFAPI_RX_FRAME *frame = frames[--frame_count];
        // Process frame here
        free(frame);
        pthread_mutex_unlock(&frames_lock);
    }
}

int main() {
    pthread_t consumer;
    pthread_create(&consumer, NULL, consumer_thread, NULL);

    for (int i = 0; i < 1000; i++) { // Example loop to simulate multiple frames
        create_and_populate_frames();
        usleep(100); // Simulate time delay between frames
    }

    pthread_join(consumer, NULL);
    return 0;
}
```

This code snippet provides a basic structure for managing and processing NFAPI_RX_FRAME structures in a multi-threaded environment. It includes functions to create and populate frames, manage a producer-consumer pattern using pthreads, and handle synchronization with mutexes and condition variables. The consumer thread waits for new frames and processes them as they become available. This example assumes the existence of helper functions like `get_next_UE_ID()`, `populate_frame_data()`, etc., which should be implemented according to specific requirements.']

