#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t size;
    size_t capacity;
} CRCList;

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void destroy_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle out-of-memory error
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

bool remove_from_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.rnti == data.rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return false;
}

Node* find_in_crc_list(CRCList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void* filter_crc_list(void* arg) {
    // Implement filtering logic here
    return NULL;
}
