#include <stdlib.h>

typedef struct LogEvent {
    time_t timestamp;
    char log_level[10];
    char message[256];
    char filename[256];
    int line_number;
} LogEvent;

LogEvent** processLogFiles(const char* directory, size_t* num_events) {
    DIR *dir;
    struct dirent *ent;
    LogEvent** events = NULL;
    size_t count = 0;

    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (ent->d_type == DT_REG && strstr(ent->d_name, ".log")) {
                char path[256];
                snprintf(path, sizeof(path), "%s/%s", directory, ent->d_name);
                FILE *file = fopen(path, "r");
                if (file) {
                    while (!feof(file)) {
                        LogEvent event;
                        // Parse line into event structure
                        fscanf(file, "%ld %9s %[^\n]", &event.timestamp, event.log_level, event.message);
                        event.filename[0] = '\0';
                        event.line_number = 0;
                        // Add event to dynamic array
                        events = realloc(events, (count + 1) * sizeof(LogEvent*));
                        events[count++] = malloc(sizeof(LogEvent));
                        memcpy(events[count - 1], &event, sizeof(LogEvent));
                    }
                    fclose(file);
                } else {
                    perror("Failed to open log file");
                }
            }
        }
        closedir(dir);
    } else {
        perror("Failed to open directory");
    }

    *num_events = count;
    return events;
}
