from PIL import Image, ImageOps
import os

def optimize_image_compression(directory, target_size=None, quality=85):
    for filename in os.listdir(directory):
        if filename.endswith(('.png', '.jpg', '.jpeg')):
            file_path = os.path.join(directory, filename)
            with Image.open(file_path) as img:
                # Resize image to maintain aspect ratio
                width, height = img.size
                new_width = 800 if width > 800 else width
                new_height = int(new_width * height / width)
                img = img.resize((new_width, new_height), Image.ANTIALIAS)

                # Apply compression
                if target_size:
                    compressed_img = io.BytesIO()
                    while True:
                        img.save(compressed_img, format='JPEG', quality=quality, optimize=True)
                        if compressed_img.tell() < target_size:
                            break
                        quality -= 5
                        if quality < 10:
                            raise ValueError("Cannot achieve target size with given images")
                else:
                    compressed_img = io.BytesIO()
                    img.save(compressed_img, format='JPEG', quality=quality, optimize=True)

                # Save or replace the image
                img.close()
                compressed_img.seek(0)
                with open(file_path, 'wb') as f:
                    f.write(compressed_img.read())
