void* allocate_element() {
    pthread_mutex_lock(&mutex);
    if (size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Handle memory allocation failure
    }
    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Handle memory allocation failure
    }
    dynamic_array[size++] = element;
    pthread_mutex_unlock(&mutex);
    return element;
}

void free_elements() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; i++) {
        free(dynamic_array[i]);
    }
    size = 0;
    pthread_mutex_unlock(&mutex);
}
