typedef struct LTE_UE_CONTEXT {
    void* rrc_connection_setup_response;
    uint64_t stmsi;
    uint64_t guti;
    time_t last_update;
} LTE_UE_CONTEXT;

typedef struct Dynamic_List {
    LTE_UE_CONTEXT** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t condition;
    time_t outdated_threshold;
} Dynamic_List;

Dynamic_List* create_dynamic_list(size_t initial_capacity, time_t outdated_threshold) {
    Dynamic_List* list = (Dynamic_List*)malloc(sizeof(Dynamic_List));
    list->entries = (LTE_UE_CONTEXT**)calloc(initial_capacity, sizeof(LTE_UE_CONTEXT*));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->condition, NULL);
    list->outdated_threshold = outdated_threshold;
    return list;
}

void destroy_dynamic_list(Dynamic_List* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->entries[i]);
    }
    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->condition);
    free(list);
}

void add_ue_context(Dynamic_List* list, void* rrc_connection_setup_response, uint64_t stmsi, uint64_t guti) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->entries = realloc(list->entries, 2 * list->capacity * sizeof(LTE_UE_CONTEXT*));
        list->capacity *= 2;
    }
    LTE_UE_CONTEXT* new_context = (LTE_UE_CONTEXT*)malloc(sizeof(LTE_UE_CONTEXT));
    new_context->rrc_connection_setup_response = rrc_connection_setup_response;
    new_context->stmsi = stmsi;
    new_context->guti = guti;
    new_context->last_update = time(NULL);
    list->entries[list->size++] = new_context;
    pthread_cond_signal(&list->condition);
    pthread_mutex_unlock(&list->mutex);
}

LTE_UE_CONTEXT* get_ue_context_by_stmsi(Dynamic_List* list, uint64_t stmsi) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->stmsi == stmsi) {
            pthread_mutex_unlock(&list->mutex);
            return list->entries[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

LTE_UE_CONTEXT* get_ue_context_by_guti(Dynamic_List* list, uint64_t guti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entries[i]->guti == guti) {
            pthread_mutex_unlock(&list->mutex);
            return list->entries[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void purge_outdated_entries(Dynamic_List* list) {
    pthread_mutex_lock(&list->mutex);
    time_t now = time(NULL);
    for (size_t i = 0; i < list->size;) {
        if (difftime(now, list->entries[i]->last_update) > list->outdated_threshold) {
            free(list->entries[i]);
            for (size_t j = i; j < list->size - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->size;
        } else {
            ++i;
        }
    }
    pthread_cond_signal(&list->condition);
    pthread_mutex_unlock(&list->mutex);
}

