#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_KEYS 100000
#define OPS_PER_SEC 5000000
#define CONCURRENCY 20
#define QUEUE_SIZE 5000

typedef struct {
    char key[256];
    time_t timestamp;
    // other fields...
} KeyValue;

typedef struct {
    KeyValue* data[MAX_KEYS];
    pthread_mutex_t lock;
    int count;
} MY_KEY_VALUE_STORE;

MY_KEY_VALUE_STORE store;

void init_store() {
    memset(&store, 0, sizeof(store));
    pthread_mutex_init(&store.lock, NULL);
}

int add_key_value(const char* key, time_t timestamp) {
    pthread_mutex_lock(&store.lock);
    if (store.count >= MAX_KEYS) {
        pthread_mutex_unlock(&store.lock);
        return -1; // Store full
    }
    KeyValue* kv = malloc(sizeof(KeyValue));
    if (!kv) {
        pthread_mutex_unlock(&store.lock);
        return -2; // Memory allocation failed
    }
    strncpy(kv->key, key, sizeof(kv->key));
    kv->timestamp = timestamp;
    store.data[store.count++] = kv;
    pthread_mutex_unlock(&store.lock);
    return 0;
}

KeyValue* get_key_value(const char* key) {
    pthread_mutex_lock(&store.lock);
    for (int i = 0; i < store.count; i++) {
        if (strcmp(store.data[i]->key, key) == 0) {
            pthread_mutex_unlock(&store.lock);
            return store.data[i];
        }
    }
    pthread_mutex_unlock(&store.lock);
    return NULL;
}

void free_store() {
    for (int i = 0; i < store.count; i++) {
        free(store.data[i]);
    }
    pthread_mutex_destroy(&store.lock);
}

