#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_RNIC_INSTANCES 5000
#define MIN_PAYLOAD_SIZE 100
#define MAX_PAYLOAD_SIZE 1000

typedef struct {
    int type;
    int id;
    char data_tag[256];
    // Add other fields as needed
} LTE_PHY_TRANSPORT_LAYER_MESSAGE_T;

typedef struct {
    LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_PHY_MESSAGE_POOL_T;

LTE_PHY_MESSAGE_POOL_T *lte_phy_message_pool_create() {
    LTE_PHY_MESSAGE_POOL_T *pool = malloc(sizeof(LTE_PHY_MESSAGE_POOL_T));
    if (!pool) return NULL;

    pool->messages = calloc(INITIAL_CAPACITY, sizeof(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T));
    if (!pool->messages) {
        free(pool);
        return NULL;
    }

    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

int lte_phy_message_pool_resize(LTE_PHY_MESSAGE_POOL_T *pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->lock);
    if (new_capacity <= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return 0;
    }

    LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *new_messages = realloc(pool->messages, new_capacity * sizeof(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T));
    if (!new_messages) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->messages = new_messages;
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

int lte_phy_message_pool_add(LTE_PHY_MESSAGE_POOL_T *pool, int type, int id) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity && lte_phy_message_pool_resize(pool, pool->capacity * 2) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *msg = &pool->messages[pool->count++];
    msg->type = type;
    msg->id = id;
    int payload_size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1) + MIN_PAYLOAD_SIZE;
    for (int i = 0; i < payload_size; ++i) {
        msg->data_tag[i] = 'A' + (rand() % 26);
    }
    msg->data_tag[payload_size] = '\0';

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void lte_phy_message_pool_destroy(LTE_PHY_MESSAGE_POOL_T *pool) {
    free(pool->messages);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}
