NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int num_ues) {
    if (num_ues > MAX_UE_INSTANCES) {
        return NULL; // Handle overflow condition
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        return NULL; // Handle memory allocation failure
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < num_ues; i++) {
        pthread_mutex_lock(&mutex);
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = rand() % 4096;
        array[i].CRC_INDICATION_REL8_TAG = i * 2;
        array[i].CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return array;
}
