import hashlib
import os
import tempfile
from concurrent.futures import ThreadPoolExecutor

def calculate_md5(file_path, chunk_size=64*1024, temp_dir=None):
    if temp_dir is None:
        temp_dir = tempfile.mkdtemp()

    # Initialize the MD5 hash object
    md5_hash = hashlib.md5()

    # Process file in chunks
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            md5_hash.update(data)

    return md5_hash.hexdigest()

def hash_files_concurrently(file_paths, chunk_size=64*1024, num_threads=None):
    if num_threads is None:
        num_threads = os.cpu_count()

    results = []
    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = {executor.submit(calculate_md5, file_path, chunk_size): file_path for file_path in file_paths}
        for future in concurrent.futures.as_completed(futures):
            file_path = futures[future]
            try:
                md5_hash = future.result()
                results.append((file_path, md5_hash))
            except Exception as e:
                print(f"Error hashing {file_path}: {e}")

    return results

# Example usage
file_paths = ['path/to/file1', 'path/to/file2']
results = hash_files_concurrently(file_paths)
for file_path, md5_hash in results:
    print(f"{file_path}: {md5_hash}")
```

