int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = ".";
    int limit_frames = -1;
    int compress_keyframes = 0;

    // Parse command line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Usage: %s [options] input_file\n", argv[0]);
            printf("Options:\n");
            printf("  --manpage         Display detailed usage information.\n");
            printf("  -cs                Compress extracted keyframes using a simple algorithm.\n");
            printf("  -o output_file     Redirect output to a specified directory instead of the current working directory.\n");
            printf("  -l limit_frames    Limit the number of frames processed from the input video.\n");
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            compress_keyframes = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limit_frames = atoi(argv[++i]);
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    // Check for input file
    if (input_file == NULL) {
        fprintf(stderr, "Error: No input file specified.\n");
        return 1;
    }

    // Validate input file
    struct stat st;
    if (stat(input_file, &st) != 0 || st.st_size > MAX_FILE_SIZE) {
        fprintf(stderr, "Error: Invalid or too large video file.\n");
        return 2;
    }

    // Initialize AVFormatContext
    AVFormatContext *format_context = NULL;
    if (avformat_open_input(&format_context, input_file, NULL, NULL) != 0) {
        fprintf(stderr, "Error: Could not open video file.\n");
        return 3;
    }

    // Retrieve stream information
    if (avformat_find_stream_info(format_context, NULL) < 0) {
        fprintf(stderr, "Error: Failed to retrieve stream information.\n");
        avformat_close_input(&format_context);
        return 4;
    }

    // Find the first video stream
    int video_stream_index = -1;
    for (unsigned i = 0; i < format_context->nb_streams; ++i) {
        if (format_context->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {
            video_stream_index = i;
            break;
        }
    }

    // Check if a video stream was found
    if (video_stream_index == -1) {
        fprintf(stderr, "Error: No video stream found in the file.\n");
        avformat_close_input(&format_context);
        return 5;
    }

    // Initialize AVCodecContext and open codec
    const AVCodec *codec = avcodec_find_decoder(format_context->streams[video_stream_index]->codecpar->codec_id);
    if (codec == NULL) {
        fprintf(stderr, "Error: Unsupported video codec.\n");
        avformat_close_input(&format_context);
        return 6;
    }

    AVCodecContext *codec_context = avcodec_alloc_context3(codec);
    if (avcodec_parameters_to_context(codec_context, format_context->streams[video_stream_index]->codecpar) < 0) {
        fprintf(stderr, "Error: Could not copy codec parameters to decoder context.\n");
        avcodec_free_context(&codec_context);
        avformat_close_input(&format_context);
        return 7;
    }

    if (avcodec_open2(codec_context, codec, NULL) < 0) {
        fprintf(stderr, "Error: Could not open video codec.\n");
        avcodec_free_context(&codec_context);
        avformat_close_input(&format_context);
        return 8;
    }

    // Allocate memory for frame and packet
    AVFrame *frame = av_frame_alloc();
    if (frame == NULL) {
        fprintf(stderr, "Error: Could not allocate video frame.\n");
        avcodec_free_context(&codec_context);
        avformat_close_input(&format_context);
        return 9;
    }

    AVPacket packet;
    av_init_packet(&packet);

    // Open output directory
    if (mkdir(output_file, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error: Could not create output directory.\n");
        av_frame_free(&frame);
        avcodec_free_context(&codec_context);
        avformat_close_input(&format_context);
        return 10;
    }

    // Process video frames
    int frame_count = 0;
    while (av_read_frame(format_context, &packet) >= 0) {
        if (packet.stream_index == video_stream_index) {
            avcodec_send_packet(codec_context, &packet);
            while (avcodec_receive_frame(codec_context, frame) == 0) {
                // Process keyframe
                if (frame_count % codec_context->framerate.den / codec_context->framerate.num == 0) {
                    // Extract features and save keyframe
                    // ...
                }
                ++frame_count;
                if (limit_frames >= 0 && frame_count >= limit_frames) {
                    break;
                }
            }
        }
        av_packet_unref(&packet);
    }

    // Clean up
    av_frame_free(&frame);
    avcodec_free_context(&codec_context);
    avformat_close_input(&format_context);

    return 0;
}
