#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct ConcurrentHashMap {
    pthread_mutex_t lock;
    ListNode** buckets;
    size_t bucket_count;
} ConcurrentHashMap;

ConcurrentHashMap* create_concurrent_hashmap(size_t bucket_count) {
    ConcurrentHashMap* map = (ConcurrentHashMap*)malloc(sizeof(ConcurrentHashMap));
    if (!map) return NULL;
    map->bucket_count = bucket_count;
    map->buckets = (ListNode**)calloc(bucket_count, sizeof(ListNode*));
    if (!map->buckets) {
        free(map);
        return NULL;
    }
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void destroy_concurrent_hashmap(ConcurrentHashMap* map) {
    for (size_t i = 0; i < map->bucket_count; ++i) {
        ListNode* node = map->buckets[i];
        while (node) {
            ListNode* next = node->next;
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&map->lock);
    free(map->buckets);
    free(map);
}

unsigned hash(int tag, int rnti, size_t bucket_count) {
    return ((tag * 137 + rnti * 241) % bucket_count);
}

bool insert_into_map(ConcurrentHashMap* map, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&map->lock);
    unsigned index = hash(data.RX_UE_INFORMATION_TAG, data.RNTI, map->bucket_count);
    ListNode* node = map->buckets[index];
    while (node) {
        if (node->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG && node->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&map->lock);
            return false; // Duplicate key
        }
        node = node->next;
    }
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&map->lock);
        return false;
    }
    new_node->data = data;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;
    pthread_mutex_unlock(&map->lock);
    return true;
}

// Example usage
int main() {
    ConcurrentHashMap* map = create_concurrent_hashmap(1024);
    if (!map) {
        fprintf(stderr, "Failed to create concurrent hash map\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRCFLAG = true };
    if (insert_into_map(map, pdu)) {
        printf("Successfully inserted into map\n");
    } else {
        printf("Failed to insert into map\n");
    }

    destroy_concurrent_hashmap(map);
    return 0;
}
```

This code snippet defines a concurrent hash map using linked lists for collision resolution and provides functions for creating, destroying, and inserting elements. The `insert_into_map` function ensures that each combination of `RX_UE_INFORMATION_TAG` and `RNTI` is unique within the map. The use of pthread mutexes ensures thread safety during insertion. The example usage demonstrates how to create a hash map, insert an element, and destroy the map when done.']

