void free_crc_list(NFAPI_CRC_LIST *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
}

bool add_crc_pdu(NFAPI_CRC_LIST *list, NFAPI_CRC_INDICATION_PDU pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->pdus = realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!list->pdus) return false;
        list->capacity = new_capacity;
    }

