    if (usedCount < poolSize) {
        LTE_PHY_TRANSPORT_LAYER_MESSAGE_T* message = &memoryPool[usedCount++].message;
        pthread_mutex_unlock(&poolMutex);
        return message;
    } else {
        pthread_mutex_unlock(&poolMutex);
        return NULL; // Memory allocation failed
    }
}

void deallocateMessage(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T* message) {
    pthread_mutex_lock(&poolMutex);
    for (int i = 0; i < poolSize; i++) {
        if (&memoryPool[i].message == message) {
            memoryPool[i] = memoryPool[usedCount - 1];
            usedCount--;
            break;
        }
    }
    pthread_mutex_unlock(&poolMutex);
}

void initializeMemoryPool() {
