#define MAX_STRUCTURES 50000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    time_t creation_time;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array = NULL;

int allocate_and_populate_array(int N) {
    if (N > MAX_STRUCTURES) {
        return -1; // Error: Exceeds maximum allowed structures
    }

    pthread_mutex_lock(&mutex);

    if (array != NULL) {
        free(array);
        array = NULL;
    }

    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // Error: Memory allocation failed
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 1000;
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        array[i].creation_time = time(NULL);
    }

    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

void *periodic_update_thread(void *arg) {
    int N = 50000;
    int retries = 0;
    const int max_retries = 10;
    double backoff_factor = 2.0;

    while (retries < max_retries) {
        if (allocate_and_populate_array(N) == 0) {
            // Update successful, reset retry count
            retries = 0;
        } else {
            retries++;
            // Implement exponential backoff with jitter
            double jitter = rand() / (double)RAND_MAX * (backoff_factor - 1);
            sleep((int)(backoff_factor * (jitter + 1)));
        }
    }

    return NULL;
}

void validate_structures() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (array != NULL && array[i].RNTI == -1) { // Example validation condition
            array[i].RNTI = rand() % 1000; // Correct invalid data
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, periodic_update_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    while (1) {
        validate_structures();
        sleep(60); // Periodic validation every minute
    }

    pthread_join(thread, NULL);
    free(array);

    return 0;
}
