typedef struct LTE_PDCP_SDU_Array_T {
    LTE_PDCP_SDU_T* pdcp_sdu_array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LTE_PDCP_SDU_Array_T;

LTE_PDCP_SDU_Array_T* create_pdcp_sdu_array(size_t initial_capacity) {
    LTE_PDCP_SDU_Array_T* array = (LTE_PDCP_SDU_Array_T*)malloc(sizeof(LTE_PDCP_SDU_Array_T));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->size = 0;
    array->pdcp_sdu_array = (LTE_PDCP_SDU_T*)malloc(initial_capacity * sizeof(LTE_PDCP_SDU_T));
    if (!array->pdcp_sdu_array) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int pdcp_sdu_array_add(LTE_PDCP_SDU_Array_T* array, LTE_PDCP_SDU_T* new_pdcpsdu) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PDCP_SDU_T* new_array = (LTE_PDCP_SDU_T*)realloc(array->pdcp_sdu_array, new_capacity * sizeof(LTE_PDCP_SDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Out of memory
        }
        array->pdcp_sdu_array = new_array;
        array->capacity = new_capacity;
    }

    memcpy(&array->pdcp_sdu_array[array->size], new_pdcpsdu, sizeof(LTE_PDCP_SDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void pdcp_sdu_array_free(LTE_PDCP_SDU_Array_T* array) {
    if (array->pdcp_sdu_array) free(array->pdcp_sdu_array);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
