#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_RNIC_INSTANCES 5000
#define MIN_PAYLOAD_SIZE 100
#define MAX_PAYLOAD_SIZE 1000

typedef struct {
    uint8_t type;
    uint16_t id;
    uint32_t tag;
    uint8_t payload[MIN_PAYLOAD_SIZE];
} LTE_PHY_TRANSPORT_LAYER_MESSAGE_T;

typedef struct {
    LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_MEMORY_POOL_T;

LTE_MEMORY_POOL_T *lte_create_memory_pool(size_t initial_capacity) {
    LTE_MEMORY_POOL_T *pool = (LTE_MEMORY_POOL_T *)malloc(sizeof(LTE_MEMORY_POOL_T));
    if (!pool) return NULL;

    pool->messages = (LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *)calloc(initial_capacity, sizeof(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T));
    if (!pool->messages) {
        free(pool);
        return NULL;
    }

    pool->count = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void lte_destroy_memory_pool(LTE_MEMORY_POOL_T *pool) {
    if (pool) {
        free(pool->messages);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *lte_alloc_message(LTE_MEMORY_POOL_T *pool, uint8_t type, uint16_t id, uint32_t tag, const void *payload, size_t payload_size) {
    if (!pool || payload_size < MIN_PAYLOAD_SIZE || payload_size > MAX_PAYLOAD_SIZE) return NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *new_messages = realloc(pool->messages, new_capacity * sizeof(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T));
        if (!new_messages) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->messages = new_messages;
        pool->capacity = new_capacity;
    }

    LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *msg = &pool->messages[pool->count++];
    msg->type = type;
    msg->id = id;
    msg->tag = tag;
    memcpy(msg->payload, payload, payload_size);
    pthread_mutex_unlock(&pool->lock);

    return msg;
}

void lte_free_message(LTE_MEMORY_POOL_T *pool, LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *msg) {
    if (!pool || !msg) return;

    pthread_mutex_lock(&pool->lock);
    size_t index = msg - pool->messages;
    if (index < pool->count) {
        memmove(&pool->messages[index], &pool->messages[index + 1], (pool->count - index - 1) * sizeof(LTE_PHY_TRANSPORT_LAYER_MESSAGE_T));
        pool->count--;
    }
    pthread_mutex_unlock(&pool->lock);
}

void lte_log_message(const LTE_PHY_TRANSPORT_LAYER_MESSAGE_T *msg) {
    if (!msg) return;

    // Implement logging mechanism here
}
