#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef enum {
    ECB,
    CBC,
    CFB,
    OFB,
    GCM
} CipherMode;

typedef enum {
    KEY_56 = 7,
    KEY_112 = 14,
    KEY_160 = 20,
    KEY_192 = 24,
    KEY_224 = 28,
    KEY_256 = 32
} KeySize;

void generate_secure_iv(unsigned char *iv, size_t iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate secure IV\n");
        exit(EXIT_FAILURE);
    }
}

void encrypt_data(const unsigned char *key, KeySize key_size, CipherMode mode,
                  const unsigned char *plaintext, size_t plaintext_len,
                  unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    int len;
    int ciphertext_len = 0;

    if (mode == GCM) {
        unsigned char tag[EVP_GCM_TLS_TAG_LEN];
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, NULL)) {
            fprintf(stderr, "Failed to initialize GCM encryption\n");
            exit(EXIT_FAILURE);
        }

        unsigned char iv[EVP_CIPHER_BLOCK_SIZE];
        generate_secure_iv(iv, EVP_CIPHER_BLOCK_SIZE);

        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
            fprintf(stderr, "Failed to update GCM encryption\n");
            exit(EXIT_FAILURE);
        }
        ciphertext_len += len;

        if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
            fprintf(stderr, "Failed to finalize GCM encryption\n");
            exit(EXIT_FAILURE);
        }
        ciphertext_len += len;

        if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, EVP_CIPHER_BLOCK_SIZE, NULL) ||
            !EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
            fprintf(stderr, "Failed to set IV for GCM encryption\n");
            exit(EXIT_FAILURE);
        }

        if (!EVP_EncryptUpdate(ctx, NULL, &len, plaintext, 0)) {
            fprintf(stderr, "Failed to update GCM encryption\n");
            exit(EXIT_FAILURE);
        }
        if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, sizeof(tag), tag)) {
            fprintf(stderr, "Failed to get GCM tag\n");
            exit(EXIT_FAILURE);
        }

        memcpy(ciphertext + ciphertext_len, tag, sizeof(tag));
        ciphertext_len += sizeof(tag);
    } else {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL)) {
            fprintf(stderr, "Failed to initialize ECB encryption\n");
            exit(EXIT_FAILURE);
        }

        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
            fprintf(stderr, "Failed to update ECB encryption\n");
            exit(EXIT_FAILURE);
        }
        ciphertext_len += len;

        if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
            fprintf(stderr, "Failed to finalize ECB encryption\n");
            exit(EXIT_FAILURE);
        }
        ciphertext_len += len;
    }

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const unsigned char *key, KeySize key_size, CipherMode mode,
                  const unsigned char *ciphertext, size_t ciphertext_len,
                  unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }

    int len;
    int plaintext_len = 0;

    if (mode == GCM) {
        unsigned char tag[EVP_GCM_TLS_TAG_LEN];
        memcpy(tag, ciphertext + ciphertext_len - sizeof(tag), sizeof(tag));
        ciphertext_len -= sizeof(tag);

        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, NULL)) {
            fprintf(stderr, "Failed to initialize GCM decryption\n");
            exit(EXIT_FAILURE);
        }

        unsigned char iv[EVP_CIPHER_BLOCK_SIZE];
        generate_secure_iv(iv, EVP_CIPHER_BLOCK_SIZE);

        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
            fprintf(stderr, "Failed to update GCM decryption\n");
            exit(EXIT_FAILURE);
        }
        plaintext_len += len;

        if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, EVP_CIPHER_BLOCK_SIZE, NULL) ||
            !EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv)) {
            fprintf(stderr, "Failed to set IV for GCM decryption\n");
            exit(EXIT_FAILURE);
        }

        if (!EVP_DecryptUpdate(ctx, NULL, &len, ciphertext, 0)) {
            fprintf(stderr, "Failed to update GCM decryption\n");
            exit(EXIT_FAILURE);
        }
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, sizeof(tag), tag) != 1 ||
            !EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
            fprintf(stderr, "Decryption failed or tag verification failed\n");
            exit(EXIT_FAILURE);
        }
        plaintext_len += len;
    } else {
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL)) {
            fprintf(stderr, "Failed to initialize ECB decryption\n");
            exit(EXIT_FAILURE);
        }

        if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
            fprintf(stderr, "Failed to update ECB decryption\n");
            exit(EXIT_FAILURE);
        }
        plaintext_len += len;

        if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
            fprintf(stderr, "Decryption failed\n");
            exit(EXIT_FAILURE);
        }
        plaintext_len += len;
    }

    EVP_CIPHER_CTX_free(ctx);
}

void rotate_key(unsigned char *key, KeySize key_size) {
    // Implement secure key rotation logic here
}

void escrow_key(const unsigned char *key, KeySize key_size) {
    // Implement secure key escrow logic here
}

int verify_checksum(const unsigned char *data, size_t data_len) {
    // Implement checksum verification logic here
    return 1; // Return 1 if checksum is valid, otherwise return 0
}

void generate_key(unsigned char *key, KeySize key_size) {
    if (!RAND_bytes(key, key_size)) {
        fprintf(stderr, "Failed to generate secure key\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    unsigned char key[32];
    generate_key(key, KEY_256);

    unsigned char plaintext[] = "This is a secret message";
    size_t plaintext_len = strlen((char *)plaintext);

    unsigned char ciphertext[1024];
