import java.util.concurrent.locks.ReentrantLock;
import redis.clients.jedis.Jedis;
import net.spy.memcached.MemcachedClient;

public class DistributedCachingSystem {
    private Jedis jedis;
    private MemcachedClient memcachedClient;
    private ConcurrentHashMap<String, Object> localCache;
    private ReentrantLock lock = new ReentrantLock();

    public DistributedCachingSystem(String redisUrl, int memcachedPort) {
        this.jedis = new Jedis(redisUrl);
        this.memcachedClient = new MemcachedClient("localhost:" + memcachedPort);
        this.localCache = new ConcurrentHashMap<>();
    }

    public void set(String key, Object value) {
        lock.lock();
        try {
            jedis.set(key.getBytes(), serialize(value));
            memcachedClient.set(key, 3600, serialize(value));
            localCache.put(key, value);
        } finally {
            lock.unlock();
        }
    }

    public Object get(String key) {
        lock.lock();
        try {
            Object result = localCache.get(key);
            if (result == null) {
                byte[] dataFromJedis = jedis.get(key.getBytes());
                if (dataFromJedis != null) {
                    result = deserialize(dataFromJedis);
                    localCache.put(key, result);
                } else {
                    byte[] dataFromMemcached = memcachedClient.get(key);
                    if (dataFromMemcached != null) {
                        result = deserialize(dataFromMemcached);
                        jedis.set(key.getBytes(), serialize(result));
                        localCache.put(key, result);
                    }
                }
            }
            return result;
        } finally {
            lock.unlock();
        }
    }

    public void delete(String key) {
        lock.lock();
        try {
            jedis.del(key.getBytes());
            memcachedClient.delete(key);
            localCache.remove(key);
        } finally {
            lock.unlock();
        }
    }

    private byte[] serialize(Object obj) {
        // Implement serialization logic
        return new byte[0];
    }

    private Object deserialize(byte[] data) {
        // Implement deserialization logic
        return null;
    }

    public void shutdown() {
        jedis.close();
        memcachedClient.shutdown();
    }
}
