#define MAX_CONCURRENT_MODIFICATIONS 10000

typedef struct {
    // Define your structure here
} UL_RX_PDU_TAG;

typedef struct {
    // Define your structure here
} RRC_NAS_PDU;

typedef struct {
    UL_RX_PDU_TAG ul_rx_pdu_tag;
    RRC_NAS_PDU rrc_nas_pdu;
} UL_TXDU_PDU_T;

typedef struct Node {
    UL_TXDU_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    int modifications;
    FILE* log_file;
} PDULIST;

PDULIST* create_pdulist() {
    PDULIST* pdulist = (PDULIST*)malloc(sizeof(PDULIST));
    if (pdulist == NULL) return NULL;
    pdulist->head = NULL;
    pdulist->size = 0;
    pdulist->modifications = 0;
    pdulist->log_file = fopen("pdu_list_log.txt", "w");
    time_t now = time(NULL);
    fprintf(pdulist->log_file, "Log started at %s\n", ctime(&now));
    return pdulist;
}

void free_pdulist(PDULIST* pdulist) {
    Node* current = pdulist->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    fclose(pdulist->log_file);
    free(pdulist);
}

int add_pdu_to_list(PDULIST* pdulist, UL_TXDU_PDU_T pdu) {
    if (pdulist->modifications >= MAX_CONCURRENT_MODIFICATIONS) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return -1;

    new_node->data = pdu;
    new_node->next = pdulist->head;
    pdulist->head = new_node;
    pdulist->size++;

    time_t now = time(NULL);
    fprintf(pdulist->log_file, "Inserted at position 0, size: %zu, modifications: %d, timestamp: %s\n", pdulist->size, pdulist->modifications, ctime(&now));

    pdulist->modifications++;
    return 0;
}

int remove_pdu_from_list(PDULIST* pdulist, size_t index) {
    if (pdulist->modifications >= MAX_CONCURRENT_MODIFICATIONS || index >= pdulist->size) return -1;

    Node* current = pdulist->head;
    Node* previous = NULL;
    for (size_t i = 0; i < index; i++) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL) {
        pdulist->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);

    pdulist->size--;

    time_t now = time(NULL);
    fprintf(pdulist->log_file, "Removed at position %zu, size: %zu, modifications: %d, timestamp: %s\n", index, pdulist->size, pdulist->modifications, ctime(&now));

    pdulist->modifications++;
    return 0;
}

