#define MAX_CONCURRENT_MODIFICATIONS 10000

typedef struct DCI_PDU {
    int tag;
    int fdma;
    int mcs;
    int power_control;
    // 其他字段...
} DCI_PDU;

typedef struct ListElement {
    DCI_PDU pdu;
    struct ListElement* next;
} ListElement;

typedef struct DynamicList {
    ListElement* head;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE* log_file;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    list->capacity = 16; // 初始容量
    pthread_mutex_init(&list->mutex, NULL);

    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);
    char filename[256];
    snprintf(filename, sizeof(filename), "dci_list_log_%04d%02d%02d-%02d%02d%02d.txt", 
             local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
             local_time->tm_hour, local_time->tm_min, local_time->tm_sec);
    list->log_file = fopen(filename, "w");
    if (list->log_file) {
        fprintf(list->log_file, "Dynamic List Log File\n");
    }

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    while (list->head) {
        ListElement* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);

    if (list->log_file) fclose(list->log_file);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int validate_dci_pdu(DCI_PDU* pdu) {
    // 实现验证逻辑...
    return 1; // 返回1表示有效，0表示无效
}

void log_operation(DynamicList* list, const char* operation, size_t position, int result) {
    if (list->log_file) {
        time_t now = time(NULL);
        fprintf(list->log_file, "%s - %s at position %zu - Result: %d\n", 
                ctime(&now), operation, position, result);
    }
}

int insert_dci_pdu(DynamicList* list, size_t position, DCI_PDU* pdu) {
    pthread_mutex_lock(&list->mutex);

    if (position > list->size) {
        log_operation(list, "Insert", position, 0);
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    ListElement* new_element = (ListElement*)malloc(sizeof(ListElement));
    if (!new_element) {
        log_operation(list, "Insert", position, 0);
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }
    new_element->pdu = *pdu;
    new_element->next = NULL;

    if (validate_dci_pdu(&new_element->pdu)) {
        ListElement** prev = &list->head;
        for (size_t i = 0; i < position; ++i) {
            prev = &(*prev)->next;
        }
        new_element->next = *prev;
        *prev = new_element;

        if (position == list->size) {
            list->size++;
        }

        log_operation(list, "Insert", position, 1);
    } else {
        free(new_element);
        log_operation(list, "Insert", position, 0);
    }

    pthread_mutex_unlock(&list->mutex);
    return 1;
}

int delete_dci_pdu(DynamicList* list, size_t position) {
    pthread_mutex_lock(&list->mutex);

    if (position >= list->size) {
        log_operation(list, "Delete", position, 0);
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    ListElement** prev = &list->head;
    for (size_t i = 0; i < position; ++i) {
        prev = &(*prev)->next;
    }
    ListElement* temp = *prev;
    *prev = (*prev)->next;
    free(temp);

    list->size--;

    log_operation(list, "Delete", position, 1);

    pthread_mutex_unlock(&list->mutex);
    return 1;
}
