typedef struct {
    EVP_CIPHER_CTX *ctx;
    int encryption_mode;
} CryptoContext;

int initializeCrypto(CryptoContext *ctx, int mode, const unsigned char *key, int key_len) {
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) return -1;

    switch (mode) {
        case ECB:
            if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_ecb(), NULL, key, NULL) != 1 &&
                EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_ecb(), NULL, key, NULL) != 1) {
                EVP_CIPHER_CTX_free(ctx->ctx);
                return -1;
            }
            break;
        case EDE:
            if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1 &&
                EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
                EVP_CIPHER_CTX_free(ctx->ctx);
                return -1;
            }
            break;
        case EDE3:
            if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_ofb(), NULL, key, NULL) != 1 &&
                EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_ofb(), NULL, key, NULL) != 1) {
                EVP_CIPHER_CTX_free(ctx->ctx);
                return -1;
            }
            break;
        case CFB:
            if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cfb8(), NULL, key, NULL) != 1 &&
                EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cfb8(), NULL, key, NULL) != 1) {
                EVP_CIPHER_CTX_free(ctx->ctx);
                return -1;
            }
            break;
        default:
            EVP_CIPHER_CTX_free(ctx->ctx);
            return -1;
    }

    ctx->encryption_mode = mode;
    return 0;
}

int encryptData(CryptoContext *ctx, const unsigned char *in, int in_len, unsigned char *out) {
    int len;
    if (EVP_EncryptUpdate(ctx->ctx, out, &len, in, in_len) != 1) return -1;
    int final_len = len;
    if (EVP_EncryptFinal_ex(ctx->ctx, out + len, &final_len) != 1) return -1;

    return len + final_len;
}

int decryptData(CryptoContext *ctx, const unsigned char *in, int in_len, unsigned char *out) {
    int len;
    if (EVP_DecryptUpdate(ctx->ctx, out, &len, in, in_len) != 1) return -1;
    int final_len = len;
    if (EVP_DecryptFinal_ex(ctx->ctx, out + len, &final_len) != 1) return -1;

    return len + final_len;
}

void freeCryptoContext(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
}
```

This code provides a basic framework for implementing a cryptographic library in C using OpenSSL. It includes functions to initialize the context, encrypt and decrypt data, and clean up the context. The `initializeCrypto` function sets up the encryption mode based on the provided parameter, and the `encryptData` and `decryptData` functions handle the actual encryption and decryption processes.']

