} ListNode;

typedef struct List {
    ListNode* head;
    size_t length;
    size_t capacity;
} List;

List* createList() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->length = 0;
    list->capacity = 16; // Initial capacity
    return list;
}

void freeList(List* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int addPDUToList(List* list, DCIPDU pdu) {
    if (!list || !pdu.label) return -1; // Invalid PDU

    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return -2; // Memory allocation failed

    newNode->pdu = pdu;
    newNode->next = list->head;
    list->head = newNode;
    list->length++;

    if (list->length == list->capacity) {
        list->capacity *= 2;
        ListNode* newHead = (ListNode*)realloc(list->head, list->capacity * sizeof(ListNode));
        if (!newHead) {
            free(newNode);
            return -3; // Memory reallocation failed
        }
        list->head = newHead;
    }

    return 0; // Success
}

