int lte_dci_list_insert(LteDciList* list, size_t position, LteDciPdu pdu, LteLogEntry* log) {
    if (position > list->count) {
        return -1; // Invalid position
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LteDciPdu* new_pdus = realloc(list->pdus, new_capacity * sizeof(LteDciPdu));
        if (new_pdus == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1; // Memory allocation failure
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    memmove(list->pdus + position + 1, list->pdus + position, (list->count - position) * sizeof(LteDciPdu));
    list->pdus[position] = pdu;
    list->count++;

    if (log != NULL) {
        time_t now = time(NULL);
        strftime(log->timestamp, sizeof(log->timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        log->operation = "Insert";
        log->position = position;
        log->result = 0; // Assuming insert is successful
    }

    return 0; // Success
}

// Function to delete a DCI PDU at a specific position
int lte_dci_list_delete(LteDciList* list, size_t position, LteLogEntry* log) {
    if (position >= list->count) {
        return -1; // Invalid position
    }

    memmove(list->pdus + position, list->pdus + position + 1, (list->count - position - 1) * sizeof(LteDciPdu));
    list->count--;

    if (log != NULL) {
        time_t now = time(NULL);
        strftime(log->timestamp, sizeof(log->timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        log->operation = "Delete";
