void initialize_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->sessions = malloc(initial_capacity * sizeof(UeSessionData));
    array->capacity = initial_capacity;
    array->size = 0;
}

void add_session(DynamicArray *array) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->sessions = realloc(array->sessions, array->capacity * sizeof(UeSessionData));
    }
    // Initialize new session data
    memset(&array->sessions[array->size], 0, sizeof(UeSessionData));
    array->size++;
}

void remove_session(DynamicArray *array) {
    if (array->size > 0) {
        array->size--;
        // Optionally clear memory of removed session
        memset(&array->sessions[array->size], 0, sizeof(UeSessionData));
    }
}

void configure_sessions(DynamicArray *array, size_t load_pattern[]) {
    for (size_t i = 0; i < array->size; i++) {
        // Configure each session based on load pattern
        memset(&array->sessions[i].rrc_config, 0, sizeof(RrcConnectionConfig));
        memset(&array->sessions[i].rrc_reconfig, 0, sizeof(RrcConnectionReconfiguration));
    }
}

void free_dynamic_array(DynamicArray *array) {
    free(array->sessions);
    array->sessions = NULL;
    array->capacity = 0;
    array->size = 0;
}
