bool validateOauth2Token(const char *tokenResponse) {
    struct json_object *parsed_json, *access_token, *expires_in, *token_type, *refresh_token = NULL;
    bool isValid = true;

    parsed_json = json_tokener_parse(tokenResponse);
    if (!parsed_json) {
        return false;
    }

    access_token = json_object_object_get_ex(parsed_json, "access_token", &isValid);
    expires_in = json_object_object_get_ex(parsed_json, "expires_in", &isValid);
    token_type = json_object_object_get_ex(parsed_json, "token_type", &isValid);

    if (isValid) {
        refresh_token = json_object_object_get_ex(parsed_json, "refresh_token", &isValid);
    }

    if (!isValid ||
        !json_is_string(access_token) ||
        !json_is_int(expires_in) ||
        strcmp(json_object_get_string(token_type), "Bearer") != 0 ||
        json_object_get_int(expires_in) <= 0) {
        isValid = false;
    }

    json_object_put(parsed_json);
    return isValid;
}

void manageUeSessions(const char *loadPattern, int maxSessions) {
    UeSessionData *sessions = NULL;
    int currentSessions = 0;

    for (int i = 0; loadPattern[i]; i++) {
        if (loadPattern[i] == 'A' && currentSessions < maxSessions) {
            // Allocate new session
            sessions = realloc(sessions, sizeof(UeSessionData) * (currentSessions + 1));
            // Initialize UeSessionData structure
            currentSessions++;
        } else if (loadPattern[i] == 'R' && currentSessions > 0) {
            // Free existing session
            currentSessions--;
            sessions = realloc(sessions, sizeof(UeSessionData) * currentSessions);
        }
    }

    free(sessions);
}

int main() {
    const char *tokenResponse = "{\"access_token\":\"validToken\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    bool isTokenValid = validateOauth2Token(tokenResponse);
    printf("Is token valid? %s\n", isTokenValid ? "Yes" : "No");

    manageUeSessions("AARRRR", 5);

    return 0;
}
