#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PDUS 10000

typedef struct LTE_DCI_PDU {
    char label[256];
    int fdma;
    int mcs;
    int power_control;
} LTE_DCI_PDU;

typedef struct PDU_List {
    LTE_DCI_PDU *pdus[MAX_PDUS];
    int size;
    int re_alloc_count;
    void (*log)(const char*, ...);
    void* (*custom_malloc)(size_t);
    void (*custom_free)(void*);
} PDU_List;

void default_log(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

PDU_List* create_pdu_list(void (*log_func)(), void *(*malloc_func)(), void (*free_func)()) {
    PDU_List *list = (PDU_List *)malloc(sizeof(PDU_List));
    if (!list) {
        return NULL;
    }
    list->size = 0;
    list->re_alloc_count = 0;
    list->log = log_func ? log_func : default_log;
    list->custom_malloc = malloc_func ? malloc_func : malloc;
    list->custom_free = free_func ? free_func : free;
    return list;
}

void add_pdu(PDU_List *list, LTE_DCI_PDU *pdu) {
    if (list->size >= MAX_PDUS) {
        list->log("Error: List is full\n");
        return;
    }
    for (int i = 0; i < list->size; i++) {
        if (!list->pdus[i]) {
            list->pdus[i] = pdu;
            break;
        }
    }
    list->size++;
}

void remove_pdu(PDU_List *list, int index) {
    if (index < 0 || index >= list->size) {
        list->log("Error: Invalid index\n");
        return;
    }
    list->custom_free(list->pdus[index]);
    list->pdus[index] = NULL;
    for (int i = index; i < list->size - 1; i++) {
        list->pdus[i] = list->pdus[i + 1];
    }
    list->size--;
}

void log_operation(PDU_List *list, const char* operation, int index) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    list->log("Time: %s, Operation: %s, Index: %d\n", asctime(tm_info), operation, index);
}

int main() {
    PDU_List *list = create_pdu_list(default_log, malloc, free);
    if (!list) {
        printf("Failed to create PDU list\n");
        return 1;
    }

    LTE_DCI_PDU pdu;
    strcpy(pdu.label, "PDU_0");
    pdu.fdma = 10;
    pdu.mcs = 25;
    pdu.power_control = 1;

    add_pdu(list, &pdu);
    log_operation(list, "Insert", 0);

    remove_pdu(list, 0);
    log_operation(list, "Delete", 0);

    list->custom_free(list);
    return 0;
}
