#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_DCI_PDUS 10000

typedef struct {
    int label;
    // FDMA, MCS, and power control information fields go here
} DCI_PDU;

typedef struct {
    DCI_PDU *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DCI_List;

void init_dci_list(DCI_List *list) {
    list->pdus = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_dci_list(DCI_List *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

int add_dci_pdu(DCI_List *list, DCI_PDU pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        DCI_PDU *new_pdus = realloc(list->pdus, new_capacity * sizeof(DCI_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_dci_pdu(DCI_List *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Index out of bounds
    }
    for (size_t i = index; i < list->count - 1; ++i) {
        list->pdus[i] = list->pdus[i + 1];
    }
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_operation(DCI_List *list, const char *operation_type, size_t index, int result) {
    time_t now = time(NULL);
    printf("[%s] %s operation at index %zu: Result = %d\n", ctime(&now), operation_type, index, result);
}

char* process_string(const char *input, size_t max_size, int append_separator, const char *separator) {
    if (!input || max_size == 0) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    size_t input_len = strlen(input);
    if (input_len >= max_size) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    char *output = malloc((input_len + (append_separator ? strlen(separator) : 0) + 1) * sizeof(char));
    if (!output) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }
    strcpy(output, input);

    if (append_separator && input_len > 0) {
        strcat(output, separator);
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
    return output;
}
