typedef struct Packet {
    char *ip_header;
    char *payload;
    int source_ip;
    int destination_ip;
    int source_port;
    int destination_port;
    int length;
} Packet;

typedef struct PacketList {
    Packet **packets;
    int size;
    int capacity;
} PacketList;

PacketList* create_packet_list() {
    PacketList *list = (PacketList*)malloc(sizeof(PacketList));
    list->packets = (Packet**)malloc(100 * sizeof(Packet*)); // Initial capacity
    list->size = 0;
    list->capacity = 100;
    return list;
}

void free_packet_list(PacketList *list) {
    for (int i = 0; i < list->size; i++) {
        free(list->packets[i]->ip_header);
        free(list->packets[i]->payload);
        free(list->packets[i]);
    }
    free(list->packets);
    free(list);
}

void log_operation(const char *operation, int position, const char *outcome) {
    time_t now = time(NULL);
    printf("%s: %s at position %d - %s\n", ctime(&now), operation, position, outcome);
}

int is_valid_packet(Packet *packet, int source_range_start, int source_range_end, int destination_range_start, int destination_range_end) {
    // Implement validation logic
    return packet->source_ip >= source_range_start && packet->source_ip <= source_range_end &&
           packet->destination_ip >= destination_range_start && packet->destination_ip <= destination_range_end &&
           packet->length > 0;
}

void resize_packet_list(PacketList *list) {
    list->capacity *= 2;
    Packet **new_packets = (Packet**)realloc(list->packets, list->capacity * sizeof(Packet*));
    if (new_packets == NULL) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    list->packets = new_packets;
}

void insert_packet(PacketList *list, Packet *packet, int position) {
    if (position < 0 || position > list->size) {
        printf("Invalid position for insertion.\n");
        return;
    }

    if (list->size == list->capacity) {
        resize_packet_list(list);
    }

    for (int i = list->size; i > position; i--) {
        list->packets[i] = list->packets[i - 1];
    }

    list->packets[position] = packet;
    list->size++;
    log_operation("Insert", position, "Success");
}

void remove_packet(PacketList *list, int position) {
    if (position < 0 || position >= list->size) {
        printf("Invalid position for removal.\n");
        return;
    }

    free(list->packets[position]->ip_header);
    free(list->packets[position]->payload);
    free(list->packets[position]);

    for (int i = position; i < list->size - 1; i++) {
        list->packets[i] = list->packets[i + 1];
    }

    list->size--;
    log_operation("Remove", position, "Success");
}

void update_packet(PacketList *list, Packet *packet, int position) {
    if (position < 0 || position >= list->size) {
        printf("Invalid position for update.\n");
        return;
    }

    free(list->packets[position]->ip_header);
    free(list->packets[position]->payload);

    list->packets[position] = packet;
    log_operation("Update", position, "Success");
}

int main() {
