int re_allocation_counter = 0;

void log_operation(const char *operation, const char *details) {
    time_t current_time;
    time(&current_time);
    printf("%s - %s\n", ctime(&current_time), details);
}

int validate_pdu(LTE_DCI_PDU pdu) {
    // Implement validation logic here
    return 1; // Return 1 if valid, 0 otherwise
}

void insert_pdu(int position, LTE_DCI_PDU pdu) {
    if (position < 0 || position > pdu_count) {
        log_operation("ERROR", "Invalid position for PDU insertion");
        return;
    }

    if (pdu_count >= MAX_PDUS) {
        log_operation("WARNING", "PDU list is full, reallocating memory");
        // Reallocate memory in smaller chunks until successful
        re_allocation_counter++;
        while ((pdu_list = realloc(pdu_list, sizeof(LTE_DCI_PDU *) * (MAX_PDUS + 100))) == NULL) {
            log_operation("WARNING", "Memory allocation failed, retrying...");
        }
    }

    for (int i = pdu_count; i > position; i--) {
        pdu_list[i] = pdu_list[i - 1];
    }

    if (validate_pdu(pdu)) {
        pdu_list[position] = malloc(sizeof(LTE_DCI_PDU));
        *pdu_list[position] = pdu;
        pdu_count++;
        log_operation("INSERT", "PDU inserted successfully");
    } else {
        log_operation("ERROR", "Invalid PDU, insertion aborted");
    }
}

void delete_pdu(int position) {
    if (position < 0 || position >= pdu_count) {
        log_operation("ERROR", "Invalid position for PDU deletion");
        return;
    }

    free(pdu_list[position]);
    for (int i = position; i < pdu_count - 1; i++) {
        pdu_list[i] = pdu_list[i + 1];
    }
    pdu_count--;
    log_operation("DELETE", "PDU deleted successfully");
}

