#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 1024

typedef struct LTE_UE_Context {
    int rrc_state;
    void* pdp_context;
    char mme_ip[16];
    char* s1ap_message;
    int qos_priority;
} LTE_UE_Context;

LTE_UE_Context ue_contexts[MAX_UE_CONTEXTS];
int num_contexts = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_s1ap_message(int payload_size) {
    return malloc(payload_size);
}

void free_s1ap_message(void* message) {
    free(message);
}

void initialize_ue_context(LTE_UE_Context* ctx, int rrc_state, void* pdp_context, const char* mme_ip, const char* s1ap_message, int qos_priority) {
    ctx->rrc_state = rrc_state;
    ctx->pdp_context = pdp_context;
    strcpy(ctx->mme_ip, mme_ip);
    ctx->s1ap_message = allocate_s1ap_message(strlen(s1ap_message) + 1);
    strcpy(ctx->s1ap_message, s1ap_message);
    ctx->qos_priority = qos_priority;
}

void cleanup_ue_context(LTE_UE_Context* ctx) {
    free_s1ap_message(ctx->s1ap_message);
    ctx->pdp_context = NULL;
    memset(ctx->mme_ip, 0, sizeof(ctx->mme_ip));
    memset(ctx->s1ap_message, 0, strlen(ctx->s1ap_message) + 1);
}

void add_ue_context(int rrc_state, void* pdp_context, const char* mme_ip, const char* s1ap_message, int qos_priority) {
    pthread_mutex_lock(&mutex);
    if (num_contexts < MAX_UE_CONTEXTS) {
        initialize_ue_context(&ue_contexts[num_contexts], rrc_state, pdp_context, mme_ip, s1ap_message, qos_priority);
        num_contexts++;
    } else {
        printf("Maximum number of UE contexts reached\n");
    }
    pthread_mutex_unlock(&mutex);
}

void remove_ue_context(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_contexts) {
        cleanup_ue_context(&ue_contexts[index]);
        for (int i = index; i < num_contexts - 1; i++) {
            ue_contexts[i] = ue_contexts[i + 1];
        }
        num_contexts--;
    } else {
        printf("Invalid UE context index\n");
    }
    pthread_mutex_unlock(&mutex);
}

void update_ue_context(int index, int rrc_state, void* pdp_context, const char* mme_ip, const char* s1ap_message, int qos_priority) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_contexts) {
        cleanup_ue_context(&ue_contexts[index]);
        initialize_ue_context(&ue_contexts[index], rrc_state, pdp_context, mme_ip, s1ap_message, qos_priority);
    } else {
        printf("Invalid UE context index\n");
    }
    pthread_mutex_unlock(&mutex);
}

void* get_s1ap_message(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_contexts) {
        void* message = ue_contexts[index].s1ap_message;
        pthread_mutex_unlock(&mutex);
        return message;
    } else {
        printf("Invalid UE context index\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}
```

This code provides a basic structure for managing LTE UE contexts with mutex locking for thread safety. It includes functions to add, remove, update, and retrieve S1AP messages from the context array. Error handling is minimal, focusing on locking and unlocking mutexes. Memory management is simplified by using `malloc` and `free`. This implementation assumes that S1AP message sizes are known and manageable, and it does not include detailed error logging or performance monitoring features.']

