#include <time.h>

#define MAX_SESSIONS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *sessions[MAX_SESSIONS];
int session_count = 0;

void initialize_session() {
    srand(time(0));
}

NFAPI_CRC_INDICATION_PDU_T* create_session(int RX_UE_INFORMATION_TAG, int RNTI) {
    if (session_count >= MAX_SESSIONS) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *new_session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_session->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_session->RNTI = RNTI;
    new_session->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

    sessions[session_count++] = new_session;
    return new_session;
}

void destroy_session(NFAPI_CRC_INDICATION_PDU_T* session) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i] == session) {
            free(session);
            for (; i < session_count - 1; i++) {
                sessions[i] = sessions[i + 1];
            }
            sessions[session_count - 1] = NULL;
            session_count--;
            break;
        }
    }
}

void scale_sessions(int new_capacity) {
    if (new_capacity > MAX_SESSIONS || new_capacity < session_count) return;

    NFAPI_CRC_INDICATION_PDU_T **new_sessions = realloc(sessions, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (new_sessions == NULL) return; // Handle memory allocation failure

    sessions = new_sessions;
    MAX_SESSIONS = new_capacity;
}

void log_session_creation(int RX_UE_INFORMATION_TAG, int RNTI) {
    printf("Session created for UE %d with RNTI %d\n", RX_UE_INFORMATION_TAG, RNTI);
}

void log_session_destruction(NFAPI_CRC_INDICATION_PDU_T* session) {
    printf("Session destroyed for UE %d with RNTI %d\n", session->RX_UE_INFORMATION_TAG, session->RNTI);
}

int main() {
    initialize_session();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *session1 = create_session(12345, 67890);
    log_session_creation(session1->RX_UE_INFORMATION_TAG, session1->RNTI);

    destroy_session(session1);
    log_session_destruction(session1);

    return 0;
}
