#define MIN_AGG_INTERVAL 100 // milliseconds
#define MAX_AGG_INTERVAL 5000 // milliseconds

typedef struct {
    int snr;
} UE_TX_INFO_TAG;

typedef struct {
    int id;
} SRS_TAG;

typedef struct {
    int index;
} PDSCH_TAG;

typedef struct {
    UE_TX_INFO_TAG ue_tx_info;
    SRS_TAG srs_tag;
    PDSCH_TAG pdsch_tag;
} LTE_PHY_RX_FRAME_T;

typedef struct {
    LTE_PHY_RX_FRAME_T* frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    clock_t last_aggregation_time;
    int aggregation_interval;
} LTE_PHY_RX_ARRAY;

LTE_PHY_RX_ARRAY* initialize_lte_phy_rx_array(int initial_capacity, int aggregation_interval) {
    if (aggregation_interval < MIN_AGG_INTERVAL || aggregation_interval > MAX_AGG_INTERVAL) {
        fprintf(stderr, "Invalid aggregation interval. Must be between %d and %d milliseconds.\n", MIN_AGG_INTERVAL, MAX_AGG_INTERVAL);
        return NULL;
    }

    LTE_PHY_RX_ARRAY* array = (LTE_PHY_RX_ARRAY*)malloc(sizeof(LTE_PHY_RX_ARRAY));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for LTE_PHY_RX_ARRAY.\n");
        return NULL;
    }

    array->frames = (LTE_PHY_RX_FRAME_T*)calloc(initial_capacity, sizeof(LTE_PHY_RX_FRAME_T));
    if (!array->frames) {
        free(array);
        fprintf(stderr, "Memory allocation failed for LTE_PHY_RX_FRAME_T array.\n");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->last_aggregation_time = clock();
    array->aggregation_interval = aggregation_interval;

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        array->frames[i].ue_tx_info.snr = rand() % 100; // Random SNR between 0 and 99
        array->frames[i].srs_tag.id = i;
        array->frames[i].pdsch_tag.index = i;
    }

    return array;
}

void free_lte_phy_rx_array(LTE_PHY_RX_ARRAY* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->frames);
        free(array);
    }
}
