void verify_config_file() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, &verify_config_file_thread, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread_id, NULL);
