void *verify_config_file_thread(void *arg) {
    FILE *file = fopen(CONFIG_FILE, "rb");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char *data = malloc(file_size);
    if (!data) {
        fclose(file);
        perror("Failed to allocate memory for configuration data");
        return NULL;
    }

    size_t bytes_read = fread(data, 1, file_size, file);
    fclose(file);

    if (bytes_read != file_size) {
        free(data);
        fprintf(stderr, "Error reading configuration file\n");
        return NULL;
    }

    unsigned int checksum = calculate_crc32(data, file_size);
    if (checksum != CRC32_CHECKSUM) {
        free(data);
        fprintf(stderr, "CRC32 checksum mismatch in configuration file\n");
        return NULL;
    }

    free(data);
    return NULL;
}

