#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_FRAMES 1024
#define CACHE_SIZE 256

typedef struct LTE_PHY_RX_FRAME_T {
    int valid_UE_TX_INFO_TAG;
    int SRS_TAG;
    int PDSCH_TAG;
    float SNR;
    // Custom fields support
    union {
        int intValue;
        char* stringValue;
        enum EnumType enumValue;
    } customField;
    int isCustomFieldOptional;
} LTE_PHY_RX_FRAME_T;

typedef struct LTE_EPC_NODE_PDU_T {
    char IP_ADDRESS[16];
    int PORT_NUMBER;
    int connectionStatus;
} LTE_EPC_NODE_PDU_T;

pthread_mutex_t frame_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

LTE_PHY_RX_FRAME_T* frames[MAX_FRAMES] = {NULL};
LTE_PHY_RX_FRAME_T* frame_cache[CACHE_SIZE] = {NULL};

void initialize_frames(int num_frames, int aggregation_interval) {
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME_T* frame = malloc(sizeof(LTE_PHY_RX_FRAME_T));
        if (frame == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        // Initialize fields
        frame->valid_UE_TX_INFO_TAG = rand() % 2;
        frame->SRS_TAG = rand() % 10;
        frame->PDSCH_TAG = rand() % 5;
        frame->SNR = (float)(rand() % 100) / 10.0f;
        // Custom fields support
        int field_type = rand() % 3;
        switch (field_type) {
            case 0:
                frame->customField.intValue = rand() % 100;
                break;
            case 1:
                frame->customField.stringValue = malloc(256);
                if (frame->customField.stringValue == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free(frame);
                    return;
                }
                snprintf(frame->customField.stringValue, 256, "String%d", rand() % 100);
                frame->isCustomFieldOptional = 0;
                break;
            case 2:
                // Enumerated type handling
                frame->isCustomFieldOptional = 1;
                break;
        }
        pthread_mutex_lock(&frame_mutex);
        frames[i] = frame;
        pthread_mutex_unlock(&frame_mutex);
    }
}

void aggregate_statistics(int interval) {
    for (int i = 0; i < MAX_FRAMES; i++) {
        LTE_PHY_RX_FRAME_T* frame;
        pthread_mutex_lock(&frame_mutex);
        if (frames[i] != NULL) {
            frame = frames[i];
        } else {
            pthread_mutex_unlock(&frame_mutex);
            continue;
        }
        pthread_mutex_unlock(&frame_mutex);

        // Aggregate statistics logic here
        printf("Aggregating statistics for frame %d\n", i);
    }
}

void* cache_frames(void* arg) {
    while (1) {
        pthread_mutex_lock(&cache_mutex);
        int cache_index = 0;
        for (int i = 0; i < MAX_FRAMES; i++) {
            LTE_PHY_RX_FRAME_T* frame;
            pthread_mutex_lock(&frame_mutex);
            if (frames[i] != NULL) {
                frame = frames[i];
            } else {
                pthread_mutex_unlock(&frame_mutex);
                continue;
            }
            pthread_mutex_unlock(&frame_mutex);

            // Check cache space
            if (cache_index < CACHE_SIZE) {
                pthread_mutex_lock(&cache_mutex);
                frame_cache[cache_index] = frame;
                cache_index++;
                pthread_mutex_unlock(&cache_mutex);
            } else {
                break;  // Cache is full, stop caching for now
            }
        }
        pthread_mutex_unlock(&cache_mutex);

        // Sleep to simulate periodic cache operation
        sleep(10);  // Adjust sleep time based on interval and load
    }
    return NULL;
}

void initialize_epc_nodes(int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        LTE_EPC_NODE_PDU_T* node_pdu = malloc(sizeof(LTE_EPC_NODE_PDU_T));
        if (node_pdu == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        // Initialize fields
        snprintf(node_pdu->IP_ADDRESS, 16, "192.168.0.%d", rand() % 254);
        node_pdu->PORT_NUMBER = rand() % 65535;
        node_pdu->connectionStatus = rand() % 2;

        pthread_mutex_lock(&frame_mutex);
        // Assuming frames array is used for EPC nodes as well
        frames[i] = (LTE_PHY_RX_FRAME_T*)node_pdu;
        pthread_mutex_unlock(&frame_mutex);
    }
}

int main(int argc, char* argv[]) {
    int num_frames = 100;
    int aggregation_interval = 60;

    initialize_frames(num_frames, aggregation_interval);

    pthread_t cache_thread;
    if (pthread_create(&cache_thread, NULL, cache_frames, NULL) != 0) {
        fprintf(stderr, "Failed to create cache thread\n");
        return 1;
    }

    while (1) {
        aggregate_statistics(aggregation_interval);
        sleep(aggregation_interval);  // Adjust sleep time based on interval and load
    }

    pthread_join(cache_thread, NULL);

    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME_T* frame;
        pthread_mutex_lock(&frame_mutex);
        if (frames[i] != NULL) {
            frame = frames[i];
        } else {
            pthread_mutex_unlock(&frame_mutex);
            continue;
        }
        pthread_mutex_unlock(&frame_mutex);

        // Free dynamically allocated memory
        if (frame->isCustomFieldOptional == 0 && frame->customField.stringValue != NULL) {
            free(frame->customField.stringValue);
        }
        free(frame);
    }

    return 0;
}
