#include <iostream>
#include <fstream>
#include <string>

class ResourceBundle {
public:
    enum ErrorCode {
        FILE_NOT_FOUND,
        PERMISSION_DENIED,
        OUT_OF_MEMORY
    };

    struct Header {
        char magic[4];
        uint32_t version;
        uint32_t itemCount;
    };

    struct Item {
        uint8_t type;
        uint32_t size;
    };

    ResourceBundle(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            errorCode = FILE_NOT_FOUND;
            return;
        }

        Header header;
        file.read(reinterpret_cast<char*>(&header), sizeof(header));
        if (std::string(header.magic) != "RBND" || header.version != 1) {
            errorCode = OUT_OF_MEMORY; // Invalid version or magic
            return;
        }

        items.resize(header.itemCount);
        for (uint32_t i = 0; i < header.itemCount; ++i) {
            file.read(reinterpret_cast<char*>(&items[i]), sizeof(Item));
            if (!file) {
                errorCode = OUT_OF_MEMORY; // Failed to read item
                return;
            }
        }

        state.load(file);
    }

    ~ResourceBundle() {}

    float randomFloat(float min, float max) const {
        return UnityEngine::Random.Range(min, max);
    }

    int randomInt(int min, int max) const {
        return UnityEngine::Random.Range(min, max);
    }

    std::string toString() const {
        return "Range: [" + std::to_string(randomFloat(0.0f, 1.0f)) + ", " +
               std::to_string(randomInt(0, 100)) + "]";
    }

private:
    ErrorCode errorCode;
    Header header;
    std::vector<Item> items;
    StateObject state; // Assuming StateObject is a valid class
};

// Example usage
int main() {
    ResourceBundle bundle("path_to_resource_bundle.bin");
    if (bundle.errorCode == ResourceBundle::FILE_NOT_FOUND) {
        std::cerr << "File not found." << std::endl;
    } else if (bundle.errorCode == ResourceBundle::PERMISSION_DENIED) {
        std::cerr << "Permission denied." << std::endl;
    } else if (bundle.errorCode == ResourceBundle::OUT_OF_MEMORY) {
        std::cerr << "Out of memory." << std::endl;
    } else {
        std::cout << bundle.toString() << std::endl;
    }
    return 0;
}
