#define MAX_MAC_EC_INSTANCES 100

typedef struct {
    uint8_t pdu_session_id;
    uint8_t nas_procedure_code;
    char snssai[5];
} MacEcInstance;

MacEcInstance* mac_ec_array[MAX_MAC_EC_INSTANCES] = {NULL};
int mac_ec_count = 0;

int add_mac_ec(uint8_t pdu_session_id, uint8_t nas_procedure_code, const char* snssai) {
    if (mac_ec_count >= MAX_MAC_EC_INSTANCES) return -1; // Overflow
    MacEcInstance* new_mac_ec = (MacEcInstance*)malloc(sizeof(MacEcInstance));
    if (!new_mac_ec) return -2; // Memory allocation failed

    new_mac_ec->pdu_session_id = pdu_session_id;
    new_mac_ec->nas_procedure_code = nas_procedure_code;
    strncpy(new_mac_ec->snssai, snssai, sizeof(new_mac_ec->snssai));

    mac_ec_array[mac_ec_count++] = new_mac_ec;
    return 0; // Success
}

int update_mac_ec(uint8_t pdu_session_id, uint8_t nas_procedure_code, const char* snssai) {
    for (int i = 0; i < mac_ec_count; ++i) {
        if (mac_ec_array[i]->pdu_session_id == pdu_session_id) {
            free(mac_ec_array[i]);
            MacEcInstance* updated_mac_ec = (MacEcInstance*)malloc(sizeof(MacEcInstance));
            if (!updated_mac_ec) return -2; // Memory allocation failed

            updated_mac_ec->pdu_session_id = pdu_session_id;
            updated_mac_ec->nas_procedure_code = nas_procedure_code;
            strncpy(updated_mac_ec->snssai, snssai, sizeof(updated_mac_ec->snssai));

            mac_ec_array[i] = updated_mac_ec;
            return 0; // Success
        }
    }
    return -1; // PDU Session ID not found
}

int remove_mac_ec(uint8_t pdu_session_id) {
    for (int i = 0; i < mac_ec_count; ++i) {
        if (mac_ec_array[i]->pdu_session_id == pdu_session_id) {
            free(mac_ec_array[i]);
            memmove(&mac_ec_array[i], &mac_ec_array[i + 1], (mac_ec_count - i - 1) * sizeof(MacEcInstance*));
            mac_ec_count--;
            return 0; // Success
        }
    }
    return -1; // PDU Session ID not found
}

void free_mac_ec_array() {
    for (int i = 0; i < mac_ec_count; ++i) {
        free(mac_ec_array[i]);
    }
    mac_ec_count = 0;
}
