#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct MacEc {
    uint8_t pduSessionId;
    char nasProcedureCode[10];
    char snssai[20];
    // Other necessary fields
} MacEc;

typedef struct MacEcArray {
    MacEc *macEcs;
    size_t size;
    size_t capacity;
} MacEcArray;

MacEcArray* createMacEcArray() {
    MacEcArray *array = (MacEcArray*)malloc(sizeof(MacEcArray));
    array->macEcs = NULL;
    array->size = 0;
    array->capacity = 0;
    return array;
}

void freeMacEcArray(MacEcArray *array) {
    for (size_t i = 0; i < array->size; i++) {
        // Free any dynamically allocated memory in MacEc instances
    }
    free(array->macEcs);
    free(array);
}

int addOrUpdateMacEc(MacEcArray *array, MacEc macEc) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->macEcs[i].pduSessionId == macEc.pduSessionId) {
            // Update existing MAC EC instance
            memcpy(&array->macEcs[i], &macEc, sizeof(MacEc));
            return 1;
        }
    }

    // Add new MAC EC instance
    if (array->size >= array->capacity) {
        size_t newCapacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        MacEc *newMacEcs = (MacEc*)realloc(array->macEcs, newCapacity * sizeof(MacEc));
        if (!newMacEcs) return -1; // Memory allocation failed
        array->macEcs = newMacEcs;
        array->capacity = newCapacity;
    }
    array->macEcs[array->size++] = macEc;
    return 0;
}

int removeMacEc(MacEcArray *array, uint8_t pduSessionId) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->macEcs[i].pduSessionId == pduSessionId) {
            // Remove MAC EC instance
            memmove(&array->macEcs[i], &array->macEcs[i + 1], (array->size - i - 1) * sizeof(MacEc));
            array->size--;
            return 0;
        }
    }
    return -1; // MAC EC not found
}

void logMacEcOperation(const char *operation, uint8_t pduSessionId, int result) {
    if (result == 0) {
        printf("Successfully %s MAC EC with PDU Session ID: %d\n", operation, pduSessionId);
    } else {
        printf("Error during %s MAC EC with PDU Session ID: %d\n", operation, pduSessionId);
    }
}

// Main function for demonstration
int main() {
    MacEcArray *macEcArray = createMacEcArray();
    if (!macEcArray) return -1; // Memory allocation failed

    MacEc macEc1 = {1, "Procedure1", "SNSSAI1"};
    logMacEcOperation("added", macEc1.pduSessionId, addOrUpdateMacEc(macEcArray, macEc1));

    MacEc macEc2 = {1, "Procedure1", "SNSSAI1Updated"};
    logMacEcOperation("updated", macEc2.pduSessionId, addOrUpdateMacEc(macEcArray, macEc2));

    int result = removeMacEc(macEcArray, 1);
    logMacEcOperation("removed", 1, result);

    freeMacEcArray(macEcArray);
    return 0;
}
