import argparse
import asyncio
import os
import sys
import time
from collections import deque
from typing import List

class FinancialTransaction:
    def __init__(self, timestamp: float, price: float, volume: int, bid_ask_spread: float):
        self.timestamp = timestamp
        self.price = price
        self.volume = volume
        self.bid_ask_spread = bid_ask_spread

class AnalyticsReport:
    @staticmethod
    def calculate_statistics(data: List[FinancialTransaction], metrics: List[str]):
        summary = {}
        for metric in metrics:
            values = [getattr(transaction, metric) for transaction in data]
            summary[metric] = {
                'mean': sum(values) / len(values),
                'median': sorted(values)[len(values) // 2],
                'std_dev': (sum((x - mean) ** 2 for x in values) / len(values)) ** 0.5
            }
        return summary

class DataPacket:
    @staticmethod
    def validate_header(packet: bytes):
        header = packet[:8]
        if header != b'FINANCIAL':
            raise ValueError("Invalid data packet header")

    @staticmethod
    def validate_integrity_checksum(packet: bytes):
        checksum = sum(packet[i] for i in range(8, len(packet))) % 256
        expected_checksum = int.from_bytes(packet[8:], byteorder='big')
        if checksum != expected_checksum:
            raise ValueError("Data packet integrity checksum mismatch")

async def process_data_stream(reader: asyncio.StreamReader, writer: asyncio.StreamWriter, metrics: List[str], window_size: int):
    data_buffer = deque()
    while True:
        try:
            packet = await reader.read(1024)
            if not packet:
                break
            DataPacket.validate_header(packet)
            DataPacket.validate_integrity_checksum(packet)
            transaction_data = packet[9:].decode('utf-8').split(',')
            for data in transaction_data:
                timestamp, price, volume, bid_ask_spread = map(float, data.split())
                financial_transaction = FinancialTransaction(timestamp, price, volume, bid_ask_spread)
                data_buffer.append(financial_transaction)
                if len(data_buffer) > window_size:
                    data_buffer.popleft()
            report = AnalyticsReport.calculate_statistics(list(data_buffer), metrics)
            print(report)
        except Exception as e:
            print(f"Error processing data packet: {e}", file=sys.stderr)

async def main():
    parser = argparse.ArgumentParser(description="Financial Transaction Analytics Script")
    parser.add_argument("--manpage", action="store_true", help="Print comprehensive usage details to stdout")
    parser.add_argument("-t", "--time_window", type=float, nargs='+', help="Display the financial report for a specified time window")
    parser.add_argument("-o", "--output_file", help="Redirect the output to a specified file instead of stdout")
    parser.add_argument("-w", "--window_size", type=int, default=100, help="Specify the rolling window size for computing statistical summaries")
    parser.add_argument("-m", "--metrics_list", type=str, nargs='+', choices=['price', 'volume', 'bid_ask_spread'], default=['price', 'volume'], help="Allow users to select specific metrics to compute statistics for")

    args = parser.parse_args()

    if args.manpage:
        print("Man page content goes here")
        return

    reader, writer = await asyncio.open_connection('localhost', 12345)
    try:
        await process_data_stream(reader, writer, args.metrics_list, args.window_size)
    finally:
        writer.close()
        await writer.wait_closed()

if __name__ == "__main__":
    asyncio.run(main())
