NFAPI_CRC_INDICATION_PDU_T* create_and_initialize_pdus(int n, int max_copies) {
    pthread_mutex_lock(&memory_lock);

    if (current_memory_usage + sizeof(NFAPI_CRC_INDICATION_PDU_T) * n > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation exceeded threshold\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
