            }
        }
    }

    pthread_mutex_unlock(&memory_lock);
    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, int n) {
    pthread_mutex_lock(&memory_lock);

    current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

    free(pdus);

    pthread_mutex_unlock(&memory_lock);
}

