#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1000
#define MAX_MEMORY_USAGE 500

typedef struct {
    int PID;
    time_t timestamp;
    char source_ip[16];
    char dest_ip[16];
    char protocol_type[10];
    int status_flag;
} PacketMetadata;

PacketMetadata packet_list[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t lock;
size_t current_memory_usage = 0;

void log_event(const char* message) {
    printf("%s\n", message);
}

int add_packet(PacketMetadata new_packet) {
    pthread_mutex_lock(&lock);

    if (packet_count >= MAX_PACKETS) {
        log_event("Error: Packet list is full.");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    if (current_memory_usage + sizeof(new_packet) > MAX_MEMORY_USAGE) {
        log_event("Warning: Memory usage limit reached. Adding packet may cause resource exhaustion.");
    }

    memcpy(&packet_list[packet_count], &new_packet, sizeof(PacketMetadata));
    packet_count++;
    current_memory_usage += sizeof(PacketMetadata);

    pthread_mutex_unlock(&lock);
    return 0;
}

int delete_packet(int PID) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < packet_count; i++) {
        if (packet_list[i].PID == PID) {
            memmove(&packet_list[i], &packet_list[i + 1], sizeof(PacketMetadata) * (packet_count - i - 1));
            packet_count--;
            current_memory_usage -= sizeof(PacketMetadata);
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    log_event("Error: Packet with PID not found.");
    pthread_mutex_unlock(&lock);
    return -1;
}

PacketMetadata* get_packet(int PID) {
    for (int i = 0; i < packet_count; i++) {
        if (packet_list[i].PID == PID) {
            return &packet_list[i];
        }
    }

    log_event("Error: Packet with PID not found.");
    return NULL;
}

void update_status_flag(int PID, int new_status_flag) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < packet_count; i++) {
        if (packet_list[i].PID == PID) {
            packet_list[i].status_flag = new_status_flag;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    log_event("Error: Packet with PID not found.");
    pthread_mutex_unlock(&lock);
}

void* monitor_memory(void* arg) {
    while (1) {
        printf("Current Memory Usage: %zu\n", current_memory_usage);
        sleep(5); // Adjust interval as needed
    }
    return NULL;
}

int main() {
    pthread_t mem_monitor_thread;

    pthread_mutex_init(&lock, NULL);

    // Start memory monitoring thread
    pthread_create(&mem_monitor_thread, NULL, monitor_memory, NULL);

    // Example usage
    PacketMetadata new_packet = {1, time(NULL), "192.168.1.1", "10.0.0.1", "TCP", 0};
    add_packet(new_packet);
    update_status_flag(1, 1);
    delete_packet(1);

    pthread_mutex_destroy(&lock);
    pthread_join(mem_monitor_thread, NULL);

    return 0;
}
