    Header data;
    struct Node *next;
} Node;

// Define the structure for the dynamic list
typedef struct List {
    Node *head;
    size_t count;
} List;

// Function to initialize the list
void init_list(List *list) {
    list->head = NULL;
    list->count = 0;
}

// Function to insert a new header at the specified position in the list
void insert_header(List *list, int pos, Header data) {
    if (pos < 0 || pos > list->count) {
        printf("Invalid position for insertion\n");
        return;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (pos == 0) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node *current = list->head;
        for (int i = 0; i < pos - 1; i++) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    list->count++;
}

// Function to delete a header at the specified position in the list
void delete_header(List *list, int pos) {
    if (pos < 0 || pos >= list->count) {
        printf("Invalid position for deletion\n");
        return;
    }

    Node *current = list->head;
    if (pos == 0) {
        list->head = current->next;
        free(current);
    } else {
        Node *prev = NULL;
        for (int i = 0; i < pos; i++) {
            prev = current;
            current = current->next;
        }
        prev->next = current->next;
        free(current);
    }

    list->count--;
}

