        return NULL;
    }
    array->data = (NFAPI_LTE_RX_FRAME_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_LTE_RX_FRAME_PDU_T));
    if (array->data == NULL) {
        perror("Failed to allocate memory for array elements");
        free(array);
        return NULL;
    }
    array->capacity = MAX_ELEMENTS;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array != NULL) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_to_dynamic_array(DynamicArray *array, NFAPI_LTE_RX_FRAME_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        perror("Dynamic array is full");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    array->data[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void serialize_dynamic_array(DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&array->mutex);
    fwrite(array->data, sizeof(NFAPI_LTE_RX_FRAME_PDU_T), array->size, file);
    fclose(file);
    pthread_mutex_unlock(&array->mutex);
}

