import subprocess
import hashlib
import logging

logging.basicConfig(level=logging.DEBUG)

def update_kickstart(config_file_path, placeholders):
    try:
        with open(config_file_path, 'r') as file:
            content = file.read()

        for placeholder, value in placeholders.items():
            content = content.replace(placeholder, value)

        new_content = f"{content}\nencrypted_password\n"

        with open('updated_config.ks', 'w') as file:
            file.write(new_content)

    except Exception as e:
        logging.error(f"Error updating Kickstart configuration: {e}")

def md5_hash(*strings):
    try:
        concatenated_string = ''.join(strings)
        if any(len(s) > 1024 for s in strings):
            raise ValueError("Input strings exceed maximum length of 1024 characters each")

        hash_object = hashlib.md5(concatenated_string.encode())
        return hash_object.hexdigest()

    except Exception as e:
        logging.error(f"Error computing MD5 hash: {e}")

# Example usage
placeholders = {
    "${PASSWORD}": "new_password",
    "${HOSTNAME}": "example_host"
}

update_kickstart("config.ks", placeholders)
print(md5_hash("input1", "input2"))
