#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

List list;

void init_list() {
    list.head = NULL;
    pthread_mutex_init(&list.mutex, NULL);
}

void insert_element(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list.mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = data;
    new_node->next = list.head;
    list.head = new_node;
    pthread_mutex_unlock(&list.mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    pthread_mutex_lock(&list.mutex);
    Node* current = list.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            result = &current->data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list.mutex);
    return result;
}

void update_element_by_rnti(uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list.mutex);
    Node* current = list.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            current->data = new_data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list.mutex);
}

void populate_sdc_dhm_array(int size, NFAPI_CRC_INDICATION_PDU_T* array) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % MAX_ENTRIES;
        array[i].CRC_INDICATION_REL8_TAG = rand() & 0x3F;
        array[i].CRCFLAG = rand() & 1;
    }
}

void* sdc_dhm_thread(void* arg) {
    int* index = (int*)arg;
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = *index;
    data.RNTI = *index % MAX_ENTRIES;
    data.CRC_INDICATION_REL8_TAG = rand() & 0x3F;
    data.CRCFLAG = rand() & 1;

    insert_element(data);

    return NULL;
}

void stress_test(int num_threads) {
    pthread_t threads[num_threads];
    int indices[num_threads];

    for (int i = 0; i < num_threads; i++) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, sdc_dhm_thread, &indices[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    init_list();
    NFAPI_CRC_INDICATION_PDU_T array[MAX_ENTRIES];
    populate_sdc_dhm_array(MAX_ENTRIES, array);

    stress_test(100);

    return 0;
}
