#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&mutex);
    if (head == NULL) {
        head = (Node*)malloc(sizeof(Node));
        if (head == NULL) {
            pthread_mutex_unlock(&mutex);
            return -1; // Memory allocation failed
        }
        head->next = NULL;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (Node*)malloc(sizeof(Node));
        if (current->next == NULL) {
            pthread_mutex_unlock(&mutex);
            return -1; // Memory allocation failed
        }
        current->next->next = NULL;
    }

    Node* newNode = current->next; // Assuming 'current' is the last node
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->data.CRCFLAG = CRCFLAG;

    pthread_mutex_unlock(&mutex);
    return 0; // Entry added successfully
}

int update_entry(int RNTI, int newCRCFLAG) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data.CRCFLAG = newCRCFLAG;
            pthread_mutex_unlock(&mutex);
            return 0; // Entry updated successfully
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
    return -1; // Entry not found
}

int get_entry(int RNTI, NFAPI_CRC_INDICATION_PDU_T* result) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            *result = current->data;
            pthread_mutex_unlock(&mutex);
            return 0; // Entry retrieved successfully
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
    return -1; // Entry not found
}

void free_memory() {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&mutex);
}
