UserList* createUserList(size_t initial_capacity) {
    UserList* list = malloc(sizeof(UserList));
    if (!list) return NULL;

    list->profiles = malloc(initial_capacity * sizeof(UserProfile*));
    if (!list->profiles) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int addUserToUserList(UserList* list, UserProfile profile) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->profiles = realloc(list->profiles, list->capacity * 2 * sizeof(UserProfile*));
        if (!list->profiles) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->capacity *= 2;
    }
    list->profiles[list->size++] = malloc(sizeof(UserProfile));
    if (!list->profiles[list->size-1]) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    memcpy(list->profiles[list->size-1], &profile, sizeof(UserProfile));
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void freeUserList(UserList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->profiles[i]);
    }
    free(list->profiles);
    pthread_mutex_destroy(&list->mutex);
