#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    int size;
    pthread_mutex_t lock;
} NFAPICRCList;

void initNFAPICRCList(NFAPICRCList *list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void addOrUpdateNFAPICRCList(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == pdu.RNTI) {
            list->entries[i] = pdu;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    if (list->size >= MAX_ENTRIES) {
        fprintf(stderr, "List full\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->entries[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T *getNFAPICRCList(NFAPICRCList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T *result = &list->entries[i];
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void freeNFAPICRCList(NFAPICRCList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}
