import hashlib
import os
import concurrent.futures

def computeMD5Hash(filePath):
    chunk_size = 8192  # Adjust chunk size based on memory constraints
    hasher = hashlib.md5()

    try:
        with open(filePath, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
    except FileNotFoundError:
        print("File not found")
        return None
    except PermissionError:
        print("Permission error")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

    # Add metadata handling if required
    # ...

    return hasher.hexdigest()

# Use concurrent.futures to handle multiple file hashing tasks concurrently
def hash_files(file_paths):
    with concurrent.futures.ThreadPoolExecutor() as executor:
        results = list(executor.map(computeMD5Hash, file_paths))
    return results
