#define MAX_PACKETS 100

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    char *payload;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node *next;
} Node;

Node* createNode(int packetID, const char *payload) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed for node.\n");
        return NULL;
    }
    newNode->data.packetID = packetID;
    newNode->data.timestamp = time(NULL);
    size_t payloadLength = strlen(payload) + 1;
    newNode->data.payload = (char *)malloc(payloadLength * sizeof(char));
    if (newNode->data.payload == NULL) {
        printf("Memory allocation failed for payload.\n");
        free(newNode);
        return NULL;
    }
    strncpy(newNode->data.payload, payload, payloadLength);
    newNode->next = NULL;
    return newNode;
}

void insertPacket(Node **head, int packetID, const char *payload, size_t maxPackets) {
    if (maxPackets == MAX_PACKETS) {
        printf("Maximum number of packets reached.\n");
        return;
    }
    Node *newNode = createNode(packetID, payload);
    if (newNode != NULL) {
        newNode->next = *head;
        *head = newNode;
    }
}

void freeList(Node *head) {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        free(temp->data.payload);
        free(temp);
        current = temp->next;
    }
}
