#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 1000

typedef struct DataPacket {
    int packetID;
    time_t timestamp;
    char *payload;
} DataPacket;

typedef struct PacketNode {
    DataPacket data;
    struct PacketNode *next;
} PacketNode;

typedef struct PacketList {
    PacketNode *head;
    PacketNode *tail;
    size_t current_size;
    size_t max_capacity;
    time_t expire_duration;
} PacketList;

void init_packet_list(PacketList *list, size_t max_capacity, time_t expire_duration) {
    list->head = NULL;
    list->tail = NULL;
    list->current_size = 0;
    list->max_capacity = max_capacity;
    list->expire_duration = expire_duration;
}

void free_payload(void *payload) {
    free(payload);
}

void insert_packet(PacketList *list, DataPacket packet) {
    if (list->current_size >= list->max_capacity) {
        PacketNode *oldest = list->head;
        list->head = oldest->next;
        if (list->head == NULL) {
            list->tail = NULL;
        }
        free_payload(oldest->data.payload);
        free(oldest);
        --list->current_size;
    }

    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->data = packet;
    new_node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    }
    list->tail = new_node;

    if (list->head == NULL) {
        list->head = new_node;
    }

    ++list->current_size;
}

void expire_old_packets(PacketList *list) {
    time_t current_time = time(NULL);
    PacketNode *current = list->head;
    PacketNode *prev = NULL;

    while (current != NULL && difftime(current->data.timestamp, current_time) > -1 * list->expire_duration) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }

        free_payload(current->data.payload);
        PacketNode *temp = current;
        current = current->next;
        free(temp);
        --list->current_size;

        if (prev == NULL) {
            prev = list->head;
        }
    }

    if (current != NULL) {
        list->tail = prev;
    }
}

void destroy_packet_list(PacketList *list) {
    PacketNode *current = list->head;
    while (current != NULL) {
        PacketNode *next = current->next;
        free_payload(current->data.payload);
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->current_size = 0;
}
