#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int interface_id;
    int packet_count;
} NetworkInterfaceUpdate;

typedef struct {
    NetworkInterfaceUpdate *data;
    size_t used;
    size_t size;
    pthread_mutex_t mutex;
} NetworkStatsCollection;

NetworkStatsCollection* create_collection(size_t initial_size) {
    NetworkStatsCollection *collection = malloc(sizeof(NetworkStatsCollection));
    collection->data = malloc(initial_size * sizeof(NetworkInterfaceUpdate));
    collection->used = 0;
    collection->size = initial_size;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_collection(NetworkStatsCollection *collection) {
    free(collection->data);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_update(NetworkStatsCollection *collection, NetworkInterfaceUpdate update) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->used == collection->size) {
        size_t new_size = collection->size * 2;
        collection->data = realloc(collection->data, new_size * sizeof(NetworkInterfaceUpdate));
        collection->size = new_size;
    }
    collection->data[collection->used++] = update;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

NetworkInterfaceUpdate* get_update(NetworkStatsCollection *collection, int interface_id) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->used; i++) {
        if (collection->data[i].interface_id == interface_id) {
            pthread_mutex_unlock(&collection->mutex);
            return &collection->data[i];
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

void prune_updates(NetworkStatsCollection *collection, time_t threshold) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->used;) {
        if (difftime(collection->data[i].timestamp, threshold) > 0) {
            memmove(&collection->data[i], &collection->data[i + 1], (collection->used - i - 1) * sizeof(NetworkInterfaceUpdate));
            collection->used--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}
```

