    NetworkStatusCollection *collection = (NetworkStatusCollection*)malloc(sizeof(NetworkStatusCollection));
    collection->updates = (NetworkInterfaceUpdate**)calloc(initial_capacity, sizeof(NetworkInterfaceUpdate*));
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    collection->pruning_threshold = initial_pruning_threshold;
    return collection;
}

// Function to add a new update
void add_update(NetworkStatusCollection *collection, NetworkInterfaceUpdate *update) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        // Resize the array if necessary
        collection->updates = (NetworkInterfaceUpdate**)realloc(collection->updates, 2 * collection->capacity * sizeof(NetworkInterfaceUpdate*));
        collection->capacity *= 2;
    }
    collection->updates[collection->count++] = update;
    pthread_mutex_unlock(&collection->lock);
}

// Function to prune outdated entries
void prune_updates(NetworkStatusCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    size_t new_count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (difftime(time(NULL), collection->updates[i]->timestamp) > collection->pruning_threshold) {
            free(collection->updates[i]->stats);
            free(collection->updates[i]);
        } else {
            collection->updates[new_count++] = collection->updates[i];
        }
    }
    if (new_count < collection->count) {
        // Resize the array if necessary
        collection->updates = (NetworkInterfaceUpdate**)realloc(collection->updates, new_count * sizeof(NetworkInterfaceUpdate*));
        collection->capacity = new_count;
    }
    collection->count = new_count;
    pthread_mutex_unlock(&collection->lock);
}

