#define MAX_BUFFER_SIZE 1024

typedef struct {
    char interface_name[50];
    unsigned long packet_counter;
    double error_rate;
} NICStats;

NICStats* initializeNICStats(int array_size, int *error_code) {
    NICStats *nic_stats = (NICStats*)malloc(array_size * sizeof(NICStats));
    if (nic_stats == NULL) {
        *error_code = 1; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < array_size; i++) {
        snprintf(nic_stats[i].interface_name, sizeof(nic_stats[i].interface_name), "eth%d", i);
        nic_stats[i].packet_counter = rand() % 1000;
        nic_stats[i].error_rate = (double)(rand() % 100) / 100.0;
    }

    *error_code = 0; // Success
    return nic_stats;
}

void processAndHash(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <option> [strings...]\n", argv[0]);
        return;
    }

    const char *option = argv[1];
    char *result[MAX_BUFFER_SIZE];
    int count = 0;

    for (int i = 2; i < argc; i++) {
        if (strlen(argv[i]) > 1024) {
            fprintf(stderr, "String too long: %s\n", argv[i]);
            continue;
        }
        result[count++] = argv[i];
    }

    // Concatenate strings
    char concatenated[MAX_BUFFER_SIZE * count] = "";
    for (int i = 0; i < count; i++) {
        strncat(concatenated, result[i], MAX_BUFFER_SIZE - strlen(concatenated));
    }

    // Compute MD5 hash
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)concatenated, strlen(concatenated), (unsigned char*)&digest);

    if (strcmp(option, "hex") == 0) {
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            printf("%02x", digest[i]);
        }
        printf("\n");
    } else if (strcmp(option, "base64") == 0) {
        char base64[133] = ""; // Base64 encoded string will be at most 132 characters long
        BIO *b64 = BIO_new(BIO_f_base64());
        BIO *bio = BIO_new(BIO_s_mem());
        bio = BIO_push(b64, bio);
        BIO_write(bio, digest, MD5_DIGEST_LENGTH);
        BIO_flush(bio);
        char *encoded_data;
        long length = BIO_get_mem_ptr(bio, &encoded_data);
        encoded_data[length - 1] = '\0'; // Remove newline added by BIO
        printf("%s\n", encoded_data);
        BIO_free_all(bio);
    }
}

int main(int argc, char **argv) {
    if (strcmp(argv[1], "initializeNICStats") == 0) {
        int array_size = atoi(argv[2]);
        int error_code;
        NICStats *nic_stats = initializeNICStats(array_size, &error_code);
        if (error_code != 0) {
            fprintf(stderr, "Error initializing NIC stats: %d\n", error_code);
        } else {
            // Use nic_stats for further processing
            free(nic_stats); // Don't forget to free allocated memory when done
        }
    } else if (strcmp(argv[1], "processAndHash") == 0) {
        processAndHash(argc, argv);
    } else {
        fprintf(stderr, "Unknown command: %s\n", argv[1]);
    }

    return 0;
}
```

