    unsigned long packets;
    double error_rate;
    double latency;
} NicStats;

void initializeNicStats(NicStats **stats, int *size, int min_size) {
    srand(time(0));

    if (*size < min_size) {
        printf("Error: Minimum size (%d) must be greater than or equal to the current size (%d).\n", min_size, *size);
        return;
    }

    NicStats *new_stats = realloc(*stats, (*size + 1) * sizeof(NicStats));

    if (new_stats == NULL) {
        printf("Error: Memory allocation failed.\n");
        *size = MIN_INTERFACES; // Fallback to minimum size
        new_stats = realloc(*stats, *size * sizeof(NicStats));

        if (new_stats == NULL) {
            printf("Error: Failed to allocate memory for fallback size (%d).\n", *size);
            return;
        }
    }

    *stats = new_stats;

    for (int i = 0; i < *size; i++) {
        snprintf((*stats)[i].name, sizeof((*stats)[i].name), "eth%d", i);
        (*stats)[i].packets = rand() % 100000;
        (*stats)[i].error_rate = ((double)rand()) / RAND_MAX * 0.1;
        (*stats)[i].latency = ((double)rand()) / RAND_MAX * 10.0;
    }

    printf("NicStats initialized with size: %d\n", *size);
}

int main() {
    NicStats *nic_stats = NULL;
    int size = MIN_INTERFACES;

    initializeNicStats(&nic_stats, &size, MIN_INTERFACES);

    if (nic_stats != NULL) {
        for (int i = 0; i < size; i++) {
            printf("Interface %s: Packets=%lu, Error Rate=%.2f%%, Latency=%.2fms\n",
                   nic_stats[i].name, nic_stats[i].packets, nic_stats[i].error_rate * 100,
                   nic_stats[i].latency);
        }

        free(nic_stats);
    }

    return 0;
}
