#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_PACKETS 1024

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int packetSize;
    time_t timestamp;
} DataPacket;

DataPacket* packets[MAX_PACKETS] = {NULL};
int packetCount = 0;

void generateRandomIP(char* ip) {
    for (int i = 0; i < 4; ++i) {
        snprintf(ip + (i * 3), 4, "%d.", rand() % 256);
    }
    ip[15] = '\0';
}

DataPacket* createDataPacket() {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    generateRandomIP(packet->sourceIP);
    generateRandomIP(packet->destinationIP);
    packet->packetSize = rand() % 1500 + 60; // Random size between 60 and 1560 bytes
    packet->timestamp = time(NULL);

    return packet;
}

int addPacket(DataPacket* packet) {
    if (packetCount >= MAX_PACKETS) {
        fprintf(stderr, "Maximum packet limit reached\n");
        return -1;
    }

    packets[packetCount++] = packet;
    return 0;
}

int removePacket(int index) {
    if (index < 0 || index >= packetCount) {
        fprintf(stderr, "Invalid packet index\n");
        return -1;
    }

    free(packets[index]);
    for (int i = index; i < packetCount - 1; ++i) {
        packets[i] = packets[i + 1];
    }
    packets[packetCount - 1] = NULL;
    packetCount--;

    return 0;
}

void iteratePackets(void (*callback)(DataPacket*)) {
    for (int i = 0; i < packetCount; ++i) {
        callback(packets[i]);
    }
}

// Example usage
void printPacket(DataPacket* packet) {
    printf("Source IP: %s, Destination IP: %s, Packet Size: %d, Timestamp: %ld\n",
           packet->sourceIP, packet->destinationIP, packet->packetSize, packet->timestamp);
}

int main() {
    srand(time(NULL));

    // Add packets
    for (int i = 0; i < 10; ++i) {
        DataPacket* packet = createDataPacket();
        if (addPacket(packet) != 0) {
            free(packet); // Clean up if addPacket fails
        }
    }

    // Iterate and print packets
    iteratePackets(printPacket);

    // Remove a packet
    removePacket(5);

    return 0;
}
