class Transaction {
public:
    Transaction(int id, double amount, const std::string& currency, const std::string& status)
        : transactionID(id), amount(amount), currency(currency), status(status) {}

    int getTransactionID() const { return transactionID; }
    double getAmount() const { return amount; }
    const std::string& getCurrency() const { return currency; }
    const std::string& getStatus() const { return status; }
    void setStatus(const std::string& newStatus) { status = newStatus; }

private:
    int transactionID;
    double amount;
    std::string currency;
    std::string status;
};

class TransactionManager {
public:
    static TransactionManager& getInstance() {
        static TransactionManager instance;
        return instance;
    }

    void addTransaction(const Transaction& transaction) {
        transactions.push_back(std::make_unique<Transaction>(transaction));
    }

    bool updateTransaction(int id, const std::string& newStatus) {
        for (auto& t : transactions) {
            if (t->getTransactionID() == id) {
                t->setStatus(newStatus);
                return true;
            }
        }
        return false;
    }

    Transaction* getTransaction(int id) {
        for (auto& t : transactions) {
            if (t->getTransactionID() == id) {
                return t.get();
            }
        }
        return nullptr;
    }

private:
    TransactionManager() {}
    ~TransactionManager() {}

    std::vector<std::unique_ptr<Transaction>> transactions;
};

int main() {
    TransactionManager& manager = TransactionManager::getInstance();

    manager.addTransaction(Transaction(1, 100.0, "USD", "Pending"));
    manager.updateTransaction(1, "Completed");

    Transaction* transaction = manager.getTransaction(1);
    if (transaction) {
        std::cout << "Transaction ID: " << transaction->getTransactionID() << ", Status: " << transaction->getStatus() << std::endl;
    }

    return 0;
}
