#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

typedef enum {
    LOW_PRIORITY,
    MEDIUM_PRIORITY,
    HIGH_PRIORITY
} Priority;

typedef struct task {
    char* description;
    Priority priority;
    bool status;
    struct task* next;
} Task;

Task* create_task(const char* desc, Priority pri) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (new_task == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_task->description = strdup(desc);
    new_task->priority = pri;
    new_task->status = false;
    new_task->next = NULL;
    return new_task;
}

void add_task(Task** head, const char* desc, Priority pri) {
    Task* new_task = create_task(desc, pri);
    if (new_task != NULL) {
        new_task->next = *head;
        *head = new_task;
    }
}

void update_task(Task* task, bool status) {
    if (task != NULL) {
        task->status = status;
    }
}

void list_tasks_by_priority(Task* head) {
    Task* current = head;
    while (current != NULL) {
        if (current->status == false) {
            printf("Task: %s, Priority: %d, Status: Pending\n", current->description, current->priority);
        } else {
            printf("Task: %s, Priority: %d, Status: Completed\n", current->description, current->priority);
        }
        current = current->next;
    }
}

void free_tasks(Task* head) {
    Task* current = head;
    while (current != NULL) {
        Task* next = current->next;
        free(current->description);
        free(current);
        current = next;
    }
}

int main() {
    Task* head = NULL;

    add_task(&head, "Task 1", HIGH_PRIORITY);
    add_task(&head, "Task 2", MEDIUM_PRIORITY);
    add_task(&head, "Task 3", LOW_PRIORITY);

    list_tasks_by_priority(head);

    free_tasks(head);

    return 0;
}
```

