        components[(*out_count)++] = component;
        if (*out_count >= 1024) {
            Component** new_components = realloc(components, sizeof(Component*) * (*out_count + 512));
            if (!new_components) {
                fclose(file);
                free(components);
                return MEMORY_ALLOCATION_FAILED;
            }
            components = new_components;
        }
    }

    fclose(file);

