#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_INSTANCES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
} UE_Cache;

void init_UE_cache(UE_Cache *cache) {
    pthread_mutex_init(&cache->mutex, NULL);
    cache->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_UE_INSTANCES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->size = 0;
}

void free_UE_cache(UE_Cache *cache) {
    pthread_mutex_lock(&cache->mutex);
    free(cache->array);
    pthread_mutex_unlock(&cache->mutex);
    pthread_mutex_destroy(&cache->mutex);
}

int update_UE_info(UE_Cache *cache, int UE_id) {
    pthread_mutex_lock(&cache->mutex);
    if (UE_id < 0 || UE_id >= MAX_UE_INSTANCES) {
        pthread_mutex_unlock(&cache->mutex);
        return -1;
    }

    cache->array[UE_id].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
    cache->array[UE_id].RNTI = UE_id * 2; // Example RNTI
    cache->array[UE_id].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&cache->mutex);
    return 0;
}

int get_UE_info(UE_Cache *cache, int UE_id, NFAPI_CRC_INDICATION_PDU_T *info) {
    pthread_mutex_lock(&cache->mutex);
    if (UE_id < 0 || UE_id >= MAX_UE_INSTANCES) {
        pthread_mutex_unlock(&cache->mutex);
        return -1;
    }

    *info = cache->array[UE_id];

    pthread_mutex_unlock(&cache->mutex);
    return 0;
}

void *UE_info_updater(void *arg) {
    UE_Cache *cache = (UE_Cache *)arg;
    int UE_ids[MAX_UE_INSTANCES];
    srand(time(NULL));

    for (int i = 0; i < MAX_UE_INSTANCES; i++) {
        UE_ids[i] = rand() % MAX_UE_INSTANCES;
    }

    while (1) {
        for (int i = 0; i < MAX_UE_INSTANCES; i++) {
            update_UE_info(cache, UE_ids[i]);
            // Simulate delay
            usleep(100);
        }
    }
}

void *UE_info_requester(void *arg) {
    UE_Cache *cache = (UE_Cache *)arg;
    int UE_id;

    while (1) {
        UE_id = rand() % MAX_UE_INSTANCES;
        NFAPI_CRC_INDICATION_PDU_T info;

        if (get_UE_info(cache, UE_id, &info) == 0) {
            // Process the received information
            printf("Received info for UE ID %d: RX_UE_INFORMATION_TAG = %d, RNTI = %d, CRCFLAG = %d\n",
                   UE_id, info.RX_UE_INFORMATION_TAG, info.RNTI, info.CRCFLAG);
        }

        // Simulate delay
        usleep(200);
    }
}
