ThreadSafeArray *create_thread_safe_array() {
    ThreadSafeArray *array = malloc(sizeof(ThreadSafeArray));
    if (array == NULL) {
        perror("Failed to allocate memory for thread-safe array");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    return array;
