        report += "PID: " + std::to_string(process.pid) + ", CPU Usage: " + std::to_string(process.cpuUsage) + "%, Memory Consumption: " + std::to_string(process.memoryConsumption) + " MB, IO Metrics: " + std::to_string(process.ioMetrics) + "\n";
    }

    // Simulate categorizing processes based on resource consumption patterns
    int highCpuCount = 0;
    for (const auto& process : processes) {
        if (process.cpuUsage > 75.0f) {
            ++highCpuCount;
        }
    }
    report += "High CPU Usage Processes: " + std::to_string(highCpuCount) + "\n";

    return report;
}

// Main function to demonstrate the use of the monitorProcesses and generateReport functions
int main() {
    int arraySize = 10; // Configurable array size

    try {
        std::vector<Process> processes = monitorProcesses(arraySize);
        std::string report = generateReport(processes);
        std::cout << report << std::endl;
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
