typedef struct {
    char name[MAX_INTERFACE_NAME_LENGTH];
    unsigned long packets;
    double error_rate;
    double latency;
} NICStats;

NICStats* init_nic_stats(int size, int min_performance) {
    if (size <= 0) {
        fprintf(stderr, "Error: Invalid array size\n");
        return NULL;
    }

    NICStats* stats = malloc(size * sizeof(NICStats));
    if (!stats) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        snprintf(stats[i].name, MAX_INTERFACE_NAME_LENGTH, "eth%d", i);
        stats[i].packets = rand() % 1000000 + 1;
        stats[i].error_rate = ((double)(rand() % 100)) / 100.0;
        stats[i].latency = ((double)(rand() % 100)) / 10.0;

        if (stats[i].error_rate > min_acceptable_performance) {
            // Fallback mechanism: Reduce the number of interfaces
            printf("Warning: Error rate too high for interface %s. Reducing size.\n", stats[i].name);
            size = i;
            break;
        }
    }

    return stats;
}

int main() {
    int size = 100;
    int min_performance = MIN_ACCEPTABLE_PERFORMANCE;

    NICStats* nic_stats = init_nic_stats(size, min_performance);

    if (nic_stats) {
        printf("NIC Stats initialized successfully.\n");
        free(nic_stats);
    }

    return 0;
}
