// Define data structures for sensor data and pipeline
typedef struct {
    time_t timestamp;
    int sensor_id;
    float temperature;
    float humidity;
    float pressure;
} SensorData;

typedef struct {
    SensorData** data_points;
    int count;
    int max_count;
} PipelineStage;

typedef struct {
    PipelineStage* stages;
    int stage_count;
    int max_stage_count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int buffer_size;
} DataProcessorPipeline;

// Function to initialize the data processor pipeline
DataProcessorPipeline* setupDataProcessor(int max_sensors, int max_data_points_per_sensor, int buffer_size) {
    // Allocate memory for the data processor pipeline
    DataProcessorPipeline* pipeline = (DataProcessorPipeline*)malloc(sizeof(DataProcessorPipeline));
    if (!pipeline) {
        fprintf(stderr, "Memory allocation failed for pipeline\n");
        return NULL;
    }

    // Initialize mutex and condition variable
    pthread_mutex_init(&pipeline->lock, NULL);
    pthread_cond_init(&pipeline->cond, NULL);

    // Allocate memory for stages
    pipeline->stages = (PipelineStage*)malloc(max_sensors * sizeof(PipelineStage));
    if (!pipeline->stages) {
        fprintf(stderr, "Memory allocation failed for stages\n");
        free(pipeline);
        return NULL;
    }
    pipeline->stage_count = 0;
    pipeline->max_stage_count = max_sensors;

    // Initialize buffer size
    pipeline->buffer_size = buffer_size;

    return pipeline;
}

// Function to add data points to the pipeline
void addDataToPipeline(DataProcessorPipeline* pipeline, SensorData* data) {
    pthread_mutex_lock(&pipeline->lock);

    // Check if we need to allocate more stages
    if (pipeline->stage_count >= pipeline->max_stage_count) {
        PipelineStage* new_stages = (PipelineStage*)realloc(pipeline->stages, (pipeline->max_stage_count + 1) * sizeof(PipelineStage));
        if (!new_stages) {
            fprintf(stderr, "Memory reallocation failed for stages\n");
            pthread_mutex_unlock(&pipeline->lock);
            return;
        }
        pipeline->stages = new_stages;
        pipeline->max_stage_count++;
    }

    // Allocate memory for the data point
    pipeline->stages[pipeline->stage_count].data_points = (SensorData**)realloc(pipeline->stages[pipeline->stage_count].data_points, (pipeline->stages[pipeline->stage_count].count + 1) * sizeof(SensorData*));
    if (!pipeline->stages[pipeline->stage_count].data_points) {
        fprintf(stderr, "Memory reallocation failed for data points\n");
        pthread_mutex_unlock(&pipeline->lock);
        return;
    }
    pipeline->stages[pipeline->stage_count].data_points[pipeline->stages[pipeline->stage_count].count] = data;
    pipeline->stages[pipeline->stage_count].count++;

    // Signal that new data is available
    pthread_cond_signal(&pipeline->cond);

    pthread_mutex_unlock(&pipeline->lock);
}

// Function to process the data in the pipeline
void* processData(void* arg) {
    DataProcessorPipeline* pipeline = (DataProcessorPipeline*)arg;
    while (1) {
        pthread_mutex_lock(&pipeline->lock);

        // Wait for new data to be available
        while (pipeline->stage_count == 0) {
            pthread_cond_wait(&pipeline->cond, &pipeline->lock);
        }

        // Process the first stage of data
        if (pipeline->stages[0].count > 0) {
            SensorData* data = pipeline->stages[0].data_points[--pipeline->stages[0].count];
            // Perform processing on the data
            printf("Processing data: %f\n", data->temperature);
            free(data); // Free allocated memory for the data point
        }

        pthread_mutex_unlock(&pipeline->lock);
    }
}

int main() {
    srand(time(NULL));

    // Set up the data processor pipeline with 10 sensors and 5 data points per sensor, buffer size of 20
    DataProcessorPipeline* pipeline = setupDataProcessor(10, 5, 20);
    if (!pipeline) {
        return 1;
    }

    // Create a thread to process the data
    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, processData, pipeline)) {
        fprintf(stderr, "Thread creation failed\n");
        free(pipeline->stages);
        free(pipeline);
        return 1;
    }

    // Simulate adding data to the pipeline
    for (int i = 0; i < 30; i++) {
        SensorData* data = (SensorData*)malloc(sizeof(SensorData));
        if (!data) {
            fprintf(stderr, "Memory allocation failed for data point\n");
            continue;
        }
        data->timestamp = time(NULL);
        data->sensor_id = rand() % 10 + 1;
        data->temperature = rand() / (float)RAND_MAX * 50 - 20; // Random temperature between -20°C and 30°C
        data->humidity = rand() / (float)RAND_MAX * 100; // Random humidity between 0% and 100%
        data->pressure = rand() / (float)RAND_MAX * 5 + 980; // Random pressure between 980hPa and 1030hPa
        addDataToPipeline(pipeline, data);
    }

    pthread_join(processor_thread, NULL);

    free(pipeline->stages);
    free(pipeline);

    return 0;
}
```

