    for (int i = 0; i < context->sensorCount; i++) {
        // Process sensor data
        Sensor* sensor = &context->sensors[i];
        printf("Processing data from sensor %d\n", sensor->id);
        // Apply filters, aggregate metrics, and generate alerts
    }
    pthread_mutex_unlock(&context->mutex);
}

void addSensor(SensorNetworkContext* context, int id, float samplingRate, int transmissionInterval, int faultTolerance) {
    pthread_mutex_lock(&context->mutex);
    if (context->sensorCount < MAX_SENSORS) {
        Sensor* newSensor = &context->sensors[context->sensorCount];
        newSensor->id = id;
        newSensor->samplingRate = samplingRate;
        newSensor->transmissionInterval = transmissionInterval;
        newSensor->faultTolerance = faultTolerance;
        context->sensorCount++;
        printf("Sensor %d added to network\n", id);
    } else {
        printf("Sensor network is full, cannot add more sensors\n");
    }
    pthread_mutex_unlock(&context->mutex);
}

void removeSensor(SensorNetworkContext* context, int id) {
    pthread_mutex_lock(&context->mutex);
    for (int i = 0; i < context->sensorCount; i++) {
        if (context->sensors[i].id == id) {
            // Shift sensors to fill the gap
            for (int j = i; j < context->sensorCount - 1; j++) {
                context->sensors[j] = context->sensors[j + 1];
            }
            context->sensorCount--;
            printf("Sensor %d removed from network\n", id);
            break;
        }
    }
    pthread_mutex_unlock(&context->mutex);
}
