import hashlib
import os
import threading
import time

# Define a custom pool allocator for managing memory
class MemoryPool:
    def __init__(self, block_size, num_blocks):
        self.block_size = block_size
        self.num_blocks = num_blocks
        self.pool = [bytearray(block_size) for _ in range(num_blocks)]
        self.lock = threading.Lock()

    def allocate(self):
        with self.lock:
            if not self.pool:
                return None
            return self.pool.pop()

    def deallocate(self, block):
        with self.lock:
            if len(self.pool) < self.num_blocks:
                self.pool.append(block)

# Define the structure for CRC indication PDU
class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_info_tag, rnti, crc_ind_rel8_tag):
        self.rx_ue_info_tag = rx_ue_info_tag
        self.rnti = rnti
        self.crc_ind_rel8_tag = crc_ind_rel8_tag

# Define the CRC validation table
crc_table = {
