// Define the telemetry event structure
typedef struct {
    int device_id;
    long timestamp;
    char sensor_type[50];
    float sensor_reading;
    char *metadata; // Optional metadata like units and quality indicators
    void *binary_data_payload; // Pointer to binary data payload if specific sensor data is present
} TelemetryEvent;

// Function to dynamically allocate memory for an array of telemetry events
TelemetryEvent* allocate_telemetry_events(int N) {
    TelemetryEvent *events = (TelemetryEvent *)malloc(N * sizeof(TelemetryEvent));

    if (events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each event
    for (int i = 0; i < N; i++) {
        events[i].device_id = 0;
        events[i].timestamp = 0;
        events[i].sensor_type[0] = '\0';
        events[i].sensor_reading = 0.0f;
        events[i].metadata = NULL;
        events[i].binary_data_payload = NULL;
    }

    return events;
}

// Function to free allocated memory for telemetry events
void free_telemetry_events(TelemetryEvent *events, int N) {
    if (events == NULL) {
        return;
    }

    // Free binary data payloads and metadata
    for (int i = 0; i < N; i++) {
        free(events[i].binary_data_payload);
        free(events[i].metadata);
    }

    // Free the array of telemetry events
    free(events);
}

// Function to resize the telemetry event array dynamically
TelemetryEvent* resize_telemetry_events(TelemetryEvent *events, int current_size, int new_size) {
    TelemetryEvent *new_events = allocate_telemetry_events(new_size);

    if (new_events == NULL) {
        return events; // Return the old array in case of failure
    }

    // Copy data from old to new array
    for (int i = 0; i < current_size && i < new_size; i++) {
        new_events[i] = events[i];
    }

    // Free the old array
    free_telemetry_events(events, current_size);

    return new_events;
}

// Example usage of the above functions
int main() {
    int N = 100;
    TelemetryEvent *events = allocate_telemetry_events(N);

    if (events != NULL) {
        // Use the telemetry events array here

        // Free allocated memory when done
        free_telemetry_events(events, N);
    }

    return 0;
}
