    unsigned long packetCounter;
    double errorRate;
} NICStats;

NICStats* initializeNICStats(int arraySize) {
    if (arraySize <= 0) {
        fprintf(stderr, "Invalid array size. Must be greater than zero.\n");
        return NULL;
    }

    NICStats* nicArray = malloc(arraySize * sizeof(NICStats));
    if (nicArray == NULL) {
        perror("Memory allocation failed for NICStats array.");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < arraySize; i++) {
        snprintf(nicArray[i].interfaceName, sizeof(nicArray[i].interfaceName), "Interface%d", i + 1);
        nicArray[i].packetCounter = rand() % 100000;
        nicArray[i].errorRate = (double)(rand() % 100) / 100.0;
    }

    return nicArray;
}

void computeMD5Hash(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        perror("Error opening file.");
        return;
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    memset(hash, 0, sizeof(hash));

    MD5_CTX md5;
    MD5_Init(&md5);

    size_t bytesRead;
    unsigned char buffer[4096]; // Buffer to read the file in chunks

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5, buffer, bytesRead);
    }

    fclose(file);

    if (ferror(file)) {
        perror("Error reading from file.");
        return;
    }

    MD5_Final(hash, &md5);

    printf("MD5 hash of %s: ", filePath);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <array_size> <file_path>\n", argv[0]);
        return 1;
    }

    int arraySize = atoi(argv[1]);
    NICStats* nicArray = initializeNICStats(arraySize);
    if (nicArray != NULL) {
        // Process the NIC statistics as needed
        free(nicArray); // Don't forget to free allocated memory
    }

    computeMD5Hash(argv[2]);

    return 0;
}
