void update_connection_stats(TCP_CONNECTION_STATS_T* stats, int conn_id, size_t bytes_transferred) {
    if (conn_id > 0 && conn_id <= MAX_CONNECTIONS) {
        time(&stats[conn_id - 1].LAST_ACTIVE_TIME);
        stats[conn_id - 1].BYTES_TRANSFERRED += bytes_transferred;
    }
}

void free_connection_stats_array(TCP_CONNECTION_STATS_T* stats) {
    free(stats);
}

