#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_TAGS 1024
#define MAX_RNTI_VALUES 1024

typedef struct {
    unsigned char nas_message[MAX_NAS_MESSAGE_SIZE];
    int mme_id;
    struct PHY_LAYER_STATS phy_layer_stats;
} LTE_ENB_RRC_API_MSG_T;

typedef struct {
    pthread_mutex_t mutex;
    LTE_ENB_RRC_API_MSG_T** msg_array;
    size_t array_size;
    size_t used_size;
    int crc_version;
    int default_behavior_on_version_mismatch;
    int memory_usage_logging_enabled;
} RRC_API_Manager;

RRC_API_Manager* create_rrc_manager(int initial_size, int crc_version, int default_behavior) {
    RRC_API_Manager* manager = malloc(sizeof(RRC_API_Manager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->msg_array = reallocarray(NULL, initial_size, sizeof(LTE_ENB_RRC_API_MSG_T*));
    if (!manager->msg_array) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        manager->msg_array[i] = malloc(sizeof(LTE_ENB_RRC_API_MSG_T));
        if (!manager->msg_array[i]) {
            for (size_t j = 0; j < i; ++j) free(manager->msg_array[j]);
            pthread_mutex_destroy(&manager->mutex);
            free(manager->msg_array);
            free(manager);
            return NULL;
        }
    }

    manager->array_size = initial_size;
    manager->used_size = 0;
    manager->crc_version = crc_version;
    manager->default_behavior_on_version_mismatch = default_behavior;
    manager->memory_usage_logging_enabled = 1;

    return manager;
}

void destroy_rrc_manager(RRC_API_Manager* manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->used_size; ++i) free(manager->msg_array[i]);
    pthread_mutex_unlock(&manager->mutex);

    free(manager->msg_array);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

LTE_ENB_RRC_API_MSG_T* generate_rrc_message(RRC_API_Manager* manager, const unsigned char* nas_message, int mme_id, const PHY_LAYER_STATS* phy_stats) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_size == manager->array_size) {
        size_t new_size = manager->array_size ? manager->array_size * 2 : 1;
        manager->msg_array = reallocarray(manager->msg_array, new_size, sizeof(LTE_ENB_RRC_API_MSG_T*));
        if (!manager->msg_array) {
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
        for (size_t i = manager->used_size; i < new_size; ++i) {
            manager->msg_array[i] = malloc(sizeof(LTE_ENB_RRC_API_MSG_T));
            if (!manager->msg_array[i]) {
                pthread_mutex_unlock(&manager->mutex);
                return NULL;
            }
        }
        manager->array_size = new_size;
    }

    LTE_ENB_RRC_API_MSG_T* msg = manager->msg_array[manager->used_size++];
    memcpy(msg->nas_message, nas_message, MAX_NAS_MESSAGE_SIZE);
    msg->mme_id = mme_id;
    memcpy(&msg->phy_layer_stats, phy_stats, sizeof(PHY_LAYER_STATS));

    pthread_mutex_unlock(&manager->mutex);

    return msg;
}
