#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PDU 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int count[MAX_PDU]; // Array to track RNTI occurrences
    int unique_count;  // Number of unique RNTIs
} PDU_List;

PDU_List* create_list() {
    PDU_List* list = (PDU_List*)malloc(sizeof(PDU_List));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return NULL;
    }
    list->head = list->tail = NULL;
    memset(list->count, 0, sizeof(int) * MAX_PDU);
    list->unique_count = 0;
    return list;
}

void free_list(PDU_List* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for PDU.\n");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pdu->prev = pdu->next = NULL;
    return pdu;
}

int add_pdu(PDU_List* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->unique_count >= MAX_PDU) {
        fprintf(stderr, "Maximum unique RNTIs reached.\n");
        return -1;
    }
    if (list->count[RNTI] > 0) {
        fprintf(stderr, "RNTI already exists in the list.\n");
        return -2;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_pdu(RX_UE_INFORMATION_TAG, RNTI);
    if (!new_pdu) {
        return -3; // Memory allocation failed
    }

    if (list->tail == NULL) {
        list->head = list->tail = new_pdu;
    } else {
        list->tail->next = new_pdu;
        new_pdu->prev = list->tail;
        list->tail = new_pdu;
    }

    list->count[RNTI]++;
    list->unique_count++;
    return 0; // Success
}

void serialize_list(PDU_List* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        fprintf(file, "%d %d %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRCFLAG);
        current = current->next;
    }

    fclose(file);
}

// Example usage
int main() {
    srand(time(NULL));
    PDU_List* list = create_list();
    if (!list) return -1;

    for (int i = 0; i < MAX_PDU; i++) {
        int RX_UE_INFORMATION_TAG = rand() % 100;
        int RNTI = rand() % 200;
        if (add_pdu(list, RX_UE_INFORMATION_TAG, RNTI) != 0) {
            fprintf(stderr, "Failed to add PDU at index %d.\n", i);
            free_list(list);
            return -2;
        }
    }

    serialize_list(list, "pdu_list.txt");
    free_list(list);

    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes error handling for memory allocation failures and ensures that each RNTI is unique within the list. The `serialize_list` function allows for persistent storage of the linked list to disk, and it handles both time and space efficiency by using dynamic memory allocation and efficient insertion/deletion operations at both ends of the list.']

