} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->capacity = initial_capacity;
    list->size = 0;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList **list_ptr) {
    DynamicList *list = *list_ptr;
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
    *list_ptr = NULL;
}

void dynamic_list_add(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->mutex);
            return; // Handle memory allocation failure
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    // Populate the PDU structure with random values or existing data
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdus[list->size++];
    generate_random_pdu(new_pdu);
    pthread_mutex_unlock(&list->mutex);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Implement logic to fill the PDU structure with random data
    pdu->ue_info = get_random_ue_info();
    pdu->rnti = get_random_rnti();
    pdu->crc_indication.crcflag = generate_random_crc_flag();
}

// Define helper functions like get_random_ue_info(), get_random_rnti(), and generate_random_crc_flag()

void* load_users(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    for (int i = 0; i < MAX_CONCURRENT_LOADS; ++i) {
        dynamic_list_add(list);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_LOADS];
    DynamicList *list = dynamic_list_create(16);

    if (!list) {
        // Handle memory allocation failure
        return 1;
    }

    for (int i = 0; i < MAX_CONCURRENT_LOADS; ++i) {
        if (pthread_create(&threads[i], NULL, load_users, list)) {
            // Handle thread creation failure
            dynamic_list_destroy(&list);
            return 1;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_LOADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    dynamic_list_destroy(&list);

    return 0;
}
