        return NULL;
    }

    FILE* file = fopen(params->file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        EVP_CIPHER_CTX_free(ctx);
        free(processed_data);
        return NULL;
    }

    // Read file and encrypt
    unsigned char* buffer = (unsigned char*)malloc(1024 * 1024); // 1MB buffer
    if (!buffer) {
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        free(processed_data);
        return NULL;
    }

    int len, tot_len = 0;
    while ((len = fread(buffer, 1, 1024 * 1024, file)) > 0) {
        if (EVP_EncryptUpdate(ctx, processed_data->result_data + tot_len, &len, buffer, len) != 1) {
            ERR_print_errors_fp(stderr);
            free(buffer);
            fclose(file);
            EVP_CIPHER_CTX_free(ctx);
            free(processed_data);
            return NULL;
        }
        tot_len += len;
    }

    if (EVP_EncryptFinal_ex(ctx, processed_data->result_data + tot_len, &len) != 1) {
        ERR_print_errors_fp(stderr);
        free(buffer);
        fclose(file);
        EVP_CIPHER_CTX_free(ctx);
        free(processed_data);
        return NULL;
    }
    tot_len += len;

    processed_data->result_size = tot_len;
    free(buffer);
    fclose(file);
    EVP_CIPHER_CTX_free(ctx);

    // Clean up OpenSSL library
    ERR_free_strings();
    EVP_cleanup();

    return processed_data;
}

int main(int argc, char* argv[]) {
    FileProcessingParams params = {
        .file_path = "example.txt",
        .command_line_option = 1,
        .concurrency_level = 4
    };

    ProcessedData* result = process_file(&params);
    if (result) {
        printf("Processed data size: %zu\n", result->result_size);
        // Free processed data when done
        free(result->result_data);
        free(result);
    }

    return 0;
}
