#include <iostream>
#include <vector>
#include <mutex>
#include <memory>
#include <functional>

class Transaction {
public:
    int transactionID;
    double amount;
    std::string currency;
    std::string status;
    time_t timestamp;

    Transaction(int id, double amt, const std::string& curr, const std::string& stat, time_t ts)
        : transactionID(id), amount(amt), currency(curr), status(stat), timestamp(ts) {}
};

class TransactionManager {
private:
    std::vector<std::shared_ptr<Transaction>> transactions;
    mutable std::mutex mutex;

public:
    void addTransaction(const std::shared_ptr<Transaction>& transaction) {
        std::lock_guard<std::mutex> lock(mutex);
        transactions.push_back(transaction);
    }

    void updateTransaction(int id, const std::function<void(std::shared_ptr<Transaction>)>& updateFunc) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& transaction : transactions) {
            if (transaction->transactionID == id) {
                updateFunc(transaction);
                break;
            }
        }
    }

    std::shared_ptr<const Transaction> getTransaction(int id) const {
        std::lock_guard<std::mutex> lock(mutex);
        for (const auto& transaction : transactions) {
            if (transaction->transactionID == id) {
                return transaction;
            }
        }
        return nullptr;
    }

    class Iterator {
    private:
        friend class TransactionManager;
        std::vector<std::shared_ptr<Transaction>>::iterator it;

        explicit Iterator(std::vector<std::shared_ptr<Transaction>>::iterator iter) : it(iter) {}

    public:
        bool operator!=(const Iterator& other) const { return it != other.it; }
        void operator++() { ++it; }
        std::shared_ptr<const Transaction> operator*() const { return *it; }
    };

    Iterator begin() {
        std::lock_guard<std::mutex> lock(mutex);
        return Iterator(transactions.begin());
    }

    Iterator end() {
        std::lock_guard<std::mutex> lock(mutex);
        return Iterator(transactions.end());
    }
};

int main() {
    TransactionManager manager;
    auto transaction = std::make_shared<Transaction>(1, 100.0, "USD", "pending", time(nullptr));
    manager.addTransaction(transaction);

    manager.updateTransaction(1, [](const std::shared_ptr<Transaction>& t) {
        t->status = "completed";
    });

    for (auto& transaction : manager) {
        std::cout << "ID: " << transaction->transactionID << ", Amount: " << transaction->amount
                  << ", Currency: " << transaction->currency << ", Status: " << transaction->status
                  << std::endl;
    }

    return 0;
}
```

