    for (int i = 0; i < system->nic_count; ++i) {
        free(system->nic_configs[i]);
    }

    for (int i = 0; i < system->sdc_count; ++i) {
        free(system->sdc_configs[i]);
    }

    pthread_mutex_destroy(&system->lock);
    free(system);
}

