    if (nic_index >= 0 && nic_index < system->nic_count) {
        // Update NIC statistics
    }
    if (sdc_index >= 0 && sdc_index < system->sdc_count) {
        // Update SDC statistics
    }
    pthread_mutex_unlock(&system->lock);
}

void aggregate_statistics(MonitoringSystem *system, int interval) {
    while (1) {
        for (int i = 0; i < system->nic_count; ++i) {
            update_statistics(system, i, -1);
        }
        for (int i = 0; i < system->sdc_count; ++i) {
            update_statistics(system, -1, i);
        }
        sleep(interval);
    }
}

void* monitoring_thread(void *arg) {
    MonitoringSystem *system = (MonitoringSystem*)arg;
    aggregate_statistics(system, DEFAULT_UPDATE_INTERVAL);
    return NULL;
}

int main() {
    srand(time(NULL));

    int nic_count = 50;
    int sdc_count = 20;

    MonitoringSystem *monitoring_system = initialize_monitoring_system(nic_count, sdc_count);
