    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, monitoring_thread, monitoring_system)) {
        log_message("Failed to create monitoring thread");
        destroy_monitoring_system(monitoring_system);
        return 1;
    }

    pthread_join(thread_id, NULL);

    destroy_monitoring_system(monitoring_system);
    return 0;
}
