typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t mutex;
} MemoryPool;

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(MemoryPool *pool, size_t count) {
    pthread_mutex_lock(&pool->mutex);
    if (count > pool->pool_size - pool->used_count) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = &pool->pool[pool->used_count];
    pool->used_count += count;
    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

void free_memory(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *ptr, size_t count) {
    pthread_mutex_lock(&pool->mutex);
    if (ptr >= &pool->pool[0] && ptr < &pool->pool[pool->pool_size]) {
        pool->used_count -= count;
    }
    pthread_mutex_unlock(&pool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* generate_array(size_t N, MemoryPool *pool) {
