typedef struct {
    NICStats *stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NetworkMonitor;

NetworkMonitor* init_network_monitor(size_t initial_capacity) {
    NetworkMonitor *monitor = (NetworkMonitor*)malloc(sizeof(NetworkMonitor));
    if (!monitor) {
        fprintf(stderr, "Memory allocation failed for NetworkMonitor\n");
        return NULL;
    }

    monitor->capacity = initial_capacity;
    monitor->count = 0;
    monitor->stats = (NICStats*)calloc(initial_capacity, sizeof(NICStats));
    if (!monitor->stats) {
        free(monitor);
        fprintf(stderr, "Memory allocation failed for NICStats array\n");
        return NULL;
    }

    pthread_mutex_init(&monitor->lock, NULL);

    return monitor;
}

void add_interface(NetworkMonitor *monitor, const char *name, unsigned long packets, double error_rate, double latency) {
    pthread_mutex_lock(&monitor->lock);
    if (monitor->count >= monitor->capacity) {
        size_t new_capacity = monitor->capacity * 2;
        NICStats *new_stats = (NICStats*)realloc(monitor->stats, new_capacity * sizeof(NICStats));
        if (!new_stats) {
            fprintf(stderr, "Memory reallocation failed for NICStats array\n");
            pthread_mutex_unlock(&monitor->lock);
            return;
        }
        monitor->stats = new_stats;
        monitor->capacity = new_capacity;
    }

    strncpy(monitor->stats[monitor->count].name, name, sizeof(monitor->stats[monitor->count].name) - 1);
    monitor->stats[monitor->count].packets = packets;
    monitor->stats[monitor->count].error_rate = error_rate;
    monitor->stats[monitor->count].latency = latency;

    monitor->count++;
    pthread_mutex_unlock(&monitor->lock);
}

void free_network_monitor(NetworkMonitor *monitor) {
    if (monitor) {
        pthread_mutex_destroy(&monitor->lock);
        free(monitor->stats);
        free(monitor);
    }
}
