} DynamicArray;

DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        log_error("Failed to allocate memory for DynamicArray");
        return NULL;
    }
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        log_error("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray* array) {
    if (array->array) {
        free(array->array);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int dynamic_array_add(DynamicArray* array, const UE_Information_Tag* ue_info_tag, uint16_t rnti, bool crc_flag) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            log_error("Failed to reallocate memory for NFAPI_CRC_INDICATION_PDU_T array");
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size].rx_ue_information_tag = *ue_info_tag;
    array->array[array->size].rnti = rnti;
    array->array[array->size].crc_indication_rel8_tag.crc_flag = crc_flag;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void dynamic_array_clear(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}
