    // Initialize other fields as per the LTE specification
    return msg;
}

void add_message(MessageArray *array, LTE_ENB_RRC_API_MSG_T *msg) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : MAX_UE_TAGS;
        LTE_ENB_RRC_API_MSG_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_ENB_RRC_API_MSG_T));
        if (new_messages == NULL) {
            // Handle memory allocation failure
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->count++] = *msg;
    pthread_mutex_unlock(&array->mutex);
}

