CipherPool* initialize_cipher_pool(const char *config_path, const char *option, int max_objects) {
    // Open and parse the configuration file
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open config file");
        return NULL;
    }

    // Validate configuration content (not shown in code snippet)

    CipherPool *pool = malloc(sizeof(CipherPool));
    pool->size = 0;
    pool->max_size = max_objects;
    pthread_mutex_init(&pool->lock, NULL);

    pool->objects = malloc(max_objects * sizeof(CipherObject *));
    for (int i = 0; i < max_objects; i++) {
        pool->objects[i] = malloc(sizeof(CipherObject));
        if (!pool->objects[i]) {
            perror("Failed to allocate memory for cipher object");
            // Free previously allocated objects
            for (int j = 0; j < i; j++) {
                free(pool->objects[j]);
            }
            free(pool);
            fclose(file);
            return NULL;
        }

        pool->objects[i]->ctx = EVP_CIPHER_CTX_new();
        if (!pool->objects[i]->ctx) {
