            // Free allocated memory and contexts
            for (int j = 0; j <= i; j++) {
                free(pool->objects[j]);
                EVP_CIPHER_CTX_free(pool->objects[j]->ctx);
            }
            free(pool->objects);
            free(pool);
            fclose(file);
            return NULL;
        }

        // Initialize cipher object based on the provided option
        if (strcmp(option, "AES-128-CBC") == 0) {
            EVP_EncryptInit_ex(pool->objects[i]->ctx, EVP_aes_128_cbc(), NULL, NULL, NULL);
        } else if (strcmp(option, "AES-256-CFB") == 0) {
            EVP_EncryptInit_ex(pool->objects[i]->ctx, EVP_aes_256_cfb(), NULL, NULL, NULL);
        } else {
            fprintf(stderr, "Unsupported cipher option: %s\n", option);
            // Free allocated memory and contexts
            for (int j = 0; j <= i; j++) {
                free(pool->objects[j]);
                EVP_CIPHER_CTX_free(pool->objects[j]->ctx);
            }
            free(pool->objects);
            free(pool);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return pool;
}

