    int* numbers = malloc(max_size * sizeof(int));
    if (numbers == NULL) return NULL;

    int count = 0;
    while (scanf("%d", &numbers[count]) != EOF && count < max_size) {
        count++;
    }

    // Find the largest integer
    int largest = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest integer: %d\n", largest);

    return numbers;
}
