struct NetworkMonitoring {
    std::string ipAddress;
    double bandwidthUsage;
    double latencyMetrics;
    double packetLossRates;
    std::string routingTableConfigurations;
    double congestionLevels;
};

std::mutex mtx;

void populateNetworkData(const std::string& configFilePath, std::vector<NetworkMonitoring>& networkData) {
    std::ifstream file(configFilePath);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << configFilePath << std::endl;
        return;
    }

    NetworkMonitoring data;
    while (file >> data.ipAddress >> data.bandwidthUsage >> data.latencyMetrics >> data.packetLossRates >> data.routingTableConfigurations >> data.congestionLevels) {
        std::lock_guard<std::mutex> lock(mtx);
        networkData.push_back(data);
    }
}

void analyzeNetworkHealth(const std::vector<NetworkMonitoring>& networkData) {
    for (const auto& data : networkData) {
        std::cout << "IP Address: " << data.ipAddress << "\n";
        std::cout << "Bandwidth Usage: " << data.bandwidthUsage << "\n";
        std::cout << "Latency Metrics: " << data.latencyMetrics << "\n";
        std::cout << "Packet Loss Rates: " << data.packetLossRates << "\n";
        std::cout << "Routing Table Configurations: " << data.routingTableConfigurations << "\n";
        std::cout << "Congestion Levels: " << data.congestionLevels << "\n\n";
    }
}

void networkMonitoringFunction(const std::string& configFilePath) {
    try {
        std::vector<NetworkMonitoring> networkData;
        populateNetworkData(configFilePath, networkData);

        if (networkData.empty()) {
            std::cerr << "No data found in the configuration file." << std::endl;
            return;
        }

        analyzeNetworkHealth(networkData);
    } catch (const std::exception& e) {
        std::cerr << "Error during network monitoring: " << e.what() << std::endl;
    }
}

int main() {
    std::string configFilePath = "network_config.txt";
    networkMonitoringFunction(configFilePath);

    return 0;
}
