// Define the structure for resource bundle
typedef struct {
    int itemCount;
    char **itemTypes;
    size_t *itemSizes;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char *filePath) {
    // Open the file and read its contents to populate the bundle
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open resource file");
        return NULL;
    }

    // Read header and version to validate format
    char header[10];
    int version;
    if (fread(header, sizeof(char), 9, file) != 9 || fread(&version, sizeof(int), 1, file) != 1) {
        fclose(file);
        perror("Failed to read resource file header or version");
        return NULL;
    }

    // Validate the header and version
    if (strcmp(header, "RESOURCE") != 0 || version != 1) {
        fclose(file);
        fprintf(stderr, "Invalid resource file format\n");
        return NULL;
    }

    // Allocate memory for the bundle and items
    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    bundle->itemCount = 0;
    bundle->itemTypes = NULL;
    bundle->itemSizes = NULL;

    // Read items from the file and populate the bundle
    while (!feof(file)) {
        char type[50];
        size_t size;
        if (fscanf(file, "%s %zu", type, &size) != 2) {
            break;
        }

        bundle->itemCount++;
        bundle->itemTypes = (char **)realloc(bundle->itemTypes, bundle->itemCount * sizeof(char *));
        bundle->itemSizes = (size_t *)realloc(bundle->itemSizes, bundle->itemCount * sizeof(size_t));

        bundle->itemTypes[bundle->itemCount - 1] = strdup(type);
        bundle->itemSizes[bundle->itemCount - 1] = size;
    }

    fclose(file);
    return bundle;
}

