typedef struct {
    int id;
    char name[256];
} NICStats;

void* encryptDecrypt(char* input, char* key, int option) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (option == 1) { // Encrypt
        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)key, IV)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else { // Decrypt
        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)key, IV)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    unsigned char output[1024];
    int outlen;

    if (1 != EVP_EncryptUpdate(ctx, output, &outlen, (unsigned char*)input, strlen(input))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int tmplen = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, output + outlen, &tmplen)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    unsigned char *result = (unsigned char*)malloc(outlen + tmplen + 1);
    memcpy(result, output, outlen + tmplen);
    result[outlen + tmplen] = '\0';

    return result;
}

NICStats* initializeNICStats(int maxNICs) {
    NICStats* nicStats = (NICStats*)calloc(maxNICs, sizeof(NICStats));
    if (!nicStats) return NULL;

    for (int i = 0; i < maxNICs; i++) {
        nicStats[i].id = i + 1;
        snprintf(nicStats[i].name, sizeof(nicStats[i].name), "NIC%d", i + 1);
    }

    return nicStats;
}

void findLargestInt() {
    int num, largest = INT_MIN;
    while (scanf("%d", &num) != EOF) {
        if (num > largest) {
            largest = num;
        }
    }

    printf("The largest number is: %d\n", largest);
}
