    const size_t chunk_size = 4096;
    unsigned char buffer[chunk_size];

    while (fread(buffer, sizeof(unsigned char), chunk_size, file) > 0) {
        EVP_DigestUpdate(mdctx, buffer, fread(buffer, sizeof(unsigned char), chunk_size, file));
    }

    EVP_DigestFinal_ex(mdctx, md_value, &md_len);
    EVP_MD_CTX_free(mdctx);

    printf("MD5 hash: ");
    for (int i = 0; i < md_len; ++i) {
