void parse_tiff_image(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;
    tdata_t tif = TIFFFdOpen(fileno(file), filename, "r", 8, 1);
    if (!tif) return;
    uint32_t bits_per_sample, samples_per_pixel, extra_samples_count;
