    // Implementation to handle different cases of bits per sample and extra samples
}

// Function to perform large file hashing with limited memory usage
void *large_file_hash(void *arg) {
    char *filename = (char *)arg;
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;
    MD5_CTX md5_ctx;
    MD5_Init(&md5_ctx);
    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5_ctx, buffer, bytesRead);
    }
    fclose(file);
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_Final(hash, &md5_ctx);
    // Implementation to update the MD5 hash incrementally
}

